$$;



--
-- Name: _portal_notification_unread_count_core(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._portal_notification_unread_count_core(p_customer_id bigint) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  p_customer_id BIGINT := p_customer_id;
  v_count INT;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM public.portal_notifications AS n
  WHERE n.customer_id = p_customer_id
    AND n.read_at IS NULL;

  RETURN v_count;
END;
$$;



--
-- Name: add_agency_report_occurrence(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_agency_report_occurrence(p_voyage_id bigint, p_port text, p_body text, p_section text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_report_id UUID;
  v_section TEXT := NULLIF(btrim(COALESCE(p_section, '')), '');
BEGIN
  SELECT role INTO v_role FROM public.user_profiles
  WHERE id = auth.uid() AND active = TRUE;
  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;
  v_role := CASE v_role WHEN 'admin' THEN 'administrativo'
                        WHEN 'operator' THEN 'documentacao'
                        ELSE v_role END;
  IF v_role NOT IN ('administrativo', 'operacoes', 'documentacao', 'equipamentos') THEN
    RAISE EXCEPTION 'Sem permissao para lancar ocorrencias.' USING ERRCODE = '42501';
  END IF;
  IF btrim(COALESCE(p_body, '')) = '' THEN
    RAISE EXCEPTION 'Ocorrencia vazia.' USING ERRCODE = '22023';
  END IF;
  IF v_section IS NOT NULL AND public.agency_report_section_owner(v_section) IS NULL THEN
    RAISE EXCEPTION 'Secao invalida.' USING ERRCODE = '22023';
  END IF;

  v_report_id := public.ensure_agency_departure_report(p_voyage_id, p_port);
  IF EXISTS (
    SELECT 1 FROM public.agency_departure_reports
    WHERE id = v_report_id AND status = 'closed'
  ) THEN
    RAISE EXCEPTION 'ADR fechado: reabra antes de adicionar ocorrencias.' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.agency_departure_report_occurrences (report_id, body, author_id, department, section)
  VALUES (v_report_id, btrim(p_body), auth.uid(), v_role, v_section);

  RETURN jsonb_build_object('report_id', v_report_id);
END;
$$;



--
-- Name: add_demurrage_dispute_attachment(bigint, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_demurrage_dispute_attachment(p_message_id bigint, p_storage_path text, p_file_name text, p_mime_type text, p_size_bytes bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_message public.demurrage_dispute_messages%ROWTYPE;
  v_dispute public.demurrage_disputes%ROWTYPE;
  v_id BIGINT;
BEGIN
  IF auth.uid() IS NULL OR (NOT public.is_active_user() AND public.current_portal_customer_id() IS NULL) THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(btrim(p_storage_path), '') IS NULL OR NULLIF(btrim(p_file_name), '') IS NULL
     OR NULLIF(btrim(p_mime_type), '') IS NULL OR p_size_bytes IS NULL
     OR p_size_bytes <= 0 OR p_size_bytes > 10485760 THEN
    RAISE EXCEPTION 'Anexo inválido.' USING ERRCODE = '22023';
  END IF;
  IF p_mime_type NOT IN ('application/pdf', 'image/jpeg', 'image/png', 'text/plain') THEN
    RAISE EXCEPTION 'Tipo de anexo não permitido.' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_message FROM public.demurrage_dispute_messages WHERE id = p_message_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Mensagem não encontrada.' USING ERRCODE = 'P0002'; END IF;
  SELECT * INTO v_dispute FROM public.demurrage_disputes WHERE id = v_message.dispute_id;
  IF NOT public.is_active_user() AND v_dispute.customer_id <> public.current_portal_customer_id() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;
  IF p_storage_path NOT LIKE (v_dispute.customer_id::TEXT || '/disputes/' || v_dispute.id::TEXT || '/%') THEN
    RAISE EXCEPTION 'Caminho de anexo inválido.' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.demurrage_dispute_attachments(message_id, dispute_id, customer_id, storage_path, file_name, mime_type, size_bytes, uploaded_by)
  VALUES (v_message.id, v_dispute.id, v_dispute.customer_id, p_storage_path, p_file_name, p_mime_type, p_size_bytes, auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;



--
-- Name: add_demurrage_dispute_message(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_demurrage_dispute_message(p_dispute_id bigint, p_body text, p_next_responder text DEFAULT 'cliente'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := public._portal_actor_role();
  v_dispute public.demurrage_disputes%ROWTYPE;
  v_message_id BIGINT;
  v_resolved BOOLEAN := p_next_responder = 'ninguem';
BEGIN
  IF v_role <> 'equipamentos' THEN RAISE EXCEPTION 'Apenas Equipamentos pode responder a Dispute.' USING ERRCODE = '42501'; END IF;
  IF NULLIF(btrim(p_body), '') IS NULL THEN RAISE EXCEPTION 'Informe a mensagem da disputa.' USING ERRCODE = '22023'; END IF;
  IF p_next_responder NOT IN ('cliente', 'equipamentos', 'ninguem') THEN RAISE EXCEPTION 'Responsável inválido.' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_dispute FROM public.demurrage_disputes WHERE id = p_dispute_id FOR UPDATE;
  IF NOT FOUND OR v_dispute.state <> 'aberta' THEN RAISE EXCEPTION 'Dispute não está aberta.' USING ERRCODE = '42501'; END IF;
  IF v_dispute.next_responder <> 'equipamentos' THEN RAISE EXCEPTION 'A Dispute aguarda manifestação do cliente.' USING ERRCODE = '42501'; END IF;

  INSERT INTO public.demurrage_dispute_messages(dispute_id, author_id, author_type, body, next_responder, metadata)
  VALUES (p_dispute_id, auth.uid(), 'equipamentos', btrim(p_body), p_next_responder, jsonb_build_object('channel', 'internal'))
  RETURNING id INTO v_message_id;
  IF v_resolved THEN
    UPDATE public.demurrage_disputes SET state = 'resolvida', next_responder = 'ninguem', resolved_at = now() WHERE id = p_dispute_id;
    UPDATE public.demurrage_invoices SET dispute_open = false, dispute_status = 'resolvido' WHERE id = v_dispute.demurrage_invoice_id;
  ELSE
    UPDATE public.demurrage_disputes SET state = 'aberta', next_responder = p_next_responder WHERE id = p_dispute_id;
    UPDATE public.demurrage_invoices SET dispute_open = true, dispute_status = 'aberto' WHERE id = v_dispute.demurrage_invoice_id;
  END IF;
  IF p_next_responder = 'cliente' THEN
    INSERT INTO public.portal_notifications(customer_id, bl_id, type, title, message, link)
    SELECT v_dispute.customer_id, NULL, 'dispute_responded', 'Disputa respondida', 'Equipamentos respondeu à sua disputa.', '/demurrage';
    PERFORM public.block521_resolve_alert('portal_dispute_opened', 'demurrage_invoice', v_dispute.demurrage_invoice_id::text, 'equipamentos', 'portal_dispute_message');
  ELSIF p_next_responder = 'equipamentos' THEN
    PERFORM public.block521_upsert_alert(
      'portal_dispute_opened', 'demurrage_invoice', v_dispute.demurrage_invoice_id::text,
      'Nova resposta na Dispute; ação de Equipamentos pendente.', 'portal_dispute_message', 'equipamentos',
      jsonb_build_object('dispute_id', p_dispute_id, 'message_id', v_message_id), '/demurrage?dispute=' || p_dispute_id
    );
  ELSE
    PERFORM public.block521_resolve_alert('portal_dispute_opened', 'demurrage_invoice', v_dispute.demurrage_invoice_id::text, 'equipamentos', 'portal_dispute_message');
  END IF;
  RETURN jsonb_build_object('dispute_id', p_dispute_id, 'message_id', v_message_id, 'state', CASE WHEN v_resolved THEN 'resolvida' ELSE 'aberta' END);
END;
$$;



--
-- Name: add_manual_bl_charge(text, bigint, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_manual_bl_charge(p_bl_id text, p_charge_item_id bigint, p_quantity numeric DEFAULT 1, p_notes text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl RECORD;
  v_item RECORD;
  v_actor UUID;
  v_qty NUMERIC(12,6);
  v_unit_brl NUMERIC(12,2);
  v_unit_usd NUMERIC(12,2);
  v_total_brl NUMERIC(14,2);
  v_total_usd NUMERIC(14,2);
  v_key TEXT;
  v_calc_id BIGINT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  SELECT
    b.id,
    b.customer_id,
    COALESCE(b.cargo_mode, 'container') AS cargo_mode,
    b.pod,
    b.charge_status,
    b.financial_status,
    COALESCE(ib.uploaded_at::DATE, b.created_at::DATE, CURRENT_DATE) AS reference_date
  INTO v_bl
  FROM public.bls AS b
  LEFT JOIN public.import_batches AS ib ON ib.id = b.batch_id
  WHERE b.id = p_bl_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_bl.financial_status, 'open') IN ('invoiced', 'partially_paid', 'paid') THEN
    RAISE EXCEPTION 'B/L % ja foi faturado (status financeiro=%); nao e permitido lancar taxa manual.',
      p_bl_id, v_bl.financial_status USING ERRCODE = '22023';
  END IF;

  SELECT
    cti.id,
    cti.name,
    COALESCE(cti.currency, 'BRL') AS currency,
    cti.unit_value_brl,
    cti.unit_value_usd,
    cti.value_brl,
    ct.id AS charge_table_id,
    ct.name AS charge_table_name,
    ct.cargo_mode,
    ct.pod,
    cro.override_value
  INTO v_item
  FROM public.charge_table_items AS cti
  JOIN public.charge_tables AS ct
    ON ct.id = cti.charge_table_id
   AND ct.active = true
   AND ct.cargo_mode = v_bl.cargo_mode
   AND (
     public.normalize_port_code(ct.pod) = public.normalize_port_code(v_bl.pod)
     OR UPPER(TRIM(COALESCE(ct.pod, ''))) = 'ANY'
   )
   AND ct.valid_from <= v_bl.reference_date
   AND (ct.valid_to IS NULL OR ct.valid_to >= v_bl.reference_date)
  LEFT JOIN LATERAL (
    SELECT cro.override_value
    FROM public.customer_rate_overrides AS cro
    WHERE cro.customer_id = v_bl.customer_id
      AND cro.charge_item_id = cti.id
      AND (cro.valid_from IS NULL OR cro.valid_from <= v_bl.reference_date)
      AND (cro.valid_to IS NULL OR cro.valid_to >= v_bl.reference_date)
    ORDER BY cro.created_at DESC
    LIMIT 1
  ) AS cro ON TRUE
  WHERE cti.id = p_charge_item_id
    AND COALESCE(cti.active, true) = true
    AND COALESCE(cti.manual_only, false) = true;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item manual % nao elegivel para este B/L', p_charge_item_id USING ERRCODE = '22023';
  END IF;

  v_qty := COALESCE(p_quantity, 1);
  IF v_qty <= 0 THEN
    RAISE EXCEPTION 'Quantidade deve ser maior que zero' USING ERRCODE = '22023';
  END IF;

  IF v_item.currency = 'USD' THEN
    v_unit_brl := NULL;
    v_unit_usd := COALESCE(v_item.override_value, v_item.unit_value_usd, 0);
    v_total_brl := NULL;
    v_total_usd := ROUND(v_qty * COALESCE(v_unit_usd, 0), 2);
  ELSE
    v_unit_brl := COALESCE(v_item.override_value, v_item.unit_value_brl, v_item.value_brl, 0);
    v_unit_usd := NULL;
    v_total_brl := ROUND(v_qty * COALESCE(v_unit_brl, 0), 2);
    v_total_usd := NULL;
  END IF;

  v_key := CONCAT(
    'manual:item:', p_charge_item_id, ':',
    EXTRACT(EPOCH FROM clock_timestamp())::BIGINT, ':',
    FLOOR(RANDOM() * 100000)::INT
  );

  INSERT INTO public.charge_calculations (
    bl_id,
    charge_table_id,
    charge_item_id,
    quantity,
    unit_value_brl,
    unit_value_usd,
    total_value_brl,
    total_value_usd,
    override_applied,
    source,
    status,
    calculation_key,
    notes,
    manual_reason,
    created_by,
    calculated_at
  )
  VALUES (
    p_bl_id,
    v_item.charge_table_id,
    p_charge_item_id,
    v_qty,
    v_unit_brl,
    v_unit_usd,
    v_total_brl,
    v_total_usd,
    v_item.override_value IS NOT NULL,
    'manual',
    'reviewed',
    v_key,
    NULLIF(TRIM(COALESCE(p_notes, '')), ''),
    'other_charge_manual',
    v_actor,
    NOW()
  )
  RETURNING id INTO v_calc_id;

  UPDATE public.bls
  SET
    charge_status = CASE
      WHEN charge_status IN ('not_calculated', 'exempt') THEN 'reviewed'
      ELSE charge_status
    END,
    charges_calculated_at = COALESCE(charges_calculated_at, NOW()),
    charges_reviewed_at = CASE
      WHEN charge_status IN ('not_calculated', 'exempt') THEN NOW()
      ELSE charges_reviewed_at
    END
  WHERE id = p_bl_id;

  INSERT INTO public.audit_logs (
    entity_type,
    entity_id,
    field_name,
    old_value,
    new_value,
    changed_by,
    changed_at,
    justification
  )
  VALUES (
    'charge_calculation',
    v_calc_id::TEXT,
    'manual_insert',
    NULL,
    CONCAT(v_item.name, ' | qty=', v_qty, ' | total=', COALESCE(v_total_brl::TEXT, v_total_usd::TEXT)),
    auth.uid(),
    NOW(),
    COALESCE(NULLIF(TRIM(COALESCE(p_notes, '')), ''), 'Lancamento manual de other charge')
  );

  RETURN jsonb_build_object(
    'id', v_calc_id,
    'bl_id', p_bl_id,
    'status', 'reviewed',
    'currency', v_item.currency,
    'quantity', v_qty,
    'unit_value_brl', v_unit_brl,
    'unit_value_usd', v_unit_usd,
    'total_value_brl', v_total_brl,
    'total_value_usd', v_total_usd
  );
END;
$$;



--
-- Name: add_manual_invoice_charge(bigint, text, numeric, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_manual_invoice_charge(p_invoice_id bigint, p_description text, p_quantity numeric, p_unit_value_brl numeric, p_notes text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice RECORD;
  v_actor UUID;
  v_desc TEXT;
  v_qty NUMERIC;
  v_unit NUMERIC;
  v_total NUMERIC;
  v_item_id BIGINT;
  v_payment_count INTEGER;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  v_desc := NULLIF(TRIM(COALESCE(p_description, '')), '');
  IF v_desc IS NULL THEN
    RAISE EXCEPTION 'Descricao do item e obrigatoria.' USING ERRCODE = '22023';
  END IF;

  v_qty := COALESCE(p_quantity, 0);
  v_unit := COALESCE(p_unit_value_brl, 0);
  IF v_qty <= 0 THEN
    RAISE EXCEPTION 'Quantidade deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;
  IF v_unit <= 0 THEN
    RAISE EXCEPTION 'Valor unitario deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;
  v_total := ROUND(v_qty * v_unit, 2);

  SELECT * INTO v_invoice FROM public.invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % nao encontrada.', p_invoice_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_invoice.invoice_type, 'individual') = 'consolidated' THEN
    RAISE EXCEPTION 'Nao e permitido adicionar itens manuais em fatura consolidada.' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_invoice.status, 'issued') NOT IN ('issued', 'overdue', 'draft') THEN
    RAISE EXCEPTION 'So e permitido adicionar itens em faturas em aberto (status atual: %).',
      COALESCE(v_invoice.status, 'issued') USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_payment_count FROM public.payments WHERE invoice_id = p_invoice_id;
  IF v_payment_count > 0 THEN
    RAISE EXCEPTION 'Nao e permitido adicionar itens em fatura com pagamentos registrados.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.invoice_items (
    invoice_id, description, quantity, unit_value_brl, total_value_brl, source, currency, snapshot_payload
  )
  VALUES (
    p_invoice_id, v_desc, v_qty, v_unit, v_total, 'manual', 'BRL',
    jsonb_build_object(
      'manual', true,
      'notes', NULLIF(TRIM(COALESCE(p_notes, '')), ''),
      'added_by', v_actor,
      'added_at', now()
    )
  )
  RETURNING id INTO v_item_id;

  UPDATE public.invoices
  SET
    total_brl = COALESCE(total_brl, 0) + v_total,
    balance_brl = GREATEST(COALESCE(total_brl, 0) + v_total - COALESCE(total_paid_brl, 0), 0),
    pix_payload = NULL
  WHERE id = p_invoice_id;

  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES (
    'invoice', p_invoice_id::text, 'manual_charge_added',
    NULL, format('%s: %s x %s = %s BRL', v_desc, v_qty, v_unit, v_total), v_actor,
    NULLIF(TRIM(COALESCE(p_notes, '')), '')
  );

  RETURN jsonb_build_object('invoice_id', p_invoice_id, 'item_id', v_item_id, 'total_value_brl', v_total);
END;
$$;



--
-- Name: admin_list_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_list_users() RETURNS TABLE(id uuid, full_name text, role text, active boolean, created_at timestamp with time zone, email text, last_sign_in_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Apenas administradores podem listar usuários.'
      USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
    SELECT
      p.id,
      p.full_name,
      p.role,
      p.active,
      p.created_at,
      u.email::TEXT,
      u.last_sign_in_at
    FROM public.user_profiles p
    LEFT JOIN auth.users u ON u.id = p.id
    ORDER BY p.full_name;
END;
$$;



--
-- Name: agency_report_alert_entity_id(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agency_report_alert_entity_id(p_voyage_id bigint, p_port text, p_terminal_code text, p_subject text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT public.agency_report_alert_entity_prefix(p_voyage_id, p_port, p_terminal_code) || p_subject;
$$;



--
-- Name: agency_report_alert_entity_key(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agency_report_alert_entity_key(p_voyage_id bigint, p_port text, p_terminal_code text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_voyage_id::TEXT || '::' || upper(btrim(p_port)) ||
    CASE
      WHEN NULLIF(btrim(COALESCE(p_terminal_code, '')), '') IS NULL THEN ''
      ELSE '::' || btrim(p_terminal_code)
    END;
$$;



--
-- Name: agency_report_alert_entity_prefix(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agency_report_alert_entity_prefix(p_voyage_id bigint, p_port text, p_terminal_code text DEFAULT NULL::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT p_voyage_id::TEXT || '::' || upper(btrim(p_port)) ||
    CASE
      WHEN NULLIF(btrim(COALESCE(p_terminal_code, '')), '') IS NULL THEN '::'
      ELSE '::' || btrim(p_terminal_code) || '::'
    END;
$$;



--
-- Name: agency_report_deadline_date(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agency_report_deadline_date(p_atd date) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_cursor DATE;
  v_business_days_added INTEGER := 0;
BEGIN
  IF p_atd IS NULL THEN
    RETURN NULL;
  END IF;

  v_cursor := p_atd;
  WHILE v_business_days_added < 3 LOOP
    v_cursor := v_cursor + 1;
    -- ISODOW: 1=segunda .. 5=sexta, 6=sabado, 7=domingo.
    IF EXTRACT(ISODOW FROM v_cursor) < 6 THEN
      v_business_days_added := v_business_days_added + 1;
    END IF;
  END LOOP;

  RETURN v_cursor;
END;
$$;



--
-- Name: agency_report_department_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agency_report_department_label(p_department text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_department
    WHEN 'operacoes' THEN 'Operações'
    WHEN 'documentacao' THEN 'Documentação'
    WHEN 'equipamentos' THEN 'Equipamentos'
    ELSE COALESCE(p_department, '—')
  END;
$$;



--
-- Name: agency_report_reject_closed_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agency_report_reject_closed_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_status TEXT;
BEGIN
  -- FOR SHARE serializa o sign-off/ocorrencia com o UPDATE de fechamento:
  -- quem entrou antes do fechamento termina primeiro; quem entra depois ve o
  -- relatorio fechado e nao consegue alterar o snapshot ja congelado.
  SELECT status INTO v_status
  FROM public.agency_departure_reports
  WHERE id = NEW.report_id
  FOR SHARE;

  IF v_status = 'closed' THEN
    RAISE EXCEPTION 'ADR fechado: reabra antes de alterar seus dados.' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: agency_report_section_label(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agency_report_section_label(p_section text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_section
    WHEN 'datas' THEN 'Escala'
    WHEN 'carga_descarregada' THEN 'Carga descarregada'
    WHEN 'carga_carregada' THEN 'Granito'
    WHEN 'veiculos' THEN 'Veículos'
    WHEN 'vazios_embarcados' THEN 'Embarque de vazios'
    WHEN 'vazios_descarregados' THEN 'Vazios descarregados'
    WHEN 'operacao_patio' THEN 'Operação de pátio'
    WHEN 'ocorrencias' THEN 'Ocorrências'
    ELSE p_section
  END;
$$;



--
-- Name: agency_report_section_owner(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.agency_report_section_owner(p_section text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE p_section
    WHEN 'datas' THEN 'operacoes'
    WHEN 'veiculos' THEN 'equipamentos'
    WHEN 'carga_carregada' THEN 'equipamentos'
    WHEN 'vazios_embarcados' THEN 'equipamentos'
    WHEN 'carga_descarregada' THEN 'documentacao'
    WHEN 'vazios_descarregados' THEN 'documentacao'
    ELSE NULL
  END;
$$;



--
-- Name: alert_actor_is_authorized(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.alert_actor_is_authorized() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT auth.role() IS NOT DISTINCT FROM 'service_role'
    OR (pg_trigger_depth() > 0 AND current_setting('alerts.foundation_trigger', true) = 'on')
    OR (auth.uid() IS NOT NULL AND public.is_active_user());
$$;



--
-- Name: apply_bl_review_gate_after_import(text[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_bl_review_gate_after_import(p_bl_ids text[], p_changed_by uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl RECORD;
  v_reason TEXT;
  v_reasons TEXT[];
  v_notes TEXT;
  v_changed INTEGER := 0;
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.is_active_user()
     OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para aplicar gate de importacao.'
      USING ERRCODE = '42501';
  END IF;

  IF COALESCE(cardinality(p_bl_ids), 0) = 0 THEN
    RETURN 0;
  END IF;

  -- Captura do contato do manifesto na importacao. A regra e a mesma funcao
  -- unica da 370, chamada tambem pela Revisao e pelo Aprovar da Validacao.
  --
  -- Roda ANTES do laco de pendencias, e nao dentro dele, porque o laco faz
  -- CONTINUE quando o B/L nao tem pendencia nenhuma — que e exatamente o caso
  -- do B/L auto-vinculado por CNPJ (`matched_document`), o que mais precisa
  -- desta captura: ninguem abre a Revisao para ele, entao esta e a unica
  -- oportunidade de registrar o contato.
  --
  -- DISTINCT porque um manifesto traz varios B/Ls do mesmo cliente com o mesmo
  -- e-mail: sem ele, as chamadas da mesma instrucao nao enxergam a linha que a
  -- anterior acabou de inserir e o NOT EXISTS interno deixaria passar duplicata.
  PERFORM public.capture_manifest_financial_contact(alvo.customer_id, alvo.email)
  FROM (
    SELECT DISTINCT b.customer_id, lower(btrim(b.manifest_customer_email)) AS email
    FROM public.bls AS b
    WHERE b.id = ANY(p_bl_ids)
      AND b.customer_id IS NOT NULL
      AND NULLIF(btrim(COALESCE(b.manifest_customer_email, '')), '') IS NOT NULL
  ) AS alvo;

  FOR v_bl IN
    SELECT b.id, b.review_status, b.notes, b.financial_status
    FROM public.bls b
    WHERE b.id = ANY(p_bl_ids)
    ORDER BY b.id
  LOOP
    IF v_bl.financial_status = 'invoiced'
       OR EXISTS (
         SELECT 1
         FROM public.invoice_bls ib
         JOIN public.invoices i ON i.id = ib.invoice_id
         WHERE ib.bl_id = v_bl.id
           AND i.status NOT IN ('cancelled', 'obsolete')
       ) THEN
      CONTINUE;
    END IF;

    v_reasons := public.compute_bl_review_pendencies(v_bl.id);
    IF COALESCE(cardinality(v_reasons), 0) = 0 THEN
      CONTINUE;
    END IF;

    v_notes := v_bl.notes;
    FOREACH v_reason IN ARRAY v_reasons
    LOOP
      IF COALESCE(v_notes, '') NOT ILIKE '%' || v_reason || '%' THEN
        IF COALESCE(v_notes, '') ILIKE '%Pendencias de importacao:%' THEN
          v_notes := v_notes || ', ' || v_reason;
        ELSE
          v_notes := concat_ws(
            E'\n',
            NULLIF(btrim(COALESCE(v_notes, '')), ''),
            'Pendencias de importacao: ' || v_reason
          );
        END IF;
      END IF;
    END LOOP;

    UPDATE public.bls
    SET
      review_status = 'pending_review',
      notes = v_notes
    WHERE id = v_bl.id;

    IF v_bl.review_status IS DISTINCT FROM 'pending_review' THEN
      INSERT INTO public.audit_logs (
        entity_type,
        entity_id,
        field_name,
        old_value,
        new_value,
        changed_by,
        justification
      )
      VALUES (
        'bl',
        v_bl.id,
        'review_status',
        v_bl.review_status,
        'pending_review',
        p_changed_by,
        'Gate canonico aplicado apos importacao'
      );
    END IF;

    PERFORM public.sync_customer_reconciliation_queue_for_bl(v_bl.id);
    v_changed := v_changed + 1;
  END LOOP;

  RETURN v_changed;
END;
$$;



--
-- Name: apply_ce_mercante_manifest(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_ce_mercante_manifest(p_rows jsonb, p_changed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_errors JSONB := '[]'::JSONB;
  v_part JSONB;
  v_batches BIGINT[];
  v_batch_id BIGINT;
  v_inserted INT := 0;
  v_overwritten INT := 0;
  v_unchanged INT := 0;
  v_old_ce TEXT;
  r RECORD;
BEGIN
  IF p_rows IS NULL OR jsonb_typeof(p_rows) <> 'array' OR jsonb_array_length(p_rows) = 0 THEN
    RAISE EXCEPTION 'Nenhum registro de CE Mercante informado' USING ERRCODE = '22023';
  END IF;

  -- 1) BL repetido no arquivo (mais de um CE para o mesmo BL).
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'bl_id', d.bl_id,
           'message', 'BL ' || d.bl_id || ' repetido no arquivo (mais de um CE).')), '[]'::JSONB)
    INTO v_part
  FROM (
    SELECT bl_id
    FROM jsonb_to_recordset(p_rows) AS t(bl_id TEXT, ce TEXT)
    GROUP BY bl_id HAVING count(*) > 1
  ) d;
  v_errors := v_errors || v_part;

  -- 2) CE repetido no arquivo.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'ce', d.ce,
           'message', 'CE Mercante ' || d.ce || ' duplicado no arquivo.')), '[]'::JSONB)
    INTO v_part
  FROM (
    SELECT ce
    FROM jsonb_to_recordset(p_rows) AS t(bl_id TEXT, ce TEXT)
    GROUP BY ce HAVING count(*) > 1
  ) d;
  v_errors := v_errors || v_part;

  -- 3) CE Mercante deve ter exatamente 15 digitos.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'bl_id', t.bl_id,
           'message', 'CE Mercante invalido para o BL ' || t.bl_id || ': esperado 15 digitos.')), '[]'::JSONB)
    INTO v_part
  FROM jsonb_to_recordset(p_rows) AS t(bl_id TEXT, ce TEXT)
  WHERE t.ce !~ '^[0-9]{15}$';
  v_errors := v_errors || v_part;

  -- 4) BL inexistente no sistema.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'bl_id', f.bl_id,
           'message', 'BL ' || f.bl_id || ' nao encontrado no sistema.')), '[]'::JSONB)
    INTO v_part
  FROM (SELECT DISTINCT bl_id FROM jsonb_to_recordset(p_rows) AS t(bl_id TEXT, ce TEXT)) f
  LEFT JOIN public.bls b ON b.id = f.bl_id
  WHERE b.id IS NULL;
  v_errors := v_errors || v_part;

  -- Erros estruturais/existencia abortam antes da analise de manifesto.
  IF jsonb_array_length(v_errors) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'errors', v_errors);
  END IF;

  -- 5) Deriva o manifesto: todos os BLs devem pertencer a um unico batch nao-nulo.
  SELECT array_agg(DISTINCT b.batch_id)
    INTO v_batches
  FROM (SELECT DISTINCT bl_id FROM jsonb_to_recordset(p_rows) AS t(bl_id TEXT, ce TEXT)) f
  JOIN public.bls b ON b.id = f.bl_id;

  IF array_length(v_batches, 1) > 1 OR v_batches[1] IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'errors', jsonb_build_array(
      jsonb_build_object('message',
        'Os BLs do arquivo nao pertencem a um unico manifesto (batch). Verifique se o arquivo corresponde a um unico manifesto importado.')));
  END IF;

  v_batch_id := v_batches[1];

  -- 6) Cobertura quantitativa: todo BL do manifesto deve estar no arquivo.
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'bl_id', b.id,
           'message', 'BL ' || b.id || ' pertence ao manifesto mas nao possui CE no arquivo.')), '[]'::JSONB)
    INTO v_part
  FROM public.bls b
  WHERE b.batch_id = v_batch_id
    AND NOT EXISTS (
      SELECT 1 FROM jsonb_to_recordset(p_rows) AS t(bl_id TEXT, ce TEXT)
      WHERE t.bl_id = b.id
    );
  v_errors := v_errors || v_part;

  IF jsonb_array_length(v_errors) > 0 THEN
    RETURN jsonb_build_object('ok', false, 'errors', v_errors);
  END IF;

  -- 7) Aplica (atomico). Qualquer excecao reverte tudo.
  FOR r IN
    SELECT bl_id, ce FROM jsonb_to_recordset(p_rows) AS t(bl_id TEXT, ce TEXT)
  LOOP
    SELECT ce_mercante INTO v_old_ce FROM public.bls WHERE id = r.bl_id FOR UPDATE;

    IF COALESCE(v_old_ce, '') = COALESCE(r.ce, '') THEN
      v_unchanged := v_unchanged + 1;
      CONTINUE;
    END IF;

    UPDATE public.bls SET ce_mercante = r.ce WHERE id = r.bl_id;

    INSERT INTO public.audit_logs(
      entity_type, entity_id, field_name, old_value, new_value, changed_by, justification
    ) VALUES (
      'bl', r.bl_id, 'ce_mercante',
      COALESCE(v_old_ce, ''), COALESCE(r.ce, ''),
      p_changed_by,
      'Importacao CE Mercante (EDI)'
    );

    IF v_old_ce IS NOT NULL AND v_old_ce <> '' THEN
      v_overwritten := v_overwritten + 1;
    ELSE
      v_inserted := v_inserted + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'batch_id', v_batch_id,
    'processed', jsonb_array_length(p_rows),
    'inserted', v_inserted,
    'overwritten', v_overwritten,
    'unchanged', v_unchanged
  );
END;
$_$;



--
-- Name: apply_ce_mercante_update(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_ce_mercante_update(p_bl_id text, p_new_ce text, p_changed_by uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old_ce TEXT;
  v_exists BOOLEAN;
BEGIN
  SELECT ce_mercante, TRUE INTO v_old_ce, v_exists FROM public.bls WHERE id = p_bl_id FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BL % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_old_ce, '') = COALESCE(p_new_ce, '') THEN
    RETURN 'unchanged';
  END IF;

  UPDATE public.bls SET ce_mercante = p_new_ce WHERE id = p_bl_id;

  INSERT INTO public.audit_logs(
    entity_type, entity_id, field_name, old_value, new_value, changed_by, justification
  ) VALUES (
    'bl', p_bl_id, 'ce_mercante',
    COALESCE(v_old_ce, ''), COALESCE(p_new_ce, ''),
    p_changed_by,
    'Importacao CE Mercante'
  );

  IF v_old_ce IS NOT NULL AND v_old_ce <> '' THEN
    RETURN 'overwritten';
  END IF;
  RETURN 'inserted';
END;
$$;



--
-- Name: apply_cod_financial_effect(text, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_cod_financial_effect(p_bl_id text, p_omission_id bigint, p_previous_pod text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_bl RECORD;
  v_invoice_id BIGINT;
  v_invoice_snapshot_total NUMERIC(14,2) := 0;
  v_invoice_snapshot_count INTEGER := 0;
  v_previous_adjustment_total NUMERIC(14,2) := 0;
  v_previous_adjustment_count INTEGER := 0;
  v_original_total NUMERIC(14,2) := 0;
  v_new_total NUMERIC(14,2) := 0;
  v_manual_total NUMERIC(14,2) := 0;
  v_paid_amount NUMERIC(14,2) := 0;
  v_outstanding NUMERIC(14,2) := 0;
  v_difference NUMERIC(14,2) := 0;
  v_offset_amount NUMERIC(14,2) := 0;
  v_refund_amount NUMERIC(14,2) := 0;
  v_action TEXT;
  v_manual_review BOOLEAN := false;
  v_has_manual_lines BOOLEAN := false;
  v_roe NUMERIC(10,4);
  v_roe_effective_date DATE;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa.' USING ERRCODE = '42501';
  END IF;

  SELECT b.id, b.pod, b.financial_status
  INTO v_bl
  FROM public.bls AS b
  WHERE b.id = p_bl_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  SELECT roe, effective_date
  INTO v_roe, v_roe_effective_date
  FROM public.exchange_rate_reference
  WHERE id = 1;

  IF v_roe IS NULL AND EXISTS (
    SELECT 1
    FROM public.charge_calculations AS cc
    WHERE cc.bl_id = p_bl_id
      AND COALESCE(cc.total_value_usd, 0) > 0
  ) THEN
    RAISE EXCEPTION 'Cambio (ROE) nao configurado; nao e possivel calcular linhas em USD.'
      USING ERRCODE = '22023';
  END IF;

  SELECT
    COALESCE(SUM(COALESCE(cc.total_value_brl,
      CASE WHEN COALESCE(cc.total_value_usd, 0) > 0
        THEN ROUND(cc.total_value_usd * v_roe, 2)
      END,
      0)), 0),
    BOOL_OR(COALESCE(cc.source, 'auto') = 'manual')
  INTO v_original_total, v_has_manual_lines
  FROM public.charge_calculations AS cc
  WHERE cc.bl_id = p_bl_id;

  v_original_total := ROUND(COALESCE(v_original_total, 0), 2);
  v_has_manual_lines := COALESCE(v_has_manual_lines, false);

  SELECT COALESCE(SUM(COALESCE(cc.total_value_brl,
    CASE WHEN COALESCE(cc.total_value_usd, 0) > 0
      THEN ROUND(cc.total_value_usd * v_roe, 2)
    END,
    0)), 0)
  INTO v_manual_total
  FROM public.charge_calculations AS cc
  WHERE cc.bl_id = p_bl_id
    AND COALESCE(cc.source, 'auto') = 'manual';
  v_manual_total := ROUND(COALESCE(v_manual_total, 0), 2);

  -- Pending/non-invoiced B/Ls use the existing writing calculator. Manual
  -- rows are source = manual, so calculate_bl_local_charges deletes only auto
  -- rows and preserves their operator-entered intent.
  IF COALESCE(v_bl.financial_status, 'pending') NOT IN ('invoiced', 'partially_paid', 'paid') THEN
    PERFORM public.calculate_bl_local_charges(
      p_bl_id => p_bl_id,
      p_actor => v_actor,
      p_recalculate => true
    );

    IF v_has_manual_lines THEN
      SELECT COALESCE(SUM(COALESCE(cc.total_value_brl, 0)), 0)
      INTO v_new_total
      FROM public.charge_calculations AS cc
      WHERE cc.bl_id = p_bl_id;
      v_new_total := ROUND(COALESCE(v_new_total, 0), 2);
      v_difference := ROUND(v_new_total - v_original_total, 2);
      v_action := 'manual_charge_review';
      v_manual_review := true;
    ELSE
      RETURN;
    END IF;
  ELSE
    -- Billed states must never call the writing calculator: it intentionally
    -- rejects these states. The 311 helper is the single price-resolution
    -- source for both the previous and already-updated destination PODs.
    -- A ponta nova é uma prévia do destino atual. Linhas em USD precisam do
    -- ROE autoritativo do evento; total_value_brl é nulo nessas linhas.
    SELECT roe, effective_date
    INTO v_roe, v_roe_effective_date
    FROM public.exchange_rate_reference
    WHERE id = 1;

    IF v_roe IS NULL AND EXISTS (
      SELECT 1
      FROM public.resolve_bl_local_charge_items(p_bl_id, v_bl.pod) AS item
      WHERE COALESCE(item.total_value_usd, 0) > 0
    ) THEN
      RAISE EXCEPTION 'Cambio (ROE) nao configurado; nao e possivel reprecificar linhas em USD.'
        USING ERRCODE = '22023';
    END IF;

    SELECT COALESCE(SUM(
      COALESCE(item.total_value_brl,
        CASE WHEN COALESCE(item.total_value_usd, 0) > 0
          THEN ROUND(item.total_value_usd * v_roe, 2)
        END,
        0)
    ), 0)
    INTO v_new_total
    FROM public.resolve_bl_local_charge_items(p_bl_id, v_bl.pod) AS item;
    v_new_total := ROUND(COALESCE(v_new_total, 0) + v_manual_total, 2);

    -- A ponta original não é a tabela vigente do POD antigo. O documento que
    -- efetivamente faturou o B/L (invoice_bls, inclusive consolidadas) é o
    -- snapshot monetário; invoice_items/invoices são fallbacks legados.
    SELECT i.id
    INTO v_invoice_id
    FROM public.invoices AS i
    WHERE COALESCE(i.status, 'issued') NOT IN ('cancelled', 'obsolete', 'covered')
      AND (i.bl_id = p_bl_id OR EXISTS (
        SELECT 1 FROM public.invoice_bls AS ib
        WHERE ib.invoice_id = i.id AND ib.bl_id = p_bl_id
      ))
    ORDER BY i.issued_at DESC NULLS LAST, i.id DESC
    LIMIT 1;

    IF v_invoice_id IS NOT NULL THEN
      SELECT COALESCE(SUM(ib.subtotal_brl), 0), COUNT(*)
      INTO v_invoice_snapshot_total, v_invoice_snapshot_count
      FROM public.invoice_bls AS ib
      WHERE ib.invoice_id = v_invoice_id AND ib.bl_id = p_bl_id;

      IF v_invoice_snapshot_count = 0 THEN
        SELECT COALESCE(SUM(COALESCE(
          ii.total_value_brl,
          CASE WHEN COALESCE(ii.total_value_usd, 0) > 0
            THEN ROUND(ii.total_value_usd * NULLIF(ii.snapshot_payload->>'roe', '')::NUMERIC, 2)
          END,
          0
        )), 0), COUNT(*)
        INTO v_invoice_snapshot_total, v_invoice_snapshot_count
        FROM public.invoice_items AS ii
        WHERE ii.invoice_id = v_invoice_id AND ii.bl_id = p_bl_id;
      END IF;

      IF v_invoice_snapshot_count = 0 THEN
        SELECT COALESCE(i.total_brl, 0), 1
        INTO v_invoice_snapshot_total, v_invoice_snapshot_count
        FROM public.invoices AS i
        WHERE i.id = v_invoice_id;
      END IF;
    END IF;

    IF v_invoice_snapshot_count = 0 THEN
      RAISE EXCEPTION 'Nao foi encontrado snapshot da fatura do B/L %.', p_bl_id
        USING ERRCODE = 'P0002';
    END IF;
    v_original_total := ROUND(COALESCE(v_invoice_snapshot_total, 0), 2);

    -- Em uma reversão COD → transbordo (ou nova ida ao COD), a comparação é
    -- contra o último destino efetivamente registrado, para que cada
    -- transição gere seu próprio evento mesmo quando o snapshot original da
    -- invoice permanece imutável.
    SELECT new_destination_value_brl, 1
    INTO v_previous_adjustment_total, v_previous_adjustment_count
    FROM public.cod_adjustments
    WHERE bl_id = p_bl_id AND omission_id = p_omission_id
    ORDER BY id DESC
    LIMIT 1;
    IF v_previous_adjustment_count > 0 THEN
      v_original_total := ROUND(v_previous_adjustment_total, 2);
    END IF;

    SELECT COALESCE(SUM(
      CASE
        WHEN ib.invoice_id IS NOT NULL
          AND COALESCE(i.total_brl, 0) > 0
          AND EXISTS (
            SELECT 1
            FROM public.invoice_bls AS ib_other
            WHERE ib_other.invoice_id = i.id
              AND ib_other.bl_id <> p_bl_id
          )
        THEN p.amount_brl * COALESCE(ib.subtotal_brl, 0) / i.total_brl
        ELSE p.amount_brl
      END
    ), 0)
    INTO v_paid_amount
    FROM public.payments AS p
    JOIN public.invoices AS i ON i.id = p.invoice_id
    LEFT JOIN public.invoice_bls AS ib
      ON ib.invoice_id = i.id AND ib.bl_id = p_bl_id
    WHERE COALESCE(i.status, 'issued') <> 'cancelled'
      AND (i.bl_id = p_bl_id OR ib.bl_id = p_bl_id);
    v_paid_amount := ROUND(GREATEST(COALESCE(v_paid_amount, 0), 0), 2);
    IF v_paid_amount = 0 THEN
      SELECT COALESCE(SUM(COALESCE(i.total_paid_brl, 0)), 0)
      INTO v_paid_amount
      FROM public.invoices AS i
      WHERE i.bl_id = p_bl_id
        AND COALESCE(i.status, 'issued') <> 'cancelled';
      v_paid_amount := ROUND(GREATEST(COALESCE(v_paid_amount, 0), 0), 2);
    END IF;
    v_outstanding := ROUND(GREATEST(v_original_total - v_paid_amount, 0), 2);
    v_difference := ROUND(v_new_total - v_original_total, 2);

    -- An unpaid invoice is the only cancel/reissue branch. A B/L remains
    -- financial_status = invoiced while its invoice is partially paid, so
    -- payment money—not only the coarse B/L status—selects the next branch.
    IF v_paid_amount = 0 THEN
      v_action := 'cancel_and_reissue';
      v_manual_review := true;
    ELSIF v_difference > 0 THEN
      v_action := 'complementary_invoice';
    ELSIF v_difference < 0 THEN
      v_offset_amount := ROUND(LEAST(ABS(v_difference), v_outstanding), 2);
      v_refund_amount := ROUND(GREATEST(ABS(v_difference) - v_outstanding, 0), 2);
      v_action := CASE
        WHEN v_refund_amount > 0 THEN 'refund_overpayment'
        ELSE 'offset_open_balance'
      END;
    ELSE
      RETURN;
    END IF;
  END IF;

  INSERT INTO public.cod_adjustments (
    bl_id,
    omission_id,
    original_value_brl,
    new_destination_value_brl,
    difference_brl,
    paid_amount_brl,
    outstanding_balance_brl,
    offset_amount_brl,
    refund_amount_brl,
    action,
    status,
    manual_review_required,
    resulting_document_id,
    resulting_document_type,
    created_by
  )
  VALUES (
    p_bl_id,
    p_omission_id,
    ROUND(v_original_total, 2),
    ROUND(v_new_total, 2),
    ROUND(v_difference, 2),
    ROUND(v_paid_amount, 2),
    ROUND(v_outstanding, 2),
    ROUND(v_offset_amount, 2),
    ROUND(v_refund_amount, 2),
    v_action,
    'pending',
    v_manual_review,
    NULL,
    NULL,
    v_actor
  )
  ;
END;
$$;



--
-- Name: apply_cod_open_balance_offset(bigint, text, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_cod_open_balance_offset(p_invoice_id bigint, p_bl_id text, p_amount numeric, p_actor uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_remaining NUMERIC(14,2) := ROUND(GREATEST(COALESCE(p_amount, 0), 0), 2);
  v_applied NUMERIC(14,2) := 0;
  v_amount NUMERIC(14,2);
  v_link RECORD;
BEGIN
  IF v_remaining <= 0 THEN
    RETURN 0;
  END IF;

  FOR v_link IN
    SELECT br.id, br.balance_brl, br.original_amount_brl, br.settled_amount_brl
    FROM public.invoice_receivable_links AS irl
    JOIN public.bl_receivables AS br ON br.id = irl.receivable_id
    WHERE irl.invoice_id = p_invoice_id
      AND irl.bl_id = p_bl_id
      AND irl.status IN ('active', 'settled_by_this_invoice')
      AND br.balance_brl > 0
    ORDER BY br.id
    FOR UPDATE OF br
  LOOP
    EXIT WHEN v_remaining <= 0;
    v_amount := ROUND(LEAST(v_remaining, COALESCE(v_link.balance_brl, 0)), 2);
    IF v_amount <= 0 THEN CONTINUE; END IF;

    UPDATE public.bl_receivables
    SET balance_brl = GREATEST(balance_brl - v_amount, 0),
        status = CASE WHEN GREATEST(balance_brl - v_amount, 0) <= 0.01
          THEN 'settled' ELSE 'partially_settled' END,
        updated_at = now()
    WHERE id = v_link.id;

    v_remaining := ROUND(v_remaining - v_amount, 2);
    v_applied := ROUND(v_applied + v_amount, 2);
  END LOOP;

  -- Faturas legadas podem não ter receivable vinculado; ainda assim a
  -- liquidação deve reduzir o saldo visível do documento.
  IF v_remaining > 0 THEN
    v_applied := ROUND(v_applied + v_remaining, 2);
  END IF;

  UPDATE public.invoices AS i
  -- O total bruto continua sendo o documento emitido; o crédito de COD só
  -- reduz o saldo a cobrar. A diferença fica auditada em cod_adjustments.
  SET balance_brl = GREATEST(COALESCE(i.balance_brl, i.total_brl) - v_applied, 0),
      status = CASE
        WHEN GREATEST(COALESCE(i.balance_brl, i.total_brl) - v_applied, 0) <= 0.01
          THEN 'paid'
        WHEN i.status = 'paid' THEN 'partially_paid'
        ELSE i.status
      END
  WHERE i.id = p_invoice_id;

  INSERT INTO public.audit_logs (
    entity_type, entity_id, field_name, old_value, new_value, changed_by,
    changed_at, justification
  ) VALUES (
    'invoice', p_invoice_id::TEXT, 'cod_offset', NULL, v_applied::TEXT,
    p_actor, now(), 'Abatimento de saldo aberto por ajuste de COD'
  );

  RETURN v_applied;
END;
$$;



--
-- Name: apply_granite_ce_mercante_update(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_granite_ce_mercante_update(p_bl_id uuid, p_new_ce text, p_changed_by uuid) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old_ce TEXT;
BEGIN
  SELECT ce_mercante INTO v_old_ce
  FROM public.granite_bls
  WHERE id = p_bl_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L Granito % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_old_ce, '') = COALESCE(p_new_ce, '') THEN
    RETURN 'unchanged';
  END IF;

  UPDATE public.granite_bls SET ce_mercante = p_new_ce WHERE id = p_bl_id;

  INSERT INTO public.audit_logs(
    entity_type, entity_id, field_name, old_value, new_value, changed_by, justification
  ) VALUES (
    'granite_bl', p_bl_id::text, 'ce_mercante',
    COALESCE(v_old_ce, ''), COALESCE(p_new_ce, ''), p_changed_by,
    'Importacao CE Mercante'
  );

  IF v_old_ce IS NOT NULL AND v_old_ce <> '' THEN
    RETURN 'overwritten';
  END IF;
  RETURN 'inserted';
END;
$$;



--
-- Name: approve_customer_reconciliation(bigint, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_customer_reconciliation(p_queue_id bigint, p_customer_id bigint DEFAULT NULL::bigint, p_notes text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_queue RECORD;
  v_actor UUID;
  v_target_customer_id BIGINT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  SELECT * INTO v_queue
  FROM public.customer_reconciliation_queue
  WHERE id = p_queue_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item de reconciliacao % nao encontrado.', p_queue_id USING ERRCODE = 'P0002';
  END IF;

  v_target_customer_id := COALESCE(p_customer_id, v_queue.customer_id);
  IF v_target_customer_id IS NULL THEN
    RAISE EXCEPTION 'Informe um cliente para aprovar a reconciliacao.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.bls
  SET
    customer_id = v_target_customer_id,
    suggested_customer_id = NULL,
    customer_reconciliation_status = 'reconciled',
    customer_reconciliation_notes = COALESCE(NULLIF(TRIM(COALESCE(p_notes, '')), ''), 'Cliente reconciliado manualmente.'),
    billing_hold_reason = NULL
  WHERE id = v_queue.bl_id;

  UPDATE public.customer_reconciliation_queue
  SET
    customer_id = v_target_customer_id,
    status = 'approved',
    resolution_notes = COALESCE(NULLIF(TRIM(COALESCE(p_notes, '')), ''), 'Cliente reconciliado manualmente.'),
    approved_by = v_actor,
    approved_at = now(),
    rejected_by = NULL,
    rejected_at = NULL
  WHERE id = p_queue_id;

  -- A captura do contato do manifesto agora mora na funcao compartilhada: a
  -- Revisao (`save_bl_review`) precisa do mesmo efeito, e duas copias da regra
  -- divergiriam na primeira alteracao.
  PERFORM public.capture_manifest_financial_contact(
    v_target_customer_id,
    v_queue.manifest_customer_email
  );

  PERFORM public.sync_customer_reconciliation_queue_for_bl(v_queue.bl_id);

  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification)
  VALUES (
    'bl', v_queue.bl_id, 'customer_reconciliation_status', COALESCE(v_queue.status, 'pending'), 'reconciled',
    v_actor, now(), COALESCE(NULLIF(TRIM(COALESCE(p_notes, '')), ''), 'Cliente reconciliado manualmente.')
  );

  RETURN jsonb_build_object('queue_id', p_queue_id, 'bl_id', v_queue.bl_id, 'customer_id', v_target_customer_id, 'status', 'approved');
END;
$$;



--
-- Name: archive_vessel_schedule(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_vessel_schedule(p_vessel_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_vessel public.vessel_schedules%ROWTYPE;
  v_ended_id UUID;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao para encerrar navio.'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_vessel
  FROM public.vessel_schedules
  WHERE id = p_vessel_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Navio ativo nao encontrado.' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.ended_vessels (
    original_id,
    vessel_name,
    voyage,
    imo_number,
    qingdao_etd,
    shanghai_etd,
    taicang_etd,
    ningbo_etd,
    nansha_etd,
    salvador_eta,
    vitoria_eta,
    pecem_eta
  )
  VALUES (
    v_vessel.id,
    v_vessel.vessel_name,
    v_vessel.voyage,
    v_vessel.imo_number,
    v_vessel.qingdao_etd,
    v_vessel.shanghai_etd,
    v_vessel.taicang_etd,
    v_vessel.ningbo_etd,
    v_vessel.nansha_etd,
    v_vessel.salvador_eta,
    v_vessel.vitoria_eta,
    v_vessel.pecem_eta
  )
  RETURNING id INTO v_ended_id;

  DELETE FROM public.vessel_schedules
  WHERE id = p_vessel_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Navio ativo mudou durante o encerramento.'
      USING ERRCODE = '40001';
  END IF;

  RETURN jsonb_build_object('archived_id', v_ended_id);
END;
$$;



--
-- Name: assert_voyage_escala_ready_for_report_close(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_voyage_escala_ready_for_report_close(p_voyage_id bigint, p_port text, p_report_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_port TEXT := upper(btrim(COALESCE(p_port, '')));
  v_port_id BIGINT;
  v_report RECORD;
  v_terminal_code TEXT;
  v_terminal_tipo TEXT;
  v_terminal_port_id BIGINT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;

  SELECT p.id
  INTO v_port_id
  FROM public.ports AS p
  WHERE upper(btrim(p.locode)) = v_port
    AND upper(btrim(p.locode)) LIKE 'BR%'
  ORDER BY p.id
  LIMIT 1;
  IF v_port_id IS NULL THEN
    RAISE EXCEPTION 'Porto brasileiro % nao encontrado.', v_port USING ERRCODE = 'P0002';
  END IF;

  PERFORM 1 FROM public.voyages WHERE id = p_voyage_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Viagem nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  SELECT r.id, r.voyage_id, r.port, r.terminal_id, r.terminal_port_id
  INTO v_report
  FROM public.agency_departure_reports AS r
  WHERE r.id = p_report_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'report_id nao pertence a escala %::%.', p_voyage_id, v_port
      USING ERRCODE = '23514';
  END IF;
  IF v_report.voyage_id <> p_voyage_id
     OR upper(btrim(v_report.port)) <> v_port THEN
    RAISE EXCEPTION 'report_id nao pertence a escala %::%.', p_voyage_id, v_port
      USING ERRCODE = '23514';
  END IF;

  SELECT d.code, d.tipo, d.port_id
  INTO v_terminal_code, v_terminal_tipo, v_terminal_port_id
  FROM public.depots AS d
  WHERE d.id = v_report.terminal_id;
  IF v_report.terminal_id IS NULL OR v_report.terminal_port_id IS NULL THEN
    RAISE EXCEPTION 'report_id deve referenciar ADR terminalizado do porto %.', v_port
      USING ERRCODE = '23514';
  END IF;
  IF v_terminal_tipo IS DISTINCT FROM 'terminal_portuario'
     OR v_terminal_port_id IS DISTINCT FROM v_port_id
     OR v_report.terminal_port_id IS DISTINCT FROM v_port_id THEN
    RAISE EXCEPTION 'report_id deve referenciar ADR terminalizado do porto %.', v_port
      USING ERRCODE = '23514';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.voyage_escala_operation_fronts AS f
    WHERE f.voyage_id = p_voyage_id AND f.port = v_port AND f.terminal_id IS NULL
  ) THEN
    RAISE EXCEPTION 'Frente TBC impede o fechamento do ADR.'
      USING ERRCODE = '23514', DETAIL = 'Atribua todas as frentes a um terminal antes do fechamento.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.voyage_escala_operation_fronts AS f
    WHERE f.voyage_id = p_voyage_id AND f.port = v_port
      AND f.terminal_id = v_report.terminal_id
  ) THEN
    RAISE EXCEPTION 'ADR % nao corresponde a terminal atribuido na escala.', v_terminal_code
      USING ERRCODE = '23514';
  END IF;
END;
$$;



--
-- Name: assign_invoice_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_invoice_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  invoice_year INTEGER;
  next_number INTEGER;
BEGIN
  IF NEW.invoice_number IS NOT NULL AND NEW.invoice_number <> '' THEN
    RETURN NEW;
  END IF;

  invoice_year := EXTRACT(YEAR FROM COALESCE(NEW.issued_at, now()))::INTEGER;

  INSERT INTO public.invoice_counters(year, last_number)
  VALUES (invoice_year, 1)
  ON CONFLICT (year)
  DO UPDATE SET last_number = public.invoice_counters.last_number + 1
  RETURNING last_number INTO next_number;

  NEW.invoice_number := format('INV-%s-%s', invoice_year, lpad(next_number::TEXT, 4, '0'));
  RETURN NEW;
END;
$$;



--
-- Name: audit_row_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_row_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old JSONB := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE '{}'::jsonb END;
  v_new JSONB := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE '{}'::jsonb END;
  v_key_parts TEXT[] := string_to_array(COALESCE(TG_ARGV[0], 'id'), ',');
  v_entity_id TEXT;
  v_field RECORD;
BEGIN
  SELECT string_agg(COALESCE(v_new ->> k, v_old ->> k), '/')
    INTO v_entity_id
    FROM unnest(v_key_parts) AS k;

  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.audit_logs(entity_type, entity_id, field_name, new_value, changed_by)
    VALUES (TG_TABLE_NAME, v_entity_id, 'criado', v_new::TEXT, auth.uid());
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, changed_by)
    VALUES (TG_TABLE_NAME, v_entity_id, 'excluido', v_old::TEXT, auth.uid());
  ELSE
    FOR v_field IN
      SELECT key, value AS old_value, v_new ->> key AS new_value
      FROM jsonb_each_text(v_old)
      WHERE v_old ->> key IS DISTINCT FROM v_new ->> key
    LOOP
      INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, new_value, changed_by)
      VALUES (TG_TABLE_NAME, v_entity_id, v_field.key, v_field.old_value, v_field.new_value, auth.uid());
    END LOOP;
    FOR v_field IN
      SELECT key, value AS new_value
      FROM jsonb_each_text(v_new)
      WHERE NOT (v_old ? key)
    LOOP
      INSERT INTO public.audit_logs(entity_type, entity_id, field_name, new_value, changed_by)
      VALUES (TG_TABLE_NAME, v_entity_id, v_field.key, v_field.new_value, auth.uid());
    END LOOP;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;



--
-- Name: audit_user_profile_changes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.audit_user_profile_changes() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.role IS DISTINCT FROM OLD.role THEN
    INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by)
    VALUES ('user_profile', NEW.id::TEXT, 'role', OLD.role, NEW.role, auth.uid());
  END IF;

  IF NEW.active IS DISTINCT FROM OLD.active THEN
    INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by)
    VALUES ('user_profile', NEW.id::TEXT, 'active', OLD.active::TEXT, NEW.active::TEXT, auth.uid());
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: backfill_invoice_receivable_links(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_invoice_receivable_links(p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_inserted INTEGER := 0;
  v_missing_receivables INTEGER := 0;
  v_total_mismatches INTEGER := 0;
  v_exceptions JSONB := '[]'::jsonb;
  v_mismatch_examples JSONB := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  WITH invoice_bl_counts AS (
    SELECT invoice_id, COUNT(*) AS bl_count
    FROM public.invoice_bls
    GROUP BY invoice_id
  )
  UPDATE public.invoices i
  SET invoice_type = CASE WHEN COALESCE(c.bl_count, 1) > 1 THEN 'consolidated' ELSE 'individual' END
  FROM invoice_bl_counts c
  WHERE c.invoice_id = i.id
    AND i.invoice_type = 'individual';

  SELECT COUNT(*)
  INTO v_missing_receivables
  FROM public.invoice_bls ib
  LEFT JOIN public.bl_receivables br ON br.source = 'local_charges' AND br.bl_id = ib.bl_id
  WHERE br.id IS NULL;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'invoice_id', missing.invoice_id,
    'bl_id', missing.bl_id,
    'error', 'missing_receivable'
  )), '[]'::jsonb)
  INTO v_exceptions
  FROM (
    SELECT ib.invoice_id, ib.bl_id
    FROM public.invoice_bls ib
    LEFT JOIN public.bl_receivables br ON br.source = 'local_charges' AND br.bl_id = ib.bl_id
    WHERE br.id IS NULL
    ORDER BY ib.id DESC
    LIMIT 50
  ) AS missing;

  WITH inserted AS (
    INSERT INTO public.invoice_receivable_links (
      invoice_id,
      receivable_id,
      bl_id,
      subtotal_brl,
      status,
      bl_snapshot
    )
    SELECT
      ib.invoice_id,
      br.id,
      ib.bl_id,
      COALESCE(ib.subtotal_brl, br.original_amount_brl, 0),
      CASE
        WHEN COALESCE(i.status, 'issued') = 'paid' THEN 'settled_by_this_invoice'
        WHEN COALESCE(i.status, 'issued') = 'cancelled' THEN 'obsolete'
        ELSE 'active'
      END,
      jsonb_build_object(
        'bl_id', b.id,
        'voyage_id', b.voyage_id,
        'cargo_mode', b.cargo_mode,
        'pol', b.pol,
        'pod', b.pod
      )
    FROM public.invoice_bls ib
    JOIN public.invoices i ON i.id = ib.invoice_id
    JOIN public.bl_receivables br ON br.source = 'local_charges' AND br.bl_id = ib.bl_id
    JOIN public.bls b ON b.id = ib.bl_id
    ORDER BY ib.id DESC
    LIMIT GREATEST(COALESCE(p_limit, 5000), 1)
    ON CONFLICT (invoice_id, receivable_id)
    DO UPDATE SET
      subtotal_brl = EXCLUDED.subtotal_brl,
      status = EXCLUDED.status,
      bl_snapshot = EXCLUDED.bl_snapshot
    RETURNING id
  )
  SELECT COUNT(*) INTO v_inserted FROM inserted;

  SELECT COUNT(*)
  INTO v_total_mismatches
  FROM public.invoice_receivable_links irl
  JOIN public.invoice_bls ib ON ib.invoice_id = irl.invoice_id AND ib.bl_id = irl.bl_id
  WHERE ABS(COALESCE(irl.subtotal_brl, 0) - COALESCE(ib.subtotal_brl, 0)) > 0.01;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'invoice_id', mismatch.invoice_id,
    'bl_id', mismatch.bl_id,
    'error', 'total_mismatch',
    'invoice_bl_subtotal_brl', mismatch.invoice_bl_subtotal_brl,
    'link_subtotal_brl', mismatch.link_subtotal_brl
  )), '[]'::jsonb)
  INTO v_mismatch_examples
  FROM (
    SELECT
      irl.invoice_id,
      irl.bl_id,
      COALESCE(ib.subtotal_brl, 0) AS invoice_bl_subtotal_brl,
      COALESCE(irl.subtotal_brl, 0) AS link_subtotal_brl
    FROM public.invoice_receivable_links irl
    JOIN public.invoice_bls ib ON ib.invoice_id = irl.invoice_id AND ib.bl_id = irl.bl_id
    WHERE ABS(COALESCE(irl.subtotal_brl, 0) - COALESCE(ib.subtotal_brl, 0)) > 0.01
    ORDER BY irl.id DESC
    LIMIT 50
  ) AS mismatch;

  v_exceptions := v_exceptions || v_mismatch_examples;

  RETURN jsonb_build_object(
    'links_upserted', v_inserted,
    'missing_receivables', v_missing_receivables,
    'total_mismatches', v_total_mismatches,
    'exceptions', v_exceptions
  );
END;
$$;



--
-- Name: backfill_local_charge_receivables(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.backfill_local_charge_receivables(p_limit integer DEFAULT 5000) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row RECORD;
  v_receivable_id BIGINT;
  v_actual_amount NUMERIC(14,2);
  v_synced INTEGER := 0;
  v_skipped INTEGER := 0;
  v_total_mismatches INTEGER := 0;
  v_exceptions JSONB := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  FOR v_row IN
    SELECT
      b.id,
      COALESCE(SUM(COALESCE(cc.total_value_brl, 0)), 0)::NUMERIC(14,2) AS expected_amount
    FROM public.bls b
    JOIN public.charge_calculations cc ON cc.bl_id = b.id
    WHERE b.customer_id IS NOT NULL
      AND COALESCE(cc.total_value_brl, 0) > 0
      AND COALESCE(cc.status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing', 'exempt')
    GROUP BY b.id, b.created_at
    ORDER BY b.created_at DESC
    LIMIT GREATEST(COALESCE(p_limit, 5000), 1)
  LOOP
    BEGIN
      v_receivable_id := public.sync_local_charge_receivable(v_row.id);
      SELECT original_amount_brl INTO v_actual_amount
      FROM public.bl_receivables
      WHERE id = v_receivable_id;

      v_synced := v_synced + 1;

      IF ABS(COALESCE(v_actual_amount, 0) - COALESCE(v_row.expected_amount, 0)) > 0.01 THEN
        v_total_mismatches := v_total_mismatches + 1;
        v_exceptions := v_exceptions || jsonb_build_array(jsonb_build_object(
          'bl_id', v_row.id,
          'error', 'total_mismatch',
          'expected_amount_brl', v_row.expected_amount,
          'actual_amount_brl', v_actual_amount
        ));
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_skipped := v_skipped + 1;
      v_exceptions := v_exceptions || jsonb_build_array(jsonb_build_object(
        'bl_id', v_row.id,
        'error', SQLERRM,
        'sqlstate', SQLSTATE
      ));
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'synced', v_synced,
    'skipped', v_skipped,
    'total_mismatches', v_total_mismatches,
    'exceptions', v_exceptions
  );
END;
$$;



--
-- Name: bl_has_portal_release(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bl_has_portal_release(p_bl_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.bls AS b
    WHERE b.id = p_bl_id
      AND trim(coalesce(b.ce_mercante, '')) <> ''
  );
$$;



--
-- Name: bl_timeline(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bl_timeline(p_bl_id text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id bigint, family text, entity_type text, field_name text, old_value text, new_value text, changed_by uuid, changed_at timestamp with time zone, justification text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    a.id,
    CASE
      WHEN a.entity_type = 'invoice' THEN 'fatura'
      WHEN a.entity_type = 'charge_calculation' THEN 'taxas'
      WHEN a.entity_type = 'bl_container' THEN 'container'
      WHEN a.entity_type = 'system_event' THEN 'sistema'
      WHEN a.entity_type = 'bl' AND a.field_name = 'charge_status' THEN 'taxas'
      WHEN a.entity_type = 'bl' AND a.field_name IN ('financial_status', 'billing_hold_reason', 'last_billing_run_id') THEN 'fatura'
      ELSE 'edicao'
    END AS family,
    a.entity_type,
    a.field_name,
    a.old_value,
    a.new_value,
    a.changed_by,
    a.changed_at,
    a.justification
  FROM public.audit_logs a
  WHERE public.is_active_read_user()
    AND (
         (a.entity_type = 'bl' AND a.entity_id = p_bl_id)
      OR (a.entity_type = 'bl_container' AND a.entity_id IN (
            SELECT c.id::text FROM public.bl_containers c WHERE c.bl_id = p_bl_id))
      OR (a.entity_type = 'charge_calculation' AND a.entity_id IN (
            SELECT cc.id::text FROM public.charge_calculations cc WHERE cc.bl_id = p_bl_id))
      OR (a.entity_type = 'invoice' AND a.entity_id IN (
            SELECT ib.invoice_id::text FROM public.invoice_bls ib WHERE ib.bl_id = p_bl_id))
      OR (a.entity_type = 'system_event' AND a.entity_id = p_bl_id)
    )
  ORDER BY a.changed_at DESC
  LIMIT GREATEST(COALESCE(p_limit, 50), 0)
  OFFSET GREATEST(COALESCE(p_offset, 0), 0);
$$;



--
-- Name: block521_resolve_alert(text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block521_resolve_alert(p_type text, p_entity_type text, p_entity_id text, p_department text, p_source text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_result BOOLEAN;
BEGIN
  IF to_regprocedure('public.resolve_alert_item_for_department(text,text,text,text,text,jsonb)') IS NOT NULL THEN
    EXECUTE 'SELECT public.resolve_alert_item_for_department($1,$2,$3,$4,$5,$6)'
      INTO v_result
      USING p_type, p_entity_type, p_entity_id, p_department, p_source, '{}'::jsonb;
  ELSE
    EXECUTE 'SELECT public.resolve_alert_item($1,$2,$3,$4)'
      INTO v_result
      USING p_type, p_entity_type, p_entity_id, p_source;
    v_result := true;
  END IF;
  RETURN COALESCE(v_result, false);
END;
$_$;



--
-- Name: block521_upsert_alert(text, text, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block521_upsert_alert(p_type text, p_entity_type text, p_entity_id text, p_message text, p_source text, p_department text, p_metadata jsonb DEFAULT '{}'::jsonb, p_destination text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_result JSONB;
BEGIN
  IF to_regprocedure('public.upsert_alert_item(text,text,text,text,text,text,jsonb,text)') IS NOT NULL THEN
    EXECUTE 'SELECT public.upsert_alert_item($1,$2,$3,$4,$5,$6,$7,$8)'
      INTO v_result
      USING p_type, p_entity_type, p_entity_id, p_message, p_source,
        p_department, COALESCE(p_metadata, '{}'::jsonb), p_destination;
  ELSE
    EXECUTE 'SELECT public.upsert_alert_item($1,$2,$3,$4,$5,$6,$7)'
      INTO v_result
      USING p_type, p_entity_type, p_entity_id, p_message, p_source,
        COALESCE(p_metadata, '{}'::jsonb), p_destination;
  END IF;
  RETURN v_result;
END;
$_$;



--
-- Name: build_transshipping_pix_payload(numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_transshipping_pix_payload(p_amount_brl numeric, p_txid text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_key TEXT := REGEXP_REPLACE('06352972000121', '[^0-9]', '', 'g');
  v_merchant TEXT := TRIM(REGEXP_REPLACE(SUBSTRING('TRANSHIPPING AGENCIAMENTO MARITIMO' FROM 1 FOR 25), '[^A-Za-z0-9 ]', '', 'g'));
  v_city TEXT := TRIM(REGEXP_REPLACE(SUBSTRING('VIT' FROM 1 FOR 15), '[^A-Za-z0-9 ]', '', 'g'));
  v_txid TEXT := COALESCE(NULLIF(SUBSTRING(REGEXP_REPLACE(COALESCE(p_txid, ''), '[^A-Za-z0-9]', '', 'g') FROM 1 FOR 35), ''), '***');
  v_amount_text TEXT := CASE
    WHEN COALESCE(p_amount_brl, 0) > 0 THEN TO_CHAR(ROUND(p_amount_brl::NUMERIC, 2), 'FM999999999999990.00')
    ELSE ''
  END;
  v_merchant_account TEXT;
  v_payload TEXT;
BEGIN
  v_merchant_account :=
    public.pix_tlv('00', 'br.gov.bcb.pix') ||
    public.pix_tlv('01', v_key) ||
    public.pix_tlv('05', v_txid);

  v_payload :=
    public.pix_tlv('00', '01') ||
    public.pix_tlv('26', v_merchant_account) ||
    public.pix_tlv('52', '0000') ||
    public.pix_tlv('53', '986') ||
    CASE WHEN v_amount_text <> '' THEN public.pix_tlv('54', v_amount_text) ELSE '' END ||
    public.pix_tlv('58', 'BR') ||
    public.pix_tlv('59', v_merchant) ||
    public.pix_tlv('60', v_city) ||
    public.pix_tlv('62', public.pix_tlv('05', v_txid)) ||
    '6304';

  RETURN v_payload || public.pix_crc16_ccitt(v_payload);
END;
$$;



--
-- Name: calculate_bl_local_charges(text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_bl_local_charges(p_bl_id text, p_actor uuid DEFAULT NULL::uuid, p_recalculate boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_bl RECORD;
  v_table_id BIGINT;
  v_ref_date DATE;
  v_actor UUID;
  v_has_vehicles BOOLEAN := false;
  v_is_exempt BOOLEAN := false;
  v_is_lcl_movement BOOLEAN := false;
  v_auto_review BOOLEAN := false;
  v_line_count INTEGER := 0;
  v_total_brl NUMERIC(14,2) := 0;
  v_total_usd NUMERIC(14,2) := 0;
  v_status TEXT := 'calculated';
  v_reason TEXT := NULL;
  v_qty_total NUMERIC(12,6) := 0;
  v_qty_std NUMERIC(12,6) := 0;
  v_qty_imo NUMERIC(12,6) := 0;
  v_qty_oog NUMERIC(12,6) := 0;
  v_qty_dual NUMERIC(12,6) := 0;
  v_container_shares JSONB;
  v_no_containers BOOLEAN := false;
  item RECORD;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  SELECT
    b.id,
    b.voyage_id,
    b.batch_id,
    COALESCE(b.cargo_mode, 'container') AS cargo_mode,
    b.customer_id,
    b.pod,
    NULLIF((to_jsonb(b)->>'bb_weight_ton'), '')::NUMERIC AS bb_weight_ton,
    b.total_weight_kg,
    b.movement_to,
    b.created_at,
    b.financial_status,
    ib.uploaded_at
  INTO v_bl
  FROM public.bls AS b
  LEFT JOIN public.import_batches AS ib ON ib.id = b.batch_id
  WHERE b.id = p_bl_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF v_bl.financial_status IN ('invoiced', 'partially_paid', 'paid') THEN
    RAISE EXCEPTION 'B/L % ja foi faturado (status financeiro=%); recalculo bloqueado. Cancele e reemita a fatura para corrigir.', p_bl_id, v_bl.financial_status USING ERRCODE = '22023';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  IF p_recalculate THEN
    DELETE FROM public.charge_calculations
    WHERE bl_id = p_bl_id
      AND COALESCE(source, 'auto') = 'auto';
  END IF;

  SELECT EXISTS(SELECT 1 FROM public.vehicles WHERE bl_id = p_bl_id)
  INTO v_has_vehicles;

  v_is_lcl_movement := v_bl.movement_to IS NOT NULL AND (
    UPPER(TRIM(v_bl.movement_to)) LIKE '%LCL%' OR UPPER(TRIM(v_bl.movement_to)) LIKE '%CFS%'
  );

  IF v_bl.cargo_mode = 'container' AND v_has_vehicles AND v_is_lcl_movement THEN
    v_is_exempt := true;
    v_reason := 'Carga de veiculos / LCL no destino (movement_to=' || v_bl.movement_to || ') com taxas pagas na origem';

    INSERT INTO public.charge_calculations (
      bl_id, source, status, calculation_key, quantity,
      unit_value_brl, total_value_brl, notes, review_reason, created_by, calculated_at
    )
    VALUES (
      p_bl_id, 'auto', 'exempt', 'exempt:lcl_vehicle', 1,
      0, 0, 'Linha sintetica de isencao', v_reason, v_actor, NOW()
    )
    ON CONFLICT (bl_id, calculation_key) DO UPDATE
      SET status = EXCLUDED.status,
          quantity = EXCLUDED.quantity,
          unit_value_brl = EXCLUDED.unit_value_brl,
          total_value_brl = EXCLUDED.total_value_brl,
          notes = EXCLUDED.notes,
          review_reason = EXCLUDED.review_reason,
          created_by = EXCLUDED.created_by,
          calculated_at = NOW();

    UPDATE public.bls
    SET charge_status = 'exempt',
        charges_calculated_at = NOW(),
        charge_exemption_reason = v_reason,
        billing_hold_reason = NULL
    WHERE id = p_bl_id;

    RETURN jsonb_build_object(
      'bl_id', p_bl_id, 'status', 'exempt', 'table_id', NULL,
      'line_count', 1, 'total_brl', 0, 'total_usd', 0,
      'review_required', false, 'exempt', true, 'reason', v_reason
    );
  END IF;

  SELECT v_eta_raw.eta_text::DATE
  INTO v_ref_date
  FROM public.voyages AS v
  CROSS JOIN LATERAL (
    SELECT NULLIF(TRIM(v.pod_schedule_snapshot -> v_bl.pod ->> 'eta'), '') AS eta_text
  ) AS v_eta_raw
  WHERE v.id = v_bl.voyage_id
    AND v_eta_raw.eta_text ~ '^\d{4}-\d{2}-\d{2}$';

  IF v_ref_date IS NULL THEN
    SELECT v.eta::DATE
    INTO v_ref_date
    FROM public.voyages AS v
    WHERE v.id = v_bl.voyage_id
      AND v.eta IS NOT NULL;
  END IF;
  v_ref_date := COALESCE(v_ref_date, CURRENT_DATE);
  v_table_id := public.resolve_local_charge_table_id(v_bl.cargo_mode, v_bl.pod, v_ref_date);

  IF v_table_id IS NULL THEN
    v_reason := 'Nao existe tabela de taxas ativa para este POD/modo de carga';
    v_auto_review := true;
    INSERT INTO public.charge_calculations (
      bl_id, source, status, calculation_key, quantity, total_value_brl,
      review_reason, notes, created_by, calculated_at
    )
    VALUES (
      p_bl_id, 'auto', 'review_required', 'review:no_table', 1, 0,
      v_reason, 'Revisao manual obrigatoria', v_actor, NOW()
    )
    ON CONFLICT (bl_id, calculation_key) DO UPDATE
      SET status = EXCLUDED.status,
          quantity = EXCLUDED.quantity,
          total_value_brl = EXCLUDED.total_value_brl,
          review_reason = EXCLUDED.review_reason,
          notes = EXCLUDED.notes,
          created_by = EXCLUDED.created_by,
          calculated_at = NOW();
  END IF;

  IF v_bl.cargo_mode = 'container' THEN
    WITH current_containers AS (
      SELECT
        UPPER(TRIM(bc.container_number)) AS cn,
        BOOL_OR(COALESCE(bc.is_imo, false)) AS has_imo,
        BOOL_OR(COALESCE(bc.is_oog, false)) AS has_oog
      FROM public.bl_containers AS bc
      WHERE bc.bl_id = p_bl_id
        AND TRIM(COALESCE(bc.container_number, '')) <> ''
      GROUP BY UPPER(TRIM(bc.container_number))
    ),
    shares AS (
      SELECT cc.cn, cc.has_imo, cc.has_oog, sh.share_count, sh.last_bl_id
      FROM current_containers AS cc
      JOIN LATERAL (
        SELECT COUNT(DISTINCT b2.id)::NUMERIC AS share_count, MAX(b2.id) AS last_bl_id
        FROM public.bls AS b2
        JOIN public.bl_containers AS bc2 ON bc2.bl_id = b2.id
        WHERE b2.voyage_id = v_bl.voyage_id
          AND COALESCE(b2.cargo_mode, 'container') = 'container'
          AND UPPER(TRIM(COALESCE(bc2.container_number, ''))) = cc.cn
      ) AS sh ON TRUE
    )
    SELECT
      COALESCE(SUM(CASE WHEN share_count > 0 THEN 1 / share_count ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN NOT has_imo AND NOT has_oog AND share_count > 0 THEN 1 / share_count ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN has_imo AND NOT has_oog AND share_count > 0 THEN 1 / share_count ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN has_oog AND NOT has_imo AND share_count > 0 THEN 1 / share_count ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN has_imo AND has_oog AND share_count > 0 THEN 1 / share_count ELSE 0 END), 0),
      jsonb_agg(jsonb_build_object('has_imo', has_imo, 'has_oog', has_oog, 'share_count', share_count, 'is_last', (p_bl_id = last_bl_id))) FILTER (WHERE share_count > 0)
    INTO v_qty_total, v_qty_std, v_qty_imo, v_qty_oog, v_qty_dual, v_container_shares
    FROM shares;

    IF v_qty_dual > 0 THEN
      v_auto_review := true;
      INSERT INTO public.charge_calculations (
        bl_id, charge_table_id, source, status, calculation_key, quantity,
        total_value_brl, review_reason, notes, created_by, calculated_at
      )
      VALUES (
        p_bl_id, v_table_id, 'auto', 'review_required', 'review:imo_oog_thd', v_qty_dual,
        0, 'Container com IMO e OOG ao mesmo tempo exige revisao manual de THD', 'THD nao calculado automaticamente', v_actor, NOW()
      )
      ON CONFLICT (bl_id, calculation_key) DO UPDATE
        SET status = EXCLUDED.status, quantity = EXCLUDED.quantity,
            total_value_brl = EXCLUDED.total_value_brl, review_reason = EXCLUDED.review_reason,
            notes = EXCLUDED.notes, created_by = EXCLUDED.created_by, calculated_at = NOW();
    END IF;
  END IF;

  IF v_bl.cargo_mode = 'container' THEN
    SELECT NOT EXISTS(
      SELECT 1 FROM public.bl_containers AS bc
      WHERE bc.bl_id = p_bl_id AND TRIM(COALESCE(bc.container_number, '')) <> ''
    ) INTO v_no_containers;

    IF v_no_containers THEN
      v_auto_review := true;
      INSERT INTO public.charge_calculations (
        bl_id, charge_table_id, source, status, calculation_key, quantity,
        total_value_brl, review_reason, notes, created_by, calculated_at
      )
      VALUES (
        p_bl_id, v_table_id, 'auto', 'review_required', 'review:no_containers', 1,
        0, 'B/L de container sem containers cadastrados', 'Revisao manual obrigatoria', v_actor, NOW()
      )
      ON CONFLICT (bl_id, calculation_key) DO UPDATE
        SET status = EXCLUDED.status, quantity = EXCLUDED.quantity,
            total_value_brl = EXCLUDED.total_value_brl, review_reason = EXCLUDED.review_reason,
            notes = EXCLUDED.notes, created_by = EXCLUDED.created_by, calculated_at = NOW();
    END IF;
  END IF;

  IF v_table_id IS NOT NULL THEN
    FOR item IN SELECT * FROM public.resolve_bl_local_charge_items(p_bl_id, v_bl.pod) LOOP
      IF item.status = 'review_required' THEN
        v_auto_review := true;
        -- Espelha os três INSERTs de revisão da 274: o upsert só atualiza
        -- estado/revisão; não troca a identidade, a origem nem os valores de
        -- uma linha já existente.
        INSERT INTO public.charge_calculations (
          bl_id, charge_table_id, charge_item_id, source, status, calculation_key, quantity,
          total_value_brl, review_reason, notes, created_by, calculated_at
        )
        VALUES (
          p_bl_id, item.charge_table_id, item.charge_item_id, item.source, item.status, item.calculation_key,
          item.quantity, item.total_value_brl, item.review_reason, item.notes, v_actor, NOW()
        )
        ON CONFLICT (bl_id, calculation_key) DO UPDATE
          SET status = EXCLUDED.status,
              quantity = EXCLUDED.quantity,
              total_value_brl = EXCLUDED.total_value_brl,
              review_reason = EXCLUDED.review_reason,
              notes = EXCLUDED.notes,
              created_by = EXCLUDED.created_by,
              calculated_at = NOW();
      ELSE
        -- O ramo calculado da 274 não inclui colunas de revisão no INSERT nem
        -- no ON CONFLICT; em particular, uma nota antiga não é apagada.
        INSERT INTO public.charge_calculations (
          bl_id, charge_table_id, charge_item_id, quantity,
          unit_value_brl, unit_value_usd, total_value_brl, total_value_usd,
          override_applied, source, status, calculation_key,
          created_by, calculated_at
        )
        VALUES (
          p_bl_id, item.charge_table_id, item.charge_item_id, item.quantity,
          item.unit_value_brl, item.unit_value_usd, item.total_value_brl, item.total_value_usd,
          item.override_applied, item.source, item.status, item.calculation_key,
          v_actor, NOW()
        )
        ON CONFLICT (bl_id, calculation_key) DO UPDATE
          SET charge_table_id = EXCLUDED.charge_table_id,
              charge_item_id = EXCLUDED.charge_item_id,
              quantity = EXCLUDED.quantity,
              unit_value_brl = EXCLUDED.unit_value_brl,
              unit_value_usd = EXCLUDED.unit_value_usd,
              total_value_brl = EXCLUDED.total_value_brl,
              total_value_usd = EXCLUDED.total_value_usd,
              override_applied = EXCLUDED.override_applied,
              source = EXCLUDED.source,
              status = EXCLUDED.status,
              created_by = EXCLUDED.created_by,
              calculated_at = NOW();
      END IF;
    END LOOP;
  END IF;

  SELECT COUNT(*),
         COALESCE(SUM(COALESCE(total_value_brl, 0)), 0),
         COALESCE(SUM(COALESCE(total_value_usd, 0)), 0)
  INTO v_line_count, v_total_brl, v_total_usd
  FROM public.charge_calculations
  WHERE bl_id = p_bl_id;

  IF v_is_exempt THEN
    v_status := 'exempt';
  ELSIF v_auto_review THEN
    v_status := 'review_required';
  ELSIF v_line_count > 0 THEN
    v_status := 'calculated';
  ELSE
    v_status := 'not_calculated';
  END IF;

  UPDATE public.bls
  SET charge_status = v_status,
      charges_calculated_at = NOW(),
      charge_exemption_reason = CASE WHEN v_status = 'exempt' THEN v_reason ELSE NULL END,
      billing_hold_reason = CASE
        WHEN v_status = 'review_required' THEN COALESCE(v_reason, 'Pendencia de revisao nas taxas locais.')
        WHEN v_status = 'not_calculated' THEN 'Nenhuma tabela de preco ou tarifa encontrada. Adicione os precos e recalcule.'
        ELSE NULL
      END
  WHERE id = p_bl_id;

  RETURN jsonb_build_object(
    'bl_id', p_bl_id,
    'status', v_status,
    'table_id', v_table_id,
    'line_count', v_line_count,
    'total_brl', v_total_brl,
    'total_usd', v_total_usd,
    'review_required', v_auto_review,
    'exempt', (v_status = 'exempt'),
    'reason', COALESCE(v_reason, '')
  );
END;
$_$;



--
-- Name: cancel_invoice(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_invoice(p_invoice_id bigint, p_reason text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice RECORD;
  v_actor UUID;
  v_payment_count INTEGER;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  SELECT *
  INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % nao encontrada.', p_invoice_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_invoice.status, 'issued') = 'cancelled' THEN
    RETURN jsonb_build_object('invoice_id', p_invoice_id, 'status', 'cancelled', 'changed', false);
  END IF;

  SELECT COUNT(*)
  INTO v_payment_count
  FROM public.payments
  WHERE invoice_id = p_invoice_id;

  IF v_payment_count > 0 THEN
    RAISE EXCEPTION 'Nao e permitido cancelar invoice com pagamentos registrados.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.invoices
  SET
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_by = v_actor,
    cancel_reason = NULLIF(TRIM(COALESCE(p_reason, '')), ''),
    balance_brl = GREATEST(COALESCE(total_brl, 0) - COALESCE(total_paid_brl, 0), 0)
  WHERE id = p_invoice_id;

  UPDATE public.billing_batches
  SET status = 'cancelled'
  WHERE invoice_id = p_invoice_id;

  UPDATE public.bls AS b
  SET financial_status = CASE
    WHEN EXISTS (
      SELECT 1
      FROM public.invoice_bls AS ib2
      JOIN public.invoices AS inv2 ON inv2.id = ib2.invoice_id
      WHERE ib2.bl_id = b.id
        AND inv2.id <> p_invoice_id
        AND COALESCE(inv2.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue')
    ) THEN 'invoiced'
    WHEN EXISTS (
      SELECT 1
      FROM public.invoice_bls AS ib3
      JOIN public.invoices AS inv3 ON inv3.id = ib3.invoice_id
      WHERE ib3.bl_id = b.id
        AND inv3.id <> p_invoice_id
        AND COALESCE(inv3.status, 'issued') = 'paid'
    ) THEN 'paid'
    ELSE 'pending'
  END
  WHERE b.id IN (
    SELECT ib.bl_id
    FROM public.invoice_bls AS ib
    WHERE ib.invoice_id = p_invoice_id
  );

  UPDATE public.granite_bls AS gb
  SET charge_status = CASE
    WHEN EXISTS (
      SELECT 1
      FROM public.invoice_granite_bls AS igb2
      JOIN public.invoices AS inv2 ON inv2.id = igb2.invoice_id
      WHERE igb2.granite_bl_id = gb.id
        AND inv2.id <> p_invoice_id
        AND COALESCE(inv2.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue', 'paid')
    ) THEN 'invoiced'
    ELSE 'ready_for_billing'
  END
  WHERE gb.id IN (
    SELECT igb.granite_bl_id
    FROM public.invoice_granite_bls AS igb
    WHERE igb.invoice_id = p_invoice_id
  );

  INSERT INTO public.audit_logs (
    entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification
  )
  VALUES (
    'invoice',
    p_invoice_id::TEXT,
    'cancel_invoice',
    COALESCE(v_invoice.status, 'issued'),
    'cancelled',
    v_actor,
    now(),
    COALESCE(NULLIF(TRIM(COALESCE(p_reason, '')), ''), 'Cancelamento de invoice')
  );

  RETURN jsonb_build_object('invoice_id', p_invoice_id, 'status', 'cancelled', 'changed', true);
END;
$$;



--
-- Name: canonicalize_customer_cnpj(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.canonicalize_customer_cnpj() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.cnpj_cpf := public.normalize_cnpj(NEW.cnpj_cpf);
  IF NEW.cnpj_cpf IS NULL OR NOT public.is_valid_cnpj(NEW.cnpj_cpf) THEN
    RAISE EXCEPTION 'CNPJ inválido.' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: capture_manifest_financial_contact(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.capture_manifest_financial_contact(p_customer_id bigint, p_email text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_email TEXT;
  v_rowcount INT;
BEGIN
  IF p_customer_id IS NULL THEN
    RETURN false;
  END IF;

  v_email := lower(NULLIF(TRIM(COALESCE(p_email, '')), ''));
  IF v_email IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO public.customer_contacts (customer_id, name, email, purpose, is_primary)
  SELECT p_customer_id, 'Contato manifesto', v_email, 'financeiro', false
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.customer_contacts AS cc
    WHERE cc.customer_id = p_customer_id
      AND lower(trim(cc.email)) = v_email
  );

  GET DIAGNOSTICS v_rowcount = ROW_COUNT;
  RETURN v_rowcount > 0;
END;
$$;



--
-- Name: check_portal_rate_limit(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_portal_rate_limit(p_action_name text, p_max_attempts integer DEFAULT 5, p_window_minutes integer DEFAULT 5) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT := public.current_portal_customer_id();
  v_cutoff TIMESTAMPTZ := now() - (p_window_minutes * INTERVAL '1 minute');
  v_count INT;
BEGIN
  -- Limpa entradas antigas
  DELETE FROM public.portal_rate_limits
  WHERE customer_id = v_customer_id
    AND action_name = p_action_name
    AND attempted_at < v_cutoff;

  -- Conta tentativas na janela
  SELECT COUNT(*) INTO v_count
  FROM public.portal_rate_limits
  WHERE customer_id = v_customer_id
    AND action_name = p_action_name
    AND attempted_at >= v_cutoff;

  IF v_count >= p_max_attempts THEN
    RAISE EXCEPTION 'Limite de tentativas excedido para esta acao. Aguarde % minuto(s) antes de tentar novamente.', p_window_minutes
      USING ERRCODE = 'P0429';
  END IF;

  -- Registra tentativa
  INSERT INTO public.portal_rate_limits (customer_id, action_name)
  VALUES (v_customer_id, p_action_name);

  RETURN true;
END;
$$;



--
-- Name: check_provision_rate_limit(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_provision_rate_limit(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count INT;
BEGIN
  SELECT COUNT(*) INTO v_count
    FROM public.provision_rate_limit_log
    WHERE user_id = p_user_id
      AND called_at > now() - INTERVAL '1 hour';

  IF v_count >= 20 THEN
    RETURN false;
  END IF;

  INSERT INTO public.provision_rate_limit_log (user_id) VALUES (p_user_id);
  RETURN true;
END;
$$;



--
-- Name: claim_demurrage_dunning_candidates(timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_demurrage_dunning_candidates(p_as_of timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_invoice RECORD;
  v_interval_days INTEGER;
  v_limit INTEGER;
  v_inserted INTEGER;
  v_claimed_at TIMESTAMPTZ;
  v_candidates JSONB := '[]'::JSONB;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Executor server-only.' USING ERRCODE = '42501';
  END IF;
  IF p_limit IS NOT NULL AND p_limit < 1 THEN
    RAISE EXCEPTION 'O limite do lote deve ser positivo.' USING ERRCODE = '22023';
  END IF;
  v_limit := LEAST(COALESCE(p_limit, 50), 100);
  SELECT GREATEST(COALESCE(demurrage_dunning_interval_days, 7), 1) INTO v_interval_days FROM public.app_settings WHERE id = 1;
  v_interval_days := COALESCE(v_interval_days, 7);

  -- Libera claims de execuções anteriores que reservaram mas não concluíram o envio após 30 minutos.
  UPDATE public.demurrage_dunning_claims AS claim
  SET released_at = COALESCE(p_as_of, now())
  WHERE claim.released_at IS NULL
    AND claim.claimed_at < COALESCE(p_as_of, now()) - interval '30 minutes'
    AND NOT EXISTS (
      SELECT 1
      FROM public.customer_communications AS comm
      WHERE comm.kind = 'cobranca_demurrage'
        AND comm.anchor_invoice_id = claim.demurrage_invoice_id
        AND comm.attempt_discriminator = claim.attempt_discriminator
        AND comm.status IN ('enviado', 'simulado')
    );

  FOR v_invoice IN
    SELECT di.id, di.customer_id, di.bl_id, di.doc_number, di.total_usd, di.current_total_brl,
      di.current_roe, di.roe_source, di.first_billed_at,
      COALESCE(claims.claimed_at, now()) AS claimed_at,
      COALESCE(di.updated_at::DATE, di.doc_date, CURRENT_DATE)::TEXT AS roe_reference_date,
      COALESCE(claims.attempt_count, 0)::INTEGER + 1 AS attempt_discriminator
    FROM public.demurrage_invoices AS di
    LEFT JOIN LATERAL (
      SELECT count(*) FILTER (WHERE prior_claim.released_at IS NULL)::INTEGER AS attempt_count,
        max(prior_claim.claimed_at) FILTER (WHERE prior_claim.released_at IS NULL) AS claimed_at
      FROM public.demurrage_dunning_claims AS prior_claim
      WHERE prior_claim.demurrage_invoice_id = di.id
    ) AS claims ON true
    WHERE COALESCE(di.status, 'issued') IN ('issued', 'overdue')
      AND di.first_billed_at IS NOT NULL AND di.paid_at IS NULL
      AND COALESCE(di.dispute_open, false) = false
      AND EXISTS (
        SELECT 1 FROM public.customer_contacts AS cc
        WHERE cc.customer_id = di.customer_id
          AND NULLIF(btrim(cc.email), '') IS NOT NULL
          AND NULLIF(btrim(cc.email), '') ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
          AND NOT EXISTS (SELECT 1 FROM public.portal_suppressed_emails pse WHERE lower(btrim(pse.email)) = lower(btrim(cc.email)) AND pse.reason = 'bounce_permanente')
          AND NOT EXISTS (SELECT 1 FROM public.customer_communication_suppressions ccs WHERE lower(btrim(ccs.email)) = lower(btrim(cc.email)))
          AND COALESCE((SELECT ccp.enabled FROM public.customer_contact_preferences ccp WHERE ccp.contact_id = cc.id AND ccp.nature = 'demurrage'), true)
      )
      AND COALESCE(p_as_of, now()) >= (di.first_billed_at::TIMESTAMP AT TIME ZONE 'America/Sao_Paulo' + make_interval(days => v_interval_days * COALESCE(claims.attempt_count, 0)))
    ORDER BY di.id
    LIMIT v_limit
    FOR UPDATE OF di SKIP LOCKED
  LOOP
    v_inserted := 0;
    v_claimed_at := NULL;
    INSERT INTO public.demurrage_dunning_claims (demurrage_invoice_id, attempt_discriminator)
    VALUES (v_invoice.id, v_invoice.attempt_discriminator)
    ON CONFLICT (demurrage_invoice_id, attempt_discriminator) DO UPDATE
      SET claimed_at = now(), released_at = NULL
      WHERE demurrage_dunning_claims.released_at IS NOT NULL
    RETURNING claimed_at INTO v_claimed_at;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 1 THEN
      v_candidates := v_candidates || jsonb_build_array(jsonb_build_object(
        'invoice_id', v_invoice.id, 'customer_id', v_invoice.customer_id, 'bl_id', v_invoice.bl_id,
        'doc_number', v_invoice.doc_number, 'total_usd', v_invoice.total_usd,
        'current_total_brl', v_invoice.current_total_brl, 'current_roe', v_invoice.current_roe,
        'roe_source', v_invoice.roe_source, 'first_billed_at', v_invoice.first_billed_at,
        'claimed_at', v_claimed_at, 'roe_reference_date', v_invoice.roe_reference_date,
        'attempt_discriminator', v_invoice.attempt_discriminator
      ));
    END IF;
  END LOOP;
  RETURN v_candidates;
END;
$_$;



--
-- Name: classify_granite_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.classify_granite_invoice() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.invoices
  SET invoice_type = 'granite'
  WHERE id = NEW.invoice_id
    AND invoice_type IS DISTINCT FROM 'granite';

  IF NOT FOUND THEN
    PERFORM 1 FROM public.invoices WHERE id = NEW.invoice_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Invoice vinculada ao Granito nao encontrada.'
        USING ERRCODE = 'P0002';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: clear_alert_item_destination(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_alert_item_destination() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.alert_type_catalog c
    WHERE c.type = NEW.item_type AND c.active = true
  ) THEN
    NEW.destination := NULL;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: close_agency_departure_report(bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_agency_departure_report(p_voyage_id bigint, p_port text, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_report_id UUID;
  v_signed_departments INTEGER;
  v_unknown_sections TEXT[];
  v_unknown_top_level TEXT[];
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;
  IF p_snapshot IS NULL OR jsonb_typeof(p_snapshot) <> 'object'
     OR jsonb_typeof(p_snapshot->'header') <> 'object'
     OR jsonb_typeof(p_snapshot->'sections') <> 'object'
     OR jsonb_typeof(p_snapshot->'occurrences') <> 'array'
     OR jsonb_typeof(p_snapshot->'signoffs') <> 'array'
     OR octet_length(p_snapshot::text) > 8388608 THEN
    RAISE EXCEPTION 'Snapshot invalido: esperado objeto com header, sections, occurrences e signoffs (maximo 8 MiB).' USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(key ORDER BY key) INTO v_unknown_top_level
  FROM jsonb_object_keys(p_snapshot) AS key
  WHERE key NOT IN ('header', 'sections', 'occurrences', 'signoffs', 'departmentSignoffs');
  IF v_unknown_top_level IS NOT NULL THEN
    RAISE EXCEPTION 'Snapshot possui chaves de topo desconhecidas: %.', array_to_string(v_unknown_top_level, ', ')
      USING ERRCODE = '22023';
  END IF;

  SELECT array_agg(key ORDER BY key) INTO v_unknown_sections
  FROM jsonb_object_keys(p_snapshot->'sections') AS key
  WHERE key NOT IN (
    'cargaDescarregada', 'cargaSolta', 'vaziosDescarregados', 'veiculos',
    'vaziosEmbarcados', 'vaziosUnidades', 'vehicleLocations', 'vehicleBreakdown',
    'depots', 'directEmbarkCount', 'granito', 'storage', 'operation', 'costs'
  );
  IF v_unknown_sections IS NOT NULL THEN
    RAISE EXCEPTION 'Snapshot possui secoes desconhecidas: %.', array_to_string(v_unknown_sections, ', ')
      USING ERRCODE = '22023';
  END IF;

  v_report_id := public.ensure_agency_departure_report(p_voyage_id, p_port);
  SELECT id INTO v_report_id
  FROM public.agency_departure_reports
  WHERE id = v_report_id
  FOR UPDATE;

  SELECT COUNT(*) INTO v_signed_departments
  FROM public.agency_departure_report_department_signoffs
  WHERE report_id = v_report_id AND signed_at IS NOT NULL;
  IF v_signed_departments <> 3 THEN
    RAISE EXCEPTION 'Fechamento exige os 3 departamentos assinados (% pendentes).', 3 - v_signed_departments
      USING ERRCODE = '23514';
  END IF;

  UPDATE public.agency_departure_reports
  SET status = 'closed', closed_at = now(), closed_by = auth.uid(), closed_snapshot = p_snapshot
  WHERE id = v_report_id AND status = 'open';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ADR ja fechado.' USING ERRCODE = '23505';
  END IF;

  -- 'agency_report_section_pending' e obsoleto (migration 225 introduz
  -- 'agency_report_department_pending', ja fechado por departamento no
  -- signoff); mantido aqui so para alertas legados pre-0029.
  UPDATE public.alerts
  SET status = 'closed', closed_at = now()
  WHERE type = 'agency_report_section_pending'
    AND entity_type = 'agency_departure_report'
    AND entity_id LIKE p_voyage_id || '::' || upper(btrim(p_port)) || '::%'
    AND status <> 'closed';

  -- ADR 0039: fecha os alertas de vencimento do prazo junto com o Fechamento.
  -- Chegar aqui exige os 3 departamentos assinados, entao todo alerta de
  -- vencimento desta escala ja deveria estar sem motivo; este UPDATE e uma
  -- rede de seguranca (ex.: alerta detectado entre o ultimo sign-off e o
  -- clique de Fechar).
  UPDATE public.alerts
  SET status = 'closed', closed_at = now()
  WHERE type = 'agency_report_deadline_missed'
    AND entity_type = 'agency_departure_report'
    AND entity_id LIKE p_voyage_id || '::' || upper(btrim(p_port)) || '::%'
    AND status <> 'closed';

  RETURN jsonb_build_object('report_id', v_report_id);
END;
$$;



--
-- Name: close_agency_departure_report_by_report_id(uuid, bigint, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_agency_departure_report_by_report_id(p_report_id uuid, p_voyage_id bigint, p_port text, p_snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_report RECORD;
  v_signed INTEGER;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501'; END IF;
  PERFORM public.assert_voyage_escala_ready_for_report_close(p_voyage_id, p_port, p_report_id);
  SELECT * INTO v_report FROM public.agency_departure_reports WHERE id = p_report_id FOR UPDATE;
  IF v_report.voyage_id <> p_voyage_id OR upper(btrim(v_report.port)) <> upper(btrim(p_port)) OR v_report.terminal_id IS NULL THEN
    RAISE EXCEPTION 'report_id nao pertence a ADR terminalizado da escala %::%.', p_voyage_id, upper(btrim(p_port)) USING ERRCODE = '23514';
  END IF;
  IF p_snapshot IS NULL OR jsonb_typeof(p_snapshot) <> 'object' OR jsonb_typeof(p_snapshot->'header') <> 'object'
     OR jsonb_typeof(p_snapshot->'sections') <> 'object' OR jsonb_typeof(p_snapshot->'occurrences') <> 'array'
     OR jsonb_typeof(p_snapshot->'signoffs') <> 'array' OR octet_length(p_snapshot::TEXT) > 8388608 THEN
    RAISE EXCEPTION 'Snapshot invalido.' USING ERRCODE = '22023';
  END IF;
  SELECT COUNT(*) INTO v_signed FROM public.agency_departure_report_department_signoffs
  WHERE report_id = p_report_id AND signed_at IS NOT NULL;
  IF v_signed <> 3 THEN RAISE EXCEPTION 'Fechamento exige os 3 departamentos assinados (% pendentes).', 3 - v_signed USING ERRCODE = '23514'; END IF;
  UPDATE public.agency_departure_reports SET status = 'closed', closed_at = now(), closed_by = auth.uid(), closed_snapshot = p_snapshot
  WHERE id = p_report_id AND status = 'open';
  IF NOT FOUND THEN RAISE EXCEPTION 'ADR ja fechado.' USING ERRCODE = '23505'; END IF;
  UPDATE public.alerts SET status = 'closed', closed_at = now()
  WHERE type IN ('agency_report_section_pending', 'agency_report_department_pending', 'agency_report_deadline_missed')
    AND entity_type = 'agency_departure_report'
    AND entity_id LIKE public.agency_report_alert_entity_prefix(
      v_report.voyage_id,
      v_report.port,
      (SELECT d.code FROM public.depots AS d WHERE d.id = v_report.terminal_id)
    ) || '%'
    AND status <> 'closed';
  RETURN jsonb_build_object('report_id', p_report_id);
END;
$$;



--
-- Name: close_legacy_agency_report_alerts_for_scale(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_legacy_agency_report_alerts_for_scale(p_voyage_id bigint, p_port text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_closed INTEGER;
BEGIN
  UPDATE public.alerts AS a
  SET status = 'closed', closed_at = now()
  WHERE a.type IN (
      'agency_report_section_pending',
      'agency_report_department_pending',
      'agency_report_deadline_missed'
    )
    AND a.entity_type = 'agency_departure_report'
    AND array_length(string_to_array(a.entity_id, '::'), 1) = 3
    AND a.entity_id LIKE public.agency_report_alert_entity_prefix(p_voyage_id, p_port, NULL) || '%'
    AND a.status <> 'closed'
    AND EXISTS (
      SELECT 1
      FROM public.agency_departure_reports AS r
      WHERE r.voyage_id = p_voyage_id
        AND r.port = upper(btrim(p_port))
        AND r.terminal_id IS NOT NULL
    );
  GET DIAGNOSTICS v_closed = ROW_COUNT;
  RETURN v_closed;
END;
$$;



--
-- Name: complete_review_customer_group(text[], bigint, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_review_customer_group(p_bl_ids text[], p_customer_id bigint DEFAULT NULL::bigint, p_cnpj_cpf text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_changed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_actor UUID := auth.uid();
  v_cnpj TEXT := public.normalize_cnpj(p_cnpj_cpf);
  v_name TEXT := NULLIF(btrim(p_name), '');
  v_email TEXT := lower(NULLIF(btrim(p_email), ''));
  v_customer public.customers%ROWTYPE;
  v_bl public.bls%ROWTYPE;
  v_candidates TEXT[];
  v_reasons TEXT[];
  v_human_notes TEXT;
  v_notes TEXT;
  v_bls JSONB := '[]'::JSONB;
  v_missing INTEGER := 0;
  v_requested_count INTEGER := 0;
  v_group_name_identity TEXT;
  v_bl_name_identity TEXT;
BEGIN
  IF v_actor IS NULL OR NOT public.is_active_user() OR p_changed_by IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Usuário sem permissão ativa para concluir o grupo.' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(cardinality(p_bl_ids), 0) = 0 THEN
    RAISE EXCEPTION 'Nenhum B/L informado para o grupo.' USING ERRCODE = '22023';
  END IF;
  IF v_cnpj IS NULL OR NOT public.is_valid_cnpj(v_cnpj) THEN
    RAISE EXCEPTION 'Informe um CNPJ válido antes de vincular o grupo.' USING ERRCODE = '22023';
  END IF;
  IF v_name IS NULL THEN
    RAISE EXCEPTION 'Informe a razão social do cliente.' USING ERRCODE = '22023';
  END IF;
  IF v_email IS NULL OR v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'Informe um e-mail válido para o cliente.' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*)::INTEGER INTO v_requested_count
  FROM (
    SELECT b.id
    FROM public.bls AS b
    WHERE b.id = ANY(p_bl_ids)
      AND b.review_status = 'pending_review'
    ORDER BY b.id
    FOR UPDATE
  ) AS locked_bls;

  IF EXISTS (SELECT 1 FROM unnest(p_bl_ids) AS requested(id) WHERE requested.id IS NULL OR btrim(requested.id) = '')
     OR v_requested_count <> cardinality(p_bl_ids) THEN
    RAISE EXCEPTION 'Um ou mais B/Ls não estão mais pendentes de revisão.' USING ERRCODE = 'PT409';
  END IF;

  IF p_customer_id IS NOT NULL THEN
    SELECT * INTO v_customer FROM public.customers WHERE id = p_customer_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Cliente selecionado não foi encontrado.' USING ERRCODE = 'P0002';
    END IF;
    IF public.normalize_cnpj(v_customer.cnpj_cpf) IS DISTINCT FROM v_cnpj THEN
      RAISE EXCEPTION 'O CNPJ informado não corresponde ao cliente selecionado.' USING ERRCODE = '22023';
    END IF;
  ELSE
    SELECT * INTO v_customer FROM public.customers WHERE public.normalize_cnpj(cnpj_cpf) = v_cnpj FOR UPDATE;
    IF NOT FOUND THEN
      BEGIN
        INSERT INTO public.customers (cnpj_cpf, name)
        VALUES (v_cnpj, v_name)
        RETURNING * INTO v_customer;
      EXCEPTION WHEN unique_violation THEN
        SELECT * INTO v_customer FROM public.customers WHERE public.normalize_cnpj(cnpj_cpf) = v_cnpj FOR UPDATE;
        IF NOT FOUND THEN RAISE; END IF;
      END;
    END IF;
  END IF;

  FOR v_bl IN
    SELECT * FROM public.bls WHERE id = ANY(p_bl_ids) ORDER BY id FOR UPDATE
  LOOP
    v_candidates := public.review_bl_document_candidates(
      v_bl.manifest_customer_cnpj_cpf,
      v_bl.consignee_block,
      v_bl.cargo_description
    );

    -- Grupos sem evidência documental só podem reunir B/Ls do mesmo
    -- consignatário normalizado. Grupos com CNPJ são validados pelas
    -- evidências abaixo, sem exigir igualdade textual sujeita a ruído OCR.
    IF COALESCE(cardinality(v_candidates), 0) = 0 AND v_bl.customer_id IS NULL THEN
      v_bl_name_identity := lower(regexp_replace(btrim(COALESCE(v_bl.consignee, '')), '\s+', ' ', 'g'));
      IF v_bl_name_identity = '' THEN
        RAISE EXCEPTION 'O B/L % não possui CNPJ ou consignatário suficiente para validar o grupo.', v_bl.id USING ERRCODE = 'PT409';
      END IF;
      IF v_group_name_identity IS NULL THEN
        v_group_name_identity := v_bl_name_identity;
      ELSIF v_group_name_identity <> v_bl_name_identity THEN
        RAISE EXCEPTION 'Os B/Ls informados não pertencem ao mesmo grupo de consignatário.' USING ERRCODE = 'PT409';
      END IF;
    END IF;

    IF cardinality(v_candidates) > 1
       AND NOT (cardinality(p_bl_ids) = 1 AND v_cnpj = ANY(v_candidates)) THEN
      RAISE EXCEPTION 'O B/L % contém CNPJs conflitantes nas evidências.', v_bl.id USING ERRCODE = 'PT409';
    END IF;
    IF cardinality(v_candidates) = 1 AND v_cnpj <> v_candidates[1] THEN
      RAISE EXCEPTION 'O CNPJ do B/L % não corresponde ao grupo informado.', v_bl.id USING ERRCODE = 'PT409';
    END IF;
    IF v_bl.customer_id IS NOT NULL AND v_bl.customer_id <> v_customer.id THEN
      RAISE EXCEPTION 'O B/L % já está vinculado a outro cliente; corrija o vínculo individualmente.', v_bl.id USING ERRCODE = 'PT409';
    END IF;

    PERFORM public.ensure_customer_contact_email(v_customer.id, v_email);

    UPDATE public.bls
    SET customer_id = v_customer.id,
        customer_reconciliation_status = 'reconciled',
        customer_reconciliation_notes = 'Cliente cadastrado/vinculado pela revisão manual por grupo.',
        suggested_customer_id = NULL
    WHERE id = v_bl.id;

    INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
    VALUES ('bl', v_bl.id, 'customer_id', v_bl.customer_id::TEXT, v_customer.id::TEXT, v_actor,
            'Onboarding transacional de cliente pela revisão manual.');

    v_reasons := public.compute_bl_review_pendencies(v_bl.id);
    v_human_notes := btrim(
      regexp_replace(
        COALESCE(v_bl.notes, ''),
        E'(^|\\n)Pendencias de importacao:[^\\n]*$',
        '',
        'i'
      )
    );
    v_notes := CASE
      WHEN COALESCE(cardinality(v_reasons), 0) > 0 THEN concat_ws(
        E'\n',
        NULLIF(v_human_notes, ''),
        'Pendencias de importacao: ' || array_to_string(v_reasons, ', ')
      )
      ELSE NULLIF(v_human_notes, '')
    END;

    UPDATE public.bls
    SET review_status = CASE WHEN COALESCE(cardinality(v_reasons), 0) = 0 THEN 'reviewed' ELSE 'pending_review' END,
        notes = v_notes
    WHERE id = v_bl.id;

    PERFORM public.sync_customer_reconciliation_queue_for_bl(v_bl.id);

    IF COALESCE(cardinality(v_reasons), 0) > 0 THEN v_missing := v_missing + 1; END IF;
    v_bls := v_bls || jsonb_build_array(jsonb_build_object(
      'bl_id', v_bl.id,
      'review_status', CASE WHEN COALESCE(cardinality(v_reasons), 0) = 0 THEN 'reviewed' ELSE 'pending_review' END,
      'pendencias', to_jsonb(v_reasons),
      'resolved', COALESCE(cardinality(v_reasons), 0) = 0
    ));
  END LOOP;

  RETURN jsonb_build_object(
    'customer', jsonb_build_object('id', v_customer.id, 'cnpj_cpf', v_customer.cnpj_cpf, 'name', v_customer.name),
    'bls', v_bls,
    'pending_count', v_missing
  );
END;
$_$;



--
-- Name: compute_bl_review_pendencies(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_bl_review_pendencies(p_bl_id text) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl RECORD;
BEGIN
  SELECT customer_id, cargo_mode, bb_weight_ton
  INTO v_bl
  FROM public.bls
  WHERE id = p_bl_id;

  IF NOT FOUND THEN
    RETURN ARRAY[]::TEXT[];
  END IF;

  RETURN public.compute_bl_review_pendencies(
    v_bl.customer_id,
    v_bl.cargo_mode,
    v_bl.bb_weight_ton
  );
END;
$$;



--
-- Name: compute_bl_review_pendencies(bigint, text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_bl_review_pendencies(p_customer_id bigint, p_cargo_mode text, p_bb_weight_ton numeric) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reasons TEXT[] := ARRAY[]::TEXT[];
  v_has_email BOOLEAN := false;
BEGIN
  IF p_customer_id IS NULL THEN
    v_reasons := array_append(v_reasons, 'Cliente nao vinculado');
  ELSE
    SELECT EXISTS (
      SELECT 1
      FROM public.customer_contacts c
      WHERE c.customer_id = p_customer_id
        AND NULLIF(btrim(c.email), '') IS NOT NULL
    ) INTO v_has_email;

    IF NOT v_has_email THEN
      v_reasons := array_append(v_reasons, 'Cliente sem e-mail cadastrado');
    END IF;

    IF NOT public.customer_portal_access_ready(p_customer_id) THEN
      v_reasons := array_append(v_reasons, 'Acesso ao portal nao provisionado');
    END IF;
  END IF;

  IF p_cargo_mode = 'carga_solta'
     AND (p_bb_weight_ton IS NULL OR p_bb_weight_ton <= 0) THEN
    v_reasons := array_append(v_reasons, 'Peso BB ausente');
  END IF;

  RETURN v_reasons;
END;
$$;



--
-- Name: confirm_demurrage_pix_matches(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_demurrage_pix_matches(p_matches jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count integer := 0;
  r RECORD;
  v_roe NUMERIC(10,4);
BEGIN
  FOR r IN
    SELECT (m->>'invoice_id')::bigint AS invoice_id,
           (m->>'paid_at')::date      AS paid_at,
           NULLIF(m->>'pix_txid', '') AS pix_txid,
           (m->>'total_brl')::numeric AS total_brl,
           (m->>'ptax_used')::numeric AS ptax_used
    FROM jsonb_array_elements(p_matches) AS m
  LOOP
    v_roe := ROUND(COALESCE(r.ptax_used, 0) * 1.065, 4);

    UPDATE public.demurrage_invoices d
    SET status = 'paid',
        paid_at = r.paid_at,
        pix_txid = r.pix_txid,
        conciliated_by_extract = true,
        current_total_brl = COALESCE(r.total_brl, d.current_total_brl),
        current_roe = CASE WHEN v_roe > 0 THEN v_roe ELSE d.current_roe END
    WHERE d.id = r.invoice_id;

    IF FOUND THEN
      INSERT INTO public.demurrage_invoice_history
        (invoice_id, event_date, ptax_used, roe_used, total_usd, total_brl, discount_usd, source)
      SELECT d.id, r.paid_at,
             COALESCE(r.ptax_used, ROUND(d.current_roe / 1.065, 4)),
             COALESCE(NULLIF(v_roe, 0), d.current_roe),
             d.total_usd,
             COALESCE(r.total_brl, d.current_total_brl),
             GREATEST(0, ROUND(d.total_usd - COALESCE(r.total_brl, d.current_total_brl) / NULLIF(COALESCE(NULLIF(v_roe, 0), d.current_roe), 0), 2)),
             'payment'
      FROM public.demurrage_invoices d
      WHERE d.id = r.invoice_id;
      v_count := v_count + 1;
    END IF;
  END LOOP;
  RETURN v_count;
END;
$$;



--
-- Name: confirm_unified_pix_matches(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_unified_pix_matches(p_matches jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item RECORD;
  v_result JSONB;
  v_items JSONB := '[]'::jsonb;
  v_local_count INTEGER := 0;
  v_demurrage_count INTEGER := 0;
  v_demurrage_updates JSONB := '[]'::jsonb;
  v_updated_demurrage INTEGER := 0;
  v_paid_date DATE;
  v_match_brl NUMERIC;
  v_match_ptax NUMERIC;
BEGIN
  FOR v_item IN
    SELECT *
    FROM jsonb_to_recordset(p_matches) AS row(
      source TEXT,
      invoice_id BIGINT,
      doc_number TEXT,
      txid TEXT,
      amount NUMERIC,
      expected_amount NUMERIC,
      paid_at TIMESTAMPTZ
    )
  LOOP
    IF v_item.paid_at IS NULL THEN
      RAISE EXCEPTION 'Data do extrato nao parseada para %.', COALESCE(v_item.doc_number, v_item.txid, v_item.invoice_id::TEXT)
        USING ERRCODE = '22007';
    END IF;

    IF v_item.source = 'local' THEN
      v_result := public.reconcile_invoice_payment_by_txid(v_item.txid, v_item.amount, v_item.paid_at);
      IF COALESCE((v_result->>'matched')::BOOLEAN, false) IS NOT TRUE
         OR COALESCE((v_result->>'settled')::BOOLEAN, false) IS NOT TRUE THEN
        RAISE EXCEPTION 'Falha ao conciliar fatura local %: %.',
          COALESCE(v_item.doc_number, v_item.txid),
          COALESCE(v_result->>'reason', 'erro desconhecido')
          USING ERRCODE = 'P0001';
      END IF;
      v_local_count := v_local_count + 1;
      v_items := v_items || jsonb_build_array(jsonb_build_object(
        'source', 'local', 'invoice_id', v_item.invoice_id, 'doc_number', v_item.doc_number, 'status', 'ok'));

    ELSIF v_item.source = 'demurrage' THEN
      v_paid_date := (v_item.paid_at AT TIME ZONE 'UTC')::date;

      -- Janela das duas PTAX mais recentes com event_date <= data do pagamento.
      SELECT w.total_brl, w.ptax_used
      INTO v_match_brl, v_match_ptax
      FROM public.get_demurrage_recent_values(v_item.invoice_id, v_paid_date) AS w
      WHERE ABS(w.total_brl - COALESCE(v_item.amount, 0)) <= 0.01
      ORDER BY w.event_date DESC
      LIMIT 1;

      IF NOT FOUND THEN
        -- Fallback: sem histórico (legado) compara com o valor corrente.
        SELECT d.current_total_brl, ROUND(d.current_roe / 1.065, 4)
        INTO v_match_brl, v_match_ptax
        FROM public.demurrage_invoices d
        WHERE d.id = v_item.invoice_id
        FOR UPDATE;

        IF NOT FOUND THEN
          RAISE EXCEPTION 'Demurrage % nao encontrada.', v_item.doc_number USING ERRCODE = 'P0002';
        END IF;
        IF v_match_brl IS NULL OR ABS(v_match_brl - COALESCE(v_item.amount, 0)) > 0.01 THEN
          RAISE EXCEPTION 'Valor divergente para demurrage %.', v_item.doc_number USING ERRCODE = '22003';
        END IF;
      END IF;

      v_demurrage_updates := v_demurrage_updates || jsonb_build_array(jsonb_build_object(
        'invoice_id', v_item.invoice_id,
        'paid_at', v_paid_date,
        'pix_txid', v_item.txid,
        'total_brl', v_match_brl,
        'ptax_used', v_match_ptax));
      v_demurrage_count := v_demurrage_count + 1;
      v_items := v_items || jsonb_build_array(jsonb_build_object(
        'source', 'demurrage', 'invoice_id', v_item.invoice_id, 'doc_number', v_item.doc_number, 'status', 'ok'));
    ELSE
      RAISE EXCEPTION 'Origem de conciliacao PIX invalida: %.', v_item.source USING ERRCODE = '22023';
    END IF;
  END LOOP;

  IF v_demurrage_count > 0 THEN
    v_updated_demurrage := public.confirm_demurrage_pix_matches(v_demurrage_updates);
    IF v_updated_demurrage <> v_demurrage_count THEN
      RAISE EXCEPTION 'Conciliacao de demurrage atualizou % de % faturas.', v_updated_demurrage, v_demurrage_count
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RETURN jsonb_build_object('local', v_local_count, 'demurrage', v_demurrage_count, 'items', v_items);
END;
$$;



--
-- Name: count_alert_queue(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_alert_queue(p_filter text DEFAULT 'active'::text) RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count BIGINT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501'; END IF;
  IF p_filter NOT IN ('active', 'dismissed', 'all') THEN RAISE EXCEPTION 'Filtro inválido.' USING ERRCODE = '22023'; END IF;

  SELECT count(*) INTO v_count
  FROM (
    SELECT i.id
    FROM public.alerts a
    JOIN public.alert_items i ON i.alert_id = a.id AND i.status = 'active'
    LEFT JOIN LATERAL (
      SELECT ad.review_at
      FROM public.alert_item_dismissals ad
      WHERE ad.alert_item_id = i.id AND ad.occurrence_id = i.occurrence_id
      ORDER BY ad.dismissed_at DESC
      LIMIT 1
    ) d ON true
    WHERE a.status <> 'closed'
      AND (
        p_filter = 'all'
        OR (p_filter = 'dismissed' AND d.review_at > now())
        OR (p_filter = 'active' AND (d.review_at IS NULL OR d.review_at <= now()))
      )
    UNION ALL
    SELECT a.id
    FROM public.alerts a
    WHERE p_filter IN ('active', 'all')
      AND a.status <> 'closed'
      AND NOT EXISTS (SELECT 1 FROM public.alert_items i WHERE i.alert_id = a.id)
  ) queue_rows;

  RETURN v_count;
END;
$$;



--
-- Name: count_distinct_containers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_distinct_containers() RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COUNT(DISTINCT upper(trim(container_number)))
  FROM public.bl_containers;
$$;



--
-- Name: count_unread_internal_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_unread_internal_notifications() RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count BIGINT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;

  SELECT count(*) INTO v_count
  FROM public.internal_notifications
  WHERE recipient_id = auth.uid()
    AND read_at IS NULL;

  RETURN v_count;
END;
$$;



--
-- Name: create_customer_communication_atomic(bigint, text, text, bigint, text, uuid, bigint, integer, uuid, text, text, text, uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_customer_communication_atomic(p_customer_id bigint, p_kind text, p_nature text, p_anchor_voyage_id bigint DEFAULT NULL::bigint, p_anchor_port text DEFAULT NULL::text, p_anchor_atracacao_id uuid DEFAULT NULL::uuid, p_anchor_invoice_id bigint DEFAULT NULL::bigint, p_attempt_discriminator integer DEFAULT 0, p_dispatch_id uuid DEFAULT NULL::uuid, p_vessel_name text DEFAULT NULL::text, p_voyage_number text DEFAULT NULL::text, p_terminal_name text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_bl_ids text[] DEFAULT '{}'::text[]) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_communication_id BIGINT;
  v_requested_bls INTEGER := COALESCE(cardinality(p_bl_ids), 0);
  v_valid_bls INTEGER := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Executor server-only.' USING ERRCODE = '42501';
  END IF;

  IF p_attempt_discriminator < 0 THEN
    RAISE EXCEPTION 'O discriminador de tentativa nao pode ser negativo.' USING ERRCODE = '22023';
  END IF;

  IF p_kind IN ('aviso_chegada_noa', 'aviso_prontidao_nor', 'aviso_atracacao_nob')
     AND p_dispatch_id IS NOT NULL THEN
    RAISE EXCEPTION 'Avisos operacionais nao usam dispatch_id.' USING ERRCODE = '22023';
  END IF;

  IF p_kind IN ('institucional', 'livre')
     AND p_dispatch_id IS NULL THEN
    RAISE EXCEPTION 'Comunicado sem ancora exige dispatch_id.' USING ERRCODE = '22023';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.customers WHERE id = p_customer_id) THEN
    RAISE EXCEPTION 'Cliente nao encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.customer_communication_kinds
    WHERE kind = p_kind AND nature = p_nature
  ) THEN
    RAISE EXCEPTION 'Natureza invalida para o tipo de comunicado.' USING ERRCODE = '22023';
  END IF;

  IF v_requested_bls > 0 THEN
    IF p_kind = 'institucional' THEN
      RAISE EXCEPTION 'Comunicado institucional nao pode conter B/Ls.' USING ERRCODE = '22023';
    END IF;
    SELECT count(*)::INTEGER INTO v_valid_bls
    FROM public.bls
    WHERE id = ANY(p_bl_ids) AND customer_id = p_customer_id;
    IF v_valid_bls <> v_requested_bls THEN
      RAISE EXCEPTION 'B/L fora do cliente do comunicado.' USING ERRCODE = '42501';
    END IF;
  END IF;

  SELECT id
    INTO v_communication_id
  FROM public.customer_communications
  WHERE kind = p_kind
    AND customer_id = p_customer_id
    AND nature = p_nature
    AND anchor_voyage_id IS NOT DISTINCT FROM p_anchor_voyage_id
    AND anchor_port IS NOT DISTINCT FROM NULLIF(btrim(p_anchor_port), '')
    AND anchor_atracacao_id IS NOT DISTINCT FROM p_anchor_atracacao_id
    AND anchor_invoice_id IS NOT DISTINCT FROM p_anchor_invoice_id
    AND dispatch_id IS NOT DISTINCT FROM p_dispatch_id
    AND attempt_discriminator = p_attempt_discriminator
  ORDER BY id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_communication_id IS NULL THEN
    INSERT INTO public.customer_communications (
      customer_id, kind, nature,
      anchor_voyage_id, anchor_port, anchor_atracacao_id, anchor_invoice_id,
      attempt_discriminator, status, dispatch_id,
      vessel_name, voyage_number, terminal_name, created_by
    )
    VALUES (
      p_customer_id, p_kind, p_nature,
      p_anchor_voyage_id, NULLIF(btrim(p_anchor_port), ''),
      p_anchor_atracacao_id, p_anchor_invoice_id,
      p_attempt_discriminator, 'simulado', p_dispatch_id,
      NULLIF(btrim(p_vessel_name), ''), NULLIF(btrim(p_voyage_number), ''),
      NULLIF(btrim(p_terminal_name), ''), p_created_by
    )
    RETURNING id INTO v_communication_id;
  END IF;

  IF v_requested_bls > 0 THEN
    INSERT INTO public.customer_communication_bls (communication_id, bl_id)
    SELECT v_communication_id, value
    FROM unnest(p_bl_ids) AS requested(value)
    ON CONFLICT DO NOTHING;
  END IF;

  RETURN v_communication_id;
END;
$$;



--
-- Name: create_customer_with_contacts(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_customer_with_contacts(p_customer jsonb, p_contacts jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_customer public.customers%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Credenciais invalidas para criar cliente.' USING ERRCODE = '42501';
  END IF;

  IF jsonb_typeof(p_customer) <> 'object'
     OR jsonb_typeof(p_contacts) <> 'array'
     OR NULLIF(BTRIM(p_customer->>'cnpj_cpf'), '') IS NULL
     OR NULLIF(BTRIM(p_customer->>'name'), '') IS NULL THEN
    RAISE EXCEPTION 'Cadastro de cliente invalido.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.customers (
    cnpj_cpf, name, trade_name, address, city, state, zip, notes
  )
  VALUES (
    BTRIM(p_customer->>'cnpj_cpf'),
    BTRIM(p_customer->>'name'),
    NULLIF(BTRIM(p_customer->>'trade_name'), ''),
    NULLIF(BTRIM(p_customer->>'address'), ''),
    NULLIF(BTRIM(p_customer->>'city'), ''),
    NULLIF(BTRIM(p_customer->>'state'), ''),
    NULLIF(BTRIM(p_customer->>'zip'), ''),
    NULLIF(BTRIM(p_customer->>'notes'), '')
  )
  RETURNING * INTO v_customer;

  INSERT INTO public.customer_contacts (
    customer_id, name, email, phone, purpose, is_primary
  )
  SELECT
    v_customer.id,
    BTRIM(contact.name),
    NULLIF(BTRIM(contact.email), ''),
    NULLIF(BTRIM(contact.phone), ''),
    COALESCE(NULLIF(BTRIM(contact.purpose), ''), 'geral'),
    COALESCE(contact.is_primary, false)
  FROM jsonb_to_recordset(p_contacts) AS contact(
    name TEXT,
    email TEXT,
    phone TEXT,
    purpose TEXT,
    is_primary BOOLEAN
  )
  WHERE NULLIF(BTRIM(contact.name), '') IS NOT NULL;

  RETURN to_jsonb(v_customer);
END;
$$;



--
-- Name: create_demurrage_invoice_with_items(text, text, bigint, numeric, date, boolean, numeric, numeric, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_demurrage_invoice_with_items(p_doc_number text, p_bl_id text, p_customer_id bigint, p_total_usd numeric, p_ready_at date, p_roe_manual boolean, p_roe numeric, p_current_roe numeric, p_roe_source text, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice_id BIGINT;
  v_customer_id BIGINT;
  v_item_count INTEGER;
  v_invalid_container_count INTEGER;
  v_inconsistent_item_count INTEGER;
  v_item_total NUMERIC(14,2);
  v_total_brl NUMERIC(14,2);
  v_pix_payload TEXT;
  v_ptax NUMERIC(10,4);
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(TRIM(COALESCE(p_doc_number, '')), '') IS NULL
     OR NULLIF(TRIM(COALESCE(p_bl_id, '')), '') IS NULL
     OR p_customer_id IS NULL
     OR COALESCE(p_total_usd, 0) <= 0
     OR p_current_roe IS NULL OR p_current_roe <= 0
     OR p_roe_source NOT IN ('bcb_live', 'cached', 'manual')
     OR jsonb_typeof(p_items) <> 'array'
     OR jsonb_array_length(p_items) = 0 THEN
    RAISE EXCEPTION 'Dados invalidos para criar invoice de Demurrage.' USING ERRCODE = '22023';
  END IF;

  SELECT b.customer_id
  INTO v_customer_id
  FROM public.bls b
  WHERE b.id = p_bl_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado.', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.demurrage_invoices di
    WHERE di.bl_id = p_bl_id AND di.status IN ('issued', 'paid')
  ) THEN
    RAISE EXCEPTION 'Ja existe fatura de Demurrage emitida ou paga para o B/L %. Cancele a fatura atual antes de reemitir.', p_bl_id
      USING ERRCODE = '23505';
  END IF;

  IF v_customer_id IS DISTINCT FROM p_customer_id THEN
    RAISE EXCEPTION 'Cliente informado nao corresponde ao cliente do B/L %.', p_bl_id USING ERRCODE = '22023';
  END IF;

  SELECT
    COUNT(*)::INTEGER,
    COUNT(*) FILTER (WHERE bc.id IS NULL OR bc.bl_id IS DISTINCT FROM p_bl_id)::INTEGER,
    COUNT(*) FILTER (
      WHERE item.discharge_date IS NULL
         OR item.return_date IS NULL
         OR item.return_date < item.discharge_date
         OR COALESCE(item.total_days, -1) <> (item.return_date - item.discharge_date)
         OR COALESCE(item.free_days, -1) < 0
         OR COALESCE(item.days_p1, -1) < 0
         OR COALESCE(item.days_p2, -1) < 0
         OR COALESCE(item.rate_p1_usd, -1) < 0
         OR COALESCE(item.rate_p2_usd, -1) < 0
         OR item.days_p1 + item.days_p2 > GREATEST(item.total_days - item.free_days, 0)
         OR ABS(COALESCE(item.subtotal_usd, -1)
                - (item.days_p1 * item.rate_p1_usd + item.days_p2 * item.rate_p2_usd)) > 0.01
    )::INTEGER,
    COALESCE(SUM(item.subtotal_usd), 0)
  INTO v_item_count, v_invalid_container_count, v_inconsistent_item_count, v_item_total
  FROM jsonb_to_recordset(p_items) AS item(
    container_id BIGINT,
    container_number TEXT,
    container_type TEXT,
    discharge_date DATE,
    return_date DATE,
    total_days INTEGER,
    free_days INTEGER,
    days_p1 INTEGER,
    rate_p1_usd NUMERIC,
    days_p2 INTEGER,
    rate_p2_usd NUMERIC,
    subtotal_usd NUMERIC
  )
  LEFT JOIN public.bl_containers bc ON bc.id = item.container_id;

  IF v_item_count = 0 OR v_invalid_container_count > 0 THEN
    RAISE EXCEPTION 'Itens de Demurrage invalidos para o B/L %.', p_bl_id USING ERRCODE = '22023';
  END IF;

  IF v_inconsistent_item_count > 0 THEN
    RAISE EXCEPTION 'Calculo de Demurrage inconsistente em % item(ns) do B/L %.', v_inconsistent_item_count, p_bl_id
      USING ERRCODE = '22023';
  END IF;

  IF ABS(v_item_total - p_total_usd) > 0.01 THEN
    RAISE EXCEPTION 'Total dos itens diverge do total da invoice de Demurrage.' USING ERRCODE = '22023';
  END IF;

  -- Sem desconto na criação (descontos são aplicados depois, em USD).
  v_total_brl := ROUND(p_total_usd * p_current_roe, 2);
  v_pix_payload := public.build_transshipping_pix_payload(v_total_brl, TRIM(p_doc_number));
  v_ptax := ROUND(p_current_roe / 1.065, 4);

  INSERT INTO public.demurrage_invoices (
    doc_number, bl_id, customer_id, total_usd, ready_at,
    roe_manual, roe, status, billed_at, first_billed_at,
    current_roe, current_total_brl, roe_source, pix_payload
  )
  VALUES (
    TRIM(p_doc_number), p_bl_id, p_customer_id, p_total_usd, p_ready_at,
    COALESCE(p_roe_manual, false), p_roe, 'issued', CURRENT_DATE, CURRENT_DATE,
    p_current_roe, v_total_brl, p_roe_source, v_pix_payload
  )
  RETURNING id INTO v_invoice_id;

  INSERT INTO public.demurrage_invoice_items (
    invoice_id, container_id, container_number, container_type,
    discharge_date, return_date, total_days, free_days,
    days_p1, rate_p1_usd, days_p2, rate_p2_usd, subtotal_usd
  )
  SELECT
    v_invoice_id, item.container_id, item.container_number, item.container_type,
    item.discharge_date, item.return_date, item.total_days, item.free_days,
    item.days_p1, item.rate_p1_usd, item.days_p2, item.rate_p2_usd, item.subtotal_usd
  FROM jsonb_to_recordset(p_items) AS item(
    container_id BIGINT,
    container_number TEXT,
    container_type TEXT,
    discharge_date DATE,
    return_date DATE,
    total_days INTEGER,
    free_days INTEGER,
    days_p1 INTEGER,
    rate_p1_usd NUMERIC,
    days_p2 INTEGER,
    rate_p2_usd NUMERIC,
    subtotal_usd NUMERIC
  );

  -- Foto inicial de histórico (source conforme a origem da PTAX na emissão).
  INSERT INTO public.demurrage_invoice_history
    (invoice_id, event_date, ptax_used, roe_used, total_usd, total_brl, discount_usd, source)
  VALUES
    (v_invoice_id, CURRENT_DATE, v_ptax, p_current_roe, p_total_usd, v_total_brl, 0, p_roe_source);

  RETURN jsonb_build_object('invoice_id', v_invoice_id);
END;
$$;



--
-- Name: create_invoice_from_bls(text[], bigint, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_from_bls(p_bl_ids text[], p_customer_id bigint DEFAULT NULL::bigint, p_notes text DEFAULT NULL::text, p_issue_now boolean DEFAULT true, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  RETURN public.create_invoice_from_bls_core(
    p_bl_ids,
    p_customer_id,
    p_notes,
    p_issue_now,
    COALESCE(p_actor, auth.uid()),
    'internal',
    NULL
  );
END;
$$;



--
-- Name: create_invoice_from_bls_core(text[], bigint, text, boolean, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_from_bls_core(p_bl_ids text[], p_customer_id bigint, p_notes text DEFAULT NULL::text, p_issue_now boolean DEFAULT true, p_actor uuid DEFAULT NULL::uuid, p_origin text DEFAULT 'internal'::text, p_portal_account_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_requested_bls TEXT[];
  v_bl_count INTEGER;
  v_missing_bls TEXT;
  v_customer_id BIGINT;
  v_max_customer_id BIGINT;
  v_conflict_count INTEGER;
  v_usd_count INTEGER;
  v_invoice_id BIGINT;
  v_invoice_number TEXT;
  v_total_brl NUMERIC(14,2);
  v_item_count INTEGER;
  v_status TEXT;
  v_batch_id BIGINT;
  v_roe NUMERIC(10,4);
  v_roe_effective_date DATE;
BEGIN
  v_status := CASE WHEN COALESCE(p_issue_now, true) THEN 'issued' ELSE 'draft' END;

  SELECT ARRAY_AGG(DISTINCT UPPER(TRIM(bl_id)) ORDER BY UPPER(TRIM(bl_id)))
  INTO v_requested_bls
  FROM UNNEST(COALESCE(p_bl_ids, ARRAY[]::TEXT[])) AS input(bl_id)
  WHERE TRIM(COALESCE(bl_id, '')) <> '';

  IF COALESCE(ARRAY_LENGTH(v_requested_bls, 1), 0) = 0 THEN
    RAISE EXCEPTION 'Nenhum B/L informado para emissao.' USING ERRCODE = '22023';
  END IF;

  PERFORM 1
  FROM public.bls
  WHERE id = ANY(v_requested_bls)
  FOR UPDATE;

  SELECT COUNT(*) INTO v_bl_count
  FROM public.bls
  WHERE id = ANY(v_requested_bls);

  IF v_bl_count <> ARRAY_LENGTH(v_requested_bls, 1) THEN
    SELECT STRING_AGG(req.bl_id, ', ' ORDER BY req.bl_id)
    INTO v_missing_bls
    FROM UNNEST(v_requested_bls) AS req(bl_id)
    LEFT JOIN public.bls AS b ON b.id = req.bl_id
    WHERE b.id IS NULL;

    RAISE EXCEPTION 'B/L(s) nao encontrado(s): %', COALESCE(v_missing_bls, '-')
      USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.bls AS b
    WHERE b.id = ANY(v_requested_bls)
      AND COALESCE(b.charge_status, 'not_calculated') <> 'ready_for_billing'
  ) THEN
    RAISE EXCEPTION 'Todos os B/Ls devem estar como ready_for_billing.' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.bls AS b
    WHERE b.id = ANY(v_requested_bls)
      AND COALESCE(b.financial_status, 'pending') <> 'pending'
  ) THEN
    RAISE EXCEPTION 'Existe B/L ja faturado/pago/cancelado na selecao.' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.bls AS b
    WHERE b.id = ANY(v_requested_bls)
      AND (b.customer_id IS NULL OR COALESCE(b.customer_reconciliation_status, 'missing_customer') NOT IN ('matched_document', 'reconciled'))
  ) THEN
    RAISE EXCEPTION 'Todos os B/Ls precisam de cliente reconciliado para faturar.' USING ERRCODE = '22023';
  END IF;

  SELECT MIN(b.customer_id), MAX(b.customer_id)
  INTO v_customer_id, v_max_customer_id
  FROM public.bls AS b
  WHERE b.id = ANY(v_requested_bls);

  IF v_customer_id IS NULL OR v_customer_id <> v_max_customer_id THEN
    RAISE EXCEPTION 'Selecao contem B/Ls de clientes diferentes.' USING ERRCODE = '22023';
  END IF;

  IF p_customer_id IS NOT NULL AND p_customer_id <> v_customer_id THEN
    RAISE EXCEPTION 'Cliente informado nao corresponde aos B/Ls selecionados.' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*)
  INTO v_conflict_count
  FROM public.invoice_bls AS ib
  JOIN public.invoices AS inv ON inv.id = ib.invoice_id
  WHERE ib.bl_id = ANY(v_requested_bls)
    AND COALESCE(inv.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue');

  IF v_conflict_count > 0 THEN
    RAISE EXCEPTION 'Existe B/L vinculado a invoice ativa.' USING ERRCODE = '23505';
  END IF;

  SELECT COUNT(*)
  INTO v_usd_count
  FROM public.charge_calculations AS cc
  WHERE cc.bl_id = ANY(v_requested_bls)
    AND COALESCE(cc.total_value_usd, 0) > 0
    AND COALESCE(cc.status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing');

  IF v_usd_count > 0 THEN
    SELECT roe, effective_date INTO v_roe, v_roe_effective_date
    FROM public.exchange_rate_reference WHERE id = 1;

    IF v_roe IS NULL THEN
      RAISE EXCEPTION 'Cambio (ROE) nao configurado; nao e possivel converter linhas em USD para emitir a fatura.' USING ERRCODE = '22023';
    END IF;
  END IF;

  IF ARRAY_LENGTH(v_requested_bls, 1) > 1 THEN
    INSERT INTO public.billing_batches (
      customer_id,
      origin,
      status,
      notes,
      requested_by,
      portal_account_id
    )
    VALUES (
      v_customer_id,
      COALESCE(p_origin, 'internal'),
      'requested',
      NULLIF(TRIM(COALESCE(p_notes, '')), ''),
      p_actor,
      p_portal_account_id
    )
    RETURNING id INTO v_batch_id;
  END IF;

  INSERT INTO public.invoices (
    customer_id,
    bl_id,
    issued_at,
    total_brl,
    status,
    notes,
    total_paid_brl,
    balance_brl,
    issued_by
  )
  VALUES (
    v_customer_id,
    CASE WHEN ARRAY_LENGTH(v_requested_bls, 1) = 1 THEN v_requested_bls[1] ELSE NULL END,
    CASE WHEN v_status = 'issued' THEN now() ELSE NULL END,
    0,
    v_status,
    NULLIF(TRIM(COALESCE(p_notes, '')), ''),
    0,
    0,
    p_actor
  )
  RETURNING id, invoice_number
  INTO v_invoice_id, v_invoice_number;

  INSERT INTO public.invoice_bls (
    invoice_id,
    bl_id,
    charge_status_snapshot,
    financial_status_snapshot,
    subtotal_brl,
    subtotal_usd
  )
  SELECT
    v_invoice_id,
    b.id,
    b.charge_status,
    b.financial_status,
    COALESCE(calc.total_brl, 0),
    COALESCE(calc.total_usd, 0)
  FROM public.bls AS b
  LEFT JOIN (
    -- Bug da review da PR 501 (achado 1): subtotal_brl precisa somar o MESMO
    -- valor convertido que alimenta invoice_items/invoices.total_brl (mesma
    -- conversao USD->BRL feita no INSERT de invoice_items abaixo), e nao
    -- apenas cc.total_value_brl -- que fica NULL para linhas em USD e
    -- deixava o subtotal do B/L zerado/nulo mesmo com fatura cobrando valor
    -- convertido. link_invoice_to_ledger usa esse subtotal para sobrescrever
    -- bl_receivables.original_amount_brl, entao um subtotal errado aqui
    -- zerava o receivable de B/Ls 100% em USD.
    SELECT
      cc.bl_id,
      SUM(COALESCE(cc.total_value_brl, CASE WHEN COALESCE(cti.currency, 'BRL') = 'USD' THEN ROUND(COALESCE(cc.total_value_usd, 0) * v_roe, 2) END, 0)) AS total_brl,
      SUM(COALESCE(cc.total_value_usd, 0)) AS total_usd
    FROM public.charge_calculations AS cc
    LEFT JOIN public.charge_table_items AS cti ON cti.id = cc.charge_item_id
    WHERE cc.bl_id = ANY(v_requested_bls)
      AND COALESCE(cc.status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing', 'exempt')
    GROUP BY cc.bl_id
  ) AS calc ON calc.bl_id = b.id
  WHERE b.id = ANY(v_requested_bls);

  INSERT INTO public.invoice_items (
    invoice_id,
    charge_calculation_id,
    description,
    quantity,
    unit_value_brl,
    total_value_brl,
    bl_id,
    manifest_id,
    charge_table_id,
    charge_item_id,
    source,
    currency,
    unit_value_usd,
    total_value_usd,
    pricing_rule_version_id,
    billing_run_id,
    calculation_key,
    snapshot_payload
  )
  SELECT
    v_invoice_id,
    cc.id,
    CONCAT('BL ', cc.bl_id, ' - ', COALESCE(cti.name, cc.calculation_key, 'Linha de taxa')),
    COALESCE(cc.quantity, 1),
    COALESCE(cc.unit_value_brl, CASE WHEN COALESCE(cti.currency, 'BRL') = 'USD' THEN ROUND(COALESCE(cc.unit_value_usd, 0) * v_roe, 2) END, 0),
    COALESCE(cc.total_value_brl, CASE WHEN COALESCE(cti.currency, 'BRL') = 'USD' THEN ROUND(COALESCE(cc.total_value_usd, 0) * v_roe, 2) END, 0),
    cc.bl_id,
    cc.manifest_id,
    cc.charge_table_id,
    cc.charge_item_id,
    cc.source,
    COALESCE(cti.currency, CASE WHEN COALESCE(cc.total_value_usd, 0) > 0 THEN 'USD' ELSE 'BRL' END),
    cc.unit_value_usd,
    cc.total_value_usd,
    cc.pricing_rule_version_id,
    cc.billing_run_id,
    cc.calculation_key,
    jsonb_build_object(
      'manifest_id', cc.manifest_id,
      'bl_id', cc.bl_id,
      'charge_table_id', cc.charge_table_id,
      'charge_item_id', cc.charge_item_id,
      'source', cc.source,
      'currency', COALESCE(cti.currency, CASE WHEN COALESCE(cc.total_value_usd, 0) > 0 THEN 'USD' ELSE 'BRL' END),
      'pricing_rule_version_id', cc.pricing_rule_version_id,
      'calculation_key', cc.calculation_key,
      'charge_name', cti.name,
      'roe', CASE WHEN COALESCE(cti.currency, 'BRL') = 'USD' THEN v_roe ELSE NULL END,
      'roe_effective_date', CASE WHEN COALESCE(cti.currency, 'BRL') = 'USD' THEN v_roe_effective_date ELSE NULL END
    )
  FROM public.charge_calculations AS cc
  LEFT JOIN public.charge_table_items AS cti ON cti.id = cc.charge_item_id
  WHERE cc.bl_id = ANY(v_requested_bls)
    AND (COALESCE(cc.total_value_brl, 0) > 0 OR COALESCE(cc.total_value_usd, 0) > 0)
    AND COALESCE(cc.status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing', 'exempt');

  GET DIAGNOSTICS v_item_count = ROW_COUNT;

  IF v_item_count = 0 THEN
    RAISE EXCEPTION 'Nenhuma linha BRL elegivel para faturamento.' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(SUM(total_value_brl), 0)
  INTO v_total_brl
  FROM public.invoice_items
  WHERE invoice_id = v_invoice_id;

  UPDATE public.invoices
  SET
    total_brl = v_total_brl,
    total_paid_brl = 0,
    balance_brl = v_total_brl
  WHERE id = v_invoice_id;

  IF v_status = 'issued' THEN
    UPDATE public.bls
    SET financial_status = 'invoiced'
    WHERE id = ANY(v_requested_bls);
  END IF;

  IF v_batch_id IS NOT NULL THEN
    UPDATE public.billing_batches
    SET
      status = CASE WHEN v_status = 'issued' THEN 'issued' ELSE 'requested' END,
      invoice_id = v_invoice_id,
      notes = NULLIF(TRIM(COALESCE(p_notes, '')), '')
    WHERE id = v_batch_id;
  END IF;

  INSERT INTO public.audit_logs (
    entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification
  )
  VALUES (
    'invoice',
    v_invoice_id::TEXT,
    'create_invoice',
    NULL,
    CONCAT('invoice=', v_invoice_number, ' | bl_count=', ARRAY_LENGTH(v_requested_bls, 1), ' | total=', v_total_brl),
    p_actor,
    now(),
    CASE WHEN COALESCE(p_origin, 'internal') = 'portal' THEN 'Emissao consolidada via portal do cliente' ELSE 'Emissao de invoice por B/L' END
  );

  RETURN jsonb_build_object(
    'invoice_id', v_invoice_id,
    'invoice_number', v_invoice_number,
    'status', v_status,
    'customer_id', v_customer_id,
    'bl_count', ARRAY_LENGTH(v_requested_bls, 1),
    'total_brl', v_total_brl,
    'balance_brl', v_total_brl,
    'billing_batch_id', v_batch_id
  );
END;
$$;



--
-- Name: create_invoice_from_bls_with_ledger(text[], bigint, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_from_bls_with_ledger(p_bl_ids text[], p_customer_id bigint DEFAULT NULL::bigint, p_notes text DEFAULT NULL::text, p_issue_now boolean DEFAULT true, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
  v_invoice_id BIGINT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  v_result := public.create_invoice_from_bls_core(
    p_bl_ids,
    p_customer_id,
    p_notes,
    p_issue_now,
    COALESCE(p_actor, auth.uid()),
    'internal',
    NULL
  );

  v_invoice_id := (v_result->>'invoice_id')::BIGINT;
  IF v_invoice_id IS NULL THEN
    RAISE EXCEPTION 'Falha ao criar invoice para B/Ls.' USING ERRCODE = 'P0001';
  END IF;

  PERFORM public.link_invoice_to_ledger(v_invoice_id);

  RETURN v_result;
END;
$$;



--
-- Name: create_invoice_from_granite_bls(uuid[], bigint, text, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_invoice_from_granite_bls(p_granite_bl_ids uuid[], p_customer_id bigint DEFAULT NULL::bigint, p_notes text DEFAULT NULL::text, p_issue_now boolean DEFAULT true, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION 'Granito não participa do faturamento financeiro.' USING ERRCODE = 'PT409';
END;
$$;



--
-- Name: create_local_consolidated_invoice(bigint, bigint[], text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_local_consolidated_invoice(p_customer_id bigint, p_receivable_ids bigint[], p_notes text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor UUID;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  RETURN public.create_local_consolidated_invoice_core(
    p_customer_id,
    p_receivable_ids,
    v_actor,
    'internal'
  );
END;
$$;



--
-- Name: create_local_consolidated_invoice_core(bigint, bigint[], uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_local_consolidated_invoice_core(p_customer_id bigint, p_receivable_ids bigint[], p_actor uuid DEFAULT NULL::uuid, p_origin text DEFAULT 'internal'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ids BIGINT[];
  v_count INTEGER;
  v_invoice_id BIGINT;
  v_invoice_number TEXT;
  v_total NUMERIC(14,2);
  v_missing_roe_count INTEGER;
BEGIN
  SELECT ARRAY_AGG(DISTINCT id ORDER BY id)
  INTO v_ids
  FROM UNNEST(COALESCE(p_receivable_ids, ARRAY[]::BIGINT[])) AS u(id)
  WHERE id IS NOT NULL;

  IF COALESCE(ARRAY_LENGTH(v_ids, 1), 0) < 1 THEN
    RAISE EXCEPTION 'Nenhum receivable informado para consolidar.' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.bl_receivables WHERE id = ANY(v_ids) ORDER BY id FOR UPDATE;

  SELECT COUNT(*) INTO v_count FROM public.bl_receivables WHERE id = ANY(v_ids);
  IF v_count <> ARRAY_LENGTH(v_ids, 1) THEN
    RAISE EXCEPTION 'Receivable(s) inexistente(s) na selecao.' USING ERRCODE = 'P0002';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.bl_receivables WHERE id = ANY(v_ids) AND customer_id <> p_customer_id
  ) THEN
    RAISE EXCEPTION 'Selecao contem receivables de clientes diferentes.' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.bl_receivables
    WHERE id = ANY(v_ids) AND (status NOT IN ('open', 'partially_settled') OR balance_brl <= 0)
  ) THEN
    RAISE EXCEPTION 'Todos os receivables precisam estar abertos com saldo positivo.' USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.invoice_receivable_links l
    JOIN public.invoices inv ON inv.id = l.invoice_id
    WHERE l.receivable_id = ANY(v_ids)
      AND inv.invoice_type = 'consolidated'
      AND COALESCE(inv.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue')
  ) THEN
    RAISE EXCEPTION 'Um ou mais B/Ls ja estao em consolidada aberta.' USING ERRCODE = '23505';
  END IF;

  SELECT COALESCE(SUM(balance_brl), 0) INTO v_total
  FROM public.bl_receivables WHERE id = ANY(v_ids);

  INSERT INTO public.invoices (
    customer_id, bl_id, issued_at, total_brl, status, invoice_type,
    notes, total_paid_brl, balance_brl, issued_by
  )
  VALUES (
    p_customer_id, NULL, now(), v_total, 'issued', 'consolidated',
    NULL, 0, v_total, p_actor
  )
  RETURNING id, invoice_number INTO v_invoice_id, v_invoice_number;

  INSERT INTO public.invoice_receivable_links (invoice_id, receivable_id, bl_id, subtotal_brl, status, bl_snapshot)
  SELECT
    v_invoice_id, br.id, br.bl_id, br.balance_brl, 'active',
    jsonb_build_object('bl_id', br.bl_id, 'voyage_id', br.voyage_id, 'cargo_mode', br.cargo_mode, 'pol', br.pol, 'pod', br.pod)
  FROM public.bl_receivables br
  WHERE br.id = ANY(v_ids);

  -- Achado 4 da review da PR 501: garante que todo receivable USD selecionado
  -- tem ROE congelado antes de montar o detalhamento (evita usar um ROE
  -- global "current" como fallback silencioso).
  SELECT COUNT(*)
  INTO v_missing_roe_count
  FROM public.bl_receivables br
  JOIN public.charge_calculations cc ON cc.bl_id = br.bl_id
  LEFT JOIN public.charge_table_items cti ON cti.id = cc.charge_item_id
  WHERE br.id = ANY(v_ids)
    AND br.roe_frozen IS NULL
    AND COALESCE(cti.currency, 'BRL') = 'USD'
    AND COALESCE(cc.total_value_usd, 0) > 0
    AND COALESCE(cc.status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing', 'exempt');

  IF v_missing_roe_count > 0 THEN
    RAISE EXCEPTION 'Um ou mais receivables selecionados nao tem ROE congelado para linhas em USD; recalcule/atualize o B/L antes de consolidar.' USING ERRCODE = '22023';
  END IF;

  WITH links AS (
    SELECT l.bl_id, l.subtotal_brl, br.roe_frozen, br.roe_effective_date_frozen
    FROM public.invoice_receivable_links l
    JOIN public.bl_receivables br ON br.id = l.receivable_id
    WHERE l.invoice_id = v_invoice_id
  ),
  calcs AS (
    SELECT
      cc.bl_id, cc.id AS charge_calculation_id, cc.charge_table_id, cc.charge_item_id,
      cc.quantity,
      COALESCE(cc.unit_value_brl, CASE WHEN COALESCE(cti.currency, 'BRL') = 'USD' THEN ROUND(COALESCE(cc.unit_value_usd, 0) * links.roe_frozen, 2) END) AS unit_value_brl,
      COALESCE(cc.total_value_brl, CASE WHEN COALESCE(cti.currency, 'BRL') = 'USD' THEN ROUND(COALESCE(cc.total_value_usd, 0) * links.roe_frozen, 2) END, 0) AS total_value_brl,
      cti.currency,
      cc.unit_value_usd, cc.total_value_usd, cc.calculation_key, cti.name AS charge_name,
      links.roe_frozen, links.roe_effective_date_frozen
    FROM public.charge_calculations cc
    JOIN links ON links.bl_id = cc.bl_id
    LEFT JOIN public.charge_table_items cti ON cti.id = cc.charge_item_id
    WHERE (COALESCE(cc.total_value_brl, 0) > 0 OR COALESCE(cc.total_value_usd, 0) > 0)
      AND COALESCE(cc.status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing', 'exempt')
  ),
  bl_recon AS (
    SELECT links.bl_id, links.subtotal_brl,
      COUNT(calcs.charge_calculation_id) AS calc_count,
      COALESCE(SUM(calcs.total_value_brl), 0) AS detailed_sum
    FROM links
    LEFT JOIN calcs ON calcs.bl_id = links.bl_id
    GROUP BY links.bl_id, links.subtotal_brl
  )
  INSERT INTO public.invoice_items (
    invoice_id, charge_calculation_id, description, quantity, unit_value_brl,
    total_value_brl, bl_id, charge_table_id, charge_item_id, source, currency,
    unit_value_usd, total_value_usd, calculation_key, snapshot_payload
  )
  SELECT
    v_invoice_id, calcs.charge_calculation_id,
    CONCAT('BL ', calcs.bl_id, ' - ', COALESCE(calcs.charge_name, calcs.calculation_key, 'Linha de taxa')),
    COALESCE(calcs.quantity, 1), calcs.unit_value_brl, calcs.total_value_brl,
    calcs.bl_id, calcs.charge_table_id, calcs.charge_item_id, 'ledger',
    COALESCE(calcs.currency, 'BRL'), calcs.unit_value_usd, calcs.total_value_usd,
    calcs.calculation_key,
    jsonb_build_object(
      'reconciled', true,
      'roe', CASE WHEN COALESCE(calcs.currency, 'BRL') = 'USD' THEN calcs.roe_frozen ELSE NULL END,
      'roe_effective_date', CASE WHEN COALESCE(calcs.currency, 'BRL') = 'USD' THEN calcs.roe_effective_date_frozen ELSE NULL END
    )
  FROM calcs
  JOIN bl_recon ON bl_recon.bl_id = calcs.bl_id
  WHERE bl_recon.calc_count > 0 AND ABS(bl_recon.detailed_sum - bl_recon.subtotal_brl) < 0.01
  UNION ALL
  SELECT
    v_invoice_id, NULL, CONCAT('BL ', bl_recon.bl_id, ' - Taxas locais'),
    1, bl_recon.subtotal_brl, bl_recon.subtotal_brl,
    bl_recon.bl_id, NULL, NULL, 'ledger', 'BRL', NULL, NULL, NULL,
    jsonb_build_object('reconciled', false)
  FROM bl_recon
  WHERE NOT (bl_recon.calc_count > 0 AND ABS(bl_recon.detailed_sum - bl_recon.subtotal_brl) < 0.01);

  INSERT INTO public.invoice_lifecycle_events (invoice_id, event_type, actor, payload)
  VALUES (v_invoice_id, 'issued', p_actor,
    jsonb_build_object('invoice_type', 'consolidated', 'receivable_count', ARRAY_LENGTH(v_ids, 1), 'total_brl', v_total, 'origin', COALESCE(p_origin, 'internal')));

  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification)
  VALUES ('invoice', v_invoice_id::TEXT, 'create_consolidated', NULL,
    CONCAT('invoice=', v_invoice_number, ' | receivables=', ARRAY_LENGTH(v_ids, 1), ' | total=', v_total),
    p_actor, now(),
    CASE WHEN COALESCE(p_origin, 'internal') = 'portal' THEN 'Emissao de consolidada via portal do cliente' ELSE 'Emissao de consolidada via ledger' END);

  RETURN jsonb_build_object(
    'invoice_id', v_invoice_id,
    'invoice_number', v_invoice_number,
    'status', 'issued',
    'invoice_type', 'consolidated',
    'receivable_count', ARRAY_LENGTH(v_ids, 1),
    'total_brl', v_total
  );
END;
$$;



--
-- Name: create_manual_vazios_booking(uuid, bigint, uuid, text, text, uuid, text, date, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_manual_vazios_booking(p_operation_id uuid, p_voyage_id bigint, p_uploaded_by uuid, p_container_number text, p_container_type text, p_local_id uuid, p_condition text, p_hand_in_date date, p_hand_out_date date, p_movement_date date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_manifest_id UUID;
  v_booking_id UUID;
BEGIN
  IF auth.uid() IS NULL OR NOT (public.is_active_user() OR public.is_active_user())
     OR p_uploaded_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para incluir unidade.' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.vazios_export_operations
    WHERE id = p_operation_id AND voyage_id = p_voyage_id
  ) THEN
    RAISE EXCEPTION 'Unidade deve pertencer a uma operacao da mesma viagem.' USING ERRCODE = '22023';
  END IF;
  IF upper(btrim(COALESCE(p_container_number, ''))) !~ '^[A-Z]{4}[0-9]{7}$' THEN
    RAISE EXCEPTION 'Container invalido.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.vazios_manifests (voyage_id, description, total_bookings, imported_by)
  VALUES (p_voyage_id, 'Inclusao manual no Embarque de Vazios', 1, p_uploaded_by)
  RETURNING id INTO v_manifest_id;

  INSERT INTO public.vazios_bookings (
    voyage_id, operation_id, manifest_id, container_number, container_type,
    local_id, condition, hand_in_date, hand_out_date, movement_date
  ) VALUES (
    p_voyage_id, p_operation_id, v_manifest_id, upper(btrim(p_container_number)), p_container_type,
    p_local_id, p_condition, p_hand_in_date, p_hand_out_date, p_movement_date
  ) RETURNING id INTO v_booking_id;

  RETURN v_booking_id;
END;
$_$;



--
-- Name: current_actor_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_actor_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN auth.role() = 'service_role' THEN 'sistema'
    ELSE (
      SELECT CASE up.role
        WHEN 'admin' THEN 'administrativo'
        WHEN 'operator' THEN 'documentacao'
        ELSE up.role
      END
      FROM public.user_profiles AS up
      WHERE up.id = auth.uid() AND up.active = true
    )
  END;
$$;



--
-- Name: current_portal_customer_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_portal_customer_id() RETURNS bigint
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id bigint;
  v_revoked_at timestamptz;
  v_issued_at timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sessao do portal invalida ou expirada.' USING ERRCODE = '28000';
  END IF;

  SELECT a.customer_id, a.credentials_revoked_at
  INTO v_customer_id, v_revoked_at
  FROM public.customer_portal_accounts AS a
  WHERE a.auth_user_id = auth.uid()
    AND a.active = true;

  IF v_customer_id IS NULL THEN
    RAISE EXCEPTION 'Sessao do portal invalida ou expirada.' USING ERRCODE = '28000';
  END IF;

  IF v_revoked_at IS NOT NULL THEN
    v_issued_at := to_timestamp(NULLIF(auth.jwt() ->> 'iat', '')::double precision);
    IF v_issued_at IS NOT NULL AND v_issued_at < v_revoked_at - interval '5 seconds' THEN
      RAISE EXCEPTION 'Sessao do portal invalida ou expirada.' USING ERRCODE = '28000';
    END IF;
  END IF;

  RETURN v_customer_id;
END;
$$;



--
-- Name: current_user_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_role() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT role FROM public.user_profiles WHERE id = auth.uid();
$$;



--
-- Name: customer_communication_safe_timestamptz(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_communication_safe_timestamptz(p_value text) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NULLIF(btrim(p_value), '') IS NULL
     OR btrim(p_value) !~ '^\d{4}-\d{2}-\d{2}' THEN
    RETURN NULL;
  END IF;
  RETURN btrim(p_value)::TIMESTAMPTZ;
EXCEPTION WHEN OTHERS THEN
  RETURN NULL;
END;
$$;



--
-- Name: customer_local_charges_communication_payload(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_local_charges_communication_payload(p_voyage_id bigint, p_customer_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Executor server-only.' USING ERRCODE = '42501';
  END IF;

  RETURN (
    WITH base_bls AS (
      SELECT b.id AS bl_id, b.ce_mercante, b.pod, c.name AS customer_name,
             v.eta, v.voyage_number, vs.name AS vessel_name
      FROM public.bls b
      JOIN public.customers c ON c.id = b.customer_id
      JOIN public.voyages v ON v.id = b.voyage_id
      LEFT JOIN public.vessels vs ON vs.id = v.vessel_id
      WHERE b.voyage_id = p_voyage_id
        AND b.customer_id = p_customer_id
        AND COALESCE(b.financial_status, 'pending') <> 'cancelled'
    ), direct_totals AS (
      SELECT ib.bl_id, sum(COALESCE(ib.subtotal_brl, 0)) AS total_brl
      FROM public.invoice_bls ib
      JOIN base_bls b ON b.bl_id = ib.bl_id
      JOIN public.invoices i ON i.id = ib.invoice_id
      WHERE i.status IN ('issued', 'partially_paid', 'paid', 'covered')
      GROUP BY ib.bl_id
    ), ledger_totals AS (
      SELECT rl.bl_id, sum(COALESCE(rl.subtotal_brl, 0)) AS total_brl
      FROM public.invoice_receivable_links rl
      JOIN base_bls b ON b.bl_id = rl.bl_id
      JOIN public.invoices i ON i.id = rl.invoice_id
      WHERE COALESCE(rl.status, '') <> 'obsolete'
        AND i.status IN ('issued', 'partially_paid', 'paid', 'covered')
        AND NOT EXISTS (SELECT 1 FROM direct_totals d WHERE d.bl_id = rl.bl_id)
      GROUP BY rl.bl_id
    )
    SELECT CASE WHEN count(*) = 0 THEN NULL ELSE jsonb_build_object(
      'customer_id', p_customer_id,
      'customer_name', max(customer_name),
      'vessel_name', max(vessel_name),
      'voyage_number', max(voyage_number),
      'port', (array_agg(COALESCE(pod, '—') ORDER BY bl_id))[1],
      'milestone_at', max(COALESCE(eta::TEXT, '')),
      'bls', jsonb_agg(jsonb_build_object(
        'bl_id', base_bls.bl_id,
        'ce_mercante', NULLIF(btrim(base_bls.ce_mercante), ''),
        'total_brl', COALESCE(direct_totals.total_brl, ledger_totals.total_brl, 0)
      ) ORDER BY base_bls.bl_id)
    ) END
    FROM base_bls
    LEFT JOIN direct_totals ON direct_totals.bl_id = base_bls.bl_id
    LEFT JOIN ledger_totals ON ledger_totals.bl_id = base_bls.bl_id
  );
END;
$$;



--
-- Name: customer_local_charges_communication_readiness(bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_local_charges_communication_readiness(p_voyage_id bigint, p_customer_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     AND (auth.uid() IS NULL OR NOT public.is_active_read_user()) THEN
    RAISE EXCEPTION 'Usuário interno ativo é obrigatório.' USING ERRCODE = '42501';
  END IF;

  IF p_voyage_id IS NULL OR p_customer_id IS NULL THEN
    RAISE EXCEPTION 'Viagem e cliente são obrigatórios.' USING ERRCODE = '22023';
  END IF;

  WITH bl_state AS (
    SELECT
      b.id AS bl_id,
      NULLIF(btrim(b.ce_mercante), '') AS ce_mercante,
      COALESCE(b.financial_status, 'pending') AS financial_status,
      COALESCE(b.cargo_mode, 'container') AS cargo_mode,
      b.bb_weight_ton,
      public.compute_bl_review_pendencies(
        b.customer_id,
        COALESCE(b.cargo_mode, 'container'),
        b.bb_weight_ton
      ) AS review_pendencies
    FROM public.bls AS b
    WHERE b.voyage_id = p_voyage_id
      AND b.customer_id = p_customer_id
      -- B/L cancelado não participa do resumo nem pode bloquear o cliente.
      AND COALESCE(b.financial_status, 'pending') <> 'cancelled'
  ), annotated AS (
    SELECT
      bl_state.*,
      array_remove(ARRAY[
        CASE WHEN bl_state.ce_mercante IS NULL THEN 'ce_mercante_ausente'::TEXT END,
        CASE WHEN COALESCE(cardinality(bl_state.review_pendencies), 0) > 0 THEN 'revisao_pendente'::TEXT END,
        CASE WHEN bl_state.financial_status NOT IN ('invoiced', 'paid') THEN 'faturamento_pendente'::TEXT END
      ], NULL) AS blocked_reasons
    FROM bl_state
  ), aggregate AS (
    SELECT
      count(*)::INTEGER AS bl_count,
      count(*) FILTER (WHERE cardinality(blocked_reasons) > 0)::INTEGER AS blocked_bl_count,
      COALESCE(bool_and(cardinality(blocked_reasons) = 0), false) AS ready,
      COALESCE(jsonb_agg(
        jsonb_build_object(
          'bl_id', bl_id,
          'ce_mercante', ce_mercante,
          'financial_status', financial_status,
          'cargo_mode', cargo_mode,
          'review_pendencies', to_jsonb(review_pendencies),
          'blocked_reasons', to_jsonb(blocked_reasons)
        ) ORDER BY bl_id
      ), '[]'::JSONB) AS bls
    FROM annotated
  ), reason_aggregate AS (
    SELECT COALESCE(jsonb_agg(DISTINCT reason ORDER BY reason), '[]'::JSONB) AS reasons
    FROM annotated
    CROSS JOIN LATERAL unnest(annotated.blocked_reasons) AS reason
  )
  SELECT jsonb_build_object(
    'voyage_id', p_voyage_id,
    'customer_id', p_customer_id,
    'ready', CASE WHEN bl_count = 0 THEN false ELSE ready END,
    'reason_code', CASE
      WHEN bl_count = 0 THEN 'no_bls'
      WHEN ready THEN 'ready'
      ELSE COALESCE(reasons ->> 0, 'readiness_blocked')
    END,
    'bl_count', bl_count,
    'blocked_bl_count', blocked_bl_count,
    'reasons', reasons,
    'bls', bls
  )
  INTO v_result
  FROM aggregate CROSS JOIN reason_aggregate;

  RETURN v_result;
END;
$$;



--
-- Name: customer_portal_access_ready(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_portal_access_ready(p_customer_id bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- `active` sozinho não basta: `account_situation` é a máquina de estados do
  -- provisionamento (178) e `recovery_email_status` é marcado pelo webhook de
  -- bounce/complaint (299), independente dela. Cliente que não recebe o e-mail
  -- não vê a fatura, que é o motivo de o gate existir.
  SELECT EXISTS (
    SELECT 1
    FROM public.customer_portal_accounts a
    WHERE a.customer_id = p_customer_id
      AND a.active = true
      AND a.account_situation = 'ativo'
      AND a.auth_user_id IS NOT NULL
      AND NULLIF(btrim(a.recovery_email), '') IS NOT NULL
      AND COALESCE(a.recovery_email_status, 'ok') = 'ok'
      AND NOT EXISTS (
        SELECT 1
        FROM public.portal_suppressed_emails s
        WHERE s.email = lower(btrim(a.recovery_email))
      )
  );
$$;



--
-- Name: customer_rate_overrides_validate_range(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.customer_rate_overrides_validate_range() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.valid_from IS NOT NULL AND NEW.valid_to IS NOT NULL AND NEW.valid_from > NEW.valid_to THEN
    RAISE EXCEPTION 'valid_from (%) nao pode ser posterior a valid_to (%) em customer_rate_overrides (customer_id=%, charge_item_id=%)',
      NEW.valid_from, NEW.valid_to, NEW.customer_id, NEW.charge_item_id
      USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: delete_baplie_manifest_for_voyage(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_baplie_manifest_for_voyage(p_voyage_id bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Apenas usuários ativos podem substituir manifesto BAPLIE.'
      USING ERRCODE = '42501';
  END IF;

  DELETE FROM public.vazios_importacao_manifests
  WHERE voyage_id = p_voyage_id
    AND source = 'baplie';

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;



--
-- Name: delete_manual_bl_charge(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_manual_bl_charge(p_charge_calculation_id bigint, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row RECORD;
  v_bl_id TEXT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  SELECT
    cc.id,
    cc.bl_id,
    cc.source,
    cc.charge_item_id,
    cc.quantity,
    cc.total_value_brl,
    cc.total_value_usd,
    b.financial_status AS bl_financial_status
  INTO v_row
  FROM public.charge_calculations AS cc
  LEFT JOIN public.bls AS b ON b.id = cc.bl_id
  WHERE cc.id = p_charge_calculation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Linha de calculo % nao encontrada', p_charge_calculation_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_row.source, '') <> 'manual' THEN
    RAISE EXCEPTION 'Somente linhas manuais podem ser removidas' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_row.bl_financial_status, 'open') IN ('invoiced', 'partially_paid', 'paid') THEN
    RAISE EXCEPTION 'B/L % ja foi faturado; nao e permitido remover taxa manual.', v_row.bl_id
      USING ERRCODE = '22023';
  END IF;

  v_bl_id := v_row.bl_id;

  DELETE FROM public.charge_calculations
  WHERE id = p_charge_calculation_id;

  INSERT INTO public.audit_logs (
    entity_type,
    entity_id,
    field_name,
    old_value,
    new_value,
    changed_by,
    changed_at,
    justification
  )
  VALUES (
    'charge_calculation',
    p_charge_calculation_id::TEXT,
    'manual_delete',
    CONCAT('charge_item_id=', COALESCE(v_row.charge_item_id::TEXT, '-'), ' | qty=', COALESCE(v_row.quantity::TEXT, '0')),
    NULL,
    auth.uid(),
    NOW(),
    'Remocao manual de other charge'
  );

  RETURN jsonb_build_object(
    'deleted', true,
    'id', p_charge_calculation_id,
    'bl_id', v_bl_id
  );
END;
$$;



--
-- Name: delete_manual_invoice_charge(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_manual_invoice_charge(p_item_id bigint, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item RECORD;
  v_invoice RECORD;
  v_actor UUID;
  v_payment_count INTEGER;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  SELECT * INTO v_item FROM public.invoice_items WHERE id = p_item_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item % nao encontrado.', p_item_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_item.source, '') <> 'manual' THEN
    RAISE EXCEPTION 'Apenas itens manuais podem ser removidos.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_invoice FROM public.invoices WHERE id = v_item.invoice_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice nao encontrada para o item %.', p_item_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_invoice.status, 'issued') NOT IN ('issued', 'overdue', 'draft') THEN
    RAISE EXCEPTION 'So e permitido remover itens de faturas em aberto (status atual: %).',
      COALESCE(v_invoice.status, 'issued') USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_payment_count FROM public.payments WHERE invoice_id = v_invoice.id;
  IF v_payment_count > 0 THEN
    RAISE EXCEPTION 'Nao e permitido remover itens em fatura com pagamentos registrados.' USING ERRCODE = '22023';
  END IF;

  DELETE FROM public.invoice_items WHERE id = p_item_id;

  UPDATE public.invoices
  SET
    total_brl = GREATEST(COALESCE(total_brl, 0) - COALESCE(v_item.total_value_brl, 0), 0),
    balance_brl = GREATEST(COALESCE(total_brl, 0) - COALESCE(v_item.total_value_brl, 0) - COALESCE(total_paid_brl, 0), 0),
    pix_payload = NULL
  WHERE id = v_invoice.id;

  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by)
  VALUES (
    'invoice', v_invoice.id::text, 'manual_charge_removed',
    format('%s = %s BRL', v_item.description, v_item.total_value_brl), NULL, v_actor
  );

  RETURN jsonb_build_object('invoice_id', v_invoice.id, 'item_id', p_item_id, 'removed', true);
END;
$$;



--
-- Name: delete_manual_vazios_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_manual_vazios_booking(p_booking_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_manifest_id UUID;
BEGIN
  IF auth.uid() IS NULL OR NOT (public.is_active_user() OR public.is_active_user()) THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para excluir unidade.' USING ERRCODE = '42501';
  END IF;

  SELECT manifest_id INTO v_manifest_id
  FROM public.vazios_bookings
  WHERE id = p_booking_id;
  IF v_manifest_id IS NULL THEN
    RAISE EXCEPTION 'Unidade embarcada nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  DELETE FROM public.vazios_bookings WHERE id = p_booking_id;

  DELETE FROM public.vazios_manifests manifest
  WHERE manifest.id = v_manifest_id
    AND manifest.description = 'Inclusao manual no Embarque de Vazios'
    AND NOT EXISTS (
      SELECT 1 FROM public.vazios_bookings booking
      WHERE booking.manifest_id = manifest.id
    );
END;
$$;



