--
-- Name: detect_bl_review_pendencies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_bl_review_pendencies() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_cust RECORD;
  v_cons RECORD;
  v_old_alert RECORD;
  v_count INTEGER := 0;
  v_type TEXT;
BEGIN
  PERFORM set_config('alerts.foundation_trigger', 'on', true);

  -- 1. Reconcilia clientes vinculados com B/Ls em pending_review
  FOR v_cust IN
    SELECT DISTINCT customer_id
    FROM public.bls
    WHERE review_status = 'pending_review'
      AND customer_id IS NOT NULL
  LOOP
    PERFORM public.reconcile_customer_bl_review_alerts(v_cust.customer_id, NULL, 'detector_bl_review');
    v_count := v_count + 1;
  END LOOP;

  -- 2. Reconcilia consignatários não vinculados com B/Ls em pending_review
  FOR v_cons IN
    SELECT DISTINCT COALESCE(NULLIF(btrim(consignee), ''), 'sem_cliente') AS consignee_key
    FROM public.bls
    WHERE review_status = 'pending_review'
      AND customer_id IS NULL
  LOOP
    PERFORM public.reconcile_customer_bl_review_alerts(NULL, v_cons.consignee_key, 'detector_bl_review');
    v_count := v_count + 1;
  END LOOP;

  -- 3. Resolve alertas ativos de clientes que não possuem mais pendências
  FOR v_old_alert IN
    SELECT DISTINCT a.entity_id, i.item_type
    FROM public.alert_items i
    JOIN public.alerts a ON a.id = i.alert_id
    WHERE i.status = 'active'
      AND a.entity_type = 'customer'
      AND i.item_type IN (
        'review_customer_unlinked',
        'review_customer_email_missing',
        'review_portal_not_ready',
        'review_breakbulk_weight_missing'
      )
  LOOP
    IF v_old_alert.entity_id ~ '^[0-9]+$' THEN
      PERFORM public.reconcile_customer_bl_review_alerts(v_old_alert.entity_id::BIGINT, NULL, 'detector_bl_review_cleanup');
    ELSE
      PERFORM public.reconcile_customer_bl_review_alerts(NULL, v_old_alert.entity_id, 'detector_bl_review_cleanup');
    END IF;
  END LOOP;

  -- 4. Limpa itens legados por B/L
  FOREACH v_type IN ARRAY ARRAY[
    'review_customer_unlinked',
    'review_customer_email_missing',
    'review_portal_not_ready',
    'review_breakbulk_weight_missing'
  ] LOOP
    FOR v_old_alert IN
      SELECT a.entity_id
      FROM public.alert_items i
      JOIN public.alerts a ON a.id = i.alert_id
      WHERE i.status = 'active'
        AND a.entity_type = 'bl'
        AND i.item_type = v_type
    LOOP
      PERFORM public.resolve_alert_item(v_type, 'bl', v_old_alert.entity_id, 'detector_bl_review_cleanup', '{}'::jsonb);
    END LOOP;
  END LOOP;

  PERFORM set_config('alerts.foundation_trigger', 'off', true);
  RETURN v_count;
END;
$_$;



--
-- Name: detect_customer_communication_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_customer_communication_alerts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_now TIMESTAMPTZ := now();
  v_source TEXT := 'customer_communication_detector';
  v_scale RECORD;
  v_terminal RECORD;
  v_customer RECORD;
  v_stale RECORD;
  v_scale_entity_id TEXT;
  v_terminal_entity_id TEXT;
  v_is_deleted BOOLEAN;
  v_is_omitted BOOLEAN;
  v_eta TIMESTAMPTZ;
  v_ata TIMESTAMPTZ;
  v_has_bounced_contact BOOLEAN;
  v_valid_contacts INTEGER;
  v_scales_evaluated INTEGER := 0;
  v_terminals_evaluated INTEGER := 0;
  v_noa_pending INTEGER := 0;
  v_nor_pending INTEGER := 0;
  v_nob_pending INTEGER := 0;
  v_bounce_pending INTEGER := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Executor server-only.' USING ERRCODE = '42501';
  END IF;

  -- A escala é identificada pelo mesmo par usado por
  -- customer_communications.anchor_voyage_id/anchor_port. O filtro evita
  -- casts sobre entity_ids históricos fora do formato esperado.
  FOR v_scale IN
    SELECT DISTINCT
      split_part(entity_id, '::', 1)::BIGINT AS voyage_id,
      upper(btrim(split_part(entity_id, '::', 2))) AS port
    FROM public.audit_logs
    WHERE entity_type = 'voyage_pod_schedule'
      AND entity_id ~ '^[0-9]+::[^:]+$'
  LOOP
    v_scales_evaluated := v_scales_evaluated + 1;
    v_scale_entity_id := v_scale.voyage_id || '::' || v_scale.port;

    SELECT
      COALESCE((
        SELECT lower(btrim(a.new_value)) = 'true'
        FROM public.audit_logs a
        WHERE a.entity_type = 'voyage_pod_schedule'
          AND a.entity_id = v_scale_entity_id
          AND a.field_name = 'deleted'
        ORDER BY a.changed_at DESC, a.id DESC
        LIMIT 1
      ), false),
      COALESCE((
        SELECT lower(btrim(a.new_value)) = 'true'
        FROM public.audit_logs a
        WHERE a.entity_type = 'voyage_pod_schedule'
          AND a.entity_id = v_scale_entity_id
          AND a.field_name = 'omitted'
        ORDER BY a.changed_at DESC, a.id DESC
        LIMIT 1
      ), false),
      public.customer_communication_safe_timestamptz((
        SELECT a.new_value
        FROM public.audit_logs a
        WHERE a.entity_type = 'voyage_pod_schedule'
          AND a.entity_id = v_scale_entity_id
          AND a.field_name = 'eta'
        ORDER BY a.changed_at DESC, a.id DESC
        LIMIT 1
      )),
      public.customer_communication_safe_timestamptz((
        SELECT a.new_value
        FROM public.audit_logs a
        WHERE a.entity_type = 'voyage_pod_schedule'
          AND a.entity_id = v_scale_entity_id
          AND a.field_name = 'ata'
        ORDER BY a.changed_at DESC, a.id DESC
        LIMIT 1
      ))
    INTO v_is_deleted, v_is_omitted, v_eta, v_ata;

    IF v_is_deleted OR v_is_omitted THEN
      PERFORM public.resolve_alert_item(
        'comunicado_noa_pendente', 'voyage_pod_schedule', v_scale_entity_id,
        v_source, jsonb_build_object('reason', 'scale_deleted_or_omitted')
      );
      PERFORM public.resolve_alert_item(
        'comunicado_nor_pendente', 'voyage_pod_schedule', v_scale_entity_id,
        v_source, jsonb_build_object('reason', 'scale_deleted_or_omitted')
      );
      CONTINUE;
    END IF;

    -- NOA só existe entre D-5 e o instante anterior ao ETA. A janela
    -- fechada no lado passado impede um alerta por cada escala histórica.
    IF v_eta IS NOT NULL
       AND v_eta - interval '5 days' <= v_now
       AND v_now < v_eta
       AND NOT EXISTS (
         SELECT 1
         FROM public.customer_communications c
         WHERE c.kind = 'aviso_chegada_noa'
           AND c.status = 'enviado'
           AND c.anchor_voyage_id = v_scale.voyage_id
           AND upper(btrim(c.anchor_port)) = v_scale.port
       ) THEN
      v_noa_pending := v_noa_pending + 1;
      PERFORM public.upsert_alert_item(
        'comunicado_noa_pendente', 'voyage_pod_schedule', v_scale_entity_id,
        'NOA pendente para a escala ' || v_scale.port ||
          ' (ETA ' || to_char(v_eta AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI') || ')',
        v_source, 'documentacao',
        jsonb_build_object(
          'voyage_id', v_scale.voyage_id,
          'port', v_scale.port,
          'milestone', 'eta',
          'eta', v_eta,
          'window_days', 5
        ),
        '/clientes/comunicacao'
      );
    ELSE
      PERFORM public.resolve_alert_item(
        'comunicado_noa_pendente', 'voyage_pod_schedule', v_scale_entity_id,
        v_source, jsonb_build_object('reason', 'sent_or_outside_eta_window')
      );
    END IF;

    -- NOR é reativo à ATA e só permanece acionável por 30 dias.
    IF v_ata IS NOT NULL
       AND v_ata >= v_now - interval '30 days'
       AND v_ata <= v_now
       AND NOT EXISTS (
         SELECT 1
         FROM public.customer_communications c
         WHERE c.kind = 'aviso_prontidao_nor'
           AND c.status = 'enviado'
           AND c.anchor_voyage_id = v_scale.voyage_id
           AND upper(btrim(c.anchor_port)) = v_scale.port
       ) THEN
      v_nor_pending := v_nor_pending + 1;
      PERFORM public.upsert_alert_item(
        'comunicado_nor_pendente', 'voyage_pod_schedule', v_scale_entity_id,
        'NOR pendente para a escala ' || v_scale.port ||
          ' (ATA ' || to_char(v_ata AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI') || ')',
        v_source, 'documentacao',
        jsonb_build_object(
          'voyage_id', v_scale.voyage_id,
          'port', v_scale.port,
          'milestone', 'ata',
          'ata', v_ata,
          'window_days', 30
        ),
        '/clientes/comunicacao'
      );
    ELSE
      PERFORM public.resolve_alert_item(
        'comunicado_nor_pendente', 'voyage_pod_schedule', v_scale_entity_id,
        v_source, jsonb_build_object('reason', 'sent_or_outside_ata_window')
      );
    END IF;
  END LOOP;

  -- Cada estado de terminal tem identidade própria. O ID UUID da linha é a
  -- âncora de NOB; o código do depot é apenas a chave humana do alerta.
  FOR v_terminal IN
    SELECT
      s.id AS state_id,
      s.voyage_id,
      upper(btrim(s.port)) AS port,
      s.terminal_id,
      public.voyage_terminal_code(s.terminal_id) AS terminal_code,
      s.terminal_atb
    FROM public.voyage_escala_terminal_state s
    WHERE s.terminal_id IS NOT NULL
  LOOP
    v_terminals_evaluated := v_terminals_evaluated + 1;
    v_terminal_entity_id := v_terminal.voyage_id || '::' || v_terminal.port || '::' || v_terminal.terminal_code;
    v_scale_entity_id := v_terminal.voyage_id || '::' || v_terminal.port;

    SELECT
      COALESCE((
        SELECT lower(btrim(a.new_value)) = 'true'
        FROM public.audit_logs a
        WHERE a.entity_type = 'voyage_pod_schedule'
          AND a.entity_id = v_scale_entity_id
          AND a.field_name = 'deleted'
        ORDER BY a.changed_at DESC, a.id DESC
        LIMIT 1
      ), false),
      COALESCE((
        SELECT lower(btrim(a.new_value)) = 'true'
        FROM public.audit_logs a
        WHERE a.entity_type = 'voyage_pod_schedule'
          AND a.entity_id = v_scale_entity_id
          AND a.field_name = 'omitted'
        ORDER BY a.changed_at DESC, a.id DESC
        LIMIT 1
      ), false)
    INTO v_is_deleted, v_is_omitted;

    IF v_terminal.terminal_code IS NULL THEN
      CONTINUE;
    END IF;

    IF v_is_deleted
       OR v_is_omitted
       OR v_terminal.terminal_atb IS NULL
       OR v_terminal.terminal_atb < v_now - interval '30 days'
       OR v_terminal.terminal_atb > v_now
       OR EXISTS (
         SELECT 1
         FROM public.customer_communications c
         WHERE c.kind = 'aviso_atracacao_nob'
           AND c.status = 'enviado'
           AND c.anchor_voyage_id = v_terminal.voyage_id
           AND upper(btrim(c.anchor_port)) = v_terminal.port
           AND c.anchor_atracacao_id = v_terminal.state_id
       ) THEN
      PERFORM public.resolve_alert_item(
        'comunicado_nob_pendente', 'voyage_escala_terminal', v_terminal_entity_id,
        v_source, jsonb_build_object('reason', 'sent_or_outside_atb_window')
      );
    ELSE
      v_nob_pending := v_nob_pending + 1;
      PERFORM public.upsert_alert_item(
        'comunicado_nob_pendente', 'voyage_escala_terminal', v_terminal_entity_id,
        'NOB pendente no terminal ' || v_terminal.terminal_code ||
          ' para a escala ' || v_terminal.port ||
          ' (ATB ' || to_char(v_terminal.terminal_atb AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI') || ')',
        v_source, 'documentacao',
        jsonb_build_object(
          'voyage_id', v_terminal.voyage_id,
          'port', v_terminal.port,
          'terminal_id', v_terminal.terminal_id,
          'terminal_code', v_terminal.terminal_code,
          'state_id', v_terminal.state_id,
          'milestone', 'atb',
          'atb', v_terminal.terminal_atb,
          'window_days', 30
        ),
        '/clientes/comunicacao'
      );
    END IF;
  END LOOP;

  -- Um terminal removido fisicamente não volta no loop acima; feche o alerta
  -- que ficou apontando para a antiga chave, preservando sua ocorrência.
  FOR v_stale IN
    SELECT DISTINCT a.entity_id
    FROM public.alert_items i
    JOIN public.alerts a ON a.id = i.alert_id
    WHERE i.item_type = 'comunicado_nob_pendente'
      AND i.status = 'active'
      AND a.entity_type = 'voyage_escala_terminal'
      AND a.entity_id ~ '^[0-9]+::[^:]+::[^:]+$'
  LOOP
    IF NOT EXISTS (
         SELECT 1
         FROM public.voyage_escala_terminal_state s
         WHERE s.voyage_id = split_part(v_stale.entity_id, '::', 1)::BIGINT
           AND upper(btrim(s.port)) = upper(btrim(split_part(v_stale.entity_id, '::', 2)))
           AND public.voyage_terminal_code(s.terminal_id) = split_part(v_stale.entity_id, '::', 3)
       ) THEN
      PERFORM public.resolve_alert_item(
        'comunicado_nob_pendente', 'voyage_escala_terminal', v_stale.entity_id,
        v_source, jsonb_build_object('reason', 'terminal_deleted')
      );
    END IF;
  END LOOP;

  -- A cascata de bounce é o produtor imediato, mas a varredura também fecha
  -- a pendência quando um novo contato válido é cadastrado na Ficha.
  FOR v_customer IN
    SELECT c.id, c.cnpj_cpf
    FROM public.customers c
  LOOP
    SELECT
      EXISTS (
        SELECT 1
        FROM public.customer_contacts cc
        JOIN public.portal_suppressed_emails pse
          ON lower(btrim(pse.email)) = lower(btrim(cc.email))
         AND pse.reason = 'bounce_permanente'
        WHERE cc.customer_id = v_customer.id
          AND NULLIF(btrim(cc.email), '') IS NOT NULL
      ),
      COUNT(*) FILTER (
        WHERE NULLIF(btrim(cc.email), '') IS NOT NULL
          AND NOT EXISTS (
            SELECT 1
            FROM public.portal_suppressed_emails pse
            WHERE lower(btrim(pse.email)) = lower(btrim(cc.email))
          )
      )::INTEGER
    INTO v_has_bounced_contact, v_valid_contacts
    FROM public.customer_contacts cc
    WHERE cc.customer_id = v_customer.id;

    IF v_has_bounced_contact AND v_valid_contacts = 0 THEN
      v_bounce_pending := v_bounce_pending + 1;
      -- Encerra apenas o carrier legado; o item catalogado abaixo passa a ser
      -- a fonte única da fila para esta regra.
      UPDATE public.alerts
      SET status = 'closed', closed_at = COALESCE(closed_at, now())
      WHERE type = 'cliente_contato_bounced_sem_alternativa'
        AND entity_type = 'customer'
        AND entity_id = v_customer.id::TEXT
        AND NOT EXISTS (
          SELECT 1
          FROM public.alert_items i
          WHERE i.alert_id = public.alerts.id
            AND i.item_type = 'cliente_contato_bounced_sem_alternativa'
        )
        AND status <> 'closed';

      PERFORM public.upsert_alert_item(
        'cliente_contato_bounced_sem_alternativa', 'customer', v_customer.id::TEXT,
        'Cliente sem contato alternativo válido após bounce permanente; atualize o cadastro.',
        v_source, 'documentacao',
        jsonb_build_object(
          'customer_id', v_customer.id,
          'customer_cnpj', v_customer.cnpj_cpf,
          'reason', 'all_contacts_bounced_or_suppressed'
        ),
        '/clientes'
      );
    ELSE
      PERFORM public.resolve_alert_item(
        'cliente_contato_bounced_sem_alternativa', 'customer', v_customer.id::TEXT,
        v_source, jsonb_build_object('reason', 'valid_contact_available')
      );
      UPDATE public.alerts
      SET status = 'closed', closed_at = COALESCE(closed_at, now())
      WHERE type = 'cliente_contato_bounced_sem_alternativa'
        AND entity_type = 'customer'
        AND entity_id = v_customer.id::TEXT
        AND NOT EXISTS (
          SELECT 1
          FROM public.alert_items i
          WHERE i.alert_id = public.alerts.id
            AND i.item_type = 'cliente_contato_bounced_sem_alternativa'
        )
        AND status <> 'closed';
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'scales_evaluated', v_scales_evaluated,
    'terminals_evaluated', v_terminals_evaluated,
    'noa_pending', v_noa_pending,
    'nor_pending', v_nor_pending,
    'nob_pending', v_nob_pending,
    'bounced_without_alternative', v_bounce_pending
  );
END;
$_$;



--
-- Name: detect_granite_bl_review_pendencies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_granite_bl_review_pendencies() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_gbl RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR v_gbl IN
    SELECT id FROM public.granite_bls WHERE client_id IS NULL
  LOOP
    PERFORM set_config('alerts.foundation_trigger', 'on', true);
    PERFORM public.reconcile_granite_bl_review_alerts(v_gbl.id);
    PERFORM set_config('alerts.foundation_trigger', 'off', true);
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;



--
-- Name: detect_voyage_operation_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.detect_voyage_operation_alerts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_voyage RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR v_voyage IN
    SELECT id
    FROM public.voyages
    WHERE status = 'active'
    ORDER BY id
  LOOP
    PERFORM public.reconcile_voyage_operation_alerts(v_voyage.id, 'voyage_operation_detector');
    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;



--
-- Name: dismiss_alert_item(bigint, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_alert_item(p_item_id bigint, p_reason text, p_review_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item public.alert_items%ROWTYPE;
  v_alert public.alerts%ROWTYPE;
  v_dismissal public.alert_item_dismissals%ROWTYPE;
  v_event_id BIGINT;
  v_actor_name TEXT;
  v_author_name TEXT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(btrim(p_reason), '') IS NULL THEN
    RAISE EXCEPTION 'Motivo da dispensa é obrigatório.' USING ERRCODE = '22023';
  END IF;
  IF p_review_at IS NULL OR p_review_at <= now() THEN
    RAISE EXCEPTION 'A revisão deve ser uma data futura.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_item FROM public.alert_items WHERE id = p_item_id AND status = 'active' FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item de alerta não está ativo.' USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_alert FROM public.alerts WHERE id = v_item.alert_id;

  SELECT full_name INTO v_actor_name FROM public.user_profiles WHERE id = auth.uid();
  v_author_name := COALESCE(NULLIF(btrim(v_actor_name), ''), 'Usuário');

  -- Gravar a dispensa auditada
  INSERT INTO public.alert_item_dismissals(alert_item_id, occurrence_id, reason, dismissed_by, review_at)
  VALUES (v_item.id, v_item.occurrence_id, btrim(p_reason), auth.uid(), p_review_at)
  RETURNING * INTO v_dismissal;

  -- Gravar o evento 'dismissed' na ocorrência corrente
  INSERT INTO public.alert_item_events (
    alert_item_id, occurrence_id, event_type, previous_status, new_status, actor_id, metadata
  )
  VALUES (
    v_item.id,
    v_item.occurrence_id,
    'dismissed',
    v_item.status,
    v_item.status,
    auth.uid(),
    jsonb_build_object(
      'reason', btrim(p_reason),
      'review_at', p_review_at,
      'dismissal_id', v_dismissal.id
    )
  )
  RETURNING id INTO v_event_id;

  -- Fan-out do Eco de Tratamento para os destinatários que já receberam notificações
  -- nesta ocorrência, excluindo o autor da dispensa (auth.uid()).
  INSERT INTO public.internal_notifications (
    alert_id,
    alert_item_id,
    event_id,
    recipient_id,
    recipient_department,
    is_fallback,
    item_type,
    severity,
    title,
    message,
    entity_type,
    entity_id,
    destination,
    payload
  )
  SELECT DISTINCT ON (n.recipient_id)
    v_alert.id,
    v_item.id,
    v_event_id,
    n.recipient_id,
    n.recipient_department,
    n.is_fallback,
    v_item.item_type,
    'normal',
    'Pendência dispensada',
    'Pendência dispensada por ' || v_author_name || ' até ' || to_char(p_review_at AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY'),
    v_alert.entity_type,
    v_alert.entity_id,
    NULL,
    jsonb_build_object(
      'is_echo', true,
      'dismissed_by', auth.uid(),
      'dismissed_by_name', v_author_name,
      'reason', btrim(p_reason),
      'review_at', p_review_at,
      'dismissal_id', v_dismissal.id
    )
  FROM public.internal_notifications n
  JOIN public.alert_item_events e ON e.id = n.event_id
  WHERE n.alert_item_id = v_item.id
    AND e.occurrence_id = v_item.occurrence_id
    AND n.recipient_id <> auth.uid()
  ORDER BY n.recipient_id, n.id DESC
  ON CONFLICT (event_id, recipient_id) DO NOTHING;

  -- Zero destinatários no Eco é normal (ex.: autor era o único destinatário).
  -- Não grava em alert_notification_failures.

  RETURN jsonb_build_object(
    'id', v_dismissal.id,
    'item_id', v_item.id,
    'review_at', v_dismissal.review_at,
    'event_id', v_event_id
  );
END;
$$;



--
-- Name: enforce_portal_invoice_bl_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_portal_invoice_bl_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_status TEXT;
  v_gate JSONB;
BEGIN
  SELECT status INTO v_status FROM public.invoices WHERE id = NEW.invoice_id;
  IF v_status = 'issued' THEN
    v_gate := public.portal_billing_gate(NEW.bl_id);
    IF NOT COALESCE((v_gate->>'allowed')::boolean, false) THEN
      RAISE EXCEPTION 'Faturamento bloqueado pelo Portal para B/L %: %', NEW.bl_id, v_gate->>'reason' USING ERRCODE = 'P0003';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: enforce_portal_invoice_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_portal_invoice_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_gate JSONB;
  v_bl RECORD;
BEGIN
  IF NEW.status = 'issued' THEN
    IF NEW.bl_id IS NOT NULL THEN
      v_gate := public.portal_billing_gate(NEW.bl_id);
      IF NOT COALESCE((v_gate->>'allowed')::boolean, false) THEN
        RAISE EXCEPTION 'Faturamento bloqueado pelo Portal: %', v_gate->>'reason' USING ERRCODE = 'P0003';
      END IF;
    END IF;
    FOR v_bl IN SELECT ib.bl_id FROM public.invoice_bls ib WHERE ib.invoice_id = NEW.id LOOP
      v_gate := public.portal_billing_gate(v_bl.bl_id);
      IF NOT COALESCE((v_gate->>'allowed')::boolean, false) THEN
        RAISE EXCEPTION 'Faturamento bloqueado pelo Portal para B/L %: %', v_bl.bl_id, v_gate->>'reason' USING ERRCODE = 'P0003';
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: ensure_agency_departure_report(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_agency_departure_report(p_voyage_id bigint, p_port text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_report_id UUID;
  v_port TEXT := upper(btrim(COALESCE(p_port, '')));
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;
  IF v_port = '' THEN
    RAISE EXCEPTION 'Porto obrigatorio.' USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.voyages WHERE id = p_voyage_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Viagem nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  SELECT id INTO v_report_id
  FROM public.agency_departure_reports
  WHERE voyage_id = p_voyage_id AND port = v_port AND terminal_id IS NULL
  FOR UPDATE;
  IF FOUND THEN
    RETURN v_report_id;
  END IF;

  INSERT INTO public.agency_departure_reports (voyage_id, port)
  VALUES (p_voyage_id, v_port)
  RETURNING id INTO v_report_id;
  RETURN v_report_id;
END;
$$;



--
-- Name: ensure_container_bl_charge_status_default(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_container_bl_charge_status_default() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF COALESCE(NEW.cargo_mode, 'container') = 'container' AND NEW.charge_status IS NULL THEN
    NEW.charge_status := 'not_calculated';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: ensure_customer_contact_email(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_customer_contact_email(p_customer_id bigint, p_email text, p_contact_name text DEFAULT 'Contato manifesto'::text, p_purpose text DEFAULT 'financeiro'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_email TEXT := lower(NULLIF(btrim(COALESCE(p_email, '')), ''));
  v_inserted BOOLEAN := false;
BEGIN
  IF p_customer_id IS NULL OR v_email IS NULL THEN
    RETURN false;
  END IF;

  IF v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN
    RAISE EXCEPTION 'E-mail inválido.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.customer_contacts (customer_id, name, email, purpose, is_primary)
  SELECT p_customer_id, COALESCE(NULLIF(btrim(p_contact_name), ''), 'Contato manifesto'), v_email,
         COALESCE(NULLIF(btrim(p_purpose), ''), 'financeiro'), false
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.customer_contacts AS cc
    WHERE cc.customer_id = p_customer_id
      AND lower(btrim(COALESCE(cc.email, ''))) = v_email
  );

  v_inserted := FOUND;
  RETURN v_inserted;
END;
$_$;



--
-- Name: ensure_demurrage_dispute(bigint, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_demurrage_dispute(p_invoice_id bigint, p_customer_id bigint, p_opened_by text, p_subject text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_id BIGINT;
BEGIN
  SELECT id INTO v_id FROM public.demurrage_disputes WHERE demurrage_invoice_id = p_invoice_id AND state = 'aberta' FOR UPDATE;
  IF v_id IS NULL THEN
    INSERT INTO public.demurrage_disputes(demurrage_invoice_id, customer_id, opened_by, subject, state, next_responder)
    VALUES (p_invoice_id, p_customer_id, p_opened_by, p_subject, 'aberta', 'equipamentos')
    RETURNING id INTO v_id;
  END IF;
  RETURN v_id;
END;
$$;



--
-- Name: ensure_pricing_rule_version(bigint, bigint, bigint, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_pricing_rule_version(p_charge_table_id bigint, p_charge_item_id bigint, p_customer_id bigint, p_reference_date date, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_override_id BIGINT;
  v_version_key TEXT;
  v_id BIGINT;
BEGIN
  IF p_charge_item_id IS NULL THEN
    RETURN NULL;
  END IF;

  IF p_customer_id IS NOT NULL THEN
    SELECT cro.id
    INTO v_override_id
    FROM public.customer_rate_overrides AS cro
    WHERE cro.customer_id = p_customer_id
      AND cro.charge_item_id = p_charge_item_id
      AND (cro.valid_from IS NULL OR cro.valid_from <= p_reference_date)
      AND (cro.valid_to IS NULL OR cro.valid_to >= p_reference_date)
    ORDER BY cro.created_at DESC
    LIMIT 1;
  END IF;

  v_version_key := CONCAT_WS(
    '|',
    'table:' || COALESCE(p_charge_table_id::TEXT, 'none'),
    'item:' || p_charge_item_id::TEXT,
    'customer:' || COALESCE(p_customer_id::TEXT, 'none'),
    'override:' || COALESCE(v_override_id::TEXT, 'none'),
    'ref:' || COALESCE(p_reference_date::TEXT, 'none')
  );

  INSERT INTO public.pricing_rule_versions (
    version_key,
    charge_table_id,
    charge_item_id,
    customer_id,
    customer_rate_override_id,
    reference_date,
    metadata
  )
  VALUES (
    v_version_key,
    p_charge_table_id,
    p_charge_item_id,
    p_customer_id,
    v_override_id,
    p_reference_date,
    COALESCE(p_metadata, '{}'::JSONB)
  )
  ON CONFLICT (version_key) DO UPDATE
  SET metadata = public.pricing_rule_versions.metadata || EXCLUDED.metadata
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;



--
-- Name: evaluate_and_dispatch_automatic_communications(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.evaluate_and_dispatch_automatic_communications(p_as_of timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_schedule RECORD;
  v_customer_bl RECORD;
  v_candidates JSONB := '[]'::JSONB;
  v_as_of TIMESTAMPTZ := COALESCE(p_as_of, now());
  v_kind TEXT;
  v_milestone TIMESTAMPTZ;
  v_key TEXT;
  v_voyage_id BIGINT;
  v_vessel_name TEXT;
  v_voyage_number TEXT;
  v_port TEXT;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Executor server-only.' USING ERRCODE = '42501';
  END IF;

  -- NOA: somente D-5 até antes do ETA. NOR: a partir do ATA no dia do marco.
  FOR v_schedule IN
    WITH entities AS (
      SELECT DISTINCT entity_id
      FROM public.audit_logs
      WHERE entity_type = 'voyage_pod_schedule'
        AND entity_id ~ '^[0-9]+::[^:]+$'
    ), latest AS (
      SELECT e.entity_id,
        public.customer_communication_safe_timestamptz((SELECT a.new_value FROM public.audit_logs a WHERE a.entity_type = 'voyage_pod_schedule' AND a.entity_id = e.entity_id AND a.field_name = 'eta' ORDER BY a.changed_at DESC, a.id DESC LIMIT 1)) AS eta,
        public.customer_communication_safe_timestamptz((SELECT a.new_value FROM public.audit_logs a WHERE a.entity_type = 'voyage_pod_schedule' AND a.entity_id = e.entity_id AND a.field_name = 'ata' ORDER BY a.changed_at DESC, a.id DESC LIMIT 1)) AS ata,
        COALESCE((SELECT lower(a.new_value) = 'true' FROM public.audit_logs a WHERE a.entity_type = 'voyage_pod_schedule' AND a.entity_id = e.entity_id AND a.field_name = 'deleted' ORDER BY a.changed_at DESC, a.id DESC LIMIT 1), false) AS deleted,
        COALESCE((SELECT lower(a.new_value) = 'true' FROM public.audit_logs a WHERE a.entity_type = 'voyage_pod_schedule' AND a.entity_id = e.entity_id AND a.field_name = 'omitted' ORDER BY a.changed_at DESC, a.id DESC LIMIT 1), false) AS omitted
      FROM entities e
    )
    SELECT v.id AS voyage_id, v.voyage_number, vs.name AS vessel_name,
      split_part(l.entity_id, '::', 2) AS port, l.eta, l.ata
    FROM latest l
    JOIN public.voyages v ON v.id = split_part(l.entity_id, '::', 1)::bigint
    LEFT JOIN public.vessels vs ON vs.id = v.vessel_id
    WHERE NOT l.deleted AND NOT l.omitted
      AND ((l.ata IS NULL AND l.eta IS NOT NULL
            AND v_as_of >= l.eta - interval '5 days' AND v_as_of < l.eta)
        OR (l.ata IS NOT NULL AND l.ata BETWEEN v_as_of - interval '30 days' AND v_as_of))
  LOOP
    v_voyage_id := v_schedule.voyage_id;
    v_vessel_name := v_schedule.vessel_name;
    v_voyage_number := v_schedule.voyage_number;
    v_port := v_schedule.port;
    v_kind := CASE WHEN v_schedule.ata IS NOT NULL THEN 'aviso_prontidao_nor' ELSE 'aviso_chegada_noa' END;
    v_milestone := CASE WHEN v_kind = 'aviso_prontidao_nor' THEN v_schedule.ata ELSE v_schedule.eta END;

    FOR v_customer_bl IN
      SELECT b.customer_id, array_agg(DISTINCT b.id ORDER BY b.id) AS bl_ids,
        c.name AS customer_name, c.cnpj_cpf,
        array_agg(DISTINCT NULLIF(btrim(cc.email), '') ORDER BY NULLIF(btrim(cc.email), ''))
          FILTER (WHERE NULLIF(btrim(cc.email), '') IS NOT NULL
            AND NULLIF(btrim(cc.email), '') ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') AS emails
      FROM public.bls b
      JOIN public.customers c ON c.id = b.customer_id
      LEFT JOIN public.customer_contacts cc ON cc.customer_id = b.customer_id
      WHERE b.voyage_id = v_voyage_id
        AND upper(btrim(b.pod)) = upper(btrim(v_port))
        AND b.customer_id IS NOT NULL
        AND COALESCE(b.financial_status, 'pending') <> 'cancelled'
        AND NULLIF(btrim(cc.email), '') IS NOT NULL
        AND NULLIF(btrim(cc.email), '') ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
        AND NOT EXISTS (
          SELECT 1 FROM public.customer_contact_preferences cp
          WHERE cp.contact_id = cc.id AND cp.nature = 'avisos_operacionais' AND cp.enabled = false
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.portal_suppressed_emails pse
          WHERE lower(btrim(pse.email)) = lower(btrim(cc.email)) AND pse.reason = 'bounce_permanente'
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.customer_communication_suppressions ccs
          WHERE lower(btrim(ccs.email)) = lower(btrim(cc.email))
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.customer_communications sent
          WHERE sent.customer_id = b.customer_id
            AND sent.kind = v_kind
            AND sent.nature = 'avisos_operacionais'
            AND sent.status IN ('enviado', 'simulado')
            AND sent.anchor_voyage_id = v_voyage_id
            AND upper(btrim(sent.anchor_port)) = upper(btrim(v_port))
        )
      GROUP BY b.customer_id, c.name, c.cnpj_cpf
    LOOP
      v_key := v_kind || ':' || v_customer_bl.customer_id || ':' || v_voyage_id || ':' || upper(v_port);
      INSERT INTO public.customer_communication_automation_claims (claim_key)
      VALUES (v_key)
      ON CONFLICT (claim_key) DO UPDATE
        SET claimed_at = now(), released_at = NULL
        WHERE customer_communication_automation_claims.released_at IS NOT NULL
           OR customer_communication_automation_claims.claimed_at < v_as_of - interval '30 minutes';
      IF FOUND THEN
        v_candidates := v_candidates || jsonb_build_array(jsonb_build_object(
          'claim_key', v_key, 'kind', v_kind, 'nature', 'avisos_operacionais',
          'customer_id', v_customer_bl.customer_id, 'customer_name', v_customer_bl.customer_name,
          'customer_cnpj', v_customer_bl.cnpj_cpf, 'voyage_id', v_voyage_id,
          'vessel_name', v_vessel_name, 'voyage_number', v_voyage_number,
          'port', upper(v_port), 'milestone_at', v_milestone,
          'bl_ids', to_jsonb(v_customer_bl.bl_ids), 'emails', to_jsonb(v_customer_bl.emails)
        ));
      END IF;
    END LOOP;
  END LOOP;

  -- CE Mercante: produtor server-side durável, independente da tela de B/L.
  FOR v_customer_bl IN
    SELECT b.voyage_id, b.customer_id, c.name AS customer_name, c.cnpj_cpf,
      v.voyage_number, vs.name AS vessel_name, min(b.pod) AS port,
      v.eta AS milestone_at, array_agg(DISTINCT b.id ORDER BY b.id) AS bl_ids,
      array_agg(DISTINCT NULLIF(btrim(cc.email), '') ORDER BY NULLIF(btrim(cc.email), '')) AS emails
    FROM public.bls b
    JOIN public.customers c ON c.id = b.customer_id
    JOIN public.voyages v ON v.id = b.voyage_id
    LEFT JOIN public.vessels vs ON vs.id = v.vessel_id
    JOIN public.customer_contacts cc ON cc.customer_id = b.customer_id
    WHERE b.customer_id IS NOT NULL
      AND COALESCE(b.financial_status, 'pending') <> 'cancelled'
      AND NULLIF(btrim(cc.email), '') IS NOT NULL
      AND NULLIF(btrim(cc.email), '') ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
      AND NOT EXISTS (SELECT 1 FROM public.customer_contact_preferences cp WHERE cp.contact_id = cc.id AND cp.nature = 'documentacao' AND cp.enabled = false)
      AND NOT EXISTS (SELECT 1 FROM public.portal_suppressed_emails pse WHERE lower(btrim(pse.email)) = lower(btrim(cc.email)) AND pse.reason = 'bounce_permanente')
      AND NOT EXISTS (SELECT 1 FROM public.customer_communication_suppressions ccs WHERE lower(btrim(ccs.email)) = lower(btrim(cc.email)))
      AND (public.customer_local_charges_communication_readiness(b.voyage_id, b.customer_id)->>'ready')::BOOLEAN
      AND NOT EXISTS (
        SELECT 1 FROM public.customer_communications sent
        WHERE sent.customer_id = b.customer_id AND sent.kind = 'ce_mercante_taxas'
          AND sent.nature = 'documentacao' AND sent.status IN ('enviado', 'simulado')
          AND sent.anchor_voyage_id = b.voyage_id AND sent.attempt_discriminator = 0
      )
    GROUP BY b.voyage_id, b.customer_id, c.name, c.cnpj_cpf, v.voyage_number, vs.name, v.eta
  LOOP
    v_key := 'ce_mercante_taxas:' || v_customer_bl.customer_id || ':' || v_customer_bl.voyage_id;
    INSERT INTO public.customer_communication_automation_claims (claim_key)
    VALUES (v_key)
    ON CONFLICT (claim_key) DO UPDATE
      SET claimed_at = now(), released_at = NULL
      WHERE customer_communication_automation_claims.released_at IS NOT NULL
         OR customer_communication_automation_claims.claimed_at < v_as_of - interval '30 minutes';
    IF FOUND THEN
      v_candidates := v_candidates || jsonb_build_array(jsonb_build_object(
        'claim_key', v_key, 'kind', 'ce_mercante_taxas', 'nature', 'documentacao',
        'customer_id', v_customer_bl.customer_id, 'customer_name', v_customer_bl.customer_name,
        'customer_cnpj', v_customer_bl.cnpj_cpf, 'voyage_id', v_customer_bl.voyage_id,
        'vessel_name', v_customer_bl.vessel_name, 'voyage_number', v_customer_bl.voyage_number,
        'port', COALESCE(v_customer_bl.port, '—'), 'milestone_at', v_customer_bl.milestone_at,
        'bl_ids', to_jsonb(v_customer_bl.bl_ids), 'emails', to_jsonb(v_customer_bl.emails)
      ));
    END IF;
  END LOOP;

  RETURN v_candidates;
END;
$_$;



--
-- Name: extract_ncm_codes(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extract_ncm_codes(p_text text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
  v_match TEXT[];
  v_chunk TEXT[];
  v_digits TEXT;
  v_result TEXT[] := ARRAY[]::TEXT[];
BEGIN
  IF NULLIF(btrim(COALESCE(p_text, '')), '') IS NULL THEN
    RETURN v_result;
  END IF;

  FOR v_match IN
    SELECT match
    FROM regexp_matches(
      p_text,
      '(^|[^A-Za-z])(UN[[:space:]]+)?NCM(?:[[:space:]]*(?:NO\.?|NUMBER|CODE))?[[:space:]]*[:.]?[[:space:]]*([0-9][0-9.,[:space:]/-]{2,30})',
      'gi'
    ) AS match
  LOOP
    -- "UN NCM.:3556" é número ONU de carga perigosa, não NCM.
    CONTINUE WHEN v_match[2] IS NOT NULL;

    -- A corrida capturada pode trazer mais de um código ("5509 1234"); fatiar
    -- em blocos de 4, 6 ou 8 dígitos mantém a paridade com src/lib/ncm.ts.
    FOR v_chunk IN
      SELECT chunk
      FROM regexp_matches(v_match[3], '[0-9]{4}(?:[.,]?[0-9]{2})?(?:[.,]?[0-9]{2})?', 'g') AS chunk
    LOOP
      v_digits := regexp_replace(v_chunk[1], '[^0-9]', '', 'g');
      IF length(v_digits) >= 4 AND NOT (v_digits = ANY(v_result)) THEN
        v_result := array_append(v_result, v_digits);
      END IF;
    END LOOP;
  END LOOP;

  RETURN v_result;
END;
$$;



--
-- Name: extract_review_cnpjs_from_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extract_review_cnpjs_from_text(p_text text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_match TEXT;
  v_value TEXT;
  v_result TEXT[] := ARRAY[]::TEXT[];
BEGIN
  IF NULLIF(p_text, '') IS NULL THEN
    RETURN v_result;
  END IF;

  FOR v_match IN
    SELECT match[1]
    FROM regexp_matches(
      p_text,
      '\mCNPJ\M[[:space:]]*[:-]?[[:space:]]*([0-9A-Z]{2}[./][0-9A-Z]{3}[./][0-9A-Z]{3}/[0-9A-Z]{4}-[0-9]{2}|[0-9A-Z]{14})([^0-9A-Z]|$)',
      'gi'
    ) AS match
  LOOP
    v_value := public.normalize_cnpj(v_match);
    IF v_value IS NOT NULL
       AND public.is_valid_cnpj(v_value)
       AND NOT (v_value = ANY(v_result)) THEN
      v_result := array_append(v_result, v_value);
    END IF;
  END LOOP;

  RETURN v_result;
END;
$_$;



--
-- Name: fanout_alert_item(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fanout_alert_item(p_alert_id bigint, p_item_id bigint, p_event_id bigint) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item public.alert_items%ROWTYPE;
  v_alert public.alerts%ROWTYPE;
  v_catalog public.alert_type_catalog%ROWTYPE;
  v_user RECORD;
  v_count INTEGER := 0;
  v_fallback BOOLEAN := false;
BEGIN
  SELECT * INTO v_item FROM public.alert_items WHERE id = p_item_id;
  SELECT * INTO v_alert FROM public.alerts WHERE id = p_alert_id;
  SELECT * INTO v_catalog FROM public.alert_type_catalog WHERE type = v_item.item_type;

  FOR v_user IN
    SELECT up.id, up.role
    FROM public.user_profiles up
    WHERE up.active = true
      AND up.role = ANY(v_catalog.audience_departments)
  LOOP
    INSERT INTO public.internal_notifications (
      alert_id, alert_item_id, event_id, recipient_id, recipient_department,
      is_fallback, item_type, severity, title, message, entity_type, entity_id,
      destination, payload
    )
    VALUES (
      p_alert_id, p_item_id, p_event_id, v_user.id, v_user.role,
      false, v_item.item_type, v_item.severity, 'Nova pendência operacional',
      v_item.message, v_alert.entity_type, v_alert.entity_id, v_item.destination,
      v_item.metadata
    )
    ON CONFLICT (event_id, recipient_id) DO NOTHING;
    v_count := v_count + 1;
  END LOOP;

  IF v_count = 0 AND v_item.severity = 'critical' THEN
    v_fallback := true;
    FOR v_user IN
      SELECT up.id, up.role
      FROM public.user_profiles up
      WHERE up.active = true AND up.role IN ('administrativo', 'admin')
    LOOP
      INSERT INTO public.internal_notifications (
        alert_id, alert_item_id, event_id, recipient_id, recipient_department,
        is_fallback, item_type, severity, title, message, entity_type, entity_id,
        destination, payload
      )
      VALUES (
        p_alert_id, p_item_id, p_event_id, v_user.id, v_user.role,
        true, v_item.item_type, v_item.severity, 'Nova pendência operacional',
        v_item.message, v_alert.entity_type, v_alert.entity_id, v_item.destination,
        jsonb_build_object('fallback_for', v_item.department) || v_item.metadata
      )
      ON CONFLICT (event_id, recipient_id) DO NOTHING;
      v_count := v_count + 1;
    END LOOP;
  END IF;

  IF v_count = 0 THEN
    INSERT INTO public.alert_notification_failures (
      alert_id, alert_item_id, event_id, item_type, department, reason
    )
    VALUES (
      p_alert_id, p_item_id, p_event_id, v_item.item_type,
      COALESCE(v_item.department, v_catalog.responsible_department),
      CASE WHEN v_fallback THEN 'Nenhum destinatário ativo no fallback Administrativo.'
           ELSE 'Nenhum destinatário ativo na audiência do item.' END
    );
  END IF;

  RETURN v_count;
END;
$$;



--
-- Name: fanout_alert_item_for_department(bigint, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fanout_alert_item_for_department(p_alert_id bigint, p_item_id bigint, p_event_id bigint, p_department text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item public.alert_items%ROWTYPE;
  v_alert public.alerts%ROWTYPE;
  v_catalog public.alert_type_catalog%ROWTYPE;
  v_user RECORD;
  v_audience TEXT[];
  v_count INTEGER := 0;
  v_fallback BOOLEAN := false;
BEGIN
  SELECT * INTO v_item FROM public.alert_items WHERE id = p_item_id;
  SELECT * INTO v_alert FROM public.alerts WHERE id = p_alert_id;
  SELECT * INTO v_catalog FROM public.alert_type_catalog WHERE type = v_item.item_type;

  SELECT COALESCE(array_agg(DISTINCT department ORDER BY department), '{}'::TEXT[])
  INTO v_audience
  FROM unnest(
    COALESCE(v_catalog.audience_departments, '{}'::TEXT[])
    || CASE WHEN NULLIF(btrim(p_department), '') IS NULL THEN '{}'::TEXT[]
            ELSE ARRAY[NULLIF(btrim(p_department), '')] END
  ) AS departments(department)
  WHERE department IS NOT NULL;

  FOR v_user IN
    SELECT up.id, up.role
    FROM public.user_profiles up
    WHERE up.active = true AND up.role = ANY(v_audience)
  LOOP
    INSERT INTO public.internal_notifications (
      alert_id, alert_item_id, event_id, recipient_id, recipient_department,
      is_fallback, item_type, severity, title, message, entity_type, entity_id,
      destination, payload
    )
    VALUES (
      p_alert_id, p_item_id, p_event_id, v_user.id, v_user.role,
      false, v_item.item_type, v_item.severity, 'Nova pendência operacional',
      v_item.message, v_alert.entity_type, v_alert.entity_id, v_item.destination,
      v_item.metadata
    )
    ON CONFLICT (event_id, recipient_id) DO NOTHING;
    v_count := v_count + 1;
  END LOOP;

  IF v_count = 0 AND v_item.severity = 'critical' THEN
    v_fallback := true;
    FOR v_user IN
      SELECT up.id, up.role
      FROM public.user_profiles up
      WHERE up.active = true AND up.role IN ('administrativo', 'admin')
    LOOP
      INSERT INTO public.internal_notifications (
        alert_id, alert_item_id, event_id, recipient_id, recipient_department,
        is_fallback, item_type, severity, title, message, entity_type, entity_id,
        destination, payload
      )
      VALUES (
        p_alert_id, p_item_id, p_event_id, v_user.id, v_user.role,
        true, v_item.item_type, v_item.severity, 'Nova pendência operacional',
        v_item.message, v_alert.entity_type, v_alert.entity_id, v_item.destination,
        jsonb_build_object('fallback_for', COALESCE(NULLIF(btrim(p_department), ''), v_catalog.responsible_department)) || v_item.metadata
      )
      ON CONFLICT (event_id, recipient_id) DO NOTHING;
      v_count := v_count + 1;
    END LOOP;
  END IF;

  IF v_count = 0 THEN
    INSERT INTO public.alert_notification_failures (
      alert_id, alert_item_id, event_id, item_type, department, reason
    )
    VALUES (
      p_alert_id, p_item_id, p_event_id, v_item.item_type,
      COALESCE(NULLIF(btrim(p_department), ''), v_catalog.responsible_department, 'desconhecido'),
      CASE WHEN v_fallback THEN 'Nenhum destinatário ativo no fallback Administrativo.'
           ELSE 'Nenhum destinatário ativo na audiência do item.' END
    );
  END IF;

  RETURN v_count;
END;
$$;



--
-- Name: freeze_import_batch_route_summary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_import_batch_route_summary() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_route TEXT;
BEGIN
  IF NEW.route_summary IS NOT NULL OR NEW.status NOT IN ('completed', 'partial') THEN RETURN NEW; END IF;
  SELECT string_agg(route, ', ' ORDER BY route)
    INTO v_route
  FROM (
    SELECT DISTINCT concat_ws(' → ', NULLIF(b.pol, ''), NULLIF(b.pod, '')) AS route
    FROM public.bls AS b
    WHERE b.batch_id = NEW.id
      AND (b.pol IS NOT NULL OR b.pod IS NOT NULL)
  ) AS routes
  WHERE route IS NOT NULL AND route <> '';
  IF v_route IS NOT NULL THEN
    UPDATE public.import_batches SET route_summary = v_route WHERE id = NEW.id AND route_summary IS NULL;
    NEW.route_summary := v_route;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: get_agency_report_actor_names(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agency_report_actor_names(p_voyage_id bigint, p_port text) RETURNS TABLE(user_id uuid, full_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_report_id UUID;
  v_prefix TEXT := p_voyage_id || '::' || upper(btrim(p_port)) || '::';
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;
  SELECT id INTO v_report_id
  FROM public.agency_departure_reports
  WHERE voyage_id = p_voyage_id
    AND port = upper(btrim(p_port))
    AND terminal_id IS NULL;
  IF v_report_id IS NULL THEN RETURN; END IF;
  RETURN QUERY SELECT up.id, up.full_name FROM public.user_profiles AS up
  WHERE up.id IN (
    SELECT r.closed_by FROM public.agency_departure_reports AS r WHERE r.id = v_report_id AND r.closed_by IS NOT NULL
    UNION SELECT so.signed_by FROM public.agency_departure_report_signoffs AS so WHERE so.report_id = v_report_id AND so.signed_by IS NOT NULL
    UNION SELECT dso.signed_by FROM public.agency_departure_report_department_signoffs AS dso WHERE dso.report_id = v_report_id AND dso.signed_by IS NOT NULL
    UNION SELECT oc.author_id FROM public.agency_departure_report_occurrences AS oc WHERE oc.report_id = v_report_id
    UNION SELECT al.changed_by FROM public.audit_logs AS al
      WHERE al.entity_type IN ('agency_departure_report_signoff', 'agency_departure_report_department_signoff')
        AND al.entity_id LIKE v_prefix || '%' AND al.changed_by IS NOT NULL
  );
END;
$$;



--
-- Name: get_agency_report_actor_names_by_report_id(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agency_report_actor_names_by_report_id(p_report_id uuid) RETURNS TABLE(user_id uuid, full_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY SELECT up.id, up.full_name FROM public.user_profiles AS up
  WHERE up.id IN (
    SELECT r.closed_by FROM public.agency_departure_reports AS r WHERE r.id = p_report_id AND r.closed_by IS NOT NULL
    UNION SELECT so.signed_by FROM public.agency_departure_report_signoffs AS so WHERE so.report_id = p_report_id AND so.signed_by IS NOT NULL
    UNION SELECT dso.signed_by FROM public.agency_departure_report_department_signoffs AS dso WHERE dso.report_id = p_report_id AND dso.signed_by IS NOT NULL
    UNION SELECT oc.author_id FROM public.agency_departure_report_occurrences AS oc WHERE oc.report_id = p_report_id
    UNION SELECT al.changed_by FROM public.audit_logs AS al
      WHERE al.entity_type IN ('agency_departure_report_signoff', 'agency_departure_report_department_signoff')
        AND al.entity_id LIKE p_report_id::TEXT || '::%' AND al.changed_by IS NOT NULL
  );
END;
$$;



--
-- Name: get_agency_report_closer_name(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_agency_report_closer_name(p_voyage_id bigint, p_port text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_closed_by UUID;
  v_closer_name TEXT;
BEGIN
  -- Espelha a policy SELECT de agency_departure_reports: quem nao pode ler o
  -- ADR tambem nao pode resolver o perfil do seu autor.
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;

  SELECT closed_by INTO v_closed_by
  FROM public.agency_departure_reports
  WHERE voyage_id = p_voyage_id
    AND port = upper(btrim(p_port));

  IF v_closed_by IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT full_name INTO v_closer_name
  FROM public.user_profiles
  WHERE id = v_closed_by;

  RETURN v_closer_name;
END;
$$;



--
-- Name: get_billing_run_details(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_billing_run_details(p_billing_run_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_run JSONB;
  v_logs JSONB;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  SELECT to_jsonb(br.*) || jsonb_build_object('filename', ib.filename)
  INTO v_run
  FROM public.billing_runs AS br
  JOIN public.import_batches AS ib ON ib.id = br.manifest_id
  WHERE br.id = p_billing_run_id;

  IF v_run IS NULL THEN
    RAISE EXCEPTION 'Billing run % nao encontrado.', p_billing_run_id USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(log_row) ORDER BY log_row.created_at DESC), '[]'::JSONB)
  INTO v_logs
  FROM (
    SELECT *
    FROM public.billing_run_logs
    WHERE billing_run_id = p_billing_run_id
    ORDER BY created_at DESC
    LIMIT 300
  ) AS log_row;

  RETURN jsonb_build_object('run', v_run, 'logs', v_logs);
END;
$$;



--
-- Name: get_bl_portal_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_bl_portal_status(p_bl_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT;
  v_ce_mercante TEXT;
  v_account_situation TEXT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa.' USING ERRCODE = '42501';
  END IF;

  SELECT b.customer_id, b.ce_mercante
  INTO v_customer_id, v_ce_mercante
  FROM public.bls b
  WHERE b.id = p_bl_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  SELECT a.account_situation
  INTO v_account_situation
  FROM public.customer_portal_accounts a
  WHERE a.customer_id = v_customer_id;

  RETURN jsonb_build_object(
    'customer_id', v_customer_id,
    'ce_mercante', v_ce_mercante,
    'account_situation', v_account_situation,
    'notifications', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', n.id,
        'type', n.type,
        'title', n.title,
        'created_at', n.created_at,
        'read_at', n.read_at
      ) ORDER BY n.created_at DESC)
      FROM (
        SELECT id, type, title, created_at, read_at
        FROM public.portal_notifications
        WHERE bl_id = p_bl_id
        ORDER BY created_at DESC
        LIMIT 10
      ) n
    ), '[]'::JSONB),
    'open_disputes', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', d.id,
        'doc_number', d.doc_number,
        'dispute_status', d.dispute_status
      ) ORDER BY d.id DESC)
      FROM public.demurrage_invoices d
      WHERE d.bl_id = p_bl_id
        AND d.dispute_open = true
    ), '[]'::JSONB)
  );
END;
$$;



--
-- Name: get_consolidated_invoice_item_breakdown(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_consolidated_invoice_item_breakdown(p_invoice_id bigint) RETURNS TABLE(bl_id text, charge_calculation_id bigint, charge_table_id bigint, charge_item_id bigint, quantity numeric, unit_value_brl numeric, total_value_brl numeric, currency text, unit_value_usd numeric, total_value_usd numeric, calculation_key text, charge_name text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT irl.bl_id, cc.id, cc.charge_table_id, cc.charge_item_id, cc.quantity, cc.unit_value_brl, cc.total_value_brl, cti.currency, cc.unit_value_usd, cc.total_value_usd, cc.calculation_key, cti.name
  FROM public.invoice_receivable_links irl
  JOIN public.charge_calculations cc ON cc.bl_id = irl.bl_id
  LEFT JOIN public.charge_table_items cti ON cti.id = cc.charge_item_id
  WHERE public.is_active_user() AND irl.invoice_id = p_invoice_id
    AND COALESCE(cc.total_value_brl, 0) > 0
    AND COALESCE(cc.status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing', 'exempt')
  ORDER BY irl.bl_id, cc.id;
$$;



--
-- Name: get_customer_portal_account(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_portal_account(p_customer_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result JSONB;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao.' USING ERRCODE = '42501';
  END IF;
  SELECT to_jsonb(t.*) INTO v_result
  FROM (SELECT a.id, a.customer_id, a.contact_email, a.active, a.auth_user_id, a.portal_email, a.login_cnpj, a.created_by, a.last_login_at, a.created_at, a.updated_at
        FROM public.customer_portal_accounts a WHERE a.customer_id = p_customer_id) t;
  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;



