--
-- Name: get_voyage_eligible_pods(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_voyage_eligible_pods(p_voyage_id bigint) RETURNS TABLE(pod text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH latest_states AS (
    SELECT DISTINCT ON (entity_id, field_name)
      entity_id,
      field_name,
      new_value
    FROM public.audit_logs
    WHERE entity_type = 'voyage_pod_schedule'
      AND entity_id LIKE p_voyage_id || '::%'
      AND field_name IN ('deleted', 'omitted', 'tem_importacao', 'eta')
    ORDER BY entity_id, field_name, changed_at DESC
  ),
  aggregated AS (
    SELECT
      upper(btrim(split_part(entity_id, '::', 2))) AS port_code,
      bool_or(field_name = 'deleted' AND new_value = 'true') AS is_deleted,
      bool_or(field_name = 'omitted' AND new_value = 'true') AS is_omitted,
      bool_or(field_name = 'tem_importacao' AND new_value = 'false') AS is_no_import
    FROM latest_states
    GROUP BY upper(btrim(split_part(entity_id, '::', 2)))
  )
  SELECT port_code AS pod
  FROM aggregated
  WHERE NOT COALESCE(is_deleted, false)
    AND NOT COALESCE(is_omitted, false)
    AND NOT COALESCE(is_no_import, false);
$$;



--
-- Name: get_voyage_first_brazilian_eta(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_voyage_first_brazilian_eta(p_voyage_id bigint) RETURNS date
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_has_eligible_pod BOOLEAN;
  v_min_own_eta DATE;
  v_indicated_eta DATE;
  v_indicated_port TEXT;
BEGIN
  IF NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.get_voyage_eligible_pods(p_voyage_id))
    INTO v_has_eligible_pod;
  IF NOT v_has_eligible_pod THEN
    RETURN NULL;
  END IF;

  WITH latest_eta AS (
    SELECT DISTINCT ON (entity_id)
      upper(btrim(split_part(entity_id, '::', 2))) AS port_code,
      NULLIF(btrim(new_value), '')::date AS eta
    FROM public.audit_logs
    WHERE entity_type = 'voyage_pod_schedule'
      AND entity_id LIKE p_voyage_id || '::%'
      AND field_name = 'eta'
    ORDER BY entity_id, changed_at DESC
  )
  SELECT MIN(eta) INTO v_min_own_eta
  FROM latest_eta
  WHERE port_code IN (SELECT pod FROM public.get_voyage_eligible_pods(p_voyage_id));

  SELECT
    (SELECT NULLIF(btrim(new_value), '')::date FROM public.audit_logs
     WHERE entity_type = 'voyages' AND entity_id = p_voyage_id::text
       AND field_name = 'indicated_first_brazilian_eta'
     ORDER BY changed_at DESC LIMIT 1),
    (SELECT NULLIF(btrim(new_value), '') FROM public.audit_logs
     WHERE entity_type = 'voyages' AND entity_id = p_voyage_id::text
       AND field_name = 'indicated_first_brazilian_port'
     ORDER BY changed_at DESC LIMIT 1)
  INTO v_indicated_eta, v_indicated_port;

  IF v_indicated_eta IS NOT NULL AND v_indicated_port IS NOT NULL
     AND (v_min_own_eta IS NULL OR v_indicated_eta < v_min_own_eta) THEN
    RETURN v_indicated_eta;
  END IF;

  RETURN v_min_own_eta;
END;
$$;



--
-- Name: guard_container_bl_without_containers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_container_bl_without_containers() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_reason TEXT := 'B/L container sem container vinculado para calculo de taxas locais';
BEGIN
  IF COALESCE(NEW.cargo_mode, 'container') = 'container'
     AND COALESCE(NEW.charge_status, 'not_calculated') IN ('calculated', 'reviewed', 'ready_for_billing')
     AND NOT EXISTS (
       SELECT 1
       FROM public.bl_containers bc
       WHERE bc.bl_id = NEW.id
         AND TRIM(COALESCE(bc.container_number, '')) <> ''
     ) THEN
    INSERT INTO public.charge_calculations (
      bl_id,
      source,
      status,
      calculation_key,
      quantity,
      total_value_brl,
      review_reason,
      notes,
      created_by,
      calculated_at
    )
    VALUES (
      NEW.id,
      'auto',
      'review_required',
      'review:no_container',
      1,
      0,
      v_reason,
      'Revisao manual obrigatoria',
      auth.uid(),
      NOW()
    )
    ON CONFLICT (bl_id, calculation_key) DO UPDATE
      SET status = EXCLUDED.status,
          quantity = EXCLUDED.quantity,
          total_value_brl = EXCLUDED.total_value_brl,
          review_reason = EXCLUDED.review_reason,
          notes = EXCLUDED.notes,
          created_by = EXCLUDED.created_by,
          calculated_at = NOW();

    UPDATE public.bls
    SET
      charge_status = 'review_required',
      billing_hold_reason = v_reason
    WHERE id = NEW.id
      AND COALESCE(charge_status, 'not_calculated') <> 'review_required';
  END IF;

  RETURN NULL;
END;
$$;



--
-- Name: guard_granite_financial_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_granite_financial_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.charge_status = 'ready_for_billing' THEN
    NEW.charge_status := 'calculated';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: import_baplie_staging_transactional(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_baplie_staging_transactional(p_voyage_id bigint, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count INTEGER := COALESCE(jsonb_array_length(p_rows), 0);
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao para importar Baplie.' USING ERRCODE = '42501';
  END IF;

  PERFORM set_config('alerts.baplie_coverage_deferred', 'on', true);

  DELETE FROM public.baplie_containers
  WHERE voyage_id = p_voyage_id;

  IF v_count > 0 THEN
    INSERT INTO public.baplie_containers (
      voyage_id,
      container_number,
      size_type,
      status,
      weight_kg,
      pol,
      pod,
      final_dest,
      bl_ref,
      slot,
      is_imo,
      imo_class,
      un_number,
      is_oog,
      imported_by
    )
    SELECT
      p_voyage_id,
      row.container_number,
      row.size_type,
      row.status,
      row.weight_kg,
      row.pol,
      row.pod,
      row.final_dest,
      row.bl_ref,
      row.slot,
      row.is_imo,
      row.imo_class,
      row.un_number,
      row.is_oog,
      row.imported_by
    FROM jsonb_to_recordset(p_rows) AS row(
      container_number TEXT,
      size_type TEXT,
      status TEXT,
      weight_kg NUMERIC,
      pol TEXT,
      pod TEXT,
      final_dest TEXT,
      bl_ref TEXT,
      slot TEXT,
      is_imo BOOLEAN,
      imo_class TEXT,
      un_number TEXT,
      is_oog BOOLEAN,
      imported_by UUID
    );
  END IF;

  PERFORM set_config('alerts.baplie_coverage_deferred', 'off', true);
  PERFORM public.reconcile_voyage_baplie_coverage_alerts(p_voyage_id, 'baplie_coverage_import');
  RETURN v_count;
END;
$$;



--
-- Name: import_bl_freight_transactional(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_bl_freight_transactional(p_bls jsonb, p_changed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
  v_item JSONB;
  v_bl_id TEXT;
  v_next TEXT[];
  v_current TEXT[];
  v_voyage_ids BIGINT[] := ARRAY[]::BIGINT[];
  v_voyage_id BIGINT;
BEGIN
  SELECT COALESCE(array_agg(DISTINCT b.voyage_id ORDER BY b.voyage_id), ARRAY[]::BIGINT[])
  INTO v_voyage_ids
  FROM public.bls AS b
  WHERE b.id IN (
    SELECT item->>'id'
    FROM jsonb_array_elements(COALESCE(p_bls, '[]'::JSONB)) AS item
    WHERE item->>'id' IS NOT NULL
  )
    AND b.voyage_id IS NOT NULL;

  PERFORM set_config('alerts.baplie_coverage_deferred', 'on', true);
  v_result := public.import_bl_freight_transactional_legacy_357(p_bls, p_changed_by);

  FOR v_item IN SELECT item FROM jsonb_array_elements(COALESCE(p_bls, '[]'::JSONB)) AS item
  LOOP
    v_bl_id := v_item->>'id';
    CONTINUE WHEN v_bl_id IS NULL;

    v_next := public.normalize_ncm_codes(v_item->'ncm_codes');
    CONTINUE WHEN cardinality(v_next) = 0;

    SELECT ncm_codes INTO v_current FROM public.bls WHERE id = v_bl_id;
    CONTINUE WHEN NOT FOUND;
    CONTINUE WHEN v_current = v_next;

    UPDATE public.bls SET ncm_codes = v_next WHERE id = v_bl_id;

    INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
    VALUES (
      'bl',
      v_bl_id,
      'ncm_codes',
      array_to_string(COALESCE(v_current, ARRAY[]::TEXT[]), ', '),
      array_to_string(v_next, ', '),
      p_changed_by,
      'NCM declarado no documento reimportado'
    );
  END LOOP;

  PERFORM set_config('alerts.baplie_coverage_deferred', 'off', true);

  SELECT v_voyage_ids || COALESCE(array_agg(DISTINCT b.voyage_id ORDER BY b.voyage_id), ARRAY[]::BIGINT[])
  INTO v_voyage_ids
  FROM public.bls AS b
  WHERE b.id IN (
    SELECT item->>'id'
    FROM jsonb_array_elements(COALESCE(p_bls, '[]'::JSONB)) AS item
    WHERE item->>'id' IS NOT NULL
  )
    AND b.voyage_id IS NOT NULL;

  FOR v_voyage_id IN
    SELECT DISTINCT ids.voyage_id
    FROM unnest(v_voyage_ids) AS ids(voyage_id)
    WHERE ids.voyage_id IS NOT NULL
    ORDER BY ids.voyage_id
  LOOP
    PERFORM public.reconcile_voyage_baplie_coverage_alerts(v_voyage_id, 'baplie_coverage_import');
  END LOOP;

  RETURN v_result;
END;
$$;



--
-- Name: import_bl_freight_transactional_legacy_205(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_bl_freight_transactional_legacy_205(p_bls jsonb, p_changed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_total_bls INTEGER := COALESCE(jsonb_array_length(p_bls), 0);
  v_inserted_freight_lines INTEGER := 0;
  v_locked_bls TEXT[] := ARRAY[]::TEXT[];
  v_unlocked_bls TEXT[] := ARRAY[]::TEXT[];
  v_container_bls TEXT[] := ARRAY[]::TEXT[];
  v_vehicle_bls TEXT[] := ARRAY[]::TEXT[];
  v_weight_locked_bls TEXT[] := ARRAY[]::TEXT[];
  v_billing_hold_bls TEXT[] := ARRAY[]::TEXT[];
  v_imported_bl_ids TEXT[] := ARRAY[]::TEXT[];
  v_bl_id TEXT;
  v_inserted_vehicles INTEGER := 0;
  v_vehicle_items_total INTEGER := 0;
  v_vehicles_skipped INTEGER := 0;
  v_audited_fields TEXT[] := ARRAY[
    'voyage_id',
    'cargo_mode',
    'shipper',
    'consignee',
    'notify_party',
    'customer_id',
    'customer_reconciliation_status',
    'customer_reconciliation_notes',
    'billing_hold_reason',
    'pol',
    'pod',
    'place_of_delivery',
    'place_of_receipt',
    'movement_from',
    'movement_to',
    'issue_place',
    'cargo_description',
    'total_packages',
    'packages_unit',
    'consignee_phone',
    'total_weight_kg',
    'total_cbm',
    'incoterm',
    'payment_type',
    'bl_emission_date',
    'manifest_customer_cnpj_cpf',
    'manifest_customer_name',
    'manifest_customer_email',
    'notes'
  ];
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.is_active_user()
     OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Credenciais invalidas para importar frete do BL.'
      USING ERRCODE = '42501';
  END IF;

  IF p_bls IS NULL OR jsonb_typeof(p_bls) <> 'array' THEN
    RAISE EXCEPTION 'Payload de B/Ls invalido.'
      USING ERRCODE = '22023';
  END IF;

  CREATE TEMP TABLE pg_temp.tmp_bl_freight_import (
    id TEXT PRIMARY KEY,
    payload JSONB NOT NULL,
    voyage_id BIGINT,
    batch_id BIGINT,
    cargo_mode TEXT,
    shipper TEXT,
    consignee TEXT,
    notify_party TEXT,
    consignee_block TEXT,
    shipper_block TEXT,
    notify_block TEXT,
    notify2_block TEXT,
    notify_cnpj_cpf TEXT,
    customer_id BIGINT,
    customer_reconciliation_status TEXT,
    customer_reconciliation_notes TEXT,
    billing_hold_reason TEXT,
    pol TEXT,
    pod TEXT,
    place_of_delivery TEXT,
    place_of_receipt TEXT,
    movement_from TEXT,
    movement_to TEXT,
    issue_place TEXT,
    cargo_description TEXT,
    total_packages INTEGER,
    packages_unit TEXT,
    consignee_phone TEXT,
    total_weight_kg NUMERIC,
    total_cbm NUMERIC,
    incoterm TEXT,
    payment_type TEXT,
    bl_emission_date DATE,
    manifest_customer_cnpj_cpf TEXT,
    manifest_customer_name TEXT,
    manifest_customer_email TEXT,
    notes TEXT,
    billing_locked BOOLEAN NOT NULL DEFAULT false,
    override_billing BOOLEAN NOT NULL DEFAULT false,
    billing_impact BOOLEAN NOT NULL DEFAULT false
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.tmp_bl_freight_import (
    id,
    payload,
    voyage_id,
    batch_id,
    cargo_mode,
    shipper,
    consignee,
    notify_party,
    consignee_block,
    shipper_block,
    notify_block,
    notify2_block,
    notify_cnpj_cpf,
    customer_id,
    customer_reconciliation_status,
    customer_reconciliation_notes,
    billing_hold_reason,
    pol,
    pod,
    place_of_delivery,
    place_of_receipt,
    movement_from,
    movement_to,
    issue_place,
    cargo_description,
    total_packages,
    packages_unit,
    consignee_phone,
    total_weight_kg,
    total_cbm,
    incoterm,
    payment_type,
    bl_emission_date,
    manifest_customer_cnpj_cpf,
    manifest_customer_name,
    manifest_customer_email,
    notes,
    override_billing,
    billing_impact
  )
  SELECT
    NULLIF(bl->>'id', ''),
    bl,
    NULLIF(bl->>'voyage_id', '')::BIGINT,
    NULLIF(bl->>'batch_id', '')::BIGINT,
    NULLIF(bl->>'cargo_mode', ''),
    NULLIF(bl->>'shipper', ''),
    NULLIF(bl->>'consignee', ''),
    NULLIF(bl->>'notify_party', ''),
    NULLIF(bl->>'consignee_block', ''),
    NULLIF(bl->>'shipper_block', ''),
    NULLIF(bl->>'notify_block', ''),
    NULLIF(bl->>'notify2_block', ''),
    NULLIF(bl->>'notify_cnpj_cpf', ''),
    NULLIF(bl->>'customer_id', '')::BIGINT,
    reconciliation.status,
    COALESCE(
      NULLIF(bl->>'customer_reconciliation_notes', ''),
      CASE
        WHEN reconciliation.status = 'matched_document' THEN 'Cliente reconciliado automaticamente por CNPJ/CPF.'
        WHEN reconciliation.status = 'matched_name' THEN 'Cliente sugerido por nome; validar documento.'
        ELSE 'Cliente nao encontrado na base cadastral.'
      END
    ),
    COALESCE(
      NULLIF(bl->>'billing_hold_reason', ''),
      CASE
        WHEN reconciliation.status = 'matched_document' THEN NULL
        ELSE 'Aguardando reconciliacao de cliente antes do faturamento.'
      END
    ),
    NULLIF(bl->>'pol', ''),
    NULLIF(bl->>'pod', ''),
    NULLIF(bl->>'place_of_delivery', ''),
    NULLIF(bl->>'place_of_receipt', ''),
    NULLIF(bl->>'movement_from', ''),
    NULLIF(bl->>'movement_to', ''),
    NULLIF(bl->>'issue_place', ''),
    NULLIF(bl->>'cargo_description', ''),
    NULLIF(bl->>'total_packages', '')::INTEGER,
    NULLIF(bl->>'packages_unit', ''),
    NULLIF(bl->>'consignee_phone', ''),
    NULLIF(bl->>'total_weight_kg', '')::NUMERIC,
    NULLIF(bl->>'total_cbm', '')::NUMERIC,
    NULLIF(bl->>'incoterm', ''),
    NULLIF(bl->>'payment_type', ''),
    NULLIF(bl->>'bl_emission_date', '')::DATE,
    public.normalize_document_text(bl->>'manifest_customer_cnpj_cpf'),
    NULLIF(bl->>'manifest_customer_name', ''),
    NULLIF(bl->>'manifest_customer_email', ''),
    NULLIF(bl->>'notes', ''),
    COALESCE(NULLIF(bl->>'override_billing', '')::BOOLEAN, false),
    COALESCE(NULLIF(bl->>'billing_impact', '')::BOOLEAN, false)
  FROM jsonb_array_elements(p_bls) AS bl
  CROSS JOIN LATERAL (
    SELECT COALESCE(
      NULLIF(bl->>'customer_reconciliation_status', ''),
      CASE
        WHEN NULLIF(bl->>'customer_id', '') IS NOT NULL THEN 'matched_document'
        ELSE 'missing_customer'
      END
    ) AS status
  ) AS reconciliation;

  IF EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import WHERE id IS NULL) THEN
    RAISE EXCEPTION 'B/L sem identificador no payload de frete.'
      USING ERRCODE = '22023';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM pg_temp.tmp_bl_freight_import
    WHERE customer_reconciliation_status NOT IN ('matched_document', 'matched_name', 'missing_customer', 'reconciled')
  ) THEN
    RAISE EXCEPTION 'Status de reconciliacao de cliente invalido no payload de frete.'
      USING ERRCODE = '22023';
  END IF;

  UPDATE pg_temp.tmp_bl_freight_import AS t
  SET billing_locked = EXISTS (
    SELECT 1
    FROM public.charge_calculations AS cc
    WHERE cc.bl_id = t.id
  ) OR EXISTS (
    SELECT 1
    FROM public.invoice_bls AS ib
    WHERE ib.bl_id = t.id
  )
  WHERE EXISTS (
    SELECT 1
    FROM public.bls AS b
    WHERE b.id = t.id
  );

  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::TEXT[])
  INTO v_locked_bls
  FROM pg_temp.tmp_bl_freight_import
  WHERE billing_locked;

  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::TEXT[])
  INTO v_unlocked_bls
  FROM pg_temp.tmp_bl_freight_import
  WHERE NOT billing_locked;

  SELECT COALESCE(array_agg(t.id ORDER BY t.id), ARRAY[]::TEXT[])
  INTO v_weight_locked_bls
  FROM pg_temp.tmp_bl_freight_import AS t
  JOIN public.bls AS b ON b.id = t.id
  WHERE t.billing_locked
    AND NOT t.override_billing
    AND b.cargo_mode = 'carga_solta';

  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::TEXT[])
  INTO v_billing_hold_bls
  FROM pg_temp.tmp_bl_freight_import
  WHERE billing_locked
    AND NOT override_billing;

  CREATE TEMP TABLE pg_temp.tmp_old_bl_values ON COMMIT DROP AS
  SELECT
    b.id,
    to_jsonb(b) AS old_row,
    to_jsonb(t) AS new_row,
    t.billing_locked
  FROM public.bls AS b
  JOIN pg_temp.tmp_bl_freight_import AS t ON t.id = b.id;

  INSERT INTO public.bls (
    id,
    voyage_id,
    batch_id,
    cargo_mode,
    shipper,
    consignee,
    notify_party,
    consignee_block,
    shipper_block,
    notify_block,
    notify2_block,
    notify_cnpj_cpf,
    customer_id,
    customer_reconciliation_status,
    customer_reconciliation_notes,
    billing_hold_reason,
    pol,
    pod,
    place_of_delivery,
    place_of_receipt,
    movement_from,
    movement_to,
    issue_place,
    cargo_description,
    total_packages,
    packages_unit,
    consignee_phone,
    total_weight_kg,
    total_cbm,
    incoterm,
    payment_type,
    bl_emission_date,
    manifest_customer_cnpj_cpf,
    manifest_customer_name,
    manifest_customer_email,
    notes
  )
  SELECT
    id,
    voyage_id,
    batch_id,
    COALESCE(cargo_mode, 'container'),
    shipper,
    consignee,
    notify_party,
    consignee_block,
    shipper_block,
    notify_block,
    notify2_block,
    notify_cnpj_cpf,
    customer_id,
    customer_reconciliation_status,
    customer_reconciliation_notes,
    billing_hold_reason,
    pol,
    pod,
    place_of_delivery,
    place_of_receipt,
    movement_from,
    movement_to,
    issue_place,
    cargo_description,
    total_packages,
    packages_unit,
    consignee_phone,
    total_weight_kg,
    total_cbm,
    incoterm,
    payment_type,
    bl_emission_date,
    manifest_customer_cnpj_cpf,
    COALESCE(manifest_customer_name, consignee),
    manifest_customer_email,
    notes
  FROM pg_temp.tmp_bl_freight_import
  ON CONFLICT (id) DO UPDATE SET
    voyage_id = CASE WHEN EXCLUDED.id = ANY(v_unlocked_bls) AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'voyage_id') THEN EXCLUDED.voyage_id ELSE bls.voyage_id END,
    batch_id = CASE WHEN EXCLUDED.id = ANY(v_unlocked_bls) AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'batch_id') THEN EXCLUDED.batch_id ELSE bls.batch_id END,
    cargo_mode = CASE WHEN EXCLUDED.id = ANY(v_unlocked_bls) AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'cargo_mode') THEN EXCLUDED.cargo_mode ELSE bls.cargo_mode END,
    shipper = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'shipper') THEN EXCLUDED.shipper ELSE bls.shipper END,
    consignee = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'consignee') THEN EXCLUDED.consignee ELSE bls.consignee END,
    notify_party = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'notify_party') THEN EXCLUDED.notify_party ELSE bls.notify_party END,
    consignee_block = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'consignee_block') THEN EXCLUDED.consignee_block ELSE bls.consignee_block END,
    shipper_block = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'shipper_block') THEN EXCLUDED.shipper_block ELSE bls.shipper_block END,
    notify_block = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'notify_block') THEN EXCLUDED.notify_block ELSE bls.notify_block END,
    notify2_block = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'notify2_block') THEN EXCLUDED.notify2_block ELSE bls.notify2_block END,
    notify_cnpj_cpf = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'notify_cnpj_cpf') THEN EXCLUDED.notify_cnpj_cpf ELSE bls.notify_cnpj_cpf END,
    customer_id = CASE
      WHEN bls.customer_id IS NULL
        AND EXCLUDED.customer_id IS NOT NULL
        AND EXCLUDED.id <> ALL(v_billing_hold_bls)
        THEN EXCLUDED.customer_id
      ELSE bls.customer_id
    END,
    customer_reconciliation_status = CASE
      WHEN bls.customer_id IS NULL
        AND EXCLUDED.customer_id IS NOT NULL
        AND EXCLUDED.id <> ALL(v_billing_hold_bls)
        THEN EXCLUDED.customer_reconciliation_status
      WHEN bls.customer_id = EXCLUDED.customer_id
        AND EXCLUDED.customer_id IS NOT NULL
        AND COALESCE(bls.customer_reconciliation_status, 'missing_customer') IN ('missing_customer', 'matched_name')
        AND EXCLUDED.customer_reconciliation_status IN ('matched_document', 'matched_name')
        AND EXCLUDED.id <> ALL(v_billing_hold_bls)
        THEN EXCLUDED.customer_reconciliation_status
      WHEN COALESCE(bls.customer_reconciliation_status, '') = ''
        AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'customer_reconciliation_status')
        THEN EXCLUDED.customer_reconciliation_status
      ELSE bls.customer_reconciliation_status
    END,
    customer_reconciliation_notes = CASE
      WHEN bls.customer_id IS NULL
        AND EXCLUDED.customer_id IS NOT NULL
        AND EXCLUDED.id <> ALL(v_billing_hold_bls)
        THEN EXCLUDED.customer_reconciliation_notes
      WHEN bls.customer_id = EXCLUDED.customer_id
        AND EXCLUDED.customer_id IS NOT NULL
        AND COALESCE(bls.customer_reconciliation_status, 'missing_customer') IN ('missing_customer', 'matched_name')
        AND EXCLUDED.customer_reconciliation_status IN ('matched_document', 'matched_name')
        AND EXCLUDED.id <> ALL(v_billing_hold_bls)
        THEN EXCLUDED.customer_reconciliation_notes
      WHEN COALESCE(bls.customer_reconciliation_notes, '') = ''
        AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'customer_reconciliation_notes')
        THEN EXCLUDED.customer_reconciliation_notes
      ELSE bls.customer_reconciliation_notes
    END,
    billing_hold_reason = CASE
      WHEN bls.customer_id IS NULL
        AND EXCLUDED.customer_id IS NOT NULL
        AND EXCLUDED.id <> ALL(v_billing_hold_bls)
        THEN EXCLUDED.billing_hold_reason
      WHEN bls.customer_id = EXCLUDED.customer_id
        AND EXCLUDED.customer_id IS NOT NULL
        AND COALESCE(bls.customer_reconciliation_status, 'missing_customer') IN ('missing_customer', 'matched_name')
        AND EXCLUDED.customer_reconciliation_status IN ('matched_document', 'matched_name')
        AND EXCLUDED.id <> ALL(v_billing_hold_bls)
        THEN EXCLUDED.billing_hold_reason
      WHEN COALESCE(bls.billing_hold_reason, '') = ''
        AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'billing_hold_reason')
        THEN EXCLUDED.billing_hold_reason
      ELSE bls.billing_hold_reason
    END,
    pol = CASE WHEN EXCLUDED.id = ANY(v_unlocked_bls) AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'pol') THEN EXCLUDED.pol ELSE bls.pol END,
    pod = CASE WHEN EXCLUDED.id = ANY(v_unlocked_bls) AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'pod') THEN EXCLUDED.pod ELSE bls.pod END,
    place_of_delivery = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'place_of_delivery') THEN EXCLUDED.place_of_delivery ELSE bls.place_of_delivery END,
    place_of_receipt = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'place_of_receipt') THEN EXCLUDED.place_of_receipt ELSE bls.place_of_receipt END,
    movement_from = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'movement_from') THEN EXCLUDED.movement_from ELSE bls.movement_from END,
    movement_to = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'movement_to') THEN EXCLUDED.movement_to ELSE bls.movement_to END,
    issue_place = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'issue_place') THEN EXCLUDED.issue_place ELSE bls.issue_place END,
    cargo_description = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'cargo_description') THEN EXCLUDED.cargo_description ELSE bls.cargo_description END,
    total_packages = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'total_packages') THEN EXCLUDED.total_packages ELSE bls.total_packages END,
    packages_unit = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'packages_unit') THEN EXCLUDED.packages_unit ELSE bls.packages_unit END,
    consignee_phone = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'consignee_phone') THEN EXCLUDED.consignee_phone ELSE bls.consignee_phone END,
    total_weight_kg = CASE WHEN EXCLUDED.id <> ALL(v_weight_locked_bls) AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'total_weight_kg') THEN EXCLUDED.total_weight_kg ELSE bls.total_weight_kg END,
    total_cbm = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'total_cbm') THEN EXCLUDED.total_cbm ELSE bls.total_cbm END,
    incoterm = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'incoterm') THEN EXCLUDED.incoterm ELSE bls.incoterm END,
    payment_type = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'payment_type') THEN EXCLUDED.payment_type ELSE bls.payment_type END,
    bl_emission_date = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'bl_emission_date') THEN EXCLUDED.bl_emission_date ELSE bls.bl_emission_date END,
    manifest_customer_cnpj_cpf = CASE WHEN EXCLUDED.id <> ALL(v_billing_hold_bls) AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'manifest_customer_cnpj_cpf') THEN EXCLUDED.manifest_customer_cnpj_cpf ELSE bls.manifest_customer_cnpj_cpf END,
    manifest_customer_name = CASE WHEN EXCLUDED.id <> ALL(v_billing_hold_bls) AND EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'manifest_customer_name') THEN EXCLUDED.manifest_customer_name ELSE bls.manifest_customer_name END,
    manifest_customer_email = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'manifest_customer_email') THEN EXCLUDED.manifest_customer_email ELSE bls.manifest_customer_email END,
    notes = CASE WHEN EXISTS (SELECT 1 FROM pg_temp.tmp_bl_freight_import t WHERE t.id = EXCLUDED.id AND t.payload ? 'notes') THEN EXCLUDED.notes ELSE bls.notes END,
    updated_at = now();

  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::TEXT[])
  INTO v_imported_bl_ids
  FROM pg_temp.tmp_bl_freight_import;

  INSERT INTO public.audit_logs (
    entity_type,
    entity_id,
    field_name,
    old_value,
    new_value,
    changed_by,
    justification
  )
  SELECT
    'bl',
    old_values.id,
    field_name,
    old_values.old_row->>field_name,
    to_jsonb(b)->>field_name,
    p_changed_by,
    CASE
      WHEN old_values.billing_locked THEN 'Importacao automatica de frete do BL; campos operacionais protegidos por faturamento existente'
      ELSE 'Importacao automatica de frete do BL'
    END
  FROM pg_temp.tmp_old_bl_values AS old_values
  JOIN public.bls AS b ON b.id = old_values.id
  CROSS JOIN unnest(v_audited_fields) AS audited(field_name)
  WHERE COALESCE(old_values.old_row->>field_name, '') IS DISTINCT FROM COALESCE(to_jsonb(b)->>field_name, '');

  DELETE FROM public.bl_freight_lines
  WHERE bl_id IN (
    SELECT id
    FROM pg_temp.tmp_bl_freight_import
    WHERE payload ? 'freight_lines'
       OR payload ? 'freightLines'
  );

  INSERT INTO public.bl_freight_lines (
    bl_id,
    seq,
    description,
    category,
    mercante_code,
    currency,
    amount,
    payment
  )
  SELECT
    t.id,
    COALESCE(NULLIF(line.item->>'seq', '')::INTEGER, line.ordinality::INTEGER),
    NULLIF(line.item->>'description', ''),
    NULLIF(line.item->>'category', ''),
    NULLIF(line.item->>'mercante_code', ''),
    NULLIF(line.item->>'currency', ''),
    NULLIF(line.item->>'amount', '')::NUMERIC,
    NULLIF(line.item->>'payment', '')
  FROM pg_temp.tmp_bl_freight_import AS t
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(COALESCE(t.payload->'freight_lines', t.payload->'freightLines')) = 'array'
        THEN COALESCE(t.payload->'freight_lines', t.payload->'freightLines')
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS line(item, ordinality);

  GET DIAGNOSTICS v_inserted_freight_lines = ROW_COUNT;

  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::TEXT[])
  INTO v_container_bls
  FROM pg_temp.tmp_bl_freight_import
  WHERE (NOT billing_locked OR override_billing)
    AND payload ? 'containers';

  SELECT COALESCE(array_agg(id ORDER BY id), ARRAY[]::TEXT[])
  INTO v_vehicle_bls
  FROM pg_temp.tmp_bl_freight_import
  WHERE (NOT billing_locked OR override_billing)
    AND payload ? 'vehicles';

  CREATE TEMP TABLE pg_temp.tmp_new_containers (
    id BIGINT,
    bl_id TEXT,
    container_number TEXT
  ) ON COMMIT DROP;

  DELETE FROM public.vehicles
  WHERE bl_id = ANY(v_vehicle_bls);

  DELETE FROM public.bl_containers
  WHERE bl_id = ANY(v_container_bls);

  WITH inserted AS (
    INSERT INTO public.bl_containers (
      bl_id,
      container_number,
      seal_number,
      type,
      tare_weight_kg,
      gross_weight_kg,
      cbm,
      is_oog,
      is_imo,
      imo_class,
      un_number
    )
    SELECT
      t.id,
      c.item->>'container_number',
      NULLIF(c.item->>'seal_number', ''),
      NULLIF(c.item->>'type', ''),
      NULLIF(c.item->>'tare_weight_kg', '')::NUMERIC,
      NULLIF(c.item->>'gross_weight_kg', '')::NUMERIC,
      NULLIF(c.item->>'cbm', '')::NUMERIC,
      COALESCE(NULLIF(c.item->>'is_oog', '')::BOOLEAN, false),
      COALESCE(NULLIF(c.item->>'is_imo', '')::BOOLEAN, false),
      NULLIF(c.item->>'imo_class', ''),
      NULLIF(c.item->>'un_number', '')
    FROM pg_temp.tmp_bl_freight_import AS t
    CROSS JOIN LATERAL jsonb_array_elements(
      CASE
        WHEN jsonb_typeof(t.payload->'containers') = 'array' THEN t.payload->'containers'
        ELSE '[]'::jsonb
      END
    ) AS c(item)
    WHERE t.id = ANY(v_container_bls)
      AND NULLIF(c.item->>'container_number', '') IS NOT NULL
    RETURNING id, bl_id, container_number
  )
  INSERT INTO pg_temp.tmp_new_containers (id, bl_id, container_number)
  SELECT id, bl_id, container_number
  FROM inserted;

  SELECT COALESCE(SUM(
    jsonb_array_length(
      CASE WHEN jsonb_typeof(t.payload->'vehicles') = 'array' THEN t.payload->'vehicles' ELSE '[]'::jsonb END
    )
  ), 0)
  INTO v_vehicle_items_total
  FROM pg_temp.tmp_bl_freight_import AS t
  WHERE t.id = ANY(v_vehicle_bls);

  INSERT INTO public.vehicles (
    voyage_id,
    container_id,
    bl_id,
    chassis,
    brand,
    model,
    weight_kg,
    cbm
  )
  SELECT
    COALESCE(NULLIF(v.item->>'voyage_id', '')::BIGINT, b.voyage_id),
    COALESCE(NULLIF(v.item->>'container_id', '')::BIGINT, c.id),
    t.id,
    v.item->>'chassis',
    v.item->>'brand',
    v.item->>'model',
    NULLIF(v.item->>'weight_kg', '')::NUMERIC,
    NULLIF(v.item->>'cbm', '')::NUMERIC
  FROM pg_temp.tmp_bl_freight_import AS t
  JOIN public.bls AS b ON b.id = t.id
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(t.payload->'vehicles') = 'array' THEN t.payload->'vehicles'
      ELSE '[]'::jsonb
    END
  ) AS v(item)
  LEFT JOIN pg_temp.tmp_new_containers AS c
    ON c.bl_id = t.id
   AND c.container_number = NULLIF(v.item->>'container_number', '')
  WHERE t.id = ANY(v_vehicle_bls)
    AND NULLIF(v.item->>'chassis', '') IS NOT NULL
    AND COALESCE(NULLIF(v.item->>'container_id', '')::BIGINT, c.id) IS NOT NULL;

  GET DIAGNOSTICS v_inserted_vehicles = ROW_COUNT;
  v_vehicles_skipped := GREATEST(v_vehicle_items_total - v_inserted_vehicles, 0);

  INSERT INTO public.audit_logs (
    entity_type,
    entity_id,
    field_name,
    old_value,
    new_value,
    changed_by,
    justification
  )
  SELECT
    'bl',
    t.id,
    'ALTERACAO_OPERACIONAL_BLOQUEADA',
    NULL,
    'billing_locked',
    p_changed_by,
    'Importacao de frete do BL: alteracao com impacto em faturamento bloqueada (sem override do operador)'
  FROM pg_temp.tmp_bl_freight_import AS t
  WHERE t.billing_locked
    AND t.billing_impact
    AND NOT t.override_billing;

  INSERT INTO public.audit_logs (
    entity_type,
    entity_id,
    field_name,
    old_value,
    new_value,
    changed_by,
    justification
  )
  SELECT
    'bl',
    t.id,
    'FATURAMENTO_SOBRESCRITO',
    NULL,
    'override_billing',
    p_changed_by,
    'Importacao de frete do BL: alteracao com impacto em faturamento aplicada por override do operador'
  FROM pg_temp.tmp_bl_freight_import AS t
  WHERE t.billing_locked
    AND t.billing_impact
    AND t.override_billing;

  PERFORM public.apply_bl_review_gate_after_import(v_imported_bl_ids, p_changed_by);

  UPDATE public.bls AS b
  SET
    review_status = 'pending_review',
    billing_hold_reason = COALESCE(NULLIF(b.billing_hold_reason, ''), 'Aguardando reconciliacao de cliente antes do faturamento.'),
    notes = CASE
      WHEN COALESCE(b.notes, '') ILIKE '%Cliente vinculado por nome; validar CNPJ%' THEN b.notes
      WHEN COALESCE(b.notes, '') ILIKE '%Pendencias de importacao:%'
        THEN b.notes || ', Cliente vinculado por nome; validar CNPJ'
      ELSE CONCAT_WS(E'\n', NULLIF(BTRIM(COALESCE(b.notes, '')), ''), 'Pendencias de importacao: Cliente vinculado por nome; validar CNPJ')
    END
  WHERE b.id = ANY(v_imported_bl_ids)
    AND b.customer_reconciliation_status = 'matched_name'
    AND COALESCE(b.financial_status, 'pending') <> 'invoiced';

  FOREACH v_bl_id IN ARRAY v_imported_bl_ids LOOP
    PERFORM public.sync_customer_reconciliation_queue_for_bl(v_bl_id);
  END LOOP;

  RETURN jsonb_build_object(
    'bls_received', v_total_bls,
    'freight_lines_inserted', v_inserted_freight_lines,
    'billing_locked', v_locked_bls,
    'operational_updated', v_unlocked_bls,
    'vehicles_inserted', v_inserted_vehicles,
    'vehicles_skipped', v_vehicles_skipped
  );
END;
$$;



--
-- Name: import_bl_freight_transactional_legacy_284(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_bl_freight_transactional_legacy_284(p_bls jsonb, p_changed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
  v_bl_id TEXT;
BEGIN
  v_result := public.import_bl_freight_transactional_legacy_205(p_bls, p_changed_by);

  UPDATE public.bls AS b
  SET
    suggested_customer_id = NULLIF(item->>'suggested_customer_id', '')::BIGINT,
    notes = CASE
      WHEN b.customer_reconciliation_status = 'matched_name' THEN regexp_replace(
        COALESCE(b.notes, ''),
        'Cliente vinculado por nome[^\n]*',
        'Cliente nao vinculado',
        'ig'
      )
      ELSE b.notes
    END
  FROM jsonb_array_elements(COALESCE(p_bls, '[]'::jsonb)) AS item
  WHERE b.id = item->>'id';

  FOR v_bl_id IN
    SELECT item->>'id'
    FROM jsonb_array_elements(COALESCE(p_bls, '[]'::jsonb)) AS item
    WHERE item->>'id' IS NOT NULL
  LOOP
    PERFORM public.sync_customer_reconciliation_queue_for_bl(v_bl_id);
  END LOOP;

  RETURN v_result;
END;
$$;



--
-- Name: import_bl_freight_transactional_legacy_322(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_bl_freight_transactional_legacy_322(p_bls jsonb, p_changed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_result JSONB;
  v_bl_id TEXT;
  v_email TEXT;
  v_customer_id BIGINT;
  v_reasons TEXT[];
  v_human_notes TEXT;
  v_notes TEXT;
  v_review_status TEXT;
  v_financial_status TEXT;
  v_new_review_status TEXT;
  v_has_active_invoice BOOLEAN;
BEGIN
  v_result := public.import_bl_freight_transactional_legacy_284(p_bls, p_changed_by);

  FOR v_bl_id, v_email IN
    SELECT item->>'id', NULLIF(btrim(item->>'manifest_customer_email'), '')
    FROM jsonb_array_elements(COALESCE(p_bls, '[]'::JSONB)) AS item
    WHERE item->>'id' IS NOT NULL
  LOOP
    IF v_email IS NOT NULL THEN
      SELECT customer_id INTO v_customer_id FROM public.bls WHERE id = v_bl_id;
      IF v_customer_id IS NOT NULL THEN
        PERFORM public.ensure_customer_contact_email(v_customer_id, v_email);
      END IF;
    END IF;

    SELECT
      b.notes,
      b.review_status,
      b.financial_status,
      EXISTS (
        SELECT 1
        FROM public.invoice_bls AS ib
        JOIN public.invoices AS i ON i.id = ib.invoice_id
        WHERE ib.bl_id = b.id
          AND i.status NOT IN ('cancelled', 'obsolete')
      )
    INTO v_notes, v_review_status, v_financial_status, v_has_active_invoice
    FROM public.bls AS b
    WHERE b.id = v_bl_id;

    IF NOT FOUND THEN CONTINUE; END IF;
    IF v_financial_status = 'invoiced' OR v_has_active_invoice THEN CONTINUE; END IF;

    v_reasons := public.compute_bl_review_pendencies(v_bl_id);
    v_human_notes := btrim(
      regexp_replace(
        COALESCE(v_notes, ''),
        E'(^|\\n)Pendencias de importacao:[^\\n]*$',
        '',
        'i'
      )
    );
    v_notes := CASE
      WHEN COALESCE(cardinality(v_reasons), 0) > 0 THEN concat_ws(
        E'\n',
        NULLIF(v_human_notes, ''),
        'Pendencias de importacao: ' || array_to_string(v_reasons, ', ')
      )
      ELSE NULLIF(v_human_notes, '')
    END;

    v_new_review_status := CASE WHEN COALESCE(cardinality(v_reasons), 0) = 0 THEN 'reviewed' ELSE 'pending_review' END;

    UPDATE public.bls
    SET review_status = v_new_review_status,
        notes = v_notes
    WHERE id = v_bl_id;

    IF v_review_status IS DISTINCT FROM v_new_review_status THEN
      INSERT INTO public.audit_logs (
        entity_type, entity_id, field_name, old_value, new_value, changed_by, justification
      )
      VALUES (
        'bl', v_bl_id, 'review_status', v_review_status, v_new_review_status, p_changed_by,
        'Gate canonico reaplicado apos e-mail importado'
      );
    END IF;

    PERFORM public.sync_customer_reconciliation_queue_for_bl(v_bl_id);
  END LOOP;

  RETURN v_result;
END;
$_$;



--
-- Name: import_bl_freight_transactional_legacy_357(jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_bl_freight_transactional_legacy_357(p_bls jsonb, p_changed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
  v_item JSONB;
  v_bl_id TEXT;
  v_billed BOOLEAN;
  v_before public.bls%ROWTYPE;
  v_relinks JSONB := '[]'::JSONB;
  v_relink JSONB;
  v_route_fields TEXT[] := ARRAY['voyage_id', 'pol', 'pod', 'cargo_mode'];
BEGIN
  v_result := public.import_bl_freight_transactional_legacy_322(p_bls, p_changed_by);

  FOR v_item IN SELECT item FROM jsonb_array_elements(COALESCE(p_bls, '[]'::JSONB)) AS item
  LOOP
    v_bl_id := v_item->>'id';
    CONTINUE WHEN v_bl_id IS NULL;

    SELECT * INTO v_before FROM public.bls WHERE id = v_bl_id;
    CONTINUE WHEN NOT FOUND;

    v_billed :=
      EXISTS (SELECT 1 FROM public.charge_calculations WHERE bl_id = v_bl_id)
      OR EXISTS (SELECT 1 FROM public.invoice_bls WHERE bl_id = v_bl_id);

    -- Rota e viagem de B/L faturado: a 205 as descartava mesmo com override.
    IF v_billed AND COALESCE((v_item->>'override_billing')::BOOLEAN, false) THEN
      UPDATE public.bls
      SET
        voyage_id  = CASE WHEN v_item ? 'voyage_id'  THEN NULLIF(v_item->>'voyage_id', '')::BIGINT ELSE voyage_id END,
        pol        = CASE WHEN v_item ? 'pol'        THEN NULLIF(v_item->>'pol', '') ELSE pol END,
        pod        = CASE WHEN v_item ? 'pod'        THEN NULLIF(v_item->>'pod', '') ELSE pod END,
        cargo_mode = CASE WHEN v_item ? 'cargo_mode' THEN COALESCE(NULLIF(v_item->>'cargo_mode', ''), cargo_mode) ELSE cargo_mode END
      WHERE id = v_bl_id;

      INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
      SELECT
        'bl',
        v_bl_id,
        audited.field_name,
        to_jsonb(v_before)->>audited.field_name,
        to_jsonb(b)->>audited.field_name,
        p_changed_by,
        'Reimportacao de B/L faturado com override: rota/viagem sobrescritas'
      FROM public.bls AS b
      CROSS JOIN unnest(v_route_fields) AS audited(field_name)
      WHERE b.id = v_bl_id
        AND COALESCE(to_jsonb(v_before)->>audited.field_name, '')
            IS DISTINCT FROM COALESCE(to_jsonb(b)->>audited.field_name, '');
    END IF;

    -- Troca de consignatário aceita pelo operador no preview.
    IF COALESCE((v_item->>'relink_customer')::BOOLEAN, false) THEN
      v_relink := public.relink_bl_customer(
        v_bl_id,
        NULLIF(v_item->>'customer_id', '')::BIGINT,
        p_changed_by
      );
      v_relinks := v_relinks || jsonb_build_array(v_relink);

      -- Aceitar a troca autoriza também o documento do consignatário: a `205`
      -- protege `manifest_customer_cnpj_cpf`/`_name` em B/L faturado sem
      -- `override_billing`, e sem isto o B/L ficaria com o cliente novo e o
      -- CNPJ antigo. `unchanged` entra junto: o documento pode mudar apontando
      -- para o mesmo cliente já vinculado, e a correção de CNPJ prometida no
      -- preview era descartada.
      IF COALESCE((v_relink->>'applied')::BOOLEAN, false)
         OR COALESCE((v_relink->>'unchanged')::BOOLEAN, false) THEN
        UPDATE public.bls
        SET
          manifest_customer_cnpj_cpf = CASE
            WHEN v_item ? 'manifest_customer_cnpj_cpf'
              THEN public.normalize_document_text(v_item->>'manifest_customer_cnpj_cpf')
            ELSE manifest_customer_cnpj_cpf
          END,
          manifest_customer_name = CASE
            WHEN v_item ? 'manifest_customer_name'
              THEN COALESCE(NULLIF(v_item->>'manifest_customer_name', ''), manifest_customer_name)
            ELSE manifest_customer_name
          END
        WHERE id = v_bl_id;

        -- A fila de reconciliação copia CNPJ e nome do B/L: sincronizada dentro
        -- do relink ela guardava o documento anterior. Idempotente, roda de novo.
        PERFORM public.sync_customer_reconciliation_queue_for_bl(v_bl_id);
      END IF;
    END IF;
  END LOOP;

  IF jsonb_array_length(v_relinks) > 0 THEN
    PERFORM public.apply_bl_review_gate_after_import(
      ARRAY(SELECT entry->>'bl_id' FROM jsonb_array_elements(v_relinks) AS entry),
      p_changed_by
    );
  END IF;

  RETURN COALESCE(v_result, '{}'::JSONB) || jsonb_build_object('customer_relinks', v_relinks);
END;
$$;



--
-- Name: import_breakbulk_manifest_transactional(text, bigint, uuid, integer, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_breakbulk_manifest_transactional(p_filename text, p_voyage_id bigint, p_uploaded_by uuid, p_total_bls integer, p_bls jsonb, p_items jsonb, p_errors jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch_id BIGINT;
  v_bl_ids TEXT[];
BEGIN
  v_batch_id := public.import_manifest_transactional(
    p_filename,
    p_voyage_id,
    p_uploaded_by,
    'carga_solta',
    NULL,
    p_total_bls,
    0,
    COALESCE(p_bls, '[]'::jsonb),
    '[]'::jsonb,
    COALESCE(p_errors, '[]'::jsonb)
  );

  UPDATE public.bls AS target
  SET
    ce_mercante = CASE
      WHEN source.row ? 'ce_mercante' THEN NULLIF(source.row->>'ce_mercante', '')
      ELSE target.ce_mercante
    END,
    notify_party = NULLIF(source.row->>'notify_party', ''),
    bb_machine_qty = NULLIF(source.row->>'bb_machine_qty', '')::NUMERIC,
    bb_packages_qty = NULLIF(source.row->>'bb_packages_qty', '')::NUMERIC,
    bb_packages_total = NULLIF(source.row->>'bb_packages_total', '')::NUMERIC,
    bb_weight_ton = NULLIF(source.row->>'bb_weight_ton', '')::NUMERIC,
    -- NCM lido dos itens do manifesto (migration 358). A descrição de carga
    -- solta descarta as linhas "NCM NUMBER" e guarda só os 3 primeiros itens,
    -- então o código precisa vir do texto completo dos itens, não dela.
    -- Vazio preserva o cadastro manual.
    ncm_codes = CASE
      WHEN cardinality(public.normalize_ncm_codes(source.row->'ncm_codes')) > 0
        THEN public.normalize_ncm_codes(source.row->'ncm_codes')
      ELSE target.ncm_codes
    END
  FROM jsonb_array_elements(COALESCE(p_bls, '[]'::jsonb)) AS source(row)
  WHERE target.id = source.row->>'id';

  SELECT COALESCE(array_agg(source.row->>'id'), ARRAY[]::TEXT[])
  INTO v_bl_ids
  FROM jsonb_array_elements(COALESCE(p_bls, '[]'::jsonb)) AS source(row);

  IF cardinality(v_bl_ids) > 0 THEN
    DELETE FROM public.bl_breakbulk_items
    WHERE bl_id = ANY(v_bl_ids);
  END IF;

  INSERT INTO public.bl_breakbulk_items (
    bl_id,
    item_description,
    package_qty,
    package_unit,
    gross_weight_kg,
    cbm,
    marks
  )
  SELECT
    source.row->>'bl_id',
    source.row->>'item_description',
    COALESCE(NULLIF(source.row->>'package_qty', '')::NUMERIC, 0),
    NULLIF(source.row->>'package_unit', ''),
    COALESCE(NULLIF(source.row->>'gross_weight_kg', '')::NUMERIC, 0),
    COALESCE(NULLIF(source.row->>'cbm', '')::NUMERIC, 0),
    NULLIF(source.row->>'marks', '')
  FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb)) AS source(row);

  IF cardinality(v_bl_ids) > 0 THEN
    PERFORM public.apply_bl_review_gate_after_import(v_bl_ids, p_uploaded_by);
  END IF;

  RETURN jsonb_build_object('batch_id', v_batch_id);
END;
$$;



--
-- Name: import_granite_manifest_transactional(bigint, text, text, text, integer, numeric, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_granite_manifest_transactional(p_voyage_id bigint, p_vessel_voyage text, p_loading_port text, p_discharge_port text, p_total_bls integer, p_total_weight_kg numeric, p_uploaded_by uuid, p_bls jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_result JSONB;
  v_manifest_id UUID;
BEGIN
  v_result := public.import_granite_manifest_transactional_legacy_136(
    p_voyage_id, p_vessel_voyage, p_loading_port, p_discharge_port,
    p_total_bls, p_total_weight_kg, p_uploaded_by, p_bls
  );
  v_manifest_id := (v_result->>'manifest_id')::UUID;

  UPDATE public.granite_bls AS g
  SET suggested_client_id = NULLIF(item->>'suggested_client_id', '')::BIGINT
  FROM jsonb_array_elements(COALESCE(p_bls, '[]'::jsonb)) AS item
  WHERE g.manifest_id = v_manifest_id
    AND g.bl_number = item->>'bl_number';

  RETURN v_result;
END;
$$;



--
-- Name: import_granite_manifest_transactional_legacy_136(bigint, text, text, text, integer, numeric, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_granite_manifest_transactional_legacy_136(p_voyage_id bigint, p_vessel_voyage text, p_loading_port text, p_discharge_port text, p_total_bls integer, p_total_weight_kg numeric, p_uploaded_by uuid, p_bls jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_manifest_id UUID;
  v_inserted_bls INTEGER;
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.is_active_user()
     OR p_uploaded_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Credenciais invalidas para importar manifesto Granito.'
      USING ERRCODE = '42501';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.voyages WHERE id = p_voyage_id
  ) THEN
    RAISE EXCEPTION 'Viagem nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF NULLIF(BTRIM(COALESCE(p_vessel_voyage, '')), '') IS NULL
     OR jsonb_typeof(p_bls) <> 'array'
     OR jsonb_array_length(p_bls) = 0
     OR p_total_bls IS DISTINCT FROM jsonb_array_length(p_bls) THEN
    RAISE EXCEPTION 'Manifesto Granito invalido.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.granite_manifests (
    voyage_id,
    vessel_voyage,
    loading_port,
    discharge_port,
    total_bls,
    total_weight_kg,
    imported_by
  )
  VALUES (
    p_voyage_id,
    BTRIM(p_vessel_voyage),
    p_loading_port,
    p_discharge_port,
    p_total_bls,
    p_total_weight_kg,
    p_uploaded_by
  )
  RETURNING id INTO v_manifest_id;

  INSERT INTO public.granite_bls (
    manifest_id,
    client_id,
    sequence,
    booking_number,
    bl_number,
    shipper_ref,
    vessel_voyage,
    loading_port,
    discharge_port,
    shipper_name,
    shipper_cnpj,
    consignee_name,
    charter,
    shipper_m3,
    shipper_weight_kg,
    blocks_qty,
    received_blocks_qty,
    final_m3,
    real_weight_kg,
    stockyard,
    remarks,
    partial_restriction,
    cosco_transport,
    fragile_blocks,
    cssc_selection,
    cargo_readiness_date,
    phase,
    charge_status
  )
  SELECT
    v_manifest_id,
    item.client_id,
    item.sequence,
    item.booking_number,
    item.bl_number,
    item.shipper_ref,
    item.vessel_voyage,
    item.loading_port,
    item.discharge_port,
    item.shipper_name,
    item.shipper_cnpj,
    item.consignee_name,
    item.charter,
    item.shipper_m3,
    item.shipper_weight_kg,
    item.blocks_qty,
    item.received_blocks_qty,
    item.final_m3,
    item.real_weight_kg,
    item.stockyard,
    item.remarks,
    COALESCE(item.partial_restriction, FALSE),
    item.cosco_transport,
    item.fragile_blocks,
    item.cssc_selection,
    item.cargo_readiness_date,
    item.phase,
    'not_calculated'
  FROM jsonb_to_recordset(p_bls) AS item(
    client_id BIGINT,
    sequence INTEGER,
    booking_number TEXT,
    bl_number TEXT,
    shipper_ref TEXT,
    vessel_voyage TEXT,
    loading_port TEXT,
    discharge_port TEXT,
    shipper_name TEXT,
    shipper_cnpj TEXT,
    consignee_name TEXT,
    charter TEXT,
    shipper_m3 NUMERIC,
    shipper_weight_kg NUMERIC,
    blocks_qty INTEGER,
    received_blocks_qty INTEGER,
    final_m3 NUMERIC,
    real_weight_kg NUMERIC,
    stockyard TEXT,
    remarks TEXT,
    partial_restriction BOOLEAN,
    cosco_transport TEXT,
    fragile_blocks INTEGER,
    cssc_selection TEXT,
    cargo_readiness_date DATE,
    phase TEXT,
    charge_status TEXT
  );

  GET DIAGNOSTICS v_inserted_bls = ROW_COUNT;
  IF v_inserted_bls <> p_total_bls THEN
    RAISE EXCEPTION 'Quantidade de B/Ls Granito inserida diverge do manifesto.'
      USING ERRCODE = '40001';
  END IF;

  RETURN jsonb_build_object(
    'manifest_id', v_manifest_id,
    'inserted_bls', v_inserted_bls
  );
END;
$$;



--
-- Name: import_manifest_transactional(text, bigint, uuid, text, text, integer, integer, jsonb, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_manifest_transactional(p_filename text, p_voyage_id bigint, p_uploaded_by uuid, p_cargo_mode text, p_file_hash text, p_total_bls integer, p_total_containers integer, p_bls jsonb, p_containers jsonb, p_errors jsonb, p_apply_overwrites boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result BIGINT;
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.is_active_user()
     OR p_uploaded_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para importar manifesto.'
      USING ERRCODE = '42501';
  END IF;

  v_result := public.import_manifest_transactional_legacy_165(
    p_filename,
    p_voyage_id,
    p_uploaded_by,
    p_cargo_mode,
    p_file_hash,
    p_total_bls,
    p_total_containers,
    p_bls,
    p_containers,
    p_errors,
    p_apply_overwrites
  );

  UPDATE public.bls AS b
  SET
    suggested_customer_id = CASE
      WHEN item ? 'suggested_customer_id' THEN NULLIF(item->>'suggested_customer_id', '')::BIGINT
      ELSE b.suggested_customer_id
    END,
    customer_reconciliation_status = COALESCE(
      NULLIF(item->>'customer_reconciliation_status', ''),
      CASE
        WHEN NULLIF(item->>'customer_id', '') IS NOT NULL THEN 'reconciled'
        ELSE 'missing_customer'
      END
    )
  FROM jsonb_array_elements(COALESCE(p_bls, '[]'::jsonb)) AS item
  WHERE b.id = item->>'id';

  RETURN v_result;
END;
$$;



--
-- Name: import_manifest_transactional_legacy_165(text, bigint, uuid, text, text, integer, integer, jsonb, jsonb, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_manifest_transactional_legacy_165(p_filename text, p_voyage_id bigint, p_uploaded_by uuid, p_cargo_mode text, p_file_hash text, p_total_bls integer, p_total_containers integer, p_bls jsonb, p_containers jsonb, p_errors jsonb, p_apply_overwrites boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch_id BIGINT;
  v_bl_ids TEXT[];
  v_error_count INT;
  v_missing_container_refs INT;
  v_ambiguous_container_refs INT;
  v_recent_imports INT;
  v_existing_bl_ids TEXT[];
BEGIN
  SELECT COUNT(*) INTO v_recent_imports
  FROM public.import_batches
  WHERE uploaded_by = p_uploaded_by
    AND created_at > NOW() - INTERVAL '60 seconds';

  IF COALESCE(v_recent_imports, 0) >= 5 THEN
    RAISE EXCEPTION 'Limite de importacoes atingido. Aguarde 60 segundos antes de importar novamente.'
      USING ERRCODE = 'P0429';
  END IF;

  IF p_voyage_id IS NULL THEN
    RAISE EXCEPTION 'voyage_id obrigatorio' USING ERRCODE = '22004';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.voyages WHERE id = p_voyage_id) THEN
    RAISE EXCEPTION 'Viagem % nao encontrada', p_voyage_id USING ERRCODE = 'P0002';
  END IF;

  v_error_count := COALESCE(jsonb_array_length(p_errors), 0);

  INSERT INTO public.import_batches(
    filename, voyage_id, cargo_mode, uploaded_by, status,
    total_bls, total_containers, error_count, file_hash
  )
  VALUES (
    p_filename,
    p_voyage_id,
    COALESCE(p_cargo_mode, 'container'),
    p_uploaded_by,
    'processing',
    p_total_bls,
    p_total_containers,
    v_error_count,
    p_file_hash
  )
  RETURNING id INTO v_batch_id;

  CREATE TEMP TABLE pg_temp.tmp_old_containers (
    old_container_id BIGINT PRIMARY KEY,
    bl_id TEXT NOT NULL,
    container_number TEXT NOT NULL
  ) ON COMMIT DROP;

  CREATE TEMP TABLE pg_temp.tmp_new_containers (
    new_container_id BIGINT PRIMARY KEY,
    bl_id TEXT NOT NULL,
    container_number TEXT NOT NULL
  ) ON COMMIT DROP;

  CREATE TEMP TABLE pg_temp.tmp_container_rebind (
    old_container_id BIGINT PRIMARY KEY,
    new_container_id BIGINT NOT NULL
  ) ON COMMIT DROP;

  IF p_bls IS NOT NULL AND jsonb_array_length(p_bls) > 0 THEN
    SELECT array_agg(b.id) INTO v_existing_bl_ids FROM public.bls b
      WHERE b.id IN (SELECT x->>'id' FROM jsonb_array_elements(p_bls) x);

    INSERT INTO public.bls (
      id,
      voyage_id,
      batch_id,
      cargo_mode,
      shipper,
      consignee,
      cargo_description,
      customer_id,
      pol,
      pod,
      total_weight_kg,
      total_cbm,
      review_status,
      financial_status,
      notes,
      manifest_customer_cnpj_cpf,
      manifest_customer_name,
      manifest_customer_email,
      customer_reconciliation_status,
      customer_reconciliation_notes,
      billing_hold_reason
    )
    SELECT
      bl->>'id',
      p_voyage_id,
      v_batch_id,
      COALESCE(p_cargo_mode, 'container'),
      bl->>'shipper',
      bl->>'consignee',
      bl->>'cargo_description',
      NULLIF(bl->>'customer_id', '')::BIGINT,
      bl->>'pol',
      bl->>'pod',
      NULLIF(bl->>'total_weight_kg', '')::NUMERIC,
      NULLIF(bl->>'total_cbm', '')::NUMERIC,
      COALESCE(bl->>'review_status', 'ok'),
      COALESCE(bl->>'financial_status', 'pending'),
      bl->>'notes',
      public.normalize_document_text(bl->>'manifest_customer_cnpj_cpf'),
      COALESCE(NULLIF(bl->>'manifest_customer_name', ''), bl->>'consignee'),
      NULLIF(bl->>'manifest_customer_email', ''),
      COALESCE(
        NULLIF(bl->>'customer_reconciliation_status', ''),
        CASE
          WHEN NULLIF(bl->>'customer_id', '') IS NOT NULL THEN 'reconciled'
          ELSE 'missing_customer'
        END
      ),
      NULLIF(bl->>'customer_reconciliation_notes', ''),
      NULLIF(bl->>'billing_hold_reason', '')
    FROM jsonb_array_elements(p_bls) AS bl
    ON CONFLICT (id) DO UPDATE SET
      voyage_id = EXCLUDED.voyage_id,
      batch_id = EXCLUDED.batch_id,
      cargo_mode = EXCLUDED.cargo_mode,
      shipper = CASE WHEN p_apply_overwrites THEN EXCLUDED.shipper ELSE public.bls.shipper END,
      consignee = CASE WHEN p_apply_overwrites THEN EXCLUDED.consignee ELSE public.bls.consignee END,
      cargo_description = CASE WHEN p_apply_overwrites THEN EXCLUDED.cargo_description ELSE public.bls.cargo_description END,
      customer_id = EXCLUDED.customer_id,
      pol = CASE WHEN p_apply_overwrites THEN EXCLUDED.pol ELSE public.bls.pol END,
      pod = CASE WHEN p_apply_overwrites THEN EXCLUDED.pod ELSE public.bls.pod END,
      total_weight_kg = CASE WHEN p_apply_overwrites THEN EXCLUDED.total_weight_kg ELSE public.bls.total_weight_kg END,
      total_cbm = CASE WHEN p_apply_overwrites THEN EXCLUDED.total_cbm ELSE public.bls.total_cbm END,
      review_status = EXCLUDED.review_status,
      financial_status = EXCLUDED.financial_status,
      notes = EXCLUDED.notes,
      manifest_customer_cnpj_cpf = EXCLUDED.manifest_customer_cnpj_cpf,
      manifest_customer_name = EXCLUDED.manifest_customer_name,
      manifest_customer_email = EXCLUDED.manifest_customer_email,
      customer_reconciliation_status = EXCLUDED.customer_reconciliation_status,
      customer_reconciliation_notes = EXCLUDED.customer_reconciliation_notes,
      billing_hold_reason = EXCLUDED.billing_hold_reason;

    IF p_apply_overwrites AND v_existing_bl_ids IS NOT NULL AND array_length(v_existing_bl_ids, 1) > 0 THEN
      INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification)
      SELECT 'bl', bid, 'FONTE_SOBRESCRITO', NULL, NULL, p_uploaded_by, now(),
             'Manifesto sobrescreveu dados comerciais do B/L com aprovacao do operador'
      FROM unnest(v_existing_bl_ids) AS bid;
    END IF;

    SELECT array_agg(DISTINCT bl->>'id')
    INTO v_bl_ids
    FROM jsonb_array_elements(p_bls) AS bl;

    IF v_bl_ids IS NOT NULL AND array_length(v_bl_ids, 1) > 0 THEN
      INSERT INTO pg_temp.tmp_old_containers (old_container_id, bl_id, container_number)
      SELECT id, bl_id, container_number
      FROM public.bl_containers
      WHERE bl_id = ANY(v_bl_ids);

      PERFORM 1
      FROM public.vehicles
      WHERE container_id IN (SELECT old_container_id FROM pg_temp.tmp_old_containers)
      FOR UPDATE;

      PERFORM 1
      FROM public.charge_calculations
      WHERE container_id IN (SELECT old_container_id FROM pg_temp.tmp_old_containers)
      FOR UPDATE;
    END IF;
  END IF;

  IF p_containers IS NOT NULL AND jsonb_array_length(p_containers) > 0 THEN
    WITH inserted AS (
      INSERT INTO public.bl_containers (
        bl_id, container_number, seal_number, type, tare_weight_kg,
        gross_weight_kg, cbm, is_oog, is_imo, imo_class, un_number
      )
      SELECT
        c->>'bl_id',
        c->>'container_number',
        c->>'seal_number',
        c->>'type',
        NULLIF(c->>'tare_weight_kg', '')::NUMERIC,
        NULLIF(c->>'gross_weight_kg', '')::NUMERIC,
        NULLIF(c->>'cbm', '')::NUMERIC,
        COALESCE((c->>'is_oog')::BOOLEAN, false),
        COALESCE((c->>'is_imo')::BOOLEAN, false),
        c->>'imo_class',
        c->>'un_number'
      FROM jsonb_array_elements(p_containers) AS c
      RETURNING id, bl_id, container_number
    )
    INSERT INTO pg_temp.tmp_new_containers (new_container_id, bl_id, container_number)
    SELECT id, bl_id, container_number
    FROM inserted;
  END IF;

  IF EXISTS (SELECT 1 FROM pg_temp.tmp_old_containers) THEN
    INSERT INTO pg_temp.tmp_container_rebind (old_container_id, new_container_id)
    SELECT old_ref.old_container_id, MIN(matched.new_container_id) AS new_container_id
    FROM pg_temp.tmp_old_containers AS old_ref
    JOIN LATERAL (
      SELECT new_ref.new_container_id
      FROM pg_temp.tmp_new_containers AS new_ref
      WHERE new_ref.bl_id = old_ref.bl_id
        AND new_ref.container_number = old_ref.container_number
    ) AS matched ON TRUE
    GROUP BY old_ref.old_container_id
    HAVING COUNT(*) = 1;

    SELECT COUNT(*)
    INTO v_missing_container_refs
    FROM (
      SELECT old_ref.old_container_id
      FROM pg_temp.tmp_old_containers AS old_ref
      WHERE EXISTS (
        SELECT 1
        FROM public.vehicles AS v
        WHERE v.container_id = old_ref.old_container_id
      )
         OR EXISTS (
        SELECT 1
        FROM public.charge_calculations AS cc
        WHERE cc.container_id = old_ref.old_container_id
      )
      EXCEPT
      SELECT old_container_id
      FROM pg_temp.tmp_container_rebind
    ) AS missing_refs;

    IF COALESCE(v_missing_container_refs, 0) > 0 THEN
      RAISE EXCEPTION
        'Reimport abortado: % vinculo(s) de container referenciados por veiculos/calculos nao puderam ser remapeados.',
        v_missing_container_refs
        USING ERRCODE = '23503';
    END IF;

    SELECT COUNT(*)
    INTO v_ambiguous_container_refs
    FROM (
      SELECT old_ref.old_container_id
      FROM pg_temp.tmp_old_containers AS old_ref
      JOIN pg_temp.tmp_new_containers AS new_ref
        ON new_ref.bl_id = old_ref.bl_id
       AND new_ref.container_number = old_ref.container_number
      WHERE EXISTS (
        SELECT 1
        FROM public.vehicles AS v
        WHERE v.container_id = old_ref.old_container_id
      )
         OR EXISTS (
        SELECT 1
        FROM public.charge_calculations AS cc
        WHERE cc.container_id = old_ref.old_container_id
      )
      GROUP BY old_ref.old_container_id
      HAVING COUNT(*) > 1
    ) AS ambiguous_refs;

    IF COALESCE(v_ambiguous_container_refs, 0) > 0 THEN
      RAISE EXCEPTION
        'Reimport abortado: % container(s) remapeados de forma ambigua por numero dentro do mesmo B/L.',
        v_ambiguous_container_refs
        USING ERRCODE = '23505';
    END IF;

    UPDATE public.vehicles AS v
    SET container_id = rebind.new_container_id
    FROM pg_temp.tmp_container_rebind AS rebind
    WHERE v.container_id = rebind.old_container_id;

    UPDATE public.charge_calculations AS cc
    SET container_id = rebind.new_container_id
    FROM pg_temp.tmp_container_rebind AS rebind
    WHERE cc.container_id = rebind.old_container_id;

    DELETE FROM public.bl_containers
    WHERE id IN (SELECT old_container_id FROM pg_temp.tmp_old_containers);
  END IF;

  IF v_error_count > 0 THEN
    INSERT INTO public.import_errors(batch_id, row_number, error_type, error_message, raw_data)
    SELECT
      v_batch_id,
      NULLIF(e->>'row_number', '')::INT,
      COALESCE(e->>'error_type', 'parser'),
      e->>'error_message',
      CASE WHEN e ? 'raw_data' THEN e->'raw_data' ELSE NULL END
    FROM jsonb_array_elements(p_errors) AS e;
  END IF;

  UPDATE public.import_batches
  SET status = CASE WHEN v_error_count > 0 THEN 'partial' ELSE 'completed' END
  WHERE id = v_batch_id;

  IF v_bl_ids IS NOT NULL THEN
    UPDATE public.charge_calculations AS cc
    SET manifest_id = v_batch_id
    WHERE cc.bl_id = ANY(v_bl_ids);
  END IF;

  RETURN v_batch_id;
END;
$$;



--
-- Name: import_vazios_bookings_transactional(bigint, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_vazios_bookings_transactional(p_voyage_id bigint, p_port text, p_uploaded_by uuid, p_bookings jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_manifest_id UUID;
  v_operation_id UUID;
  v_total INTEGER := jsonb_array_length(COALESCE(p_bookings, '[]'::JSONB));
BEGIN
  IF auth.uid() IS NULL OR NOT (public.is_active_user() OR public.is_active_user())
     OR p_uploaded_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para importar unidades.' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(btrim(p_port), '') IS NULL THEN
    RAISE EXCEPTION 'Porto de embarque obrigatorio.' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.voyages WHERE id = p_voyage_id) THEN
    RAISE EXCEPTION 'Viagem nao encontrada.' USING ERRCODE = 'P0002';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(COALESCE(p_bookings, '[]'::JSONB)) AS item(container_number TEXT)
    GROUP BY upper(btrim(container_number))
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Planilha invalida: Container duplicado na planilha.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.vazios_export_operations (voyage_id, embark_port, updated_at)
  VALUES (p_voyage_id, upper(btrim(p_port)), now())
  ON CONFLICT (voyage_id, embark_port) DO UPDATE SET updated_at = EXCLUDED.updated_at
  RETURNING id INTO v_operation_id;

  -- ponytail: validacao no RPC e tudo-ou-nada para nao subestimar pagamento por erro de uma linha.
  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(COALESCE(p_bookings, '[]'::JSONB)) AS r(
      container_number TEXT, container_type TEXT, local_code TEXT, condition TEXT,
      hand_in_date DATE, hand_out_date DATE, movement_date DATE
    )
    LEFT JOIN public.depots d ON lower(d.code) = lower(btrim(r.local_code))
    WHERE NULLIF(btrim(r.container_number), '') IS NULL
       OR r.container_number !~ '^[A-Za-z]{4}[0-9]{7}$'
       OR NULLIF(btrim(r.local_code), '') IS NULL
       OR d.id IS NULL
       OR (d.id IS NOT NULL AND NOT d.active)
       OR (COALESCE(d.tipo, 'depot') = 'depot' AND (r.hand_in_date IS NULL OR r.hand_out_date IS NULL))
       OR (COALESCE(d.tipo, 'depot') = 'depot' AND r.hand_out_date < r.hand_in_date)
       OR (d.id IS NOT NULL AND d.tipo = 'terminal_portuario' AND (r.hand_in_date IS NOT NULL OR r.hand_out_date IS NOT NULL))
       OR r.condition IS NULL OR r.condition NOT IN ('vazio', 'material')
  ) THEN
    RAISE EXCEPTION 'Planilha invalida: corrija todas as linhas e importe novamente.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.vazios_manifests (voyage_id, description, total_bookings, imported_by)
  VALUES (p_voyage_id, p_port, v_total, p_uploaded_by) RETURNING id INTO v_manifest_id;

  DELETE FROM public.vazios_bookings WHERE operation_id = v_operation_id;
  INSERT INTO public.vazios_bookings (
    voyage_id, operation_id, manifest_id, container_number, container_type,
    local_id, condition, hand_in_date, hand_out_date, movement_date
  )
  SELECT
    p_voyage_id, v_operation_id, v_manifest_id, upper(btrim(r.container_number)), r.container_type, d.id,
    r.condition, r.hand_in_date, r.hand_out_date, r.movement_date
  FROM jsonb_to_recordset(COALESCE(p_bookings, '[]'::JSONB)) AS r(
    container_number TEXT, container_type TEXT, local_code TEXT, condition TEXT,
    hand_in_date DATE, hand_out_date DATE, movement_date DATE
  )
  JOIN public.depots d ON lower(d.code) = lower(btrim(r.local_code)) AND d.active;

  RETURN jsonb_build_object(
    'manifest_id', v_manifest_id,
    'operation_id', v_operation_id,
    'total', v_total,
    'replaced', TRUE
  );
END;
$_$;



--
-- Name: import_vazios_importacao_transactional(bigint, text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_vazios_importacao_transactional(p_voyage_id bigint, p_description text, p_uploaded_by uuid, p_containers jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_manifest_id UUID;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR p_uploaded_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para importar vazios.' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.voyages WHERE id = p_voyage_id) THEN
    RAISE EXCEPTION 'Viagem nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  INSERT INTO public.vazios_importacao_manifests (
    voyage_id, description, total_containers, imported_by, source
  )
  VALUES (
    p_voyage_id, p_description,
    jsonb_array_length(COALESCE(p_containers, '[]'::JSONB)),
    p_uploaded_by, 'manual'
  )
  RETURNING id INTO v_manifest_id;

  INSERT INTO public.vazios_importacao_containers (
    manifest_id, container_number, container_type, tare_kg, pol, pod
  )
  SELECT v_manifest_id, item.container_number, item.container_type, item.tare_kg, item.pol, item.pod
  FROM jsonb_to_recordset(COALESCE(p_containers, '[]'::JSONB)) AS item(
    container_number TEXT,
    container_type TEXT,
    tare_kg NUMERIC,
    pol TEXT,
    pod TEXT
  );

  RETURN jsonb_build_object('manifest_id', v_manifest_id);
END;
$$;



--
-- Name: import_vehicle_rows_transactional(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.import_vehicle_rows_transactional(p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_count INTEGER := COALESCE(jsonb_array_length(p_rows), 0);
BEGIN
  IF auth.uid() IS NULL OR NOT (public.is_active_user() OR public.is_active_user()) THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao para importar veiculos.' USING ERRCODE = '42501';
  END IF;
  IF v_count = 0 THEN RETURN 0; END IF;
  INSERT INTO public.vehicles (voyage_id, container_id, bl_id, chassis, brand, model, weight_kg, cbm)
  SELECT row.voyage_id, row.container_id, row.bl_id, row.chassis, row.brand, row.model, row.weight_kg, row.cbm
  FROM jsonb_to_recordset(p_rows) AS row(voyage_id BIGINT, container_id BIGINT, bl_id TEXT, chassis TEXT, brand TEXT, model TEXT, weight_kg NUMERIC, cbm NUMERIC);
  UPDATE public.bl_containers AS c
  SET unpacking_location = NULLIF(trim(row.unpacking_location), '')
  FROM jsonb_to_recordset(p_rows) AS row(container_id BIGINT, unpacking_location TEXT)
  WHERE c.id = row.container_id AND row.unpacking_location IS NOT NULL;
  RETURN v_count;
END;
$$;



--
-- Name: insert_billing_run_log(bigint, bigint, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.insert_billing_run_log(p_billing_run_id bigint, p_manifest_id bigint, p_bl_id text, p_level text, p_code text, p_message text, p_details jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  INSERT INTO public.billing_run_logs (
    billing_run_id,
    manifest_id,
    bl_id,
    level,
    code,
    message,
    details
  )
  VALUES (
    p_billing_run_id,
    p_manifest_id,
    p_bl_id,
    COALESCE(p_level, 'info'),
    p_code,
    p_message,
    COALESCE(p_details, '{}'::JSONB)
  );
$$;



--
-- Name: is_active_read_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_active_read_user() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.user_profiles
    WHERE id = auth.uid() AND active = true
  );
$$;



