--
-- Name: is_valid_cnpj(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_valid_cnpj(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_cnpj TEXT := public.normalize_cnpj(p_value);
  v_sum INTEGER;
  v_remainder INTEGER;
  v_digit INTEGER;
  v_weights INTEGER[];
  v_index INTEGER;
BEGIN
  IF v_cnpj !~ '^[0-9A-Z]{14}$' OR right(v_cnpj, 2) !~ '^[0-9]{2}$' THEN
    RETURN FALSE;
  END IF;

  v_weights := ARRAY[5,4,3,2,9,8,7,6,5,4,3,2];
  v_sum := 0;
  FOR v_index IN 1..12 LOOP
    v_sum := v_sum + (ascii(substr(v_cnpj, v_index, 1)) - 48) * v_weights[v_index];
  END LOOP;
  v_remainder := v_sum % 11;
  v_digit := 11 - v_remainder;
  IF v_digit >= 10 THEN v_digit := 0; END IF;
  IF v_digit <> substr(v_cnpj, 13, 1)::INTEGER THEN RETURN FALSE; END IF;

  v_weights := ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2];
  v_sum := 0;
  FOR v_index IN 1..13 LOOP
    v_sum := v_sum + (ascii(substr(v_cnpj, v_index, 1)) - 48) * v_weights[v_index];
  END LOOP;
  v_remainder := v_sum % 11;
  v_digit := 11 - v_remainder;
  IF v_digit >= 10 THEN v_digit := 0; END IF;
  RETURN v_digit = substr(v_cnpj, 14, 1)::INTEGER;
END;
$_$;



--
-- Name: keep_single_pix_txid_settlement_row(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.keep_single_pix_txid_settlement_row() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.source = 'pix_extract'
     AND NULLIF(TRIM(COALESCE(NEW.pix_txid, '')), '') IS NOT NULL
     AND EXISTS (
       SELECT 1
       FROM public.ledger_settlements
       WHERE invoice_id = NEW.invoice_id
         AND source = 'pix_extract'
         AND pix_txid IS NOT NULL
     ) THEN
    NEW.pix_txid := NULL;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: link_invoice_to_ledger(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_invoice_to_ledger(p_invoice_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT;
  v_bl_count INTEGER;
BEGIN
  SELECT customer_id INTO v_customer_id FROM public.invoices WHERE id = p_invoice_id;
  IF v_customer_id IS NULL THEN
    RETURN;
  END IF;

  SELECT COUNT(*) INTO v_bl_count FROM public.invoice_bls WHERE invoice_id = p_invoice_id;
  IF v_bl_count = 0 THEN
    RETURN;
  END IF;

  INSERT INTO public.bl_receivables (
    bl_id, customer_id, source, original_amount_brl, settled_amount_brl, balance_brl, status,
    voyage_id, cargo_mode, pol, pod, updated_at
  )
  SELECT
    b.id, v_customer_id, 'local_charges',
    COALESCE(ib.subtotal_brl, 0), 0, COALESCE(ib.subtotal_brl, 0),
    CASE WHEN COALESCE(ib.subtotal_brl, 0) <= 0 THEN 'void' ELSE 'open' END,
    b.voyage_id, b.cargo_mode, b.pol, b.pod, now()
  FROM public.invoice_bls ib
  JOIN public.bls b ON b.id = ib.bl_id
  WHERE ib.invoice_id = p_invoice_id
  ON CONFLICT (source, bl_id) DO UPDATE SET
    customer_id = EXCLUDED.customer_id,
    original_amount_brl = EXCLUDED.original_amount_brl,
    balance_brl = GREATEST(EXCLUDED.original_amount_brl - bl_receivables.settled_amount_brl, 0),
    status = CASE
      WHEN EXCLUDED.original_amount_brl <= 0 THEN 'void'
      WHEN bl_receivables.settled_amount_brl >= EXCLUDED.original_amount_brl THEN 'settled'
      WHEN bl_receivables.settled_amount_brl > 0 THEN 'partially_settled'
      ELSE 'open'
    END,
    voyage_id = EXCLUDED.voyage_id, cargo_mode = EXCLUDED.cargo_mode,
    pol = EXCLUDED.pol, pod = EXCLUDED.pod, updated_at = now();

  INSERT INTO public.invoice_receivable_links (invoice_id, receivable_id, bl_id, subtotal_brl, status, bl_snapshot)
  SELECT
    p_invoice_id, br.id, ib.bl_id, COALESCE(ib.subtotal_brl, 0), 'active',
    jsonb_build_object('bl_id', b.id, 'voyage_id', b.voyage_id, 'cargo_mode', b.cargo_mode, 'pol', b.pol, 'pod', b.pod)
  FROM public.invoice_bls ib
  JOIN public.bls b ON b.id = ib.bl_id
  JOIN public.bl_receivables br ON br.source = 'local_charges' AND br.bl_id = ib.bl_id
  WHERE ib.invoice_id = p_invoice_id
  ON CONFLICT (invoice_id, receivable_id) DO NOTHING;

  UPDATE public.invoices
  SET invoice_type = CASE WHEN v_bl_count > 1 THEN 'consolidated' ELSE 'individual' END
  WHERE id = p_invoice_id AND invoice_type = 'individual';
END;
$$;



--
-- Name: link_pix_reconciliation_candidate(bigint, text, bigint, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_pix_reconciliation_candidate(p_exception_id bigint, p_resolution_source text, p_invoice_id bigint DEFAULT NULL::bigint, p_demurrage_invoice_id bigint DEFAULT NULL::bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_exception public.pix_reconciliation_exceptions%ROWTYPE;
  v_candidate RECORD;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao para reconciliacao PIX.' USING ERRCODE = '42501';
  END IF;
  IF p_resolution_source NOT IN ('local', 'demurrage') THEN
    RAISE EXCEPTION 'Origem de resolucao PIX invalida.' USING ERRCODE = '22023';
  END IF;
  IF (p_resolution_source = 'local' AND (p_invoice_id IS NULL OR p_demurrage_invoice_id IS NOT NULL))
     OR (p_resolution_source = 'demurrage' AND (p_demurrage_invoice_id IS NULL OR p_invoice_id IS NOT NULL)) THEN
    RAISE EXCEPTION 'Vinculo PIX exige exatamente uma candidata da origem escolhida.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_exception
  FROM public.pix_reconciliation_exceptions
  WHERE id = p_exception_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Excecao PIX % nao encontrada.', p_exception_id USING ERRCODE = 'P0002';
  END IF;
  IF v_exception.status = 'resolved' THEN
    RETURN jsonb_build_object('id', v_exception.id, 'status', 'resolved');
  END IF;
  IF v_exception.normalized_txid = '' THEN
    RAISE EXCEPTION 'Linha sem TXID nao possui candidata segura para vinculo manual.' USING ERRCODE = 'P0001';
  END IF;

  IF p_resolution_source = 'local' THEN
    SELECT i.id, COALESCE(i.invoice_number, i.id::TEXT) AS doc_number,
           COALESCE(i.balance_brl, i.total_brl, 0) AS amount_brl
    INTO v_candidate
    FROM public.invoices i
    WHERE i.id = p_invoice_id
      AND i.invoice_type IN ('individual', 'consolidated')
      AND COALESCE(i.status, 'issued') IN ('issued', 'partially_paid', 'overdue')
      AND public.normalize_pix_txid(i.pix_txid) = v_exception.normalized_txid;
  ELSE
    SELECT d.id, d.doc_number, COALESCE(d.current_total_brl, 0) AS amount_brl
    INTO v_candidate
    FROM public.demurrage_invoices d
    WHERE d.id = p_demurrage_invoice_id
      AND COALESCE(d.status, 'issued') IN ('issued', 'paid')
      AND public.normalize_pix_txid(d.pix_txid) = v_exception.normalized_txid;
  END IF;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Candidata nao corresponde exatamente ao TXID persistido.' USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.pix_reconciliation_exceptions
  SET metadata = metadata || jsonb_build_object(
        'manual_candidate', jsonb_build_object(
          'source', p_resolution_source,
          'invoice_id', CASE WHEN p_resolution_source = 'local' THEN p_invoice_id ELSE NULL END,
          'demurrage_invoice_id', CASE WHEN p_resolution_source = 'demurrage' THEN p_demurrage_invoice_id ELSE NULL END,
          'doc_number', v_candidate.doc_number,
          'linked_at', now()
        )
      ),
      updated_at = now()
  WHERE id = v_exception.id;

  RETURN jsonb_build_object('id', v_exception.id, 'status', 'active', 'candidate', v_candidate.doc_number);
END;
$$;



--
-- Name: list_alert_queue(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_alert_queue(p_filter text DEFAULT 'active'::text, p_entity_type text DEFAULT NULL::text, p_department text DEFAULT NULL::text) RETURNS SETOF jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT public.list_alert_queue_page(p_filter, p_entity_type, 0, 200, p_department);
$$;



--
-- Name: list_alert_queue_page(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_alert_queue_page(p_filter text DEFAULT 'active'::text, p_entity_type text DEFAULT NULL::text, p_offset integer DEFAULT 0, p_limit integer DEFAULT 100, p_department text DEFAULT NULL::text) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;
  IF p_filter NOT IN ('active', 'dismissed', 'all') THEN
    RAISE EXCEPTION 'Filtro inválido.' USING ERRCODE = '22023';
  END IF;
  IF p_offset < 0 OR p_limit < 1 OR p_limit > 100 THEN
    RAISE EXCEPTION 'Paginação inválida.' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  WITH queue_rows AS (
    SELECT jsonb_build_object(
      'id', a.id,
      'item_id', i.id,
      'status', a.status,
      'item_status', i.status,
      'type', i.item_type,
      'severity', i.severity,
      'department', i.department,
      'message', i.message,
      'entity_type', a.entity_type,
      'entity_id', a.entity_id,
      'destination', i.destination,
      'created_at', a.created_at,
      'updated_at', i.updated_at,
      'dismissed_until', d.review_at,
      'dismissal_reason', d.reason,
      'dismissed_by', d.dismissed_by,
      'dismissed_by_name', up.full_name,
      'dismissed_at', d.dismissed_at,
      'metadata', i.metadata
    ) AS payload,
    COALESCE(d.review_at > now(), false) AS is_dismissed,
    (i.severity = 'critical') AS is_critical,
    a.created_at,
    i.id AS item_id
    FROM public.alerts a
    JOIN public.alert_items i ON i.alert_id = a.id AND i.status = 'active'
    LEFT JOIN LATERAL (
      SELECT ad.review_at, ad.reason, ad.dismissed_by, ad.dismissed_at
      FROM public.alert_item_dismissals ad
      WHERE ad.alert_item_id = i.id AND ad.occurrence_id = i.occurrence_id
      ORDER BY ad.dismissed_at DESC
      LIMIT 1
    ) d ON true
    LEFT JOIN public.user_profiles up ON up.id = d.dismissed_by
    WHERE a.status <> 'closed'
      AND (
        p_filter = 'all'
        OR (p_filter = 'dismissed' AND d.review_at > now())
        OR (p_filter = 'active' AND (d.review_at IS NULL OR d.review_at <= now()))
      )
      AND (p_entity_type IS NULL OR a.entity_type = p_entity_type)
      AND (
        p_department IS NULL
        OR i.department = p_department
        OR (p_department = 'sem_departamento' AND (i.department IS NULL OR btrim(i.department) = ''))
      )

    UNION ALL

    SELECT jsonb_build_object(
      'id', a.id,
      'item_id', NULL,
      'status', a.status,
      'item_status', NULL,
      'type', a.type,
      'severity', COALESCE(c.severity, 'normal'),
      'department', c.responsible_department,
      'message', a.message,
      'entity_type', a.entity_type,
      'entity_id', a.entity_id,
      'destination', c.default_destination,
      'created_at', a.created_at,
      'updated_at', a.created_at,
      'dismissed_until', NULL,
      'dismissal_reason', NULL,
      'dismissed_by', NULL,
      'dismissed_by_name', NULL,
      'dismissed_at', NULL,
      'metadata', '{}'::jsonb
    ) AS payload,
    false AS is_dismissed,
    (COALESCE(c.severity, 'normal') = 'critical') AS is_critical,
    a.created_at,
    a.id AS item_id
    FROM public.alerts a
    LEFT JOIN public.alert_type_catalog c ON c.type = a.type
    WHERE p_filter IN ('active', 'all')
      AND a.status <> 'closed'
      AND (p_entity_type IS NULL OR a.entity_type = p_entity_type)
      AND (
        p_department IS NULL
        OR c.responsible_department = p_department
        OR (p_department = 'sem_departamento' AND (c.responsible_department IS NULL OR btrim(c.responsible_department) = ''))
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.alert_items i WHERE i.alert_id = a.id
      )
  )
  SELECT payload
  FROM queue_rows
  ORDER BY
    is_dismissed ASC,
    is_critical DESC,
    created_at DESC,
    item_id DESC
  OFFSET p_offset
  LIMIT p_limit;
END;
$$;



--
-- Name: list_billing_runs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_billing_runs(p_limit integer DEFAULT 50) RETURNS TABLE(id bigint, manifest_id bigint, filename text, trigger_source text, status text, started_at timestamp with time zone, completed_at timestamp with time zone, total_bls integer, eligible_bls integer, blocked_bls integer, calculated_bls integer, total_brl numeric, total_usd numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    br.id, br.manifest_id, ib.filename, br.trigger_source, br.status,
    br.started_at, br.completed_at, br.total_bls, br.eligible_bls,
    br.blocked_bls, br.calculated_bls, br.total_brl, br.total_usd
  FROM public.billing_runs AS br
  JOIN public.import_batches AS ib ON ib.id = br.manifest_id
  WHERE public.is_active_read_user()
  ORDER BY br.started_at DESC
  LIMIT GREATEST(COALESCE(p_limit, 50), 1);
$$;



--
-- Name: list_bl_local_charge_lines(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_bl_local_charge_lines(p_bl_id text) RETURNS TABLE(id bigint, bl_id text, charge_table_id bigint, charge_item_id bigint, charge_name text, charge_table_name text, charge_table_pod text, application_basis text, source text, status text, quantity numeric, currency text, unit_value_brl numeric, unit_value_usd numeric, total_value_brl numeric, total_value_usd numeric, override_applied boolean, calculation_key text, notes text, review_reason text, calculated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    cc.id,
    cc.bl_id,
    cc.charge_table_id,
    cc.charge_item_id,
    COALESCE(cti.name, '[Sistema]') AS charge_name,
    ct.name AS charge_table_name,
    ct.pod AS charge_table_pod,
    cti.application_basis,
    cc.source,
    cc.status,
    cc.quantity,
    COALESCE(cti.currency, CASE WHEN cc.unit_value_usd IS NOT NULL THEN 'USD' ELSE 'BRL' END) AS currency,
    cc.unit_value_brl,
    cc.unit_value_usd,
    cc.total_value_brl,
    cc.total_value_usd,
    cc.override_applied,
    cc.calculation_key,
    cc.notes,
    cc.review_reason,
    cc.calculated_at
  FROM public.charge_calculations AS cc
  LEFT JOIN public.charge_table_items AS cti ON cti.id = cc.charge_item_id
  -- A tabela vem da linha, não do item: a linha guarda a tabela vigente no
  -- momento do cálculo, e é essa que o operador precisa conferir.
  LEFT JOIN public.charge_tables AS ct ON ct.id = cc.charge_table_id
  WHERE cc.bl_id = p_bl_id
  ORDER BY cc.source DESC, cc.id ASC;
END;
$$;



--
-- Name: list_consolidatable_receivables(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_consolidatable_receivables(p_customer_id bigint, p_voyage_id bigint DEFAULT NULL::bigint, p_search text DEFAULT NULL::text) RETURNS TABLE(receivable_id bigint, bl_id text, customer_id bigint, customer_name text, customer_cnpj_cpf text, voyage_id bigint, vessel_name text, voyage_number text, individual_invoice_id bigint, individual_invoice_number text, balance_brl numeric, original_amount_brl numeric, receivable_status text, eligibility_status text, eligibility_reason text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa.' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH base AS (
    SELECT
      br.id AS receivable_id,
      br.bl_id,
      br.customer_id,
      c.name AS customer_name,
      c.cnpj_cpf AS customer_cnpj_cpf,
      br.voyage_id,
      v.voyage_number,
      ve.name AS vessel_name,
      br.balance_brl,
      br.original_amount_brl,
      br.status AS receivable_status,
      indiv.invoice_id AS individual_invoice_id,
      inv_ind.invoice_number AS individual_invoice_number,
      EXISTS (
        SELECT 1
        FROM public.invoice_receivable_links irl
        JOIN public.invoices inv ON inv.id = irl.invoice_id
        WHERE irl.receivable_id = br.id
          AND inv.invoice_type = 'consolidated'
          AND COALESCE(inv.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue')
      ) AS has_open_consolidated
    FROM public.bl_receivables br
    JOIN public.customers c ON c.id = br.customer_id
    LEFT JOIN public.voyages v ON v.id = br.voyage_id
    LEFT JOIN public.vessels ve ON ve.id = v.vessel_id
    LEFT JOIN LATERAL (
      SELECT irl.invoice_id
      FROM public.invoice_receivable_links irl
      JOIN public.invoices inv ON inv.id = irl.invoice_id
      WHERE irl.receivable_id = br.id
        AND inv.invoice_type = 'individual'
      ORDER BY inv.id DESC
      LIMIT 1
    ) indiv ON TRUE
    LEFT JOIN public.invoices inv_ind ON inv_ind.id = indiv.invoice_id
    WHERE br.customer_id = p_customer_id
      AND (p_voyage_id IS NULL OR br.voyage_id = p_voyage_id)
      AND (
        NULLIF(TRIM(COALESCE(p_search, '')), '') IS NULL
        OR br.bl_id ILIKE '%' || TRIM(p_search) || '%'
      )
  )
  SELECT
    base.receivable_id,
    base.bl_id,
    base.customer_id,
    base.customer_name,
    base.customer_cnpj_cpf,
    base.voyage_id,
    base.vessel_name,
    base.voyage_number,
    base.individual_invoice_id,
    base.individual_invoice_number,
    base.balance_brl,
    base.original_amount_brl,
    base.receivable_status,
    CASE
      WHEN base.receivable_status = 'settled' THEN 'paid'
      WHEN base.receivable_status = 'void' THEN 'no_balance'
      WHEN base.has_open_consolidated THEN 'open_consolidated'
      WHEN base.balance_brl <= 0 THEN 'no_balance'
      ELSE 'eligible'
    END AS eligibility_status,
    CASE
      WHEN base.receivable_status = 'settled' THEN 'B/L ja liquidado.'
      WHEN base.receivable_status = 'void' THEN 'B/L sem saldo de taxas locais.'
      WHEN base.has_open_consolidated THEN 'B/L ja esta em consolidada aberta.'
      WHEN base.balance_brl <= 0 THEN 'B/L sem saldo aberto.'
      ELSE 'Elegivel para consolidacao.'
    END AS eligibility_reason
  FROM base
  ORDER BY base.voyage_id DESC NULLS LAST, base.bl_id ASC;
END;
$$;


