--
-- Name: list_customer_reconciliation_queue(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_customer_reconciliation_queue(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 200) RETURNS TABLE(id bigint, manifest_id bigint, bl_id text, customer_id bigint, current_customer_name text, cnpj_cpf text, manifest_customer_name text, manifest_customer_email text, detection_type text, status text, notes text, resolution_notes text, charge_status text, financial_status text, billing_hold_reason text, created_at timestamp with time zone, approved_at timestamp with time zone, rejected_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  SELECT
    q.id,
    q.manifest_id,
    q.bl_id,
    q.customer_id,
    c.name AS current_customer_name,
    q.cnpj_cpf,
    q.manifest_customer_name,
    q.manifest_customer_email,
    q.detection_type,
    q.status,
    q.notes,
    q.resolution_notes,
    b.charge_status,
    b.financial_status,
    b.billing_hold_reason,
    q.created_at,
    q.approved_at,
    q.rejected_at
  FROM public.customer_reconciliation_queue AS q
  LEFT JOIN public.customers AS c ON c.id = q.customer_id
  JOIN public.bls AS b ON b.id = q.bl_id
  WHERE p_status IS NULL OR q.status = p_status
  ORDER BY q.created_at DESC
  LIMIT GREATEST(COALESCE(p_limit, 200), 1);
END;
$$;



--
-- Name: list_demurrage_disputes_internal(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_demurrage_disputes_internal(p_state text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF public._portal_actor_role() <> 'equipamentos' THEN
    RAISE EXCEPTION 'Apenas Equipamentos pode consultar a fila de Disputes.' USING ERRCODE = '42501';
  END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', d.id, 'demurrage_invoice_id', d.demurrage_invoice_id,
      'doc_number', di.doc_number, 'customer_id', d.customer_id,
      'customer_name', c.name, 'state', d.state,
      'next_responder', d.next_responder, 'subject', d.subject,
      'created_at', d.created_at, 'updated_at', d.updated_at,
      'messages', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', m.id, 'author_type', m.author_type, 'body', m.body, 'next_responder', m.next_responder, 'created_at', m.created_at) ORDER BY m.created_at) FROM public.demurrage_dispute_messages m WHERE m.dispute_id = d.id), '[]'::jsonb)
    ) ORDER BY d.updated_at DESC)
    FROM public.demurrage_disputes d
    JOIN public.demurrage_invoices di ON di.id = d.demurrage_invoice_id
    JOIN public.customers c ON c.id = d.customer_id
    WHERE p_state IS NULL OR d.state = p_state
  ), '[]'::jsonb);
END;
$$;



--
-- Name: list_demurrage_dunning_claim_statuses(bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_demurrage_dunning_claim_statuses(p_invoice_ids bigint[]) RETURNS TABLE(invoice_id bigint, attempt_count integer, last_attempt_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     AND (auth.uid() IS NULL OR NOT public.is_active_read_user()) THEN
    RAISE EXCEPTION 'Usuário interno ativo é obrigatório.' USING ERRCODE = '42501';
  END IF;

  IF p_invoice_ids IS NULL OR cardinality(p_invoice_ids) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    claim.demurrage_invoice_id,
    count(*)::INTEGER,
    max(claim.claimed_at)
  FROM public.demurrage_dunning_claims AS claim
  WHERE claim.demurrage_invoice_id = ANY(p_invoice_ids)
    AND claim.released_at IS NULL
  GROUP BY claim.demurrage_invoice_id;
END;
$$;



--
-- Name: list_internal_notifications(boolean, integer, timestamp with time zone, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_internal_notifications(p_include_read boolean DEFAULT false, p_limit integer DEFAULT 20, p_before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT jsonb_build_object(
    'id', n.id,
    'alert_id', n.alert_id,
    'alert_item_id', n.alert_item_id,
    'item_type', n.item_type,
    'severity', n.severity,
    'title', n.title,
    'message', n.message,
    'entity_type', n.entity_type,
    'entity_id', n.entity_id,
    'destination', n.destination,
    'is_fallback', n.is_fallback,
    'read_at', n.read_at,
    'created_at', n.created_at,
    'payload', n.payload
  )
  FROM public.internal_notifications n
  WHERE public.is_active_read_user()
    AND n.recipient_id = auth.uid()
    AND (p_include_read OR n.read_at IS NULL)
    AND (
      p_before_created_at IS NULL
      OR n.created_at < p_before_created_at
      OR (n.created_at = p_before_created_at AND n.id < p_before_id)
    )
  ORDER BY n.created_at DESC, n.id DESC
  LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 20), 100));
$$;



--
-- Name: list_invoice_details(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_invoice_details(p_invoice_id bigint) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice JSONB;
  v_bls JSONB;
  v_items JSONB;
  v_payments JSONB;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  SELECT TO_JSONB(i.*) || jsonb_build_object(
    'customer_name', c.name,
    'customer_cnpj_cpf', c.cnpj_cpf
  )
  INTO v_invoice
  FROM public.invoices AS i
  LEFT JOIN public.customers AS c ON c.id = i.customer_id
  WHERE i.id = p_invoice_id;

  IF v_invoice IS NULL THEN
    RAISE EXCEPTION 'Invoice % nao encontrada.', p_invoice_id USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(JSONB_AGG(
    TO_JSONB(ib.*) || jsonb_build_object(
      'charge_status', b.charge_status,
      'financial_status', b.financial_status,
      'pol', b.pol,
      'pod', b.pod,
      'voyage_number', v.voyage_number,
      'vessel_name', vs.name
    )
    ORDER BY ib.id
  ), '[]'::JSONB)
  INTO v_bls
  FROM public.invoice_bls AS ib
  JOIN public.bls AS b ON b.id = ib.bl_id
  LEFT JOIN public.voyages AS v ON v.id = b.voyage_id
  LEFT JOIN public.vessels AS vs ON vs.id = v.vessel_id
  WHERE ib.invoice_id = p_invoice_id;

  SELECT COALESCE(JSONB_AGG(TO_JSONB(ii.*) ORDER BY ii.id), '[]'::JSONB)
  INTO v_items
  FROM public.invoice_items AS ii
  WHERE ii.invoice_id = p_invoice_id;

  SELECT COALESCE(JSONB_AGG(TO_JSONB(p.*) ORDER BY p.paid_at DESC, p.id DESC), '[]'::JSONB)
  INTO v_payments
  FROM public.payments AS p
  WHERE p.invoice_id = p_invoice_id;

  RETURN jsonb_build_object(
    'invoice', v_invoice,
    'bls', v_bls,
    'items', v_items,
    'payments', v_payments
  );
END;
$$;



--
-- Name: list_invoice_refunds(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_invoice_refunds(p_invoice_id bigint) RETURNS TABLE(id bigint, amount_brl numeric, status text, created_at timestamp with time zone, settled_at timestamp with time zone, notes text, payment_id bigint, cod_adjustment_id bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT r.id, r.amount_brl, r.status, r.created_at, r.settled_at,
    r.notes, r.payment_id, r.cod_adjustment_id
  FROM public.invoice_refunds AS r
  WHERE r.invoice_id = p_invoice_id
  ORDER BY r.created_at DESC, r.id DESC;
$$;



--
-- Name: list_manual_charge_items_for_bl(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_manual_charge_items_for_bl(p_bl_id text) RETURNS TABLE(charge_item_id bigint, charge_item_name text, charge_table_id bigint, charge_table_name text, cargo_mode text, pod text, currency text, default_unit_value_brl numeric, default_unit_value_usd numeric, effective_unit_value_brl numeric, effective_unit_value_usd numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH bl_ctx AS (
    SELECT
      b.id,
      COALESCE(b.cargo_mode, 'container') AS cargo_mode,
      b.customer_id,
      b.pod,
      COALESCE(ib.uploaded_at::DATE, b.created_at::DATE, CURRENT_DATE) AS reference_date
    FROM public.bls AS b
    LEFT JOIN public.import_batches AS ib ON ib.id = b.batch_id
    WHERE b.id = p_bl_id
  )
  SELECT
    cti.id AS charge_item_id,
    cti.name AS charge_item_name,
    ct.id AS charge_table_id,
    ct.name AS charge_table_name,
    ct.cargo_mode,
    ct.pod,
    COALESCE(cti.currency, 'BRL') AS currency,
    cti.unit_value_brl AS default_unit_value_brl,
    cti.unit_value_usd AS default_unit_value_usd,
    CASE
      WHEN COALESCE(cti.currency, 'BRL') = 'USD' THEN NULL
      ELSE COALESCE(cro.override_value, cti.unit_value_brl, cti.value_brl, 0)
    END AS effective_unit_value_brl,
    CASE
      WHEN COALESCE(cti.currency, 'BRL') = 'USD' THEN COALESCE(cro.override_value, cti.unit_value_usd, 0)
      ELSE NULL
    END AS effective_unit_value_usd
  FROM bl_ctx
  JOIN public.charge_tables AS ct
    ON ct.active = true
   AND ct.cargo_mode = bl_ctx.cargo_mode
   AND (
     public.normalize_port_code(ct.pod) = public.normalize_port_code(bl_ctx.pod)
     OR UPPER(TRIM(COALESCE(ct.pod, ''))) = 'ANY'
   )
   AND ct.valid_from <= bl_ctx.reference_date
   AND (ct.valid_to IS NULL OR ct.valid_to >= bl_ctx.reference_date)
  JOIN public.charge_table_items AS cti
    ON cti.charge_table_id = ct.id
   AND COALESCE(cti.active, true) = true
   AND COALESCE(cti.manual_only, false) = true
  LEFT JOIN LATERAL (
    SELECT cro.override_value
    FROM public.customer_rate_overrides AS cro
    WHERE cro.customer_id = bl_ctx.customer_id
      AND cro.charge_item_id = cti.id
      AND (cro.valid_from IS NULL OR cro.valid_from <= bl_ctx.reference_date)
      AND (cro.valid_to IS NULL OR cro.valid_to >= bl_ctx.reference_date)
    ORDER BY cro.created_at DESC
    LIMIT 1
  ) AS cro ON TRUE
  ORDER BY ct.valid_from DESC, ct.id DESC, COALESCE(cti.sort_order, 100), cti.id;
END;
$$;



--
-- Name: list_pix_reconciliation_candidates(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pix_reconciliation_candidates(p_exception_id bigint) RETURNS TABLE(source text, invoice_id bigint, doc_number text, amount_brl numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_exception public.pix_reconciliation_exceptions%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao para reconciliacao PIX.' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_exception
  FROM public.pix_reconciliation_exceptions
  WHERE id = p_exception_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Excecao PIX % nao encontrada.', p_exception_id USING ERRCODE = 'P0002';
  END IF;

  IF v_exception.normalized_txid = '' THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT 'local', i.id, COALESCE(i.invoice_number, i.id::TEXT), COALESCE(i.balance_brl, i.total_brl, 0)
  FROM public.invoices i
  WHERE i.invoice_type IN ('individual', 'consolidated')
    AND COALESCE(i.status, 'issued') IN ('issued', 'partially_paid', 'overdue')
    AND public.normalize_pix_txid(i.pix_txid) = v_exception.normalized_txid
  UNION ALL
  SELECT 'demurrage', d.id, d.doc_number, COALESCE(d.current_total_brl, 0)
  FROM public.demurrage_invoices d
  WHERE COALESCE(d.status, 'issued') IN ('issued', 'paid')
    AND public.normalize_pix_txid(d.pix_txid) = v_exception.normalized_txid
  ORDER BY 1, 3;
END;
$$;



--
-- Name: list_pix_reconciliation_exceptions(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_pix_reconciliation_exceptions(p_status text DEFAULT 'active'::text) RETURNS SETOF public.pix_reconciliation_exceptions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao para reconciliacao PIX.' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(p_status, 'active') NOT IN ('active', 'resolved', 'all') THEN
    RAISE EXCEPTION 'Status de excecao PIX invalido.' USING ERRCODE = '22023';
  END IF;

  RETURN QUERY
  SELECT e.*
  FROM public.pix_reconciliation_exceptions e
  WHERE COALESCE(p_status, 'active') = 'all' OR e.status = COALESCE(p_status, 'active')
  ORDER BY e.created_at DESC, e.line_number DESC;
END;
$$;



--
-- Name: mark_all_internal_notifications_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_all_internal_notifications_read() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rows_updated INTEGER;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;

  UPDATE public.internal_notifications
  SET read_at = COALESCE(read_at, now())
  WHERE recipient_id = auth.uid()
    AND read_at IS NULL;

  GET DIAGNOSTICS v_rows_updated = ROW_COUNT;
  RETURN v_rows_updated;
END;
$$;



--
-- Name: mark_bl_charges_reviewed(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_bl_charges_reviewed(p_bl_id text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl RECORD;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  SELECT id, charge_status
  INTO v_bl
  FROM public.bls
  WHERE id = p_bl_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF v_bl.charge_status = 'ready_for_billing' THEN
    RETURN jsonb_build_object('bl_id', p_bl_id, 'status', v_bl.charge_status, 'changed', false);
  END IF;

  UPDATE public.charge_calculations
  SET status = 'reviewed'
  WHERE bl_id = p_bl_id
    AND status IN ('calculated', 'review_required');

  UPDATE public.bls
  SET
    charge_status = 'reviewed',
    charges_reviewed_at = NOW()
  WHERE id = p_bl_id;

  INSERT INTO public.audit_logs (
    entity_type,
    entity_id,
    field_name,
    old_value,
    new_value,
    changed_by,
    changed_at,
    justification
  )
  VALUES (
    'bl',
    p_bl_id,
    'charge_status',
    COALESCE(v_bl.charge_status, 'null'),
    'reviewed',
    auth.uid(),
    NOW(),
    'Marcado como revisado no modulo de Taxas Locais'
  );

  RETURN jsonb_build_object('bl_id', p_bl_id, 'status', 'reviewed', 'changed', true);
END;
$$;



--
-- Name: mark_bl_ready_and_create_invoice(text, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_bl_ready_and_create_invoice(p_bl_id text, p_customer_id bigint DEFAULT NULL::bigint, p_notes text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl_id TEXT := upper(trim(p_bl_id));
  v_customer_id BIGINT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  SELECT COALESCE(p_customer_id, b.customer_id)
  INTO v_customer_id
  FROM public.bls b
  WHERE b.id = v_bl_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado.', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF v_customer_id IS NULL THEN
    RAISE EXCEPTION 'B/L % sem cliente vinculado.', v_bl_id USING ERRCODE = '22023';
  END IF;

  PERFORM public.mark_bl_ready_for_billing(v_bl_id, p_actor);

  RETURN public.create_invoice_from_bls_with_ledger(
    ARRAY[v_bl_id],
    v_customer_id,
    p_notes,
    true,
    p_actor
  );
END;
$$;



--
-- Name: mark_bl_ready_for_billing(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_bl_ready_for_billing(p_bl_id text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl RECORD;
  v_pending_count INTEGER := 0;
  v_table_count INTEGER := 0;
  v_invoiceable_count INTEGER := 0;
  v_review_reasons TEXT[];
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  SELECT id, charge_status, pod, cargo_mode, customer_id, customer_reconciliation_status
  INTO v_bl FROM public.bls WHERE id = p_bl_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF v_bl.customer_id IS NULL THEN
    RAISE EXCEPTION 'B/L % nao possui cliente vinculado. Vincule um cliente antes de marcar como pronto para faturar.', p_bl_id USING ERRCODE = 'P0003';
  END IF;
  IF COALESCE(v_bl.customer_reconciliation_status, 'missing_customer') NOT IN ('matched_document', 'reconciled') THEN
    RAISE EXCEPTION 'B/L exige reconciliacao manual antes do faturamento.' USING ERRCODE = '22023';
  END IF;

  v_review_reasons := public.compute_bl_review_pendencies(p_bl_id);
  IF COALESCE(cardinality(v_review_reasons), 0) > 0 THEN
    RAISE EXCEPTION 'B/L possui pendencias no gate de revisao: %', array_to_string(v_review_reasons, ', ') USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_pending_count FROM public.charge_calculations WHERE bl_id = p_bl_id AND status = 'review_required';
  IF v_pending_count > 0 THEN
    RAISE EXCEPTION 'Ainda existem linhas com pendencia de revisao' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_invoiceable_count
  FROM public.charge_calculations
  WHERE bl_id = p_bl_id
    AND (COALESCE(total_value_brl, 0) > 0 OR COALESCE(total_value_usd, 0) > 0)
    AND COALESCE(status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing');
  IF v_invoiceable_count = 0 THEN
    RAISE EXCEPTION 'B/L sem linhas faturaveis.' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*) INTO v_table_count
  FROM public.charge_tables
  WHERE public.normalize_port_code(pod) = public.normalize_port_code(v_bl.pod)
    AND cargo_mode = v_bl.cargo_mode AND active = true;
  IF v_table_count = 0 THEN
    RAISE EXCEPTION
      'Nenhuma tabela de cobranca ativa para POD "%" (modo: %). Configure em /taxas-locais/tabelas antes de prosseguir.',
      v_bl.pod, v_bl.cargo_mode USING ERRCODE = 'P0004';
  END IF;

  UPDATE public.charge_calculations SET status = 'ready_for_billing' WHERE bl_id = p_bl_id AND status IN ('calculated', 'reviewed');
  UPDATE public.bls SET charge_status = 'ready_for_billing', billing_hold_reason = NULL WHERE id = p_bl_id;
  PERFORM public.sync_local_charge_receivable(p_bl_id);
  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification)
  VALUES ('bl', p_bl_id, 'charge_status', COALESCE(v_bl.charge_status, 'null'), 'ready_for_billing', auth.uid(), NOW(), 'Marcado como pronto para faturar no modulo de Taxas Locais');
  RETURN jsonb_build_object('bl_id', p_bl_id, 'status', 'ready_for_billing', 'changed', true);
END;
$$;



--
-- Name: mark_bls_ready_and_create_invoice(text[], bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_bls_ready_and_create_invoice(p_bl_ids text[], p_customer_id bigint, p_notes text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl_ids TEXT[];
  v_bl RECORD;
  v_bl_id TEXT;
  v_found_count INTEGER := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  SELECT ARRAY_AGG(DISTINCT upper(trim(value)) ORDER BY upper(trim(value)))
  INTO v_bl_ids
  FROM unnest(COALESCE(p_bl_ids, ARRAY[]::TEXT[])) AS value
  WHERE NULLIF(trim(value), '') IS NOT NULL;

  IF COALESCE(cardinality(v_bl_ids), 0) = 0 OR p_customer_id IS NULL THEN
    RAISE EXCEPTION 'Informe ao menos um B/L e um cliente para faturar.' USING ERRCODE = '22023';
  END IF;

  FOR v_bl IN
    SELECT b.id, b.customer_id
    FROM public.bls b
    WHERE b.id = ANY(v_bl_ids)
    ORDER BY b.id
    FOR UPDATE
  LOOP
    v_found_count := v_found_count + 1;
    IF v_bl.customer_id IS DISTINCT FROM p_customer_id THEN
      RAISE EXCEPTION 'B/L % nao pertence ao cliente informado.', v_bl.id USING ERRCODE = '22023';
    END IF;
  END LOOP;

  IF v_found_count <> cardinality(v_bl_ids) THEN
    RAISE EXCEPTION 'Um ou mais B/Ls nao foram encontrados.' USING ERRCODE = 'P0002';
  END IF;

  FOREACH v_bl_id IN ARRAY v_bl_ids
  LOOP
    PERFORM public.mark_bl_ready_for_billing(v_bl_id, p_actor);
  END LOOP;

  RETURN public.create_invoice_from_bls_with_ledger(
    v_bl_ids,
    p_customer_id,
    p_notes,
    true,
    p_actor
  );
END;
$$;



--
-- Name: mark_internal_notification_read(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_internal_notification_read(p_notification_id bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501'; END IF;
  UPDATE public.internal_notifications
  SET read_at = COALESCE(read_at, now())
  WHERE id = p_notification_id AND recipient_id = auth.uid();
  RETURN FOUND;
END;
$$;



--
-- Name: mark_obsolete_consolidated_links(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_obsolete_consolidated_links() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.invoice_type = 'consolidated'
     AND NEW.status = 'obsolete'
     AND OLD.status IS DISTINCT FROM NEW.status THEN
    UPDATE public.invoice_receivable_links
    SET status = 'obsolete'
    WHERE invoice_id = NEW.id
      AND status = 'active';
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: mark_replaced_obsolete_consolidated_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_replaced_obsolete_consolidated_invoice() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_new_invoice RECORD;
BEGIN
  SELECT id, invoice_type, status
  INTO v_new_invoice
  FROM public.invoices
  WHERE id = NEW.invoice_id;

  IF v_new_invoice.invoice_type = 'consolidated'
     AND COALESCE(v_new_invoice.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue') THEN
    UPDATE public.invoices AS old_inv
    SET replaced_by_invoice_id = NEW.invoice_id
    WHERE old_inv.invoice_type = 'consolidated'
      AND old_inv.status = 'obsolete'
      AND old_inv.replaced_by_invoice_id IS NULL
      AND old_inv.id <> NEW.invoice_id
      AND EXISTS (
        SELECT 1
        FROM public.invoice_receivable_links AS old_link
        WHERE old_link.invoice_id = old_inv.id
          AND old_link.receivable_id = NEW.receivable_id
      );
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: normalize_cnpj(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_cnpj(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN NULLIF(upper(regexp_replace(p_value, '[^0-9A-Za-z]', '', 'g')), '');
END;
$$;



