--
-- Name: populate_charge_calculation_billing_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.populate_charge_calculation_billing_metadata() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT;
  v_manifest_id BIGINT;
  v_reference_date DATE;
BEGIN
  IF NEW.bl_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT
    b.customer_id,
    b.batch_id,
    COALESCE(ib.uploaded_at::DATE, b.created_at::DATE, CURRENT_DATE)
  INTO
    v_customer_id,
    v_manifest_id,
    v_reference_date
  FROM public.bls AS b
  LEFT JOIN public.import_batches AS ib ON ib.id = b.batch_id
  WHERE b.id = NEW.bl_id;

  IF NEW.manifest_id IS NULL THEN
    NEW.manifest_id := v_manifest_id;
  END IF;

  IF NEW.pricing_rule_version_id IS NULL AND NEW.charge_item_id IS NOT NULL THEN
    NEW.pricing_rule_version_id := public.ensure_pricing_rule_version(
      NEW.charge_table_id,
      NEW.charge_item_id,
      v_customer_id,
      v_reference_date,
      jsonb_build_object(
        'source', COALESCE(NEW.source, 'auto'),
        'calculation_key', NEW.calculation_key,
        'currency', CASE
          WHEN COALESCE(NEW.total_value_usd, 0) > 0 OR COALESCE(NEW.unit_value_usd, 0) > 0 THEN 'USD'
          ELSE 'BRL'
        END
      )
    );
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: populate_local_invoice_pix_payload(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.populate_local_invoice_pix_payload() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.pix_payload IS NULL
     AND COALESCE(NEW.invoice_type, 'individual') IN ('individual', 'consolidated')
     AND NULLIF(TRIM(COALESCE(NEW.invoice_number, '')), '') IS NOT NULL
     AND COALESCE(NEW.total_brl, 0) > 0 THEN
    NEW.pix_payload := public.build_transshipping_pix_payload(NEW.total_brl, NEW.invoice_number);
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: portal_add_dispute_message(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_add_dispute_message(p_demurrage_invoice_id bigint, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT := public.current_portal_customer_id();
  v_invoice RECORD;
  v_dispute RECORD;
  v_dispute_id BIGINT;
  v_message_id BIGINT;
BEGIN
  IF NULLIF(btrim(p_body), '') IS NULL THEN RAISE EXCEPTION 'Informe a mensagem da disputa.' USING ERRCODE = '22023'; END IF;
  PERFORM public.check_portal_rate_limit('open_dispute', 3, 30);
  SELECT id, customer_id, doc_number INTO v_invoice
  FROM public.demurrage_invoices
  WHERE id = p_demurrage_invoice_id AND customer_id = v_customer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fatura de demurrage não encontrada.' USING ERRCODE = 'P0002'; END IF;

  SELECT * INTO v_dispute
  FROM public.demurrage_disputes
  WHERE demurrage_invoice_id = v_invoice.id AND state = 'aberta'
  ORDER BY id DESC LIMIT 1 FOR UPDATE;
  IF v_dispute.id IS NOT NULL AND v_dispute.next_responder <> 'cliente' THEN
    RAISE EXCEPTION 'Aguarde a resposta de Equipamentos.' USING ERRCODE = '42501';
  END IF;
  v_dispute_id := COALESCE(v_dispute.id, public.ensure_demurrage_dispute(v_invoice.id, v_customer_id, 'cliente', NULL));

  INSERT INTO public.demurrage_dispute_messages(dispute_id, author_id, author_type, body, next_responder, metadata)
  VALUES (v_dispute_id, auth.uid(), 'cliente', btrim(p_body), 'equipamentos', jsonb_build_object('channel', 'portal'))
  RETURNING id INTO v_message_id;
  UPDATE public.demurrage_disputes SET state = 'aberta', next_responder = 'equipamentos', resolved_at = NULL, cancelled_at = NULL WHERE id = v_dispute_id;
  UPDATE public.demurrage_invoices SET dispute_open = true, dispute_status = 'aberto', dispute_reason = COALESCE(dispute_reason, btrim(p_body)) WHERE id = v_invoice.id;
  INSERT INTO public.portal_notifications(customer_id, bl_id, type, title, message, link)
  SELECT v_customer_id, NULL, 'dispute_opened', 'Disputa registrada', 'Sua disputa de demurrage foi registrada.', '/demurrage'
  WHERE NOT EXISTS (
    SELECT 1 FROM public.portal_notifications n
    WHERE n.customer_id = v_customer_id AND n.type = 'dispute_opened'
      AND n.created_at > now() - interval '30 minutes'
      AND n.message = 'Sua disputa de demurrage foi registrada.'
  );
  PERFORM public.block521_upsert_alert('portal_dispute_opened', 'demurrage_invoice', v_invoice.id::text,
    'Cliente enviou mensagem na Dispute ' || v_invoice.doc_number || '; resposta de Equipamentos pendente.',
    'portal_dispute_message', 'equipamentos', jsonb_build_object('dispute_id', v_dispute_id, 'message_id', v_message_id),
    '/demurrage?dispute=' || v_dispute_id);
  RETURN jsonb_build_object('dispute_id', v_dispute_id, 'message_id', v_message_id);
END;
$$;



--
-- Name: portal_admin_change_cnpj(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_admin_change_cnpj(p_customer_id bigint, p_new_cnpj text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := public._portal_actor_role();
  v_normalized TEXT := public.normalize_cnpj(COALESCE(p_new_cnpj, ''));
  v_account public.customer_portal_accounts%ROWTYPE;
BEGIN
  IF v_role IS DISTINCT FROM 'administrativo' THEN RAISE EXCEPTION 'permission denied' USING ERRCODE='42501'; END IF;
  IF v_normalized IS NULL OR NOT public.is_valid_cnpj(v_normalized) THEN RAISE EXCEPTION 'CNPJ inválido.' USING ERRCODE='22023'; END IF;
  IF NULLIF(trim(p_reason), '') IS NULL THEN RAISE EXCEPTION 'Justificativa é obrigatória.' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_account FROM public.customer_portal_accounts WHERE customer_id = p_customer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Registro de Portal não encontrado para o Cliente.' USING ERRCODE='P0002'; END IF;
  PERFORM set_config('portal.allow_cnpj_change', 'true', true);
  UPDATE public.customers SET cnpj_cpf = v_normalized WHERE id = p_customer_id;
  UPDATE public.customer_portal_accounts SET login_cnpj = v_normalized WHERE id = v_account.id;
  PERFORM public._portal_log_event(p_customer_id, v_account.id, NULL, v_account.provisioning_decision, v_account.provisioning_decision, v_account.account_situation, v_account.account_situation, 'administrativo', p_reason, NULL);
  PERFORM set_config('portal.allow_cnpj_change', 'false', true);
END;
$$;



--
-- Name: portal_assisted_email_change(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_assisted_email_change(p_customer_id bigint, p_new_email text, p_reason text, p_request_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE v_role TEXT:=public._portal_actor_role(); v_account public.customer_portal_accounts%ROWTYPE;
BEGIN
  IF v_role IS NULL OR v_role NOT IN ('administrativo','documentacao') THEN RAISE EXCEPTION 'permission denied' USING ERRCODE='42501'; END IF;
  IF NULLIF(trim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Justificativa é obrigatória.' USING ERRCODE='22023'; END IF;
  IF p_new_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN RAISE EXCEPTION 'Email inválido.' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM public.portal_suppressed_emails WHERE email=lower(p_new_email)) THEN RAISE EXCEPTION 'Endereço suprimido por bounce/complaint. Informe outro.' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_account FROM public.customer_portal_accounts WHERE customer_id=p_customer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Registro de Portal não encontrado.' USING ERRCODE='P0002'; END IF;
  UPDATE public.customer_portal_accounts SET recovery_email=lower(p_new_email),recovery_email_source='informado_manualmente',pending_recovery_email=NULL,recovery_email_status='ok' WHERE id=v_account.id;
  UPDATE public.portal_invites SET status='invalidado_por_reenvio' WHERE account_id=v_account.id AND purpose IN ('confirmacao_email','recuperacao') AND status='pendente';
  IF v_account.auth_user_id IS NOT NULL THEN PERFORM public.portal_revoke_sessions(v_account.auth_user_id); END IF;
  PERFORM public._portal_log_event(p_customer_id,v_account.id,NULL,v_account.provisioning_decision,v_account.provisioning_decision,v_account.account_situation,v_account.account_situation,v_role,p_reason || ' Sessões anteriores encerradas.',p_request_id);
END; $_$;



--
-- Name: portal_billing_gate(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_billing_gate(p_bl_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_customer_id BIGINT;
  v_account public.customer_portal_accounts%ROWTYPE;
  v_reason TEXT;
  v_email TEXT;
BEGIN
  SELECT customer_id INTO v_customer_id FROM public.bls WHERE id = p_bl_id;
  IF v_customer_id IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'Cliente não reconciliado para faturamento.');
  END IF;

  SELECT * INTO v_account
  FROM public.customer_portal_accounts
  WHERE customer_id = v_customer_id;

  v_email := lower(NULLIF(btrim(v_account.recovery_email), ''));
  IF v_account.id IS NULL OR NOT COALESCE(v_account.active, false)
     OR v_account.account_situation <> 'ativo'
     OR v_account.auth_user_id IS NULL THEN
    v_reason := 'Portal do Cliente não está ativo.';
  ELSIF v_email IS NULL OR v_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    v_reason := 'Email de recuperação ausente ou inválido.';
  ELSIF COALESCE(v_account.recovery_email_status, 'ok') <> 'ok'
     OR EXISTS (SELECT 1 FROM public.portal_suppressed_emails s WHERE lower(s.email) = v_email) THEN
    v_reason := 'Email de recuperação suprimido ou sem entrega utilizável.';
  END IF;

  RETURN jsonb_build_object(
    'allowed', v_reason IS NULL,
    'reason', v_reason,
    'customer_id', v_customer_id,
    'account_id', v_account.id,
    'recovery_email', v_email
  );
END;
$_$;



--
-- Name: portal_cancel_invite(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_cancel_invite(p_customer_id bigint, p_reason text, p_request_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_role TEXT:=public._portal_actor_role(); v_account public.customer_portal_accounts%ROWTYPE; v_invite BIGINT;
BEGIN
  IF v_role IS NULL OR v_role NOT IN ('administrativo','documentacao') THEN RAISE EXCEPTION 'permission denied' USING ERRCODE='42501'; END IF;
  IF NULLIF(trim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Justificativa é obrigatória.' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_account FROM public.customer_portal_accounts WHERE customer_id=p_customer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Registro de Portal não encontrado.' USING ERRCODE='P0002'; END IF;
  SELECT id INTO v_invite FROM public.portal_invites WHERE account_id=v_account.id AND purpose='convite' AND status='pendente' ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  IF v_invite IS NULL THEN RAISE EXCEPTION 'Não há convite pendente para cancelar.' USING ERRCODE='P0002'; END IF;
  UPDATE public.portal_invites SET status='cancelado',cancelled_reason=p_reason WHERE id=v_invite;
  UPDATE public.customer_portal_accounts SET account_situation='sem_conta',provisioning_decision='aguardando_analise' WHERE id=v_account.id;
  PERFORM public._portal_log_event(p_customer_id,v_account.id,v_invite,v_account.provisioning_decision,'aguardando_analise',v_account.account_situation,'sem_conta',v_role,p_reason,p_request_id);
END; $$;



--
-- Name: portal_create_account_on_customer_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_create_account_on_customer_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_account_id BIGINT;
BEGIN
  INSERT INTO public.customer_portal_accounts (customer_id, active, provisioning_decision, account_situation, login_cnpj)
  VALUES (NEW.id, false, 'aguardando_analise', 'sem_conta', public.normalize_cnpj(NEW.cnpj_cpf))
  ON CONFLICT (customer_id) DO NOTHING
  RETURNING id INTO v_account_id;

  IF v_account_id IS NOT NULL THEN
    INSERT INTO public.portal_provisioning_events (
      customer_id, account_id, previous_decision, new_decision,
      previous_situation, new_situation, actor_type, actor_id, reason, request_id
    ) VALUES (
      NEW.id, v_account_id, NULL, 'aguardando_analise', NULL, 'sem_conta',
      'sistema', NULL, 'Conta de Portal criada automaticamente no cadastro do Cliente.', NULL
    );
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: portal_create_consolidation(bigint[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_create_consolidation(p_receivable_ids bigint[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT := public.current_portal_customer_id();
  v_ids BIGINT[];
  v_result JSONB;
BEGIN
  PERFORM public.check_portal_rate_limit('create_consolidation', 3, 10);
  SELECT ARRAY_AGG(DISTINCT id ORDER BY id) INTO v_ids
  FROM UNNEST(COALESCE(p_receivable_ids, ARRAY[]::BIGINT[])) AS u(id) WHERE id IS NOT NULL;
  IF EXISTS (SELECT 1 FROM public.bl_receivables br WHERE br.id = ANY(v_ids) AND br.customer_id <> v_customer_id) THEN
    RAISE EXCEPTION 'Selecao contem B/Ls de outro cliente.' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.bl_receivables br WHERE br.id = ANY(v_ids) AND NOT public.bl_has_portal_release(br.bl_id)) THEN
    RAISE EXCEPTION 'Selecao contem B/L sem CE Mercante liberado para o portal.' USING ERRCODE = '42501';
  END IF;
  v_result := public.create_local_consolidated_invoice_core(v_customer_id, p_receivable_ids, auth.uid(), 'portal');
  INSERT INTO public.portal_notifications (customer_id, type, title, message, link)
  VALUES (v_customer_id, 'system', 'Fatura consolidada criada',
    'Sua fatura consolidada foi gerada com ' || array_length(p_receivable_ids, 1) || ' B/L(s).', '/portal/billing');
  RETURN v_result;
END;
$$;



