--
-- Name: portal_get_profile_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_get_profile_legacy() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT := public.current_portal_customer_id();
  v_result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'contact_email', a.contact_email,
    'phone', (SELECT cc.phone FROM public.customer_contacts AS cc WHERE cc.customer_id = v_customer_id AND cc.purpose = 'faturamento' LIMIT 1),
    'address', c.address,
    'city', c.city,
    'state', c.state,
    'zip', c.zip
  )
  INTO v_result
  FROM public.customers AS c
  LEFT JOIN public.customer_portal_accounts AS a ON a.customer_id = c.id
  WHERE c.id = v_customer_id;

  RETURN COALESCE(v_result, '{}'::JSONB);
END;
$$;



--
-- Name: portal_get_session_overview_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_get_session_overview_v2() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_account  RECORD;
  v_customer RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sessao do portal invalida ou expirada.' USING ERRCODE = '28000';
  END IF;

  SELECT a.id, a.customer_id, a.active, a.contact_email, a.login_cnpj
  INTO v_account
  FROM public.customer_portal_accounts AS a
  WHERE a.auth_user_id = auth.uid();

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sessao do portal invalida ou expirada.' USING ERRCODE = '28000';
  END IF;

  IF NOT v_account.active THEN
    RAISE EXCEPTION 'Acesso ao portal desativado. Entre em contato com o suporte.' USING ERRCODE = '28000';
  END IF;

  SELECT c.id, c.name, c.cnpj_cpf, c.pending_balance
  INTO v_customer
  FROM public.customers AS c
  WHERE c.id = v_account.customer_id;

  UPDATE public.customer_portal_accounts
  SET last_login_at = now()
  WHERE id = v_account.id;

  RETURN jsonb_build_object(
    'customer_id',       v_customer.id,
    'customer_name',     v_customer.name,
    'customer_cnpj_cpf', v_customer.cnpj_cpf,
    'cnpj_cpf',          v_customer.cnpj_cpf,
    'pending_balance',   v_customer.pending_balance,
    'contact_email',     v_account.contact_email,
    'account_id',        v_account.id,
    'login_cnpj',        v_account.login_cnpj
  );
END;
$$;



