CREATE FUNCTION public.portal_invoice_details(p_invoice_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ BEGIN RETURN public._portal_invoice_details_core(public.current_portal_customer_id(), p_invoice_id); END; $$;



--
-- Name: portal_invoice_details_legacy(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_invoice_details_legacy(p_invoice_id bigint) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id bigint := public.current_portal_customer_id();
  v_invoice JSONB;
  v_bls JSONB;
  v_items JSONB;
  v_containers JSONB;
  v_payments JSONB;
BEGIN
  SELECT TO_JSONB(i.*) || jsonb_build_object(
    'customer_name', c.name,
    'customer_cnpj_cpf', c.cnpj_cpf
  )
  INTO v_invoice
  FROM public.invoices AS i
  LEFT JOIN public.customers AS c ON c.id = i.customer_id
  WHERE i.id = p_invoice_id
    AND i.customer_id = v_customer_id;

  IF v_invoice IS NULL THEN
    RAISE EXCEPTION 'Invoice % nao encontrada.', p_invoice_id USING ERRCODE = 'P0002';
  END IF;

  SELECT COALESCE(JSONB_AGG(
    TO_JSONB(ib.*) || jsonb_build_object(
      'charge_status', b.charge_status,
      'financial_status', b.financial_status,
      'pol', b.pol,
      'pod', b.pod,
      'voyage_number', v.voyage_number,
      'vessel_name', vs.name
    )
    ORDER BY ib.id
  ), '[]'::JSONB)
  INTO v_bls
  FROM public.invoice_bls AS ib
  JOIN public.bls AS b ON b.id = ib.bl_id
  LEFT JOIN public.voyages AS v ON v.id = b.voyage_id
  LEFT JOIN public.vessels AS vs ON vs.id = v.vessel_id
  WHERE ib.invoice_id = p_invoice_id;

  IF v_bls = '[]'::JSONB THEN
    -- Consolidated ledger invoices have no invoice_bls; build the BL summary
    -- rows from the receivable links (independente de invoice_items ja estar
    -- congelado ou nao).
    SELECT COALESCE(JSONB_AGG(
      jsonb_build_object(
        'id', l.id, 'invoice_id', p_invoice_id, 'bl_id', l.bl_id,
        'charge_status_snapshot', NULL, 'financial_status_snapshot', NULL,
        'subtotal_brl', l.subtotal_brl, 'subtotal_usd', 0, 'created_at', NULL,
        'pol', l.bl_snapshot->>'pol', 'pod', l.bl_snapshot->>'pod',
        'voyage_number', v.voyage_number, 'vessel_name', vs.name
      ) ORDER BY l.id
    ), '[]'::JSONB)
    INTO v_bls
    FROM public.invoice_receivable_links AS l
    LEFT JOIN public.voyages AS v ON v.id = (l.bl_snapshot->>'voyage_id')::bigint
    LEFT JOIN public.vessels AS vs ON vs.id = v.vessel_id
    WHERE l.invoice_id = p_invoice_id;
  END IF;

  SELECT COALESCE(JSONB_AGG(TO_JSONB(ii.*) ORDER BY ii.id), '[]'::JSONB)
  INTO v_items
  FROM public.invoice_items AS ii
  WHERE ii.invoice_id = p_invoice_id;

  IF v_items = '[]'::JSONB THEN
    -- Rede de seguranca: reconstroi ao vivo se, por algum motivo, esta
    -- consolidada nao tiver passado pelo backfill (migration 261). Mesma
    -- logica de reconciliacao usada na gravacao acima.
    WITH links AS (
      SELECT l.id AS link_id, l.bl_id, COALESCE(l.subtotal_brl, 0) AS subtotal_brl
      FROM public.invoice_receivable_links AS l
      WHERE l.invoice_id = p_invoice_id
    ),
    calcs AS (
      SELECT
        cc.bl_id,
        cc.id AS charge_calculation_id,
        cc.charge_table_id,
        cc.charge_item_id,
        cc.quantity,
        cc.unit_value_brl,
        cc.total_value_brl,
        cti.currency,
        cc.unit_value_usd,
        cc.total_value_usd,
        cc.calculation_key,
        cti.name AS charge_name
      FROM public.charge_calculations AS cc
      LEFT JOIN public.charge_table_items AS cti ON cti.id = cc.charge_item_id
      WHERE cc.bl_id IN (SELECT bl_id FROM links)
        AND COALESCE(cc.total_value_brl, 0) > 0
        AND COALESCE(cc.status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing', 'exempt')
    ),
    bl_recon AS (
      SELECT
        links.bl_id,
        links.subtotal_brl,
        COUNT(calcs.charge_calculation_id) AS calc_count,
        COALESCE(SUM(calcs.total_value_brl), 0) AS detailed_sum
      FROM links
      LEFT JOIN calcs ON calcs.bl_id = links.bl_id
      GROUP BY links.bl_id, links.subtotal_brl
    ),
    detailed_items AS (
      SELECT
        calcs.bl_id,
        calcs.charge_calculation_id AS sort_key,
        jsonb_build_object(
          'id', calcs.charge_calculation_id,
          'invoice_id', p_invoice_id,
          'charge_calculation_id', calcs.charge_calculation_id,
          'description', 'BL ' || calcs.bl_id || ' - ' || COALESCE(calcs.charge_name, calcs.calculation_key, 'Linha de taxa'),
          'quantity', COALESCE(calcs.quantity, 1),
          'unit_value_brl', calcs.unit_value_brl,
          'total_value_brl', COALESCE(calcs.total_value_brl, 0),
          'bl_id', calcs.bl_id,
          'manifest_id', NULL,
          'charge_table_id', calcs.charge_table_id,
          'charge_item_id', calcs.charge_item_id,
          'source', 'ledger',
          'currency', COALESCE(calcs.currency, 'BRL'),
          'unit_value_usd', calcs.unit_value_usd,
          'total_value_usd', calcs.total_value_usd
        ) AS item
      FROM calcs
      JOIN bl_recon ON bl_recon.bl_id = calcs.bl_id
      WHERE bl_recon.calc_count > 0
        AND ABS(bl_recon.detailed_sum - bl_recon.subtotal_brl) < 0.01
    ),
    fallback_items AS (
      SELECT
        links.bl_id,
        links.link_id AS sort_key,
        jsonb_build_object(
          'id', links.link_id,
          'invoice_id', p_invoice_id,
          'charge_calculation_id', NULL,
          'description', 'BL ' || links.bl_id || ' - Taxas locais',
          'quantity', 1,
          'unit_value_brl', links.subtotal_brl,
          'total_value_brl', links.subtotal_brl,
          'bl_id', links.bl_id,
          'manifest_id', NULL,
          'charge_table_id', NULL,
          'charge_item_id', NULL,
          'source', 'ledger',
          'currency', 'BRL',
          'unit_value_usd', NULL,
          'total_value_usd', NULL
        ) AS item
      FROM links
      JOIN bl_recon ON bl_recon.bl_id = links.bl_id
      WHERE NOT (bl_recon.calc_count > 0 AND ABS(bl_recon.detailed_sum - bl_recon.subtotal_brl) < 0.01)
    ),
    all_items AS (
      SELECT bl_id, sort_key, item FROM detailed_items
      UNION ALL
      SELECT bl_id, sort_key, item FROM fallback_items
    )
    SELECT COALESCE(JSONB_AGG(item ORDER BY bl_id, sort_key), '[]'::JSONB)
    INTO v_items
    FROM all_items;
  END IF;

  WITH inv_bls AS (
    SELECT ib.bl_id FROM public.invoice_bls AS ib WHERE ib.invoice_id = p_invoice_id
    UNION
    SELECT irl.bl_id FROM public.invoice_receivable_links AS irl
    WHERE irl.invoice_id = p_invoice_id
  )
  SELECT COALESCE(JSONB_AGG(
    jsonb_build_object(
      'id', cont.id,
      'bl_id', cont.bl_id,
      'container_number', cont.container_number,
      'type', cont.type,
      'seal_number', cont.seal_number,
      'gross_weight_kg', cont.gross_weight_kg
    ) ORDER BY cont.bl_id, cont.container_number
  ), '[]'::JSONB)
  INTO v_containers
  FROM public.bl_containers AS cont
  WHERE cont.bl_id IN (SELECT bl_id FROM inv_bls);

  SELECT COALESCE(JSONB_AGG(TO_JSONB(p.*) ORDER BY p.paid_at DESC, p.id DESC), '[]'::JSONB)
  INTO v_payments
  FROM public.payments AS p
  WHERE p.invoice_id = p_invoice_id;

  RETURN jsonb_build_object(
    'invoice', v_invoice,
    'bls', v_bls,
    'items', v_items,
    'containers', v_containers,
    'payments', v_payments
  );
END;
$$;



--
-- Name: portal_invoice_exception_on_close(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_invoice_exception_on_close() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl RECORD;
BEGIN
  IF NEW.status IN ('paid', 'partially_paid', 'cancelled', 'obsolete') AND OLD.status IS DISTINCT FROM NEW.status THEN
    IF NEW.bl_id IS NOT NULL THEN PERFORM public.block521_resolve_alert('portal_excecao_critica_fatura', 'bl', NEW.bl_id, 'documentacao', 'portal_invoice_status'); END IF;
    FOR v_bl IN SELECT ib.bl_id FROM public.invoice_bls ib WHERE ib.invoice_id = NEW.id LOOP
      PERFORM public.block521_resolve_alert('portal_excecao_critica_fatura', 'bl', v_bl.bl_id, 'documentacao', 'portal_invoice_status');
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: portal_invoice_exception_on_invoice_bl(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_invoice_exception_on_invoice_bl() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_status TEXT;
BEGIN
  SELECT status INTO v_status FROM public.invoices WHERE id = NEW.invoice_id;
  IF v_status = 'issued' THEN PERFORM public.upsert_portal_invoice_exception(NEW.invoice_id, NEW.bl_id); END IF;
  RETURN NEW;
END;
$$;



--
-- Name: portal_invoice_exception_on_issue(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_invoice_exception_on_issue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl RECORD;
BEGIN
  IF NEW.status <> 'issued' OR (TG_OP = 'UPDATE' AND OLD.status = 'issued') THEN RETURN NEW; END IF;
  IF NEW.bl_id IS NOT NULL THEN
    PERFORM public.upsert_portal_invoice_exception(NEW.id, NEW.bl_id);
  END IF;
  FOR v_bl IN SELECT ib.bl_id FROM public.invoice_bls ib WHERE ib.invoice_id = NEW.id LOOP
    PERFORM public.upsert_portal_invoice_exception(NEW.id, v_bl.bl_id);
  END LOOP;
  RETURN NEW;
END;
$$;



--
-- Name: portal_list_consolidatable_receivables(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_consolidatable_receivables() RETURNS TABLE(receivable_id bigint, bl_id text, customer_id bigint, customer_name text, customer_cnpj_cpf text, voyage_id bigint, vessel_name text, voyage_number text, individual_invoice_id bigint, individual_invoice_number text, balance_brl numeric, original_amount_brl numeric, receivable_status text, eligibility_status text, eligibility_reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ BEGIN RETURN QUERY SELECT * FROM public._portal_list_consolidatable_receivables_core(public.current_portal_customer_id()); END; $$;



--
-- Name: portal_list_consolidatable_receivables_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_consolidatable_receivables_legacy() RETURNS TABLE(receivable_id bigint, bl_id text, customer_id bigint, customer_name text, customer_cnpj_cpf text, voyage_id bigint, vessel_name text, voyage_number text, individual_invoice_id bigint, individual_invoice_number text, balance_brl numeric, original_amount_brl numeric, receivable_status text, eligibility_status text, eligibility_reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id bigint := public.current_portal_customer_id();
BEGIN
  RETURN QUERY
  WITH base AS (
    SELECT
      br.id AS receivable_id,
      br.bl_id,
      br.customer_id,
      c.name AS customer_name,
      c.cnpj_cpf AS customer_cnpj_cpf,
      br.voyage_id,
      v.voyage_number,
      ve.name AS vessel_name,
      br.balance_brl,
      br.original_amount_brl,
      br.status AS receivable_status,
      indiv.invoice_id AS individual_invoice_id,
      inv_ind.invoice_number AS individual_invoice_number,
      EXISTS (
        SELECT 1
        FROM public.invoice_receivable_links irl
        JOIN public.invoices inv ON inv.id = irl.invoice_id
        WHERE irl.receivable_id = br.id
          AND inv.invoice_type = 'consolidated'
          AND COALESCE(inv.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue')
      ) AS has_open_consolidated
    FROM public.bl_receivables br
    JOIN public.customers c ON c.id = br.customer_id
    LEFT JOIN public.voyages v ON v.id = br.voyage_id
    LEFT JOIN public.vessels ve ON ve.id = v.vessel_id
    LEFT JOIN LATERAL (
      SELECT irl.invoice_id
      FROM public.invoice_receivable_links irl
      JOIN public.invoices inv ON inv.id = irl.invoice_id
      WHERE irl.receivable_id = br.id
        AND inv.invoice_type = 'individual'
      ORDER BY inv.id DESC
      LIMIT 1
    ) indiv ON TRUE
    LEFT JOIN public.invoices inv_ind ON inv_ind.id = indiv.invoice_id
    WHERE br.customer_id = v_customer_id AND br.source = 'local_charges' AND public.bl_has_portal_release(br.bl_id)
  )
  SELECT
    base.receivable_id,
    base.bl_id,
    base.customer_id,
    base.customer_name,
    base.customer_cnpj_cpf,
    base.voyage_id,
    base.vessel_name,
    base.voyage_number,
    base.individual_invoice_id,
    base.individual_invoice_number,
    base.balance_brl,
    base.original_amount_brl,
    base.receivable_status,
    CASE
      WHEN base.receivable_status = 'settled' THEN 'paid'
      WHEN base.receivable_status = 'void' THEN 'no_balance'
      WHEN base.has_open_consolidated THEN 'open_consolidated'
      WHEN base.balance_brl <= 0 THEN 'no_balance'
      ELSE 'eligible'
    END AS eligibility_status,
    CASE
      WHEN base.receivable_status = 'settled' THEN 'B/L ja liquidado.'
      WHEN base.receivable_status = 'void' THEN 'B/L sem saldo de taxas locais.'
      WHEN base.has_open_consolidated THEN 'B/L ja esta em consolidada aberta.'
      WHEN base.balance_brl <= 0 THEN 'B/L sem saldo aberto.'
      ELSE 'Elegivel para consolidacao.'
    END AS eligibility_reason
  FROM base
  ORDER BY base.voyage_id DESC NULLS LAST, base.bl_id ASC;
END;
$$;



--
-- Name: portal_list_demurrage_invoices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_demurrage_invoices() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ BEGIN RETURN public._portal_list_demurrage_invoices_core(public.current_portal_customer_id()); END; $$;



--
-- Name: portal_list_demurrage_invoices_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_demurrage_invoices_legacy() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id bigint := public.current_portal_customer_id();
BEGIN
  RETURN (
    SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.doc_date DESC), '[]'::jsonb)
    FROM (
      SELECT
        di.id, di.doc_number, di.doc_date, di.due_date, di.billed_at, di.paid_at,
        di.total_usd, di.current_roe, di.current_total_brl, di.roe_source, di.updated_at,
        di.status, di.pix_payload,
        di.dispute_open, di.discount_type, di.discount_value, di.discount_mode,
        b.id AS bl_id, b.pol, b.pod, v.voyage_number, vs.name AS vessel_name
      FROM public.demurrage_invoices di
      JOIN public.bls b ON b.id = di.bl_id
      LEFT JOIN public.voyages v ON v.id = b.voyage_id
      LEFT JOIN public.vessels vs ON vs.id = v.vessel_id
      WHERE di.customer_id = v_customer_id AND di.status IN ('issued', 'overdue', 'paid') AND public.bl_has_portal_release(di.bl_id)
    ) t
  );
END;
$$;



--
-- Name: portal_list_disputes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_disputes() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', d.id, 'demurrage_invoice_id', d.demurrage_invoice_id,
      'doc_number', di.doc_number, 'state', d.state,
      'next_responder', d.next_responder, 'subject', d.subject,
      'created_at', d.created_at, 'updated_at', d.updated_at,
      'messages', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', m.id, 'author_type', m.author_type, 'body', m.body, 'next_responder', m.next_responder, 'created_at', m.created_at, 'attachments', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', a.id, 'file_name', a.file_name, 'mime_type', a.mime_type, 'storage_path', a.storage_path)) FROM public.demurrage_dispute_attachments a WHERE a.message_id = m.id), '[]'::jsonb)) ORDER BY m.created_at) FROM public.demurrage_dispute_messages m WHERE m.dispute_id = d.id), '[]'::jsonb)
    ) ORDER BY d.created_at DESC)
    FROM public.demurrage_disputes d
    JOIN public.demurrage_invoices di ON di.id = d.demurrage_invoice_id
    WHERE d.customer_id = public.current_portal_customer_id()
  ), '[]'::jsonb);
END;
$$;



--
-- Name: portal_list_invoices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_invoices() RETURNS TABLE(id bigint, invoice_number text, issued_at timestamp with time zone, total_brl numeric, total_paid_brl numeric, balance_brl numeric, status text, invoice_type text, vessels text[], voyages text[], vessel_voyages text[], bls text[], pods text[])
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ BEGIN RETURN QUERY SELECT * FROM public._portal_list_invoices_core(public.current_portal_customer_id()); END; $$;



--
-- Name: portal_list_notifications(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_notifications(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$ BEGIN RETURN public._portal_list_notifications_core(public.current_portal_customer_id(), p_limit); END; $$;



--
-- Name: portal_list_notifications_legacy(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_notifications_legacy(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT := public.current_portal_customer_id();
  v_result JSONB;
BEGIN
  SELECT COALESCE(JSONB_AGG(
    jsonb_build_object(
      'id', n.id,
      'type', n.type,
      'title', n.title,
      'message', n.message,
      'link', n.link,
      'read', n.read,
      'created_at', n.created_at
    ) ORDER BY n.created_at DESC
  ), '[]'::JSONB)
  INTO v_result
  FROM (
    SELECT id, type, title, message, link, (read_at IS NOT NULL) AS read, created_at
    FROM public.portal_notifications
    WHERE customer_id = v_customer_id
    ORDER BY created_at DESC
    LIMIT p_limit
  ) AS n;

  RETURN v_result;
END;
$$;



--
-- Name: portal_list_operation_bls(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_operation_bls() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rows JSONB := public._portal_list_operation_bls_core(public.current_portal_customer_id());
BEGIN
  RETURN (
    SELECT COALESCE(jsonb_agg(
      item || jsonb_build_object(
        'transshipment', CASE
          WHEN omission.id IS NULL THEN NULL
          WHEN omission.disposition = 'cod' THEN jsonb_build_object(
            'omission_id', omission.id,
            'disposition', omission.disposition,
            'omitted_pod', omission.omitted_pod,
            'discharge_pod', omission.discharge_pod
          )
          ELSE jsonb_build_object(
            'omission_id', omission.id,
            'disposition', omission.disposition,
            'omitted_pod', omission.omitted_pod,
            'discharge_pod', omission.discharge_pod,
            'onward_vessel_name', omission.onward_vessel_name,
            'onward_carrier', omission.onward_carrier,
            'onward_voyage_number', omission.onward_voyage_number,
            'onward_etd', omission.onward_etd,
            'onward_eta', omission.onward_eta
          )
        END
      ) ORDER BY ordinality
    ), '[]'::jsonb)
    FROM jsonb_array_elements(v_rows) WITH ORDINALITY AS rows(item, ordinality)
    LEFT JOIN LATERAL (
      SELECT vo.id, bt.disposition, vo.omitted_pod, vo.discharge_pod,
             vo.onward_vessel_name, vo.onward_carrier, vo.onward_voyage_number,
             vo.onward_etd, vo.onward_eta
      FROM public.bl_transshipments bt
      JOIN public.voyage_omissions vo ON vo.id = bt.omission_id
      WHERE bt.bl_id = item->>'bl_id'
        AND vo.reverted_at IS NULL
      ORDER BY vo.omitted_at DESC, vo.id DESC
      LIMIT 1
    ) omission ON true
  );
END;
$$;



--
-- Name: portal_list_operation_bls_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_operation_bls_legacy() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_rows JSONB := public.portal_list_operation_bls_without_transshipment();
BEGIN
  RETURN (
    SELECT COALESCE(jsonb_agg(
      item || jsonb_build_object(
        'transshipment', CASE WHEN omission.id IS NULL THEN NULL ELSE jsonb_build_object(
          'omission_id', omission.id,
          'disposition', omission.disposition,
          'omitted_pod', omission.omitted_pod,
          'discharge_pod', omission.discharge_pod,
          'reason', omission.reason,
          'onward_vessel_name', omission.onward_vessel_name,
          'onward_carrier', omission.onward_carrier,
          'onward_voyage_number', omission.onward_voyage_number,
          'onward_etd', omission.onward_etd,
          'onward_eta', omission.onward_eta
        ) END
      ) ORDER BY ordinality
    ), '[]'::jsonb)
    FROM jsonb_array_elements(v_rows) WITH ORDINALITY AS rows(item, ordinality)
    LEFT JOIN LATERAL (
      SELECT vo.id, bt.disposition, vo.omitted_pod, vo.discharge_pod, vo.reason,
             vo.onward_vessel_name, vo.onward_carrier, vo.onward_voyage_number,
             vo.onward_etd, vo.onward_eta
      FROM public.bl_transshipments bt
      JOIN public.voyage_omissions vo ON vo.id = bt.omission_id
      WHERE bt.bl_id = item->>'bl_id'
      ORDER BY vo.omitted_at DESC, vo.id DESC
      LIMIT 1
    ) omission ON true
  );
END;
$$;



--
-- Name: portal_list_operation_bls_without_transshipment_legacy(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_operation_bls_without_transshipment_legacy() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id bigint := public.current_portal_customer_id();
BEGIN
  RETURN (
    WITH active_rates AS (
      SELECT DISTINCT ON (upper(trim(container_type)))
        upper(trim(container_type)) AS container_type,
        free_days
      FROM public.demurrage_rates
      WHERE active = true
        AND (valid_from IS NULL OR valid_from <= CURRENT_DATE)
        AND (valid_to IS NULL OR valid_to >= CURRENT_DATE)
      ORDER BY upper(trim(container_type)), valid_from DESC NULLS LAST, id DESC
    ),
    bl_rows AS (
      SELECT
        b.id AS bl_id,
        b.ce_mercante,
        b.pol,
        b.pod,
        b.voyage_id,
        v.voyage_number,
        vs.name AS vessel_name,
        b.free_time_override
      FROM public.bls AS b
      LEFT JOIN public.voyages AS v ON v.id = b.voyage_id
      LEFT JOIN public.vessels AS vs ON vs.id = v.vessel_id
      WHERE b.customer_id = v_customer_id AND public.bl_has_portal_release(b.id)
    )
    SELECT COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'bl_id', bl.bl_id,
          'ce_mercante', bl.ce_mercante,
          'pol', bl.pol,
          'pod', bl.pod,
          'voyage_id', bl.voyage_id,
          'voyage_number', bl.voyage_number,
          'vessel_name', bl.vessel_name,
          'container_count', container_summary.container_count,
          'containers_in_demurrage', container_summary.containers_in_demurrage,
          'containers_returned', container_summary.containers_returned,
          'containers', container_summary.containers
        )
        ORDER BY bl.voyage_id DESC NULLS LAST, bl.bl_id
      ),
      '[]'::jsonb
    )
    FROM bl_rows AS bl
    LEFT JOIN LATERAL (
      WITH calculated AS (
        SELECT
          c.id,
          c.container_number,
          c.type,
          c.discharge_date,
          c.return_date,
          CASE
            WHEN c.discharge_date IS NULL THEN NULL
            ELSE GREATEST(COALESCE(c.return_date, CURRENT_DATE) - c.discharge_date, 0)
          END AS usage_days,
          CASE
            WHEN c.discharge_date IS NULL THEN NULL
            ELSE COALESCE(
              bl.free_time_override,
              ar.free_days,
              CASE
                WHEN upper(trim(COALESCE(c.type, ''))) IN ('20RF', '20RQ', '20R1', '40RF', '40RQ', '40R1', '45R1')
                  THEN 10
                ELSE 21
              END
            )
          END AS free_time_days
        FROM public.bl_containers AS c
        LEFT JOIN active_rates AS ar
          ON ar.container_type = upper(trim(COALESCE(c.type, '')))
        WHERE c.bl_id = bl.bl_id
      ),
      with_demurrage AS (
        SELECT
          calculated.*,
          CASE
            WHEN usage_days IS NULL OR free_time_days IS NULL THEN NULL
            ELSE GREATEST(usage_days - free_time_days, 0)
          END AS demurrage_days
        FROM calculated
      ),
      with_status AS (
        SELECT
          with_demurrage.*,
          CASE
            WHEN discharge_date IS NULL THEN 'sem_descarga'
            WHEN return_date IS NOT NULL THEN 'devolvido'
            WHEN COALESCE(demurrage_days, 0) > 0 THEN 'em_demurrage'
            ELSE 'dentro_free_time'
          END AS status
        FROM with_demurrage
      )
      SELECT
        COUNT(*)::int AS container_count,
        COUNT(*) FILTER (WHERE status = 'em_demurrage')::int AS containers_in_demurrage,
        COUNT(*) FILTER (WHERE status = 'devolvido')::int AS containers_returned,
        COALESCE(
          jsonb_agg(
            jsonb_build_object(
              'id', id,
              'container_number', container_number,
              'type', type,
              'discharge_date', discharge_date,
              'return_date', return_date,
              'usage_days', usage_days,
              'free_time_days', free_time_days,
              'demurrage_days', demurrage_days,
              'status', status
            )
            ORDER BY container_number
          ),
          '[]'::jsonb
        ) AS containers
      FROM with_status
    ) AS container_summary ON true
  );
END;
$$;



--
-- Name: portal_list_provisioning_console(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_provisioning_console(p_customer_id bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := public._portal_actor_role();
  v_full_access BOOLEAN := v_role IN ('administrativo', 'documentacao', 'financeiro', 'equipamentos');
BEGIN
  IF v_role IS NULL OR v_role NOT IN ('administrativo', 'documentacao', 'financeiro', 'operacoes', 'equipamentos') THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;
  PERFORM public.portal_repair_missing_accounts();
  RETURN QUERY
  SELECT jsonb_build_object(
    'account_id', a.id,
    'customer_id', c.id,
    'customer_name', c.name,
    'cnpj_cpf', c.cnpj_cpf,
    'provisioning_decision', a.provisioning_decision,
    'account_situation', CASE WHEN a.account_situation = 'convite_pendente' AND pi.expires_at < now() THEN 'convite_expirado' ELSE a.account_situation END,
    'recovery_email', CASE WHEN v_full_access THEN a.recovery_email ELSE NULL END,
    'recovery_email_source', CASE WHEN v_full_access THEN a.recovery_email_source ELSE NULL END,
    'pending_invite_expires_at', pi.expires_at,
    'latest_delivery_status', CASE WHEN v_full_access THEN ea.status ELSE NULL END,
    'exception_reason', NULL,
    'last_event_at', ev.created_at,
    'has_critical_alert', EXISTS (
      SELECT 1 FROM public.alerts al
      LEFT JOIN public.alert_items ai ON ai.alert_id = al.id
      WHERE al.status <> 'closed'
        AND ((al.entity_type = 'customer' AND al.entity_id = c.id::text)
          OR (al.entity_type = 'bl' AND EXISTS (
            SELECT 1 FROM public.bls cb WHERE cb.id = al.entity_id AND cb.customer_id = c.id
          )))
        AND (al.type = 'aggregate' OR ai.severity = 'critical' OR al.type = 'portal_abuso_login')
    ),
    'has_open_invoice', EXISTS (SELECT 1 FROM public.invoices i WHERE i.customer_id = c.id AND i.status IN ('issued', 'overdue', 'partially_paid')),
    'has_active_process', EXISTS (SELECT 1 FROM public.bls b WHERE b.customer_id = c.id AND b.financial_status IS DISTINCT FROM 'cancelled'),
    'candidates', CASE WHEN v_full_access THEN COALESCE((SELECT jsonb_agg(jsonb_build_object('email', cc.email, 'purpose', cc.purpose, 'origin', 'Contato do Cliente') ORDER BY cc.id) FROM public.customer_contacts cc WHERE cc.customer_id = c.id AND cc.email IS NOT NULL AND cc.purpose IN ('geral', 'financeiro', 'operacional', 'faturamento')), '[]'::jsonb) ELSE '[]'::jsonb END,
    'recovery_email_status', CASE WHEN v_full_access THEN a.recovery_email_status ELSE NULL END, 'recovery_email_suppressed', CASE WHEN v_full_access AND a.recovery_email IS NOT NULL THEN EXISTS (SELECT 1 FROM public.portal_suppressed_emails s WHERE s.email = lower(a.recovery_email)) ELSE false END, 'shared_email_count', CASE WHEN v_full_access AND a.recovery_email IS NOT NULL THEN (SELECT count(*) FROM public.customer_portal_accounts other WHERE lower(other.recovery_email) = lower(a.recovery_email) AND other.id <> a.id) ELSE 0 END
  )
  FROM public.customer_portal_accounts a
  JOIN public.customers c ON c.id = a.customer_id
  LEFT JOIN LATERAL (SELECT expires_at FROM public.portal_invites WHERE account_id = a.id AND purpose = 'convite' AND status = 'pendente' ORDER BY created_at DESC LIMIT 1) pi ON true
  LEFT JOIN LATERAL (SELECT status FROM public.portal_email_attempts WHERE account_id = a.id ORDER BY created_at DESC LIMIT 1) ea ON true
  LEFT JOIN LATERAL (SELECT created_at FROM public.portal_provisioning_events WHERE customer_id = c.id ORDER BY created_at DESC LIMIT 1) ev ON true
  WHERE p_customer_id IS NULL OR c.id = p_customer_id
  ORDER BY c.name;
END;
$$;



--
-- Name: portal_list_provisioning_console_legacy(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_list_provisioning_console_legacy(p_customer_id bigint DEFAULT NULL::bigint) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT := public._portal_actor_role();
  v_full_access BOOLEAN := v_role IN ('administrativo','documentacao','financeiro');
BEGIN
  IF v_role IS NULL OR v_role NOT IN ('administrativo','documentacao','financeiro','operacoes') THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE='42501';
  END IF;

  PERFORM public.portal_repair_missing_accounts();

  RETURN QUERY
  SELECT jsonb_build_object(
    'account_id', a.id,
    'customer_id', c.id,
    'customer_name', c.name,
    'cnpj_cpf', c.cnpj_cpf,
    'provisioning_decision', a.provisioning_decision,
    'account_situation', CASE WHEN a.account_situation = 'convite_pendente' AND pi.expires_at < now() THEN 'convite_expirado' ELSE a.account_situation END,
    'recovery_email', CASE WHEN v_full_access THEN a.recovery_email ELSE NULL END,
    'recovery_email_source', CASE WHEN v_full_access THEN a.recovery_email_source ELSE NULL END,
    'pending_invite_expires_at', pi.expires_at,
    'latest_delivery_status', CASE WHEN v_full_access THEN ea.status ELSE NULL END,
    'exception_reason', CASE WHEN v_full_access THEN ex.reason ELSE NULL END,
    'last_event_at', ev.created_at,
    'has_critical_alert', EXISTS (
      SELECT 1 FROM public.alerts al
      WHERE al.status <> 'closed'
        AND al.type IN ('portal_excecao_critica_fatura','portal_convite_expirado','portal_falha_envio','portal_abuso_login')
        AND (
          (al.entity_type = 'customer' AND al.entity_id = c.id::text)
          OR (al.entity_type = 'invoice' AND EXISTS (
            SELECT 1 FROM public.invoices ai
            WHERE ai.customer_id = c.id
              AND (ai.invoice_number = al.entity_id
                   OR ai.id = CASE WHEN al.entity_id ~ '^[0-9]+$' THEN al.entity_id::bigint END)
          ))
        )
    ),
    'has_open_invoice', EXISTS (SELECT 1 FROM public.invoices i WHERE i.customer_id = c.id AND i.status IN ('issued','overdue')),
    'has_active_process', EXISTS (SELECT 1 FROM public.bls b WHERE b.customer_id = c.id AND b.financial_status IS DISTINCT FROM 'cancelled'),
    'candidates', CASE WHEN v_full_access THEN COALESCE((SELECT jsonb_agg(jsonb_build_object('email', cc.email, 'purpose', cc.purpose, 'origin', 'Contato do Cliente') ORDER BY cc.id) FROM public.customer_contacts cc WHERE cc.customer_id = c.id AND cc.email IS NOT NULL AND cc.purpose IN ('geral','financeiro','operacional','faturamento')), '[]'::jsonb) ELSE '[]'::jsonb END,
    'shared_email_count', CASE WHEN v_full_access AND a.recovery_email IS NOT NULL THEN (SELECT count(*) FROM public.customer_portal_accounts other WHERE lower(other.recovery_email) = lower(a.recovery_email) AND other.id <> a.id) ELSE 0 END
  )
  FROM public.customer_portal_accounts a
  JOIN public.customers c ON c.id = a.customer_id
  LEFT JOIN LATERAL (SELECT expires_at FROM public.portal_invites WHERE account_id = a.id AND purpose = 'convite' AND status = 'pendente' ORDER BY created_at DESC LIMIT 1) pi ON true
  LEFT JOIN LATERAL (SELECT status FROM public.portal_email_attempts WHERE account_id = a.id ORDER BY created_at DESC LIMIT 1) ea ON true
  LEFT JOIN LATERAL (SELECT reason, created_at FROM public.portal_provisioning_events WHERE customer_id = c.id ORDER BY created_at DESC LIMIT 1) ev ON true
  LEFT JOIN LATERAL (SELECT reason FROM public.portal_provisioning_events WHERE customer_id = c.id AND new_decision = 'provisionamento_nao_necessario' ORDER BY created_at DESC LIMIT 1) ex ON true
  WHERE p_customer_id IS NULL OR c.id = p_customer_id
  ORDER BY c.name;
END;
$_$;



