CREATE FUNCTION public.portal_list_provisioning_events(p_customer_id bigint, p_limit integer DEFAULT 10) RETURNS SETOF public.portal_provisioning_events
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
