--
-- Name: portal_login_check_rate_limit(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_login_check_rate_limit(p_login text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_hash TEXT; v_count INTEGER;
BEGIN
  v_hash := encode(extensions.digest(coalesce(public.normalize_cnpj(coalesce(p_login,'')),''),'sha256'),'hex');
  SELECT count(*) INTO v_count FROM public.portal_login_attempts WHERE cnpj_hash=v_hash AND attempted_at > now()-interval '15 minutes' AND succeeded=false AND source='login';
  RETURN coalesce(v_count,0) >= 5;
END; $$;



--
-- Name: portal_login_register_failure(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_login_register_failure(p_login text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.portal_login_attempts(cnpj_hash,succeeded,source)
  VALUES (encode(extensions.digest(coalesce(public.normalize_cnpj(coalesce(p_login,'')),''),'sha256'),'hex'),false,'login');
END; $$;



--
-- Name: portal_login_register_success(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_login_register_success(p_login text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.portal_login_attempts(cnpj_hash,succeeded)
  VALUES (encode(extensions.digest(coalesce(public.normalize_cnpj(coalesce(p_login,'')),''),'sha256'),'hex'),true);
END; $$;



--
-- Name: portal_mark_all_notifications_read(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_mark_all_notifications_read() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT := public.current_portal_customer_id();
BEGIN
  UPDATE public.portal_notifications AS n
  SET read_at = now()
  WHERE n.customer_id = v_customer_id
    AND n.read_at IS NULL;
END;
$$;



--
-- Name: portal_mark_expired_invites(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_mark_expired_invites() RETURNS TABLE(expired_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_count BIGINT:=0; r RECORD;
BEGIN
  FOR r IN SELECT i.id invite_id,i.account_id,a.customer_id,a.provisioning_decision,a.account_situation
    FROM public.portal_invites i JOIN public.customer_portal_accounts a ON a.id=i.account_id
    WHERE i.status='pendente' AND i.purpose='convite' AND i.expires_at<now() FOR UPDATE OF i
  LOOP
    UPDATE public.portal_invites SET status='expirado' WHERE id=r.invite_id;
    UPDATE public.customer_portal_accounts SET account_situation='convite_expirado' WHERE id=r.account_id AND account_situation='convite_pendente';
    PERFORM public._portal_log_event(r.customer_id,r.account_id,r.invite_id,r.provisioning_decision,r.provisioning_decision,r.account_situation,'convite_expirado','sistema','Convite expirado após 48 horas',NULL);
    INSERT INTO public.alerts(type,entity_type,entity_id,message,status)
    SELECT 'portal_convite_expirado','customer',r.customer_id::text,'Convite do Portal expirou sem ativação. Reenvio manual necessário.','open'
    WHERE NOT EXISTS (SELECT 1 FROM public.alerts al WHERE al.type='portal_convite_expirado' AND al.entity_type='customer' AND al.entity_id=r.customer_id::text AND al.status<>'closed');
    v_count:=v_count+1;
  END LOOP;
  RETURN QUERY SELECT v_count;
END; $$;



--
-- Name: portal_mark_notification_read(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_mark_notification_read(p_notification_id bigint) RETURNS void
