DECLARE
  v_customer_id BIGINT := public.current_portal_customer_id();
BEGIN
  UPDATE public.portal_notifications AS n
  SET read_at = now()
  WHERE n.id = p_notification_id
    AND n.customer_id = v_customer_id;
END;
$$;



