--
-- Name: portal_open_inspection(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_open_inspection(p_customer_id bigint, p_origin text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_origin TEXT := CASE WHEN p_origin IN ('provisionamento', 'ficha') THEN p_origin ELSE 'ficha' END;
  v_account RECORD;
  v_customer RECORD;
BEGIN
  PERFORM public._portal_inspect_guard(p_customer_id);

  INSERT INTO public.portal_inspection_events (inspector_id, customer_id, origin)
  SELECT auth.uid(), p_customer_id, v_origin
  WHERE NOT EXISTS (
    SELECT 1 FROM public.portal_inspection_events
    WHERE inspector_id = auth.uid()
      AND customer_id = p_customer_id
      AND created_at >= now() - interval '30 minutes'
  );

  SELECT a.id, a.customer_id, a.active, a.contact_email, a.login_cnpj
    INTO v_account
    FROM public.customer_portal_accounts a
   WHERE a.customer_id = p_customer_id;

  SELECT c.id, c.name, c.cnpj_cpf, c.pending_balance
    INTO v_customer
    FROM public.customers c
   WHERE c.id = p_customer_id;

  RETURN jsonb_build_object(
    'customer_id', v_customer.id,
    'customer_name', v_customer.name,
    'customer_cnpj_cpf', v_customer.cnpj_cpf,
    'cnpj_cpf', v_customer.cnpj_cpf,
    'pending_balance', v_customer.pending_balance,
    'contact_email', v_account.contact_email,
    'account_id', v_account.id,
    'account_active', COALESCE(v_account.active, false),
    'login_cnpj', v_account.login_cnpj
  );
END;
$$;



--
-- Name: portal_protect_customer_cnpj(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_protect_customer_cnpj() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.cnpj_cpf IS DISTINCT FROM OLD.cnpj_cpf AND current_setting('portal.allow_cnpj_change', true) IS DISTINCT FROM 'true' AND EXISTS (
    SELECT 1 FROM public.customer_portal_accounts a
    WHERE a.customer_id=OLD.id AND (a.account_situation <> 'sem_conta' OR EXISTS (
      SELECT 1 FROM public.portal_invites i WHERE i.account_id=a.id AND i.status='pendente'))
  ) THEN
    RAISE EXCEPTION 'CNPJ protegido: Cliente possui convite ou Conta de Portal. Use a alteração administrativa auditada.' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END; $$;



--
-- Name: portal_provisioning_backfill(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_provisioning_backfill(p_request_id text DEFAULT NULL::text) RETURNS TABLE(created_records bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_role TEXT := public._portal_actor_role(); v_created BIGINT;
BEGIN
  IF v_role IS DISTINCT FROM 'administrativo' THEN RAISE EXCEPTION 'permission denied' USING ERRCODE='42501'; END IF;
  WITH inserted AS (
    INSERT INTO public.customer_portal_accounts (customer_id, active, provisioning_decision, account_situation, login_cnpj)
    SELECT c.id, false, 'aguardando_analise', 'sem_conta', public.normalize_cnpj(c.cnpj_cpf)
    FROM public.customers c
    WHERE NOT EXISTS (SELECT 1 FROM public.customer_portal_accounts a WHERE a.customer_id = c.id)
    RETURNING id, customer_id
  )
  INSERT INTO public.portal_provisioning_events (customer_id, account_id, new_decision, new_situation, actor_type, actor_id, reason, request_id)
  SELECT customer_id, id, 'aguardando_analise', 'sem_conta', 'sistema', auth.uid(), 'Backfill inicial do Portal', p_request_id FROM inserted;
  GET DIAGNOSTICS v_created = ROW_COUNT;
  RETURN QUERY SELECT v_created;
END;
$$;



--
-- Name: portal_recovery_check_rate_limit(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_recovery_check_rate_limit(p_login text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_hash TEXT; v_count INTEGER;
BEGIN
  v_hash := encode(extensions.digest(coalesce(public.normalize_cnpj(coalesce(p_login,'')),''),'sha256'),'hex');
  SELECT count(*) INTO v_count FROM public.portal_login_attempts WHERE cnpj_hash=v_hash AND attempted_at > now()-interval '15 minutes' AND succeeded=false AND source='recovery';
  RETURN coalesce(v_count,0) >= 5;
END; $$;



--
-- Name: portal_recovery_register_failure(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_recovery_register_failure(p_login text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.portal_login_attempts(cnpj_hash,succeeded,source)
  VALUES (encode(extensions.digest(coalesce(public.normalize_cnpj(coalesce(p_login,'')),''),'sha256'),'hex'),false,'recovery');
END; $$;



--
-- Name: portal_refresh_general_pendencies(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_refresh_general_pendencies() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.alerts (type, entity_type, entity_id, message, status)
  SELECT DISTINCT 'portal_pendencia_geral', 'customer', c.id::text,
         'Cliente com processo ativo sem Portal ativo ou sem Email de Recuperação.',
         'open'
  FROM public.customers c
  JOIN public.bls b ON b.customer_id = c.id AND b.financial_status <> 'cancelled'
  LEFT JOIN public.customer_portal_accounts a ON a.customer_id = c.id
  WHERE (a.id IS NULL OR a.recovery_email IS NULL OR a.account_situation <> 'ativo')
    AND COALESCE(a.provisioning_decision, 'aguardando_analise') <> 'provisionamento_nao_necessario'
    AND NOT EXISTS (
      SELECT 1 FROM public.alerts al
      WHERE al.type = 'portal_pendencia_geral'
        AND al.entity_type = 'customer'
        AND al.entity_id = c.id::text
        AND al.status <> 'closed');

  UPDATE public.alerts al
  SET status = 'closed', closed_at = now()
  WHERE al.type = 'portal_pendencia_geral'
    AND al.status <> 'closed'
    AND EXISTS (
      SELECT 1 FROM public.customer_portal_accounts a
      WHERE a.customer_id = al.entity_id::bigint
        AND (a.account_situation = 'ativo'
             OR a.provisioning_decision = 'provisionamento_nao_necessario'));
END;
$$;



--
-- Name: portal_release_suppressed_email(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_release_suppressed_email(p_customer_id bigint, p_email text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := public._portal_actor_role();
  v_account public.customer_portal_accounts%ROWTYPE;
  v_email TEXT := lower(NULLIF(trim(coalesce(p_email,'')),''));
  v_removed INTEGER;
  v_compartilhada public.customer_portal_accounts%ROWTYPE;
BEGIN
  IF v_role IS NULL OR v_role NOT IN ('administrativo','documentacao') THEN RAISE EXCEPTION 'permission denied' USING ERRCODE='42501'; END IF;
  IF NULLIF(trim(coalesce(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'Justificativa é obrigatória.' USING ERRCODE='22023'; END IF;
  IF v_email IS NULL THEN RAISE EXCEPTION 'Email inválido.' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_account FROM public.customer_portal_accounts WHERE customer_id=p_customer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Registro de Portal não encontrado.' USING ERRCODE='P0002'; END IF;

  -- O endereço liberado tem de ser o que este Cliente usa. Sem isto, quem pode
  -- operar um Cliente qualquer poderia limpar o bloqueio de qualquer endereço
  -- do sistema, e o único rastro ficaria no histórico do Cliente escolhido para
  -- passar na guarda -- que não tem nada a ver com o endereço liberado.
  IF v_email IS DISTINCT FROM lower(v_account.recovery_email)
     AND v_email IS DISTINCT FROM lower(v_account.pending_recovery_email) THEN
    RAISE EXCEPTION 'Endereço não pertence a este Cliente.' USING ERRCODE='22023';
  END IF;

  DELETE FROM public.portal_suppressed_emails WHERE email = v_email;
  GET DIAGNOSTICS v_removed = ROW_COUNT;
  IF v_removed = 0 THEN RAISE EXCEPTION 'Endereço não está na lista de bloqueio.' USING ERRCODE='P0002'; END IF;

  -- O sinal de email quebrado (299) é consequência do bloqueio; liberar sem
  -- limpá-lo deixaria o console acusando falha num endereço que voltou a valer.
  UPDATE public.customer_portal_accounts SET recovery_email_status='ok'
  WHERE lower(recovery_email) = v_email AND recovery_email_status <> 'ok';

  PERFORM public._portal_log_event(
    p_customer_id, v_account.id, NULL,
    v_account.provisioning_decision, v_account.provisioning_decision,
    v_account.account_situation, v_account.account_situation,
    v_role,
    'Endereço ' || v_email || ' liberado da lista de bloqueio de emails. ' || trim(p_reason),
    NULL);

  -- Caixa compartilhada: a liberação já valeu para estes Clientes no DELETE
  -- acima. Registrar só no histórico de quem pediu deixaria os outros com o
  -- endereço reaberto e nenhuma linha explicando quando, por quem e por quê.
  -- `pending_recovery_email` conta junto: a guarda de propriedade acima aceita
  -- o endereço ainda não confirmado como sendo do Cliente, e quem espera a
  -- confirmação é exatamente quem o bloqueio estava impedindo de concluir.
  FOR v_compartilhada IN
    SELECT * FROM public.customer_portal_accounts
    WHERE (lower(recovery_email) = v_email OR lower(pending_recovery_email) = v_email)
      AND customer_id <> p_customer_id
  LOOP
    PERFORM public._portal_log_event(
      v_compartilhada.customer_id, v_compartilhada.id, NULL,
      v_compartilhada.provisioning_decision, v_compartilhada.provisioning_decision,
      v_compartilhada.account_situation, v_compartilhada.account_situation,
      v_role,
      'Endereço ' || v_email || ' liberado da lista de bloqueio de emails na liberação feita para o Cliente #'
        || p_customer_id || ' (caixa compartilhada). ' || trim(p_reason),
      NULL);
  END LOOP;
END; $$;



--
-- Name: portal_reopen_on_new_process(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_reopen_on_new_process() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_account public.customer_portal_accounts%ROWTYPE;
BEGIN
  IF NEW.customer_id IS NULL THEN RETURN NEW; END IF;
  SELECT * INTO v_account
  FROM public.customer_portal_accounts
  WHERE customer_id = NEW.customer_id
  FOR UPDATE;
  IF FOUND AND v_account.provisioning_decision <> 'aguardando_analise' THEN
    UPDATE public.customer_portal_accounts
    SET provisioning_decision = 'aguardando_analise'
    WHERE id = v_account.id;
    PERFORM public._portal_log_event(
      NEW.customer_id, v_account.id, NULL,
      v_account.provisioning_decision, 'aguardando_analise',
      v_account.account_situation, v_account.account_situation,
      'sistema', 'Novo processo ativo reabriu a análise do Portal.', NULL
    );
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: portal_repair_missing_accounts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_repair_missing_accounts() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_created BIGINT;
BEGIN
  WITH inserted AS (
    INSERT INTO public.customer_portal_accounts (customer_id, active, provisioning_decision, account_situation, login_cnpj)
    SELECT c.id, false, 'aguardando_analise', 'sem_conta', public.normalize_cnpj(c.cnpj_cpf)
    FROM public.customers AS c
    WHERE NOT EXISTS (SELECT 1 FROM public.customer_portal_accounts AS a WHERE a.customer_id = c.id)
    ON CONFLICT (customer_id) DO NOTHING
    RETURNING id, customer_id
  )
  INSERT INTO public.portal_provisioning_events (
    customer_id, account_id, previous_decision, new_decision,
    previous_situation, new_situation, actor_type, actor_id, reason, request_id
  )
  SELECT customer_id, id, NULL, 'aguardando_analise', NULL, 'sem_conta',
    'sistema', NULL, 'Reparo automático da fila do Portal durante a leitura.', NULL
  FROM inserted;
  GET DIAGNOSTICS v_created = ROW_COUNT;
  RETURN v_created;
END;
$$;



--
-- Name: portal_request_dispute_reopen(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_request_dispute_reopen(p_dispute_id bigint, p_body text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT := public.current_portal_customer_id();
  v_dispute public.demurrage_disputes%ROWTYPE;
BEGIN
  IF NULLIF(btrim(p_body), '') IS NULL THEN RAISE EXCEPTION 'Justificativa é obrigatória.' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_dispute FROM public.demurrage_disputes WHERE id = p_dispute_id AND customer_id = v_customer_id;
  IF NOT FOUND OR v_dispute.state <> 'resolvida' THEN RAISE EXCEPTION 'Dispute não está disponível para solicitação de reabertura.' USING ERRCODE = '22023'; END IF;
  INSERT INTO public.demurrage_dispute_messages(dispute_id, author_id, author_type, body, next_responder, metadata)
  VALUES (p_dispute_id, auth.uid(), 'cliente', btrim(p_body), 'equipamentos', jsonb_build_object('action', 'reopen_request'));
  PERFORM public.block521_upsert_alert('portal_dispute_opened', 'demurrage_invoice', v_dispute.demurrage_invoice_id::text, 'Cliente solicitou reabertura de uma Dispute; decisão de Equipamentos pendente.', 'portal_dispute_reopen_request', 'equipamentos', jsonb_build_object('dispute_id', p_dispute_id), '/demurrage?dispute=' || p_dispute_id);
END;
$$;



--
-- Name: portal_resolve_login(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_resolve_login(p_login text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_trimmed TEXT := lower(trim(COALESCE(p_login, '')));
  v_digits TEXT := regexp_replace(trim(COALESCE(p_login, '')), '\D', '', 'g');
  v_lookup_key TEXT;
  v_login_hash TEXT;
  v_cutoff TIMESTAMPTZ := now() - INTERVAL '10 minutes';
  v_count INT;
  v_email TEXT;
BEGIN
  IF v_trimmed = '' THEN
    RAISE EXCEPTION 'Credenciais invalidas para o portal do cliente.' USING ERRCODE = '28000';
  END IF;

  IF position('@' IN v_trimmed) > 0 THEN
    v_lookup_key := 'email:' || v_trimmed;
  ELSIF length(v_digits) IN (11, 14) THEN
    v_lookup_key := 'doc:' || v_digits;
  ELSE
    v_lookup_key := 'raw:' || v_trimmed;
  END IF;

  v_login_hash := encode(extensions.digest(v_lookup_key, 'sha256'), 'hex');

  DELETE FROM public.portal_login_resolution_attempts
  WHERE attempted_at < v_cutoff;

  SELECT COUNT(*) INTO v_count
  FROM public.portal_login_resolution_attempts
  WHERE login_hash = v_login_hash
    AND attempted_at >= v_cutoff;

  IF v_count >= 8 THEN
    RAISE EXCEPTION 'Muitas tentativas de acesso. Aguarde alguns minutos antes de tentar novamente.'
      USING ERRCODE = 'P0429';
  END IF;

  INSERT INTO public.portal_login_resolution_attempts (login_hash)
  VALUES (v_login_hash);

  IF position('@' IN v_trimmed) > 0 THEN
    SELECT a.portal_email INTO v_email
    FROM public.customer_portal_accounts AS a
    WHERE a.portal_email = v_trimmed
      AND a.active = true;
  ELSIF length(v_digits) IN (11, 14) THEN
    SELECT a.portal_email INTO v_email
    FROM public.customer_portal_accounts AS a
    WHERE a.login_cnpj = v_digits
      AND a.active = true;
  ELSE
    SELECT a.portal_email INTO v_email
    FROM public.customer_portal_accounts AS a
    WHERE a.portal_email = v_trimmed
      AND a.active = true;
  END IF;

  IF v_email IS NULL THEN
    RAISE EXCEPTION 'Credenciais invalidas para o portal do cliente.' USING ERRCODE = '28000';
  END IF;

  RETURN v_email;
END;
$$;



--
-- Name: portal_return_to_analysis(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_return_to_analysis(p_customer_id bigint, p_reason text, p_actor_type text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_role TEXT := public._portal_actor_role(); v_actor TEXT := CASE WHEN auth.role() = 'service_role' THEN 'sistema' ELSE v_role END; v_account public.customer_portal_accounts%ROWTYPE;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND (v_role IS NULL OR v_role NOT IN ('administrativo','documentacao')) THEN RAISE EXCEPTION 'permission denied' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_account FROM public.customer_portal_accounts WHERE customer_id=p_customer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Registro de Portal não encontrado para o Cliente.' USING ERRCODE='P0002'; END IF;
  IF v_account.provisioning_decision='aguardando_analise' THEN RETURN; END IF;
  UPDATE public.customer_portal_accounts SET provisioning_decision='aguardando_analise' WHERE id=v_account.id;
  PERFORM public._portal_log_event(p_customer_id,v_account.id,NULL,v_account.provisioning_decision,'aguardando_analise',v_account.account_situation,v_account.account_situation,v_actor,p_reason,p_request_id);
END; $$;



--
-- Name: portal_revoke_sessions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_revoke_sessions(p_user_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  DELETE FROM auth.refresh_tokens WHERE user_id = p_user_id::text;
  DELETE FROM auth.sessions WHERE user_id = p_user_id;
  UPDATE public.customer_portal_accounts SET credentials_revoked_at = now() WHERE auth_user_id = p_user_id;
END; $$;



--
-- Name: portal_set_exception(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_set_exception(p_customer_id bigint, p_reason text, p_request_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RAISE EXCEPTION 'A decisão de provisionamento não necessário foi removida; use Aguardando análise.' USING ERRCODE = '22023';
END;
$$;



--
-- Name: portal_ship_schedule(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_ship_schedule() RETURNS TABLE(voyage_id bigint, vessel_name text, voyage text, imo_number text, port_code text, kind text, date_value text, actual_value text, omitted boolean)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH visible AS (
    SELECT v.id, ve.name AS vessel_name, v.voyage_number, ve.imo
    FROM public.voyages v
    JOIN public.vessels ve ON ve.id = v.vessel_id
    WHERE v.show_on_portal AND v.status = 'active'
  ),
  latest AS (
    SELECT DISTINCT ON (a.entity_type, a.entity_id, a.field_name)
      a.entity_type, a.entity_id, a.field_name, a.new_value
    FROM public.audit_logs a
    WHERE a.entity_type IN ('voyage_pol_schedule', 'voyage_pod_schedule')
    ORDER BY a.entity_type, a.entity_id, a.field_name, a.changed_at DESC
  ),
  deleted_pods AS (
    SELECT entity_id FROM latest
    WHERE entity_type = 'voyage_pod_schedule'
      AND field_name = 'deleted' AND new_value = 'true'
  ),
  omitted_pods AS (
    SELECT entity_id FROM latest
    WHERE entity_type = 'voyage_pod_schedule'
      AND field_name = 'omitted' AND new_value = 'true'
  ),
  pol AS (
    SELECT split_part(entity_id, '::', 1)::bigint AS vid,
           split_part(entity_id, '::', 2) AS port_code,
           new_value AS etd
    FROM latest
    WHERE entity_type = 'voyage_pol_schedule'
      AND field_name = 'etd' AND new_value IS NOT NULL
  ),
  pol_atd AS (
    SELECT split_part(entity_id, '::', 1)::bigint AS vid,
           split_part(entity_id, '::', 2) AS port_code,
           new_value AS atd
    FROM latest
    WHERE entity_type = 'voyage_pol_schedule'
      AND field_name = 'atd' AND new_value IS NOT NULL
  ),
  pod AS (
    SELECT split_part(l.entity_id, '::', 1)::bigint AS vid,
           split_part(l.entity_id, '::', 2) AS port_code,
           MAX(l.new_value) FILTER (WHERE l.field_name = 'eta') AS eta,
           (o.entity_id IS NOT NULL) AS omitted
    FROM latest l
    LEFT JOIN deleted_pods d ON d.entity_id = l.entity_id
    LEFT JOIN omitted_pods o ON o.entity_id = l.entity_id
    WHERE l.entity_type = 'voyage_pod_schedule'
      AND d.entity_id IS NULL
      AND (
        (l.field_name = 'eta' AND l.new_value IS NOT NULL)
        OR o.entity_id IS NOT NULL
      )
    GROUP BY l.entity_id, o.entity_id
  ),
  pod_ata AS (
    SELECT split_part(l.entity_id, '::', 1)::bigint AS vid,
           split_part(l.entity_id, '::', 2) AS port_code,
           l.new_value AS ata
    FROM latest l
    LEFT JOIN deleted_pods d ON d.entity_id = l.entity_id
    WHERE l.entity_type = 'voyage_pod_schedule'
      AND l.field_name = 'ata'
      AND l.new_value IS NOT NULL
      AND d.entity_id IS NULL
  )
  SELECT visible.id, visible.vessel_name, visible.voyage_number, visible.imo,
         pol.port_code, 'pol', pol.etd, pol_atd.atd, false
  FROM visible
  JOIN pol ON pol.vid = visible.id
  LEFT JOIN pol_atd ON pol_atd.vid = pol.vid AND pol_atd.port_code = pol.port_code
  UNION ALL
  SELECT visible.id, visible.vessel_name, visible.voyage_number, visible.imo,
         pod.port_code, 'pod', pod.eta, pod_ata.ata, pod.omitted
  FROM visible
  JOIN pod ON pod.vid = visible.id
  LEFT JOIN pod_ata ON pod_ata.vid = pod.vid AND pod_ata.port_code = pod.port_code;
$$;



--
-- Name: portal_sync_login_cnpj(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_sync_login_cnpj() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE public.customer_portal_accounts
  SET login_cnpj = public.normalize_cnpj(NEW.cnpj_cpf)
  WHERE customer_id = NEW.id
    AND login_cnpj IS DISTINCT FROM public.normalize_cnpj(NEW.cnpj_cpf);
  RETURN NEW;
END;
$$;



--
-- Name: portal_update_profile(text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.portal_update_profile(p_contact_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_address text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_zip text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT := public.current_portal_customer_id();
BEGIN
  -- Atualiza email de contato na conta de portal
  IF p_contact_email IS NOT NULL THEN
    UPDATE public.customer_portal_accounts
    SET contact_email = NULLIF(trim(p_contact_email), ''),
        updated_at = now()
    WHERE customer_id = v_customer_id;
  END IF;

  -- Atualiza endereco no cadastro do cliente
  UPDATE public.customers
  SET
    address = COALESCE(NULLIF(trim(COALESCE(p_address, '')), ''), address),
    city = COALESCE(NULLIF(trim(COALESCE(p_city, '')), ''), city),
    state = COALESCE(NULLIF(trim(COALESCE(p_state, '')), ''), state),
    zip = COALESCE(NULLIF(trim(COALESCE(p_zip, '')), ''), zip),
    updated_at = now()
  WHERE id = v_customer_id;

  -- Telefone: atualiza o contato de faturamento se existir, senao cria.
  IF p_phone IS NOT NULL AND trim(p_phone) <> '' THEN
    IF EXISTS (
      SELECT 1 FROM public.customer_contacts
      WHERE customer_id = v_customer_id AND purpose = 'faturamento'
    ) THEN
      UPDATE public.customer_contacts
      SET phone = NULLIF(trim(p_phone), '')
      WHERE customer_id = v_customer_id
        AND purpose = 'faturamento';
    ELSE
      INSERT INTO public.customer_contacts (customer_id, name, email, phone, purpose, is_primary)
      VALUES (v_customer_id, 'Contato principal', NULL, NULLIF(trim(p_phone), ''), 'faturamento', true);
    END IF;
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;



--
-- Name: preflight_depots_terminal_port_mapping(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preflight_depots_terminal_port_mapping() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_read_user() THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;

  RETURN jsonb_build_object(
    'pending_count', (
      SELECT count(*)
      FROM public.depots AS d
      WHERE d.tipo = 'terminal_portuario' AND d.port_id IS NULL
    ),
    'codes', COALESCE((
      SELECT jsonb_agg(d.code ORDER BY d.code)
      FROM public.depots AS d
      WHERE d.tipo = 'terminal_portuario' AND d.port_id IS NULL
    ), '[]'::JSONB)
  );
END;
$$;



--
-- Name: prevent_duplicate_active_invoice_bl_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_duplicate_active_invoice_bl_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.invoices inv
    WHERE inv.id = NEW.invoice_id
      AND COALESCE(inv.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue', 'paid')
  ) AND EXISTS (
    SELECT 1
    FROM public.invoice_bls ib
    JOIN public.invoices inv ON inv.id = ib.invoice_id
    WHERE ib.bl_id = NEW.bl_id
      AND ib.id IS DISTINCT FROM NEW.id
      AND COALESCE(inv.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue', 'paid')
  ) THEN
    RAISE EXCEPTION 'PT409: B/L ja vinculado a uma invoice ativa.' USING ERRCODE = '23505';
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: prevent_duplicate_active_invoice_granite_bl_link(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_duplicate_active_invoice_granite_bl_link() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM public.invoices inv
    WHERE inv.id = NEW.invoice_id
      AND COALESCE(inv.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue', 'paid')
  ) AND EXISTS (
    SELECT 1
    FROM public.invoice_granite_bls igb
    JOIN public.invoices inv ON inv.id = igb.invoice_id
    WHERE igb.granite_bl_id = NEW.granite_bl_id
      AND igb.id IS DISTINCT FROM NEW.id
      AND COALESCE(inv.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue', 'paid')
  ) THEN
    RAISE EXCEPTION 'PT409: B/L Granito ja vinculado a uma invoice ativa.' USING ERRCODE = '23505';
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: prevent_pending_review_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_pending_review_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_review_reasons TEXT[];
BEGIN
  IF NEW.financial_status = 'invoiced' THEN
    v_review_reasons := public.compute_bl_review_pendencies(
      NEW.customer_id,
      NEW.cargo_mode,
      NEW.bb_weight_ton
    );

    IF NEW.review_status = 'pending_review'
       OR COALESCE(cardinality(v_review_reasons), 0) > 0 THEN
      RAISE EXCEPTION
        'B/L em revisao manual nao pode ser faturado: %',
        COALESCE(array_to_string(v_review_reasons, ', '), 'revisao pendente')
        USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: prevent_user_profile_privilege_escalation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_user_profile_privilege_escalation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- service_role / contexto sem usuário autenticado (Edge Functions, jobs):
  -- não há sessão de usuário, RLS já não se aplica — liberar.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  -- Mudanças em campos sensíveis (role, active) só por admin.
  IF (NEW.role IS DISTINCT FROM OLD.role
      OR NEW.active IS DISTINCT FROM OLD.active)
     AND NOT public.is_admin() THEN
    RAISE EXCEPTION 'Apenas administradores podem alterar role ou active de um perfil.'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: propagate_voyage_ata_to_containers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.propagate_voyage_ata_to_containers() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  WITH candidates AS (
    SELECT c.id, c.discharge_date AS old_discharge
    FROM public.bl_containers AS c
    JOIN public.bls AS b ON b.id = c.bl_id
    WHERE b.voyage_id = NEW.id
      AND (c.discharge_date IS NULL OR c.discharge_date = OLD.ata::date)
    FOR UPDATE OF c
  ),
  updated AS (
    UPDATE public.bl_containers AS c
    SET discharge_date = NEW.ata::date
    FROM candidates AS candidate
    WHERE c.id = candidate.id
      AND candidate.old_discharge IS DISTINCT FROM NEW.ata::date
    RETURNING c.id, candidate.old_discharge
  )
  INSERT INTO public.audit_logs (
    entity_type,
    entity_id,
    field_name,
    old_value,
    new_value,
    changed_by,
    changed_at,
    justification
  )
  SELECT
    'bl_container',
    updated.id::TEXT,
    'discharge_date',
    updated.old_discharge::TEXT,
    NEW.ata::date::TEXT,
    auth.uid(),
    now(),
    'Data de descarga sincronizada apos correcao da ATA da viagem.'
  FROM updated;

  RETURN NEW;
END;
$$;



--
-- Name: recalculate_demurrage_invoices(numeric, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_demurrage_invoices(p_ptax numeric, p_quote_date date, p_source text DEFAULT 'bcb_live'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_roe NUMERIC; v_updated INT := 0; v_inv RECORD;
  v_total_brl NUMERIC(14,2); v_pix_payload TEXT; v_discount_usd NUMERIC(12,2);
BEGIN
  IF p_ptax IS NULL OR p_ptax <= 0 OR p_quote_date IS NULL THEN
    RAISE EXCEPTION 'PTAX e data de cotacao sao obrigatorias.' USING ERRCODE = '22023';
  END IF;
  IF p_source NOT IN ('bcb_live', 'cached', 'manual') THEN
    RAISE EXCEPTION 'Origem de PTAX invalida: %.', p_source USING ERRCODE = '22023';
  END IF;

  v_roe := ROUND(p_ptax * 1.065, 4);

  FOR v_inv IN
    SELECT id, total_usd, COALESCE(discount_value, 0) AS discount_value,
           discount_mode, doc_number, current_roe
    FROM public.demurrage_invoices
    WHERE status = 'issued' AND paid_at IS NULL
    FOR UPDATE
  LOOP
    -- Só recalcula quando a PTAX (roe) realmente mudou.
    CONTINUE WHEN v_inv.current_roe IS NOT NULL AND v_inv.current_roe = v_roe;

    v_discount_usd := 0;
    IF v_inv.discount_value > 0 THEN
      IF v_inv.discount_mode = 'percent'
        THEN v_discount_usd := ROUND(v_inv.total_usd * (v_inv.discount_value / 100), 2);
        ELSE v_discount_usd := v_inv.discount_value;   -- fixo em USD
      END IF;
    END IF;

    v_total_brl   := ROUND((v_inv.total_usd - v_discount_usd) * v_roe, 2);
    v_pix_payload := public.build_transshipping_pix_payload(v_total_brl, v_inv.doc_number);

    UPDATE public.demurrage_invoices
    SET current_roe = v_roe, current_total_brl = v_total_brl,
        roe_source = p_source, pix_payload = v_pix_payload, updated_at = now()
    WHERE id = v_inv.id;

    INSERT INTO public.demurrage_invoice_history
      (invoice_id, event_date, ptax_used, roe_used, total_usd, total_brl, discount_usd, source)
    VALUES
      (v_inv.id, p_quote_date, p_ptax, v_roe, v_inv.total_usd, v_total_brl, v_discount_usd, p_source);

    v_updated := v_updated + 1;
  END LOOP;

  RETURN jsonb_build_object('updated', v_updated, 'roe', v_roe, 'quote_date', p_quote_date);
END;
$$;



--
-- Name: recalculate_demurrage_invoices_manual(numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_demurrage_invoices_manual(p_ptax numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;
  RETURN public.recalculate_demurrage_invoices(p_ptax, CURRENT_DATE, 'manual');
END;
$$;



--
-- Name: recompute_bl_review_status(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_bl_review_status(p_bl_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_bl public.bls%ROWTYPE;
  v_reasons TEXT[];
  v_status TEXT;
  v_human_notes TEXT;
  v_notes TEXT;
BEGIN
  SELECT * INTO v_bl FROM public.bls WHERE id = p_bl_id;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  -- O gate trava a emissão; não desfaz o que já foi emitido.
  IF COALESCE(v_bl.financial_status, '') IN ('invoiced', 'partially_paid', 'paid') THEN
    RETURN v_bl.review_status;
  END IF;

  -- Só os dois estados que o gate governa; qualquer outro fica fora do alcance.
  IF COALESCE(v_bl.review_status, '') NOT IN ('pending_review', 'reviewed') THEN
    RETURN v_bl.review_status;
  END IF;

  v_reasons := public.compute_bl_review_pendencies(p_bl_id);
  v_status := CASE
    WHEN COALESCE(cardinality(v_reasons), 0) = 0 THEN 'reviewed'
    ELSE 'pending_review'
  END;

  v_human_notes := btrim(
    regexp_replace(
      COALESCE(v_bl.notes, ''),
      E'(^|\\n)Pendencias de importacao:[^\\n]*$',
      '',
      'i'
    )
  );

  v_notes := CASE
    WHEN COALESCE(cardinality(v_reasons), 0) > 0 THEN concat_ws(
      E'\n',
      NULLIF(v_human_notes, ''),
      'Pendencias de importacao: ' || array_to_string(v_reasons, ', ')
    )
    ELSE NULLIF(v_human_notes, '')
  END;

  -- Sem mudança não se escreve: evita `updated_at` novo (e o conflito de edição
  -- concorrente na Revisão) a cada passagem do trigger.
  IF v_bl.review_status IS DISTINCT FROM v_status OR v_bl.notes IS DISTINCT FROM v_notes THEN
    UPDATE public.bls SET review_status = v_status, notes = v_notes WHERE id = p_bl_id;
  END IF;

  RETURN v_status;
END;
$_$;



--
-- Name: reconcile_agency_report_alerts(uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_agency_report_alerts(p_report_id uuid, p_pending boolean DEFAULT true, p_deadline boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_report RECORD;
  v_atd DATE;
  v_atd_updated_at TIMESTAMPTZ;
  v_deadline DATE;
  v_deadline_baseline DATE;
  v_pending_baseline TIMESTAMPTZ := TIMESTAMPTZ '2026-07-19 00:00:00+00';
  v_pending_eligible BOOLEAN := false;
  v_deadline_eligible BOOLEAN := false;
  v_omitted BOOLEAN := false;
  v_deleted BOOLEAN := false;
  v_entity_id TEXT;
  v_department TEXT;
  v_pending BOOLEAN;
  v_signed BOOLEAN;
  v_deadline_missed BOOLEAN;
  v_metadata JSONB;
  v_message TEXT;
  v_upsert_result JSONB;
  v_changed INTEGER := 0;
  v_created INTEGER := 0;
BEGIN
  IF NOT public.alert_actor_is_authorized() THEN RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501'; END IF;

  SELECT r.*, d.code AS terminal_code INTO v_report
  FROM public.agency_departure_reports r
  LEFT JOIN public.depots d ON d.id = r.terminal_id
  WHERE r.id = p_report_id FOR UPDATE OF r;
  IF NOT FOUND THEN RETURN jsonb_build_object('report_id', p_report_id, 'eligible', false, 'changed', 0); END IF;

  SELECT terminal_atd::date, updated_at INTO v_atd, v_atd_updated_at
  FROM public.voyage_escala_terminal_state
  WHERE voyage_id = v_report.voyage_id AND port = upper(btrim(v_report.port)) AND terminal_id = v_report.terminal_id;

  SELECT COALESCE((SELECT a.new_value = 'true' FROM public.audit_logs a WHERE a.entity_type = 'voyage_pod_schedule' AND a.entity_id = v_report.voyage_id || '::' || upper(btrim(v_report.port)) AND a.field_name = 'omitted' ORDER BY a.changed_at DESC, a.id DESC LIMIT 1), false) INTO v_omitted;
  SELECT COALESCE((SELECT a.new_value = 'true' FROM public.audit_logs a WHERE a.entity_type = 'voyage_pod_schedule' AND a.entity_id = v_report.voyage_id || '::' || upper(btrim(v_report.port)) AND a.field_name = 'deleted' ORDER BY a.changed_at DESC, a.id DESC LIMIT 1), false) INTO v_deleted;
  SELECT captured_at::date INTO v_deadline_baseline FROM public.agency_report_pending_baselines WHERE baseline_key = 'agency_report_deadline_missed';

  v_pending_eligible := v_report.status = 'open' AND v_report.terminal_id IS NOT NULL AND v_atd IS NOT NULL AND v_atd_updated_at >= v_pending_baseline AND NOT v_omitted AND NOT v_deleted AND upper(btrim(v_report.port)) LIKE 'BR%';
  v_deadline_eligible := v_report.status = 'open' AND v_report.terminal_id IS NOT NULL AND v_atd IS NOT NULL AND NOT v_omitted AND NOT v_deleted AND upper(btrim(v_report.port)) LIKE 'BR%' AND (v_deadline_baseline IS NULL OR v_atd >= v_deadline_baseline);
  v_entity_id := public.agency_report_alert_entity_key(v_report.voyage_id, v_report.port, v_report.terminal_code);
  v_deadline := CASE WHEN v_atd IS NULL THEN NULL ELSE public.agency_report_deadline_date(v_atd) END;

  FOR v_department IN SELECT unnest(ARRAY['operacoes', 'documentacao', 'equipamentos']) LOOP
    v_metadata := jsonb_build_object('report_id', v_report.id, 'voyage_id', v_report.voyage_id, 'port', upper(btrim(v_report.port)), 'terminal_code', v_report.terminal_code, 'department', v_department, 'deadline_date', v_deadline);
    IF p_pending THEN
      SELECT EXISTS (
        SELECT 1 FROM (VALUES ('datas'), ('carga_descarregada'), ('carga_carregada'), ('veiculos'), ('vazios_embarcados'), ('vazios_descarregados')) AS sections(section)
        LEFT JOIN public.agency_departure_report_signoffs so ON so.report_id = v_report.id AND so.section = sections.section
        WHERE public.agency_report_section_owner(sections.section) = v_department AND COALESCE(so.state, 'pending') = 'pending'
      ) INTO v_pending;
      v_message := 'ADR ' || upper(btrim(v_report.port)) || ' / ' || COALESCE(v_report.terminal_code, 'terminal') || ': departamento "' || public.agency_report_department_label(v_department) || '" pendente.';
      IF v_pending_eligible AND v_pending THEN
        v_upsert_result := public.upsert_alert_item('agency_report_department_pending', 'agency_departure_report', v_entity_id, v_message, 'agency_report_reconcile', v_department, v_metadata, '/viagens');
        IF COALESCE((v_upsert_result->>'created')::boolean, false) OR COALESCE((v_upsert_result->>'reopened')::boolean, false) THEN v_changed := v_changed + 1; v_created := v_created + 1; END IF;
      ELSE
        IF public.resolve_alert_item_for_department('agency_report_department_pending', 'agency_departure_report', v_entity_id, v_department, 'agency_report_reconcile', v_metadata) THEN v_changed := v_changed + 1; END IF;
      END IF;
    END IF;
    IF p_deadline THEN
      SELECT COALESCE((SELECT signed_at IS NOT NULL FROM public.agency_departure_report_department_signoffs ds WHERE ds.report_id = v_report.id AND ds.department = v_department), false) INTO v_signed;
      v_deadline_missed := v_deadline_eligible AND v_deadline < CURRENT_DATE AND NOT v_signed;
      v_message := 'ADR ' || upper(btrim(v_report.port)) || ' / ' || COALESCE(v_report.terminal_code, 'terminal') || ': prazo de conclusão vencido para "' || public.agency_report_department_label(v_department) || '".';
      IF v_deadline_missed THEN
        v_upsert_result := public.upsert_alert_item('agency_report_deadline_missed', 'agency_departure_report', v_entity_id, v_message, 'agency_report_reconcile', v_department, v_metadata, '/viagens');
        IF COALESCE((v_upsert_result->>'created')::boolean, false) OR COALESCE((v_upsert_result->>'reopened')::boolean, false) THEN v_changed := v_changed + 1; v_created := v_created + 1; END IF;
      ELSE
        IF public.resolve_alert_item_for_department('agency_report_deadline_missed', 'agency_departure_report', v_entity_id, v_department, 'agency_report_reconcile', v_metadata) THEN v_changed := v_changed + 1; END IF;
      END IF;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('report_id', v_report.id, 'entity_id', v_entity_id, 'eligible', v_deadline_eligible, 'pending_eligible', v_pending_eligible, 'atd', v_atd, 'deadline_date', v_deadline, 'changed', v_changed, 'created', v_created);
END;
$$;



--
-- Name: FUNCTION reconcile_agency_report_alerts(p_report_id uuid, p_pending boolean, p_deadline boolean); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.reconcile_agency_report_alerts(p_report_id uuid, p_pending boolean, p_deadline boolean) IS 'Reconcilia os itens coletivos de pendência e prazo do ADR a partir da origem autoritativa.';



--
-- Name: reconcile_agency_report_alerts_for_scale(bigint, text, date, boolean, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_agency_report_alerts_for_scale(p_voyage_id bigint, p_port text, p_atd date, p_pending_eligible boolean, p_deadline_eligible boolean, p_omitted boolean DEFAULT false, p_deleted boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_department TEXT;
  v_pending BOOLEAN;
  v_deadline_missed BOOLEAN;
  v_deadline DATE := public.agency_report_deadline_date(p_atd);
  v_entity_id TEXT := public.agency_report_alert_entity_key(p_voyage_id, p_port);
  v_metadata JSONB;
  v_message TEXT;
  v_upsert_result JSONB;
  v_changed INTEGER := 0;
  v_created INTEGER := 0;
BEGIN
  IF NOT public.alert_actor_is_authorized() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;
  IF upper(btrim(p_port)) NOT LIKE 'BR%' THEN
    RETURN jsonb_build_object('entity_id', v_entity_id, 'created', 0, 'changed', 0);
  END IF;

  FOR v_department IN SELECT unnest(ARRAY['operacoes', 'documentacao', 'equipamentos'])
  LOOP
    v_metadata := jsonb_build_object(
      'report_id', NULL,
      'voyage_id', p_voyage_id,
      'port', upper(btrim(p_port)),
      'terminal_code', NULL,
      'department', v_department,
      'deadline_date', v_deadline
    );
    v_message := 'ADR ' || upper(btrim(p_port))
      || ': departamento "' || public.agency_report_department_label(v_department) || '" pendente.';
    v_pending := p_pending_eligible AND NOT p_omitted AND NOT p_deleted;
    IF v_pending THEN
      v_upsert_result := public.upsert_alert_item(
        'agency_report_department_pending', 'agency_departure_report', v_entity_id,
        v_message, 'agency_report_reconcile', v_department, v_metadata, '/viagens'
      );
      IF COALESCE((v_upsert_result->>'created')::BOOLEAN, false)
         OR COALESCE((v_upsert_result->>'reopened')::BOOLEAN, false) THEN
        v_changed := v_changed + 1;
        v_created := v_created + 1;
      END IF;
    ELSE
      IF public.resolve_alert_item_for_department(
        'agency_report_department_pending', 'agency_departure_report', v_entity_id,
        v_department, 'agency_report_reconcile', v_metadata
      ) THEN
        v_changed := v_changed + 1;
      END IF;
    END IF;

    v_deadline_missed := p_deadline_eligible AND NOT p_omitted AND NOT p_deleted
      AND v_deadline < CURRENT_DATE;
    v_message := 'ADR ' || upper(btrim(p_port))
      || ': prazo de conclusão vencido para "' || public.agency_report_department_label(v_department) || '".';
    IF v_deadline_missed THEN
      v_upsert_result := public.upsert_alert_item(
        'agency_report_deadline_missed', 'agency_departure_report', v_entity_id,
        v_message, 'agency_report_reconcile', v_department, v_metadata, '/viagens'
      );
      IF COALESCE((v_upsert_result->>'created')::BOOLEAN, false)
         OR COALESCE((v_upsert_result->>'reopened')::BOOLEAN, false) THEN
        v_changed := v_changed + 1;
        v_created := v_created + 1;
      END IF;
    ELSE
      IF public.resolve_alert_item_for_department(
        'agency_report_deadline_missed', 'agency_departure_report', v_entity_id,
        v_department, 'agency_report_reconcile', v_metadata
      ) THEN
        v_changed := v_changed + 1;
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('entity_id', v_entity_id, 'created', v_created, 'changed', v_changed);
END;
$$;



--
-- Name: reconcile_agency_report_alerts_on_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_agency_report_alerts_on_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_report RECORD;
  v_report_id UUID;
  v_section_department TEXT;
  v_section TEXT;
  v_voyage_id BIGINT;
  v_port TEXT;
BEGIN
  IF NEW.entity_type IN ('voyage_pod_schedule', 'voyage_pol_schedule')
     AND NEW.field_name IN ('atd', 'omitted', 'deleted', 'terminal_dates', 'terminal_state_removed', 'terminal_assignment') THEN
    IF NEW.entity_id !~ '^[0-9]+::[^:]+$' THEN
      RETURN NEW;
    END IF;
    v_voyage_id := split_part(NEW.entity_id, '::', 1)::BIGINT;
    v_port := upper(btrim(split_part(NEW.entity_id, '::', 2)));
    FOR v_report IN
      SELECT id FROM public.agency_departure_reports
      WHERE voyage_id = v_voyage_id AND port = v_port
    LOOP
      PERFORM public.reconcile_agency_report_alerts(v_report.id, TRUE, TRUE);
    END LOOP;
  ELSIF NEW.entity_type IN ('agency_departure_report_signoff', 'agency_departure_report_department_signoff') THEN
    IF NEW.entity_id ~ '^[0-9a-fA-F-]{36}::' THEN
      v_report_id := split_part(NEW.entity_id, '::', 1)::UUID;
    ELSIF NEW.entity_id ~ '^[0-9]+::[^:]+(::[^:]+)?$' THEN
      v_voyage_id := split_part(NEW.entity_id, '::', 1)::BIGINT;
      v_port := upper(btrim(split_part(NEW.entity_id, '::', 2)));
      SELECT id INTO v_report_id FROM public.agency_departure_reports
      WHERE voyage_id = v_voyage_id AND port = v_port AND terminal_id IS NULL;
    ELSE
      RETURN NEW;
    END IF;

    IF NEW.entity_type = 'agency_departure_report_signoff'
       AND NEW.field_name = 'state' AND NEW.new_value = 'pending' THEN
      v_section := CASE
        WHEN NEW.entity_id ~ '^[0-9a-fA-F-]{36}::' THEN split_part(NEW.entity_id, '::', 2)
        ELSE split_part(NEW.entity_id, '::', 3)
      END;
      SELECT department INTO v_section_department
      FROM public.agency_departure_report_signoffs
      WHERE report_id = v_report_id AND section = v_section;
      IF v_section_department IS NOT NULL THEN
        UPDATE public.agency_departure_report_department_signoffs
        SET signed_at = NULL, signed_by = NULL
        WHERE report_id = v_report_id
          AND department = v_section_department
          AND signed_at IS NOT NULL;
        IF FOUND THEN
          INSERT INTO public.audit_logs (
            entity_type, entity_id, field_name, old_value, new_value,
            changed_by, justification
          )
          VALUES (
            'agency_departure_report_department_signoff',
            v_report_id::TEXT || '::' || v_section_department,
            'signed', 'true', 'false', NEW.changed_by, NEW.justification
          );
        END IF;
      END IF;
    END IF;
    IF v_report_id IS NOT NULL THEN
      PERFORM public.reconcile_agency_report_alerts(v_report_id, TRUE, TRUE);
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Reconciliation is an optimization for freshness. It must never turn a
  -- malformed or unauthorized audit row into a failed business write; the
  -- scheduled detector remains the recovery path.
  RAISE WARNING 'Reconciliação de alertas ADR ignorada para audit_logs.id=%: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$_$;



--
-- Name: reconcile_agency_report_alerts_on_report_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_agency_report_alerts_on_report_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.status IS DISTINCT FROM NEW.status THEN
    PERFORM public.reconcile_agency_report_alerts(NEW.id, TRUE, TRUE);
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: reconcile_baplie_coverage_from_new_bl_containers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_baplie_coverage_from_new_bl_containers() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_voyage_id BIGINT;
BEGIN
  IF current_setting('alerts.baplie_coverage_deferred', true) = 'on' THEN
    RETURN NULL;
  END IF;

  PERFORM set_config('alerts.foundation_trigger', 'on', true);
  FOR v_voyage_id IN
    SELECT DISTINCT b.voyage_id
    FROM changed_rows c
    JOIN public.bls b ON b.id = c.bl_id
    WHERE b.voyage_id IS NOT NULL
  LOOP
    PERFORM public.reconcile_voyage_baplie_coverage_alerts(v_voyage_id, 'baplie_coverage_trigger');
  END LOOP;
  PERFORM set_config('alerts.foundation_trigger', 'off', true);
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('alerts.foundation_trigger', 'off', true);
  RAISE WARNING 'Reconciliação Baplie/BL ignorada (containers de B/L novos): %', SQLERRM;
  RETURN NULL;
END;
$$;



