--
-- Name: reconcile_bl_review_alerts(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_bl_review_alerts(p_bl_id text, p_source text DEFAULT 'bl_review_gate'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl public.bls%ROWTYPE;
  v_source TEXT := COALESCE(NULLIF(btrim(p_source), ''), 'bl_review_gate');
  v_type TEXT;
BEGIN
  -- Resolve alertas legados criados por B/L individual
  FOREACH v_type IN ARRAY ARRAY[
    'review_customer_unlinked',
    'review_customer_email_missing',
    'review_portal_not_ready',
    'review_breakbulk_weight_missing'
  ] LOOP
    PERFORM public.resolve_alert_item(v_type, 'bl', p_bl_id, 'bl_review_consolidated', '{}'::jsonb);
  END LOOP;

  SELECT * INTO v_bl FROM public.bls WHERE id = p_bl_id;
  IF FOUND THEN
    PERFORM public.reconcile_customer_bl_review_alerts(v_bl.customer_id, v_bl.consignee, v_source);
  END IF;
END;
$$;



--
-- Name: reconcile_bl_review_alerts_item(text, text, text, text, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_bl_review_alerts_item(p_type text, p_reason text, p_message text, p_bl_id text, p_reasons text[], p_source text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF p_reason = ANY(p_reasons) THEN
    PERFORM public.upsert_alert_item(p_type, 'bl', p_bl_id, p_message, p_source, '{}'::jsonb, CASE WHEN p_type = 'review_portal_not_ready' THEN '/clientes/portal' ELSE '/revisao' END);
  ELSE
    PERFORM public.resolve_alert_item(p_type, 'bl', p_bl_id, p_source, '{}'::jsonb);
  END IF;
END;
$$;



--
-- Name: reconcile_client_portal_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_client_portal_alerts() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_customer RECORD;
  v_account public.customer_portal_accounts%ROWTYPE;
  v_active_process BOOLEAN;
  v_gate_ok BOOLEAN;
  v_result JSONB := '{}'::jsonb;
  v_count INTEGER := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Executor server-only.' USING ERRCODE = '42501';
  END IF;

  FOR v_customer IN
    SELECT c.id, c.name,
           EXISTS (SELECT 1 FROM public.bls b WHERE b.customer_id = c.id AND b.financial_status IS DISTINCT FROM 'cancelled') AS active_process,
           a.id AS account_id, a.active, a.account_situation, a.auth_user_id, a.recovery_email, a.recovery_email_status
    FROM public.customers c
    LEFT JOIN public.customer_portal_accounts a ON a.customer_id = c.id
    ORDER BY c.id
  LOOP
    v_active_process := v_customer.active_process;
    v_account.id := v_customer.account_id;
    v_account.active := v_customer.active;
    v_account.account_situation := v_customer.account_situation;
    v_account.auth_user_id := v_customer.auth_user_id;
    v_account.recovery_email := v_customer.recovery_email;
    v_account.recovery_email_status := v_customer.recovery_email_status;
    v_gate_ok := false;
    IF v_account.id IS NOT NULL THEN
      v_gate_ok := v_account.active
        AND v_account.account_situation = 'ativo'
        AND v_account.auth_user_id IS NOT NULL
        AND lower(COALESCE(v_account.recovery_email, '')) ~ '^[^@\s]+@[^@\s]+\.[^@\s]+$'
        AND COALESCE(v_account.recovery_email_status, 'ok') = 'ok'
        AND NOT EXISTS (SELECT 1 FROM public.portal_suppressed_emails s WHERE lower(s.email) = lower(v_account.recovery_email));
    END IF;

    IF v_active_process AND NOT v_gate_ok THEN
      PERFORM public.block521_upsert_alert(
        'portal_pendencia_geral', 'customer', v_customer.id::text,
        'Cliente com processo ativo sem Portal ativo ou sem email de recuperação utilizável.',
        'portal_reconciliation',
        'documentacao',
        jsonb_build_object('customer_id', v_customer.id, 'active_process', true),
        '/clientes/portal?cliente=' || v_customer.id
      );
    ELSE
      PERFORM public.block521_resolve_alert('portal_pendencia_geral', 'customer', v_customer.id::text, 'documentacao', 'portal_reconciliation');
    END IF;

    IF v_active_process AND v_account.id IS NOT NULL AND v_account.account_situation = 'convite_expirado' THEN
      PERFORM public.block521_upsert_alert('portal_convite_expirado', 'customer', v_customer.id::text, 'Convite do Portal expirado; reenvie o convite.', 'portal_reconciliation', 'documentacao', jsonb_build_object('customer_id', v_customer.id), '/clientes/portal?cliente=' || v_customer.id);
    ELSE
      PERFORM public.block521_resolve_alert('portal_convite_expirado', 'customer', v_customer.id::text, 'documentacao', 'portal_reconciliation');
    END IF;

    IF v_active_process AND v_account.id IS NOT NULL AND v_account.account_situation = 'falha_no_envio' THEN
      PERFORM public.block521_upsert_alert('portal_falha_envio', 'customer', v_customer.id::text, 'Falha no envio do convite do Portal; revise o email e reenvie.', 'portal_reconciliation', 'documentacao', jsonb_build_object('customer_id', v_customer.id), '/clientes/portal?cliente=' || v_customer.id);
    ELSE
      PERFORM public.block521_resolve_alert('portal_falha_envio', 'customer', v_customer.id::text, 'documentacao', 'portal_reconciliation');
    END IF;

    IF v_active_process AND v_account.id IS NOT NULL AND (COALESCE(v_account.recovery_email_status, 'ok') <> 'ok' OR EXISTS (SELECT 1 FROM public.portal_suppressed_emails s WHERE lower(s.email) = lower(v_account.recovery_email))) THEN
      PERFORM public.block521_upsert_alert('portal_email_suprimido', 'customer', v_customer.id::text, 'Email de recuperação suprimido; escolha e confirme um endereço utilizável.', 'portal_reconciliation', 'documentacao', jsonb_build_object('customer_id', v_customer.id, 'email', v_account.recovery_email), '/clientes/portal?cliente=' || v_customer.id);
    ELSE
      PERFORM public.block521_resolve_alert('portal_email_suprimido', 'customer', v_customer.id::text, 'documentacao', 'portal_reconciliation');
    END IF;
    v_count := v_count + 1;
  END LOOP;
  v_result := jsonb_build_object('customers_scanned', v_count, 'reconciled_at', now());
  RETURN v_result;
END;
$_$;



--
-- Name: reconcile_customer_bl_review_alerts(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_customer_bl_review_alerts(p_customer_id bigint, p_consignee text, p_source text DEFAULT 'bl_review_gate'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_source TEXT := COALESCE(NULLIF(btrim(p_source), ''), 'bl_review_gate');
  v_customer_name TEXT;
  v_customer_label TEXT;
  v_entity_id TEXT;
  v_consignee_key TEXT;
  v_has_email BOOLEAN := false;
  v_portal_ready BOOLEAN := false;
  v_total_pending INTEGER := 0;
  v_bb_pending INTEGER := 0;
  v_msg TEXT;
BEGIN
  IF p_customer_id IS NOT NULL THEN
    SELECT name INTO v_customer_name FROM public.customers WHERE id = p_customer_id;
    v_customer_label := COALESCE(v_customer_name, 'Cliente #' || p_customer_id::TEXT);
    v_entity_id := p_customer_id::TEXT;

    SELECT EXISTS (
      SELECT 1 FROM public.customer_contacts c
      WHERE c.customer_id = p_customer_id
        AND NULLIF(btrim(c.email), '') IS NOT NULL
    ) INTO v_has_email;

    -- Mesmo critério do gate (ADR 0054): sem a função única, este alerta
    -- resolvia exatamente as contas que a emissão recusa.
    v_portal_ready := public.customer_portal_access_ready(p_customer_id);

    SELECT
      count(*),
      count(*) FILTER (WHERE cargo_mode = 'carga_solta' AND (bb_weight_ton IS NULL OR bb_weight_ton <= 0))
    INTO v_total_pending, v_bb_pending
    FROM public.bls
    WHERE customer_id = p_customer_id
      AND review_status = 'pending_review';

    -- 1. E-mail de contato ausente
    IF v_total_pending > 0 AND NOT v_has_email THEN
      v_msg := 'Cliente ' || v_customer_label || ': ' || v_total_pending ||
        CASE WHEN v_total_pending = 1 THEN ' B/L pendente de revisão (sem e-mail cadastrado)'
             ELSE ' B/Ls pendentes de revisão (sem e-mail cadastrado)' END;
      PERFORM public.upsert_alert_item(
        'review_customer_email_missing', 'customer', v_entity_id, v_msg, v_source,
        jsonb_build_object('customer_id', p_customer_id, 'pending_count', v_total_pending),
        '/revisao'
      );
    ELSE
      PERFORM public.resolve_alert_item('review_customer_email_missing', 'customer', v_entity_id, v_source, '{}'::jsonb);
    END IF;

    -- 2. Conta de Portal não provisionada
    IF v_total_pending > 0 AND NOT v_portal_ready THEN
      v_msg := 'Cliente ' || v_customer_label || ': ' || v_total_pending ||
        CASE WHEN v_total_pending = 1 THEN ' B/L pendente (Conta de Portal não provisionada)'
             ELSE ' B/Ls pendentes (Conta de Portal não provisionada)' END;
      PERFORM public.upsert_alert_item(
        'review_portal_not_ready', 'customer', v_entity_id, v_msg, v_source,
        jsonb_build_object('customer_id', p_customer_id, 'pending_count', v_total_pending),
        '/clientes/portal?cliente=' || p_customer_id::TEXT
      );
    ELSE
      PERFORM public.resolve_alert_item('review_portal_not_ready', 'customer', v_entity_id, v_source, '{}'::jsonb);
    END IF;

    -- 3. Peso BB ausente
    IF v_bb_pending > 0 THEN
      v_msg := 'Cliente ' || v_customer_label || ': ' || v_bb_pending ||
        CASE WHEN v_bb_pending = 1 THEN ' B/L pendente de revisão (peso BB ausente)'
             ELSE ' B/Ls pendentes de revisão (peso BB ausente)' END;
      PERFORM public.upsert_alert_item(
        'review_breakbulk_weight_missing', 'customer', v_entity_id, v_msg, v_source,
        jsonb_build_object('customer_id', p_customer_id, 'pending_count', v_bb_pending),
        '/revisao'
      );
    ELSE
      PERFORM public.resolve_alert_item('review_breakbulk_weight_missing', 'customer', v_entity_id, v_source, '{}'::jsonb);
    END IF;

    -- Para cliente já vinculado, não há pendência de vínculo
    PERFORM public.resolve_alert_item('review_customer_unlinked', 'customer', v_entity_id, v_source, '{}'::jsonb);

  ELSE
    -- B/Ls sem vínculo de cliente (chaveados por consignatário)
    v_consignee_key := COALESCE(NULLIF(btrim(p_consignee), ''), 'sem_cliente');
    v_entity_id := v_consignee_key;

    SELECT
      count(*),
      count(*) FILTER (WHERE cargo_mode = 'carga_solta' AND (bb_weight_ton IS NULL OR bb_weight_ton <= 0))
    INTO v_total_pending, v_bb_pending
    FROM public.bls
    WHERE customer_id IS NULL
      AND review_status = 'pending_review'
      AND COALESCE(NULLIF(btrim(consignee), ''), 'sem_cliente') = v_consignee_key;

    -- 1. Cliente não vinculado
    IF v_total_pending > 0 THEN
      v_msg := 'Cliente ' || v_consignee_key || ': ' || v_total_pending ||
        CASE WHEN v_total_pending = 1 THEN ' B/L pendente de vínculo com cliente'
             ELSE ' B/Ls pendentes de vínculo com cliente' END;
      PERFORM public.upsert_alert_item(
        'review_customer_unlinked', 'customer', v_entity_id, v_msg, v_source,
        jsonb_build_object('consignee', v_consignee_key, 'pending_count', v_total_pending),
        '/revisao'
      );
    ELSE
      PERFORM public.resolve_alert_item('review_customer_unlinked', 'customer', v_entity_id, v_source, '{}'::jsonb);
    END IF;

    -- 2. Peso BB ausente
    IF v_bb_pending > 0 THEN
      v_msg := 'Cliente ' || v_consignee_key || ': ' || v_bb_pending ||
        CASE WHEN v_bb_pending = 1 THEN ' B/L pendente de revisão (peso BB ausente)'
             ELSE ' B/Ls pendentes de revisão (peso BB ausente)' END;
      PERFORM public.upsert_alert_item(
        'review_breakbulk_weight_missing', 'customer', v_entity_id, v_msg, v_source,
        jsonb_build_object('consignee', v_consignee_key, 'pending_count', v_bb_pending),
        '/revisao'
      );
    ELSE
      PERFORM public.resolve_alert_item('review_breakbulk_weight_missing', 'customer', v_entity_id, v_source, '{}'::jsonb);
    END IF;

    -- Para B/L sem cliente vinculado, e-mail e portal não se aplicam
    PERFORM public.resolve_alert_item('review_customer_email_missing', 'customer', v_entity_id, v_source, '{}'::jsonb);
    PERFORM public.resolve_alert_item('review_portal_not_ready', 'customer', v_entity_id, v_source, '{}'::jsonb);
  END IF;
END;
$$;



--
-- Name: reconcile_granite_bl_review_alerts(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_granite_bl_review_alerts(p_granite_bl_id bigint, p_source text DEFAULT 'granite_review_gate'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_gbl public.granite_bls%ROWTYPE;
  v_source TEXT := COALESCE(NULLIF(btrim(p_source), ''), 'granite_review_gate');
BEGIN
  SELECT * INTO v_gbl FROM public.granite_bls WHERE id = p_granite_bl_id;
  IF NOT FOUND THEN
    PERFORM public.resolve_alert_item('review_granite_customer_unlinked', 'granite_bl', p_granite_bl_id::TEXT, 'granite_bl_deleted', '{}'::jsonb);
    RETURN;
  END IF;

  IF v_gbl.client_id IS NULL THEN
    PERFORM public.upsert_alert_item(
      'review_granite_customer_unlinked', 'granite_bl', v_gbl.id::TEXT,
      'Cliente não vinculado ao Granito B/L ' || COALESCE(v_gbl.bl_number, v_gbl.id::TEXT),
      v_source,
      jsonb_build_object('granite_bl_id', v_gbl.id, 'bl_number', v_gbl.bl_number),
      '/revisao'
    );
  ELSE
    PERFORM public.resolve_alert_item('review_granite_customer_unlinked', 'granite_bl', v_gbl.id::TEXT, 'granite_review_resolved', '{}'::jsonb);
  END IF;
END;
$$;



--
-- Name: reconcile_invoice_payment_by_txid(text, numeric, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_invoice_payment_by_txid(p_txid text, p_amount_brl numeric, p_paid_at timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_norm TEXT;
  v_invoice_id BIGINT;
  v_match_count INTEGER;
  v_result JSONB;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  v_norm := UPPER(REGEXP_REPLACE(COALESCE(p_txid, ''), '[^A-Za-z0-9]', '', 'g'));
  IF v_norm = '' THEN
    RETURN jsonb_build_object('matched', false, 'reason', 'empty_txid');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.ledger_settlements
    WHERE pix_txid IS NOT NULL
      AND UPPER(REGEXP_REPLACE(pix_txid, '[^A-Za-z0-9]', '', 'g')) = v_norm
  ) THEN
    RETURN jsonb_build_object('matched', false, 'reason', 'already_reconciled');
  END IF;

  -- TXID only: match against the payable local invoice number. No CNPJ/value fallback.
  SELECT COUNT(*), MIN(id) INTO v_match_count, v_invoice_id
  FROM public.invoices
  WHERE invoice_type IN ('individual', 'consolidated')
    AND COALESCE(status, 'issued') IN ('issued', 'partially_paid', 'overdue')
    AND UPPER(REGEXP_REPLACE(COALESCE(invoice_number, ''), '[^A-Za-z0-9]', '', 'g')) = v_norm;

  IF v_match_count = 0 THEN
    RETURN jsonb_build_object('matched', false, 'reason', 'no_match');
  ELSIF v_match_count > 1 THEN
    RETURN jsonb_build_object('matched', false, 'reason', 'ambiguous');
  END IF;

  BEGIN
    v_result := public.register_ledger_invoice_payment(
      p_invoice_id := v_invoice_id,
      p_amount_brl := p_amount_brl,
      p_method := 'pix',
      p_paid_at := COALESCE(p_paid_at, now()),
      p_pix_txid := p_txid,
      p_source := 'pix_extract',
      p_notes := 'Conciliacao automatica por TXID',
      p_actor := auth.uid()
    );
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('matched', true, 'invoice_id', v_invoice_id, 'settled', false, 'reason', SQLERRM);
  END;

  UPDATE public.invoices
  SET pix_txid = p_txid, conciliated_by_extract = true
  WHERE id = v_invoice_id;

  RETURN jsonb_build_object('matched', true, 'invoice_id', v_invoice_id, 'settled', true, 'payment', v_result);
END;
$$;



--
-- Name: reconcile_voyage_baplie_coverage_alerts(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_voyage_baplie_coverage_alerts(p_voyage_id bigint, p_source text DEFAULT 'voyage_operation_detector'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today DATE := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_first_eta DATE;
  v_is_d7 BOOLEAN;
  v_has_baplie BOOLEAN;
  v_covered_route_count INTEGER := 0;
  v_pending_route_count INTEGER := 0;
  v_divergence_count INTEGER := 0;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM public.baplie_containers WHERE voyage_id = p_voyage_id
  ) INTO v_has_baplie;

  IF NOT v_has_baplie THEN
    PERFORM public.resolve_alert_item('voyage_baplie_documentary_coverage', 'voyage', p_voyage_id::text, p_source, '{}'::jsonb);
    RETURN;
  END IF;

  v_first_eta := public.get_voyage_first_brazilian_eta(p_voyage_id);
  v_is_d7 := (v_first_eta IS NOT NULL AND v_today >= (v_first_eta - 7));

  WITH edi_routes AS (
    SELECT DISTINCT public.normalize_port_code(pol) AS pol, public.normalize_port_code(pod) AS pod
    FROM public.baplie_containers
    WHERE voyage_id = p_voyage_id
      AND pol IS NOT NULL AND pod IS NOT NULL
      AND COALESCE(status, '') <> 'empty'
  ),
  bl_routes AS (
    SELECT DISTINCT public.normalize_port_code(b.pol) AS pol, public.normalize_port_code(b.pod) AS pod
    FROM public.bls b
    WHERE b.voyage_id = p_voyage_id
      AND b.pol IS NOT NULL AND b.pod IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.bl_containers bc
        WHERE bc.bl_id = b.id
          AND NULLIF(btrim(bc.container_number), '') IS NOT NULL
      )
  ),
  valid_edi AS (
    SELECT pol, pod FROM edi_routes WHERE pol IS NOT NULL AND pod IS NOT NULL
  ),
  valid_bl AS (
    SELECT pol, pod FROM bl_routes WHERE pol IS NOT NULL AND pod IS NOT NULL
  )
  SELECT
    (SELECT count(*) FROM (SELECT pol, pod FROM valid_edi INTERSECT SELECT pol, pod FROM valid_bl) covered),
    (SELECT count(*) FROM (SELECT pol, pod FROM valid_edi EXCEPT SELECT pol, pod FROM valid_bl) pending)
  INTO v_covered_route_count, v_pending_route_count;

  IF v_covered_route_count = 0 AND v_pending_route_count > 0 AND NOT v_is_d7 THEN
    PERFORM public.resolve_alert_item('voyage_baplie_documentary_coverage', 'voyage', p_voyage_id::text, p_source, '{}'::jsonb);
    RETURN;
  END IF;

  WITH pending_routes AS (
    SELECT pol, pod FROM (
      SELECT DISTINCT public.normalize_port_code(pol) AS pol, public.normalize_port_code(pod) AS pod
      FROM public.baplie_containers
      WHERE voyage_id = p_voyage_id
        AND pol IS NOT NULL AND pod IS NOT NULL
        AND COALESCE(status, '') <> 'empty'
      EXCEPT
      SELECT DISTINCT public.normalize_port_code(b.pol) AS pol, public.normalize_port_code(b.pod) AS pod
      FROM public.bls b
      WHERE b.voyage_id = p_voyage_id
        AND b.pol IS NOT NULL AND b.pod IS NOT NULL
        AND EXISTS (
          SELECT 1 FROM public.bl_containers bc
          WHERE bc.bl_id = b.id
            AND NULLIF(btrim(bc.container_number), '') IS NOT NULL
        )
    ) missing
    WHERE pol IS NOT NULL AND pod IS NOT NULL
      AND NOT v_is_d7
  ),
  baplie_full AS (
    SELECT
      regexp_replace(upper(btrim(container_number)), '\s+', '', 'g') AS container_number,
      public.normalize_port_code(pol) AS pol,
      public.normalize_port_code(pod) AS pod
    FROM public.baplie_containers
    WHERE voyage_id = p_voyage_id
      AND COALESCE(status, '') <> 'empty'
      AND NULLIF(btrim(container_number), '') IS NOT NULL
  ),
  baplie_all AS (
    SELECT DISTINCT container_number FROM baplie_full
  ),
  baplie_reconcilable AS (
    SELECT DISTINCT f.container_number
    FROM baplie_full f
    WHERE NOT EXISTS (
      SELECT 1 FROM pending_routes p
      WHERE p.pol IS NOT DISTINCT FROM f.pol AND p.pod IS NOT DISTINCT FROM f.pod
    )
  ),
  bl_cntrs AS (
    SELECT DISTINCT regexp_replace(upper(btrim(bc.container_number)), '\s+', '', 'g') AS container_number
    FROM public.bl_containers bc
    JOIN public.bls b ON b.id = bc.bl_id
    WHERE b.voyage_id = p_voyage_id
      AND NULLIF(btrim(bc.container_number), '') IS NOT NULL
  )
  SELECT
    (SELECT count(*) FROM (SELECT container_number FROM baplie_reconcilable EXCEPT SELECT container_number FROM bl_cntrs) d1) +
    (SELECT count(*) FROM (SELECT container_number FROM bl_cntrs EXCEPT SELECT container_number FROM baplie_all) d2)
  INTO v_divergence_count;

  IF v_divergence_count > 0 THEN
    PERFORM public.upsert_alert_item(
      'voyage_baplie_documentary_coverage',
      'voyage',
      p_voyage_id::text,
      'Divergência Baplie/BL: ' || v_divergence_count || ' container(s) divergente(s) na viagem ' || p_voyage_id,
      p_source,
      jsonb_build_object(
        'voyage_id', p_voyage_id,
        'divergence_count', v_divergence_count,
        'covered_route_count', v_covered_route_count,
        'pending_route_count', v_pending_route_count
      ),
      '/baplie?voyage=' || p_voyage_id
    );
  ELSE
    PERFORM public.resolve_alert_item('voyage_baplie_documentary_coverage', 'voyage', p_voyage_id::text, p_source, '{}'::jsonb);
  END IF;
END;
$$;



--
-- Name: reconcile_voyage_baplie_missing_alerts(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_voyage_baplie_missing_alerts(p_voyage_id bigint, p_source text DEFAULT 'voyage_operation_detector'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today DATE := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_first_eta DATE;
  v_has_baplie BOOLEAN;
BEGIN
  v_first_eta := public.get_voyage_first_brazilian_eta(p_voyage_id);

  IF v_first_eta IS NULL OR v_today < (v_first_eta - 7) THEN
    PERFORM public.resolve_alert_item('voyage_baplie_missing', 'voyage', p_voyage_id::text, p_source, '{}'::jsonb);
    RETURN;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.baplie_containers WHERE voyage_id = p_voyage_id
  ) INTO v_has_baplie;

  IF v_has_baplie THEN
    PERFORM public.resolve_alert_item('voyage_baplie_missing', 'voyage', p_voyage_id::text, p_source, '{}'::jsonb);
  ELSE
    PERFORM public.upsert_alert_item(
      'voyage_baplie_missing',
      'voyage',
      p_voyage_id::text,
      'Baplie ausente para a viagem ' || p_voyage_id || ' (D-7 atingido)',
      p_source,
      jsonb_build_object('voyage_id', p_voyage_id, 'first_eta', v_first_eta),
      '/baplie?voyage=' || p_voyage_id
    );
  END IF;
END;
$$;



--
-- Name: reconcile_voyage_bl_expected_alerts(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_voyage_bl_expected_alerts(p_voyage_id bigint, p_source text DEFAULT 'voyage_operation_detector'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today DATE := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_first_eta DATE;
  v_expected_pol_count INTEGER := 0;
  v_expected_pod_count INTEGER := 0;
  v_missing_pol_count INTEGER := 0;
  v_missing_pod_count INTEGER := 0;
  v_bl_count INTEGER := 0;
  v_covered BOOLEAN := false;
BEGIN
  v_first_eta := public.get_voyage_first_brazilian_eta(p_voyage_id);

  IF v_first_eta IS NULL OR v_today < (v_first_eta - 7) THEN
    PERFORM public.resolve_alert_item('voyage_bl_expected', 'voyage', p_voyage_id::text, p_source, '{}'::jsonb);
    RETURN;
  END IF;

  -- Contagem de PODs esperados
  SELECT count(*) INTO v_expected_pod_count
  FROM public.get_voyage_eligible_pods(p_voyage_id);

  -- POLs esperados a partir de audit_logs de pol_schedule
  WITH latest_pol_etd AS (
    SELECT DISTINCT ON (entity_id)
      upper(btrim(split_part(entity_id, '::', 2))) AS pol_code,
      NULLIF(btrim(new_value), '') AS etd
    FROM public.audit_logs
    WHERE entity_type = 'voyage_pol_schedule'
      AND entity_id LIKE p_voyage_id || '::%'
      AND field_name = 'etd'
    ORDER BY entity_id, changed_at DESC
  )
  SELECT count(*) INTO v_expected_pol_count
  FROM latest_pol_etd
  WHERE etd IS NOT NULL;

  -- B/Ls atuais da viagem
  SELECT count(*) INTO v_bl_count
  FROM public.bls
  WHERE voyage_id = p_voyage_id;

  IF v_bl_count > 0 THEN
    IF v_expected_pol_count > 0 THEN
      -- POLs ausentes nos B/Ls
      WITH latest_pol_etd AS (
        SELECT DISTINCT ON (entity_id)
          upper(btrim(split_part(entity_id, '::', 2))) AS pol_code,
          NULLIF(btrim(new_value), '') AS etd
        FROM public.audit_logs
        WHERE entity_type = 'voyage_pol_schedule'
          AND entity_id LIKE p_voyage_id || '::%'
          AND field_name = 'etd'
        ORDER BY entity_id, changed_at DESC
      )
      SELECT count(*) INTO v_missing_pol_count
      FROM latest_pol_etd lp
      WHERE lp.etd IS NOT NULL
        AND NOT EXISTS (
          SELECT 1 FROM public.bls b
          WHERE b.voyage_id = p_voyage_id AND upper(btrim(b.pol)) = lp.pol_code
        );

      -- PODs ausentes nos B/Ls
      SELECT count(*) INTO v_missing_pod_count
      FROM public.get_voyage_eligible_pods(p_voyage_id) ep
      WHERE NOT EXISTS (
        SELECT 1 FROM public.bls b
        WHERE b.voyage_id = p_voyage_id AND upper(btrim(b.pod)) = ep.pod
      );

      v_covered := (v_missing_pol_count = 0 AND v_missing_pod_count = 0);
    ELSE
      -- Sem POLs planejados, cobriu se houver ao menos 1 B/L para cada POD elegível
      SELECT count(*) INTO v_missing_pod_count
      FROM public.get_voyage_eligible_pods(p_voyage_id) ep
      WHERE NOT EXISTS (
        SELECT 1 FROM public.bls b
        WHERE b.voyage_id = p_voyage_id AND upper(btrim(b.pod)) = ep.pod
      );

      v_covered := (v_missing_pod_count = 0);
    END IF;
  ELSE
    v_covered := false;
  END IF;

  IF v_covered THEN
    PERFORM public.resolve_alert_item('voyage_bl_expected', 'voyage', p_voyage_id::text, p_source, '{}'::jsonb);
  ELSE
    PERFORM public.upsert_alert_item(
      'voyage_bl_expected',
      'voyage',
      p_voyage_id::text,
      'B/Ls esperados pendentes para a viagem ' || p_voyage_id || ' (D-7 atingido)',
      p_source,
      jsonb_build_object('voyage_id', p_voyage_id, 'first_eta', v_first_eta),
      '/viagens/' || p_voyage_id
    );
  END IF;
END;
$$;



--
-- Name: reconcile_voyage_ce_mercante_missing_alerts(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_voyage_ce_mercante_missing_alerts(p_voyage_id bigint, p_source text DEFAULT 'voyage_operation_detector'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today DATE := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_first_eta DATE;
  v_total_bls INTEGER := 0;
  v_missing_ce_count INTEGER := 0;
BEGIN
  v_first_eta := public.get_voyage_first_brazilian_eta(p_voyage_id);

  IF v_first_eta IS NULL OR v_today < (v_first_eta - 5) THEN
    PERFORM public.resolve_alert_item('voyage_ce_mercante_missing', 'voyage', p_voyage_id::text, p_source, '{}'::jsonb);
    RETURN;
  END IF;

  SELECT
    count(*),
    count(*) FILTER (WHERE ce_mercante IS NULL OR btrim(ce_mercante) = '')
  INTO v_total_bls, v_missing_ce_count
  FROM public.bls
  WHERE voyage_id = p_voyage_id
    AND upper(btrim(pod)) IN (SELECT pod FROM public.get_voyage_eligible_pods(p_voyage_id));

  IF v_total_bls = 0 OR v_missing_ce_count = 0 THEN
    PERFORM public.resolve_alert_item('voyage_ce_mercante_missing', 'voyage', p_voyage_id::text, p_source, '{}'::jsonb);
  ELSE
    PERFORM public.upsert_alert_item(
      'voyage_ce_mercante_missing',
      'voyage',
      p_voyage_id::text,
      'CE Mercante pendente para ' || v_missing_ce_count || ' B/L(s) da viagem ' || p_voyage_id || ' (D-5 atingido)',
      p_source,
      jsonb_build_object('voyage_id', p_voyage_id, 'missing_ce_count', v_missing_ce_count),
      '/viagens/' || p_voyage_id
    );
  END IF;
END;
$$;



--
-- Name: reconcile_voyage_export_after_atd_alerts(bigint, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_voyage_export_after_atd_alerts(p_voyage_id bigint, p_port text, p_terminal_id text, p_source text DEFAULT 'voyage_operation_detector'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_port_norm TEXT := upper(btrim(p_port));
  v_entity_id TEXT := p_voyage_id || '::' || v_port_norm;
  v_export_rec RECORD;
  v_terminal_atd TIMESTAMPTZ;
  v_terminal_code TEXT;
  v_has_granite_link BOOLEAN := true;
  v_has_empty_link BOOLEAN := true;
BEGIN
  SELECT tem_exportacao, has_granite, has_empty
  INTO v_export_rec
  FROM public.voyage_export_schedules
  WHERE voyage_id = p_voyage_id AND upper(btrim(pol)) = v_port_norm;

  IF NOT FOUND OR NOT COALESCE(v_export_rec.tem_exportacao, false) THEN
    PERFORM public.resolve_alert_item('voyage_export_after_atd', 'voyage_pod_schedule', v_entity_id, p_source, '{}'::jsonb);
    RETURN;
  END IF;

  SELECT s.terminal_atd, public.voyage_terminal_code(s.terminal_id)
  INTO v_terminal_atd, v_terminal_code
  FROM public.voyage_escala_terminal_state s
  WHERE s.voyage_id = p_voyage_id
    AND s.port = v_port_norm
    AND s.terminal_id::text = p_terminal_id;

  IF v_terminal_atd IS NULL THEN
    PERFORM public.resolve_alert_item('voyage_export_after_atd', 'voyage_pod_schedule', v_entity_id, p_source, '{}'::jsonb);
    RETURN;
  END IF;

  IF COALESCE(v_export_rec.has_granite, false) THEN
    SELECT EXISTS (
      SELECT 1 FROM public.granite_manifests WHERE voyage_id = p_voyage_id
    ) INTO v_has_granite_link;
  END IF;

  IF COALESCE(v_export_rec.has_empty, false) THEN
    SELECT EXISTS (
      SELECT 1 FROM public.vazios_manifests WHERE voyage_id = p_voyage_id
    ) INTO v_has_empty_link;
  END IF;

  IF NOT v_has_granite_link OR NOT v_has_empty_link THEN
    PERFORM public.upsert_alert_item(
      'voyage_export_after_atd',
      'voyage_pod_schedule',
      v_entity_id,
      'Exportação pendente de vínculo após saída/ATD no terminal para a escala ' || v_port_norm,
      p_source,
      jsonb_build_object(
        'voyage_id', p_voyage_id,
        'port', v_port_norm,
        'terminal_id', p_terminal_id,
        'terminal_code', v_terminal_code,
        'has_granite', v_export_rec.has_granite,
        'has_empty', v_export_rec.has_empty,
        'granite_linked', v_has_granite_link,
        'empty_linked', v_has_empty_link
      ),
      '/viagens/' || p_voyage_id || '?escala=' || v_port_norm
    );
  ELSE
    PERFORM public.resolve_alert_item('voyage_export_after_atd', 'voyage_pod_schedule', v_entity_id, p_source, '{}'::jsonb);
  END IF;
END;
$$;



--
-- Name: reconcile_voyage_operation_alerts(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_voyage_operation_alerts(p_voyage_id bigint, p_source text DEFAULT 'voyage_operation_detector'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_port_rec RECORD;
  v_term_rec RECORD;
BEGIN
  -- Nível viagem (documentação / BL / Baplie / CE)
  PERFORM public.reconcile_voyage_bl_expected_alerts(p_voyage_id, p_source);
  PERFORM public.reconcile_voyage_baplie_missing_alerts(p_voyage_id, p_source);
  PERFORM public.reconcile_voyage_baplie_coverage_alerts(p_voyage_id, p_source);
  PERFORM public.reconcile_voyage_ce_mercante_missing_alerts(p_voyage_id, p_source);

  -- Nível escala (datas compartilhadas e por terminal)
  FOR v_port_rec IN
    SELECT DISTINCT upper(btrim(split_part(entity_id, '::', 2))) AS port
    FROM public.audit_logs
    WHERE entity_type = 'voyage_pod_schedule' AND entity_id LIKE p_voyage_id || '::%'
    UNION
    SELECT DISTINCT upper(btrim(port)) AS port
    FROM public.voyage_escala_terminal_state
    WHERE voyage_id = p_voyage_id
    UNION
    SELECT DISTINCT upper(btrim(pol)) AS port
    FROM public.voyage_export_schedules
    WHERE voyage_id = p_voyage_id
  LOOP
    IF v_port_rec.port IS NOT NULL AND v_port_rec.port <> '' THEN
      PERFORM public.reconcile_voyage_schedule_date_alerts(p_voyage_id, v_port_rec.port, p_source);

      FOR v_term_rec IN
        SELECT terminal_id
        FROM public.voyage_escala_terminal_state
        WHERE voyage_id = p_voyage_id AND port = v_port_rec.port
      LOOP
        PERFORM public.reconcile_voyage_export_after_atd_alerts(p_voyage_id, v_port_rec.port, v_term_rec.terminal_id::text, p_source);
      END LOOP;
    END IF;
  END LOOP;
END;
$$;



--
-- Name: reconcile_voyage_operation_alerts_on_audit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_voyage_operation_alerts_on_audit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_voyage_id BIGINT;
  v_port TEXT;
BEGIN
  IF NEW.entity_type NOT IN ('voyage_pod_schedule', 'voyage_pol_schedule', 'voyages') THEN
    RETURN NEW;
  END IF;
  v_voyage_id := NULLIF(split_part(NEW.entity_id, '::', 1), '')::BIGINT;
  IF NEW.entity_type = 'voyages' THEN
    PERFORM public.reconcile_voyage_operation_alerts(v_voyage_id, 'voyage_operation_trigger');
  ELSE
    v_port := NULLIF(upper(btrim(split_part(NEW.entity_id, '::', 2))), '');
    IF v_port IS NOT NULL THEN
      PERFORM public.reconcile_voyage_schedule_date_alerts(v_voyage_id, v_port, 'voyage_operation_trigger');
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Reconciliação de alertas de viagem ignorada para audit_logs.id=%: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;



--
-- Name: reconcile_voyage_operation_alerts_on_terminal_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_voyage_operation_alerts_on_terminal_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.reconcile_voyage_operation_alerts(NEW.voyage_id, 'voyage_operation_trigger');
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Reconciliação de alertas de terminal ignorada para voyage_id=%: %', NEW.voyage_id, SQLERRM;
  RETURN NEW;
END;
$$;



--
-- Name: reconcile_voyage_schedule_date_alerts(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_voyage_schedule_date_alerts(p_voyage_id bigint, p_port text, p_source text DEFAULT 'voyage_operation_detector'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_today DATE := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_port_norm TEXT := upper(btrim(p_port));
  v_scale_entity_id TEXT := p_voyage_id || '::' || v_port_norm;
  v_term_rec RECORD;
  v_term_entity_id TEXT;
  v_is_deleted BOOLEAN := false;
  v_is_omitted BOOLEAN := false;
  v_eta DATE;
  v_ata DATE;
  v_has_terminal_etb BOOLEAN := false;
BEGIN
  WITH latest_state AS (
    SELECT DISTINCT ON (field_name) field_name, new_value
    FROM public.audit_logs
    WHERE entity_type = 'voyage_pod_schedule'
      AND entity_id = v_scale_entity_id
      AND field_name IN ('deleted', 'omitted', 'eta', 'ata')
    ORDER BY field_name, changed_at DESC, id DESC
  )
  SELECT
    COALESCE(bool_or(field_name = 'deleted' AND new_value = 'true'), false),
    COALESCE(bool_or(field_name = 'omitted' AND new_value = 'true'), false),
    MAX(CASE WHEN field_name = 'eta' THEN NULLIF(btrim(new_value), '')::date END),
    MAX(CASE WHEN field_name = 'ata' THEN NULLIF(btrim(new_value), '')::date END)
  INTO v_is_deleted, v_is_omitted, v_eta, v_ata
  FROM latest_state;

  IF v_is_deleted OR v_is_omitted THEN
    PERFORM public.resolve_alert_item('voyage_schedule_date_pending', 'voyage_pod_schedule', v_scale_entity_id, p_source, jsonb_build_object('reason', 'scale_deleted_or_omitted'));
    FOR v_term_rec IN
      SELECT terminal_id FROM public.voyage_escala_terminal_state
      WHERE voyage_id = p_voyage_id AND port = v_port_norm
    LOOP
      IF v_term_rec.terminal_id IS NULL THEN CONTINUE; END IF;
      v_term_entity_id := p_voyage_id || '::' || v_port_norm || '::' || public.voyage_terminal_code(v_term_rec.terminal_id);
      PERFORM public.resolve_alert_item('voyage_terminal_date_pending', 'voyage_escala_terminal', v_term_entity_id, p_source, '{}'::jsonb);
      PERFORM public.resolve_alert_item('voyage_export_after_atd', 'voyage_escala_terminal', v_term_entity_id, p_source, '{}'::jsonb);
    END LOOP;
    RETURN;
  END IF;

  SELECT COALESCE(bool_or(terminal_etb IS NOT NULL), false)
  INTO v_has_terminal_etb
  FROM public.voyage_escala_terminal_state
  WHERE voyage_id = p_voyage_id AND port = v_port_norm;

  -- Predicado da escala: depois da chegada, cobrar somente a existência de
  -- uma Atracação com previsão de ETB. TBC conta para este conjunto.
  IF v_eta IS NOT NULL AND v_eta <= v_today AND v_ata IS NULL THEN
    PERFORM public.upsert_alert_item(
      'voyage_schedule_date_pending', 'voyage_pod_schedule', v_scale_entity_id,
      'ATA pendente para escala ' || v_port_norm || ' (ETA ' || to_char(v_eta, 'DD/MM/YYYY') || ' atingido)',
      p_source, jsonb_build_object('voyage_id', p_voyage_id, 'port', v_port_norm, 'milestone', 'ata', 'eta', v_eta),
      '/viagens/' || p_voyage_id || '?escala=' || v_port_norm
    );
  ELSIF v_ata IS NOT NULL AND NOT v_has_terminal_etb THEN
    PERFORM public.upsert_alert_item(
      'voyage_schedule_date_pending', 'voyage_pod_schedule', v_scale_entity_id,
      'ETB pendente para escala ' || v_port_norm || ' (ATA informada)',
      p_source, jsonb_build_object('voyage_id', p_voyage_id, 'port', v_port_norm, 'milestone', 'etb'),
      '/viagens/' || p_voyage_id || '?escala=' || v_port_norm
    );
  ELSE
    PERFORM public.resolve_alert_item('voyage_schedule_date_pending', 'voyage_pod_schedule', v_scale_entity_id, p_source, '{}'::jsonb);
  END IF;

  -- Predicado da Atracação: cada terminal recebe apenas a sua própria cadeia.
  FOR v_term_rec IN
    SELECT terminal_id, terminal_etb::date AS terminal_etb,
      terminal_atb::date AS terminal_atb, terminal_etd::date AS terminal_etd,
      terminal_atd::date AS terminal_atd
    FROM public.voyage_escala_terminal_state s
    WHERE s.voyage_id = p_voyage_id AND s.port = v_port_norm AND s.terminal_id IS NOT NULL
  LOOP
    v_term_entity_id := p_voyage_id || '::' || v_port_norm || '::' || public.voyage_terminal_code(v_term_rec.terminal_id);
    IF v_term_rec.terminal_etb IS NOT NULL AND v_term_rec.terminal_etb <= v_today AND v_term_rec.terminal_atb IS NULL THEN
      PERFORM public.upsert_alert_item(
        'voyage_terminal_date_pending', 'voyage_escala_terminal', v_term_entity_id,
        'ATB pendente no terminal para a escala ' || v_port_norm || ' (ETB ' || to_char(v_term_rec.terminal_etb, 'DD/MM/YYYY') || ' atingido)',
        p_source, jsonb_build_object('voyage_id', p_voyage_id, 'port', v_port_norm, 'terminal', public.voyage_terminal_code(v_term_rec.terminal_id), 'milestone', 'atb', 'etb', v_term_rec.terminal_etb),
        '/viagens/' || p_voyage_id || '?escala=' || v_port_norm || '&terminal=' || public.voyage_terminal_code(v_term_rec.terminal_id)
      );
    ELSIF v_term_rec.terminal_atb IS NOT NULL AND v_term_rec.terminal_etd IS NULL THEN
      PERFORM public.upsert_alert_item(
        'voyage_terminal_date_pending', 'voyage_escala_terminal', v_term_entity_id,
        'ETD pendente no terminal para a escala ' || v_port_norm || ' (ATB informada)',
        p_source, jsonb_build_object('voyage_id', p_voyage_id, 'port', v_port_norm, 'terminal', public.voyage_terminal_code(v_term_rec.terminal_id), 'milestone', 'etd'),
        '/viagens/' || p_voyage_id || '?escala=' || v_port_norm || '&terminal=' || public.voyage_terminal_code(v_term_rec.terminal_id)
      );
    ELSIF v_term_rec.terminal_etd IS NOT NULL AND v_term_rec.terminal_etd <= v_today AND v_term_rec.terminal_atd IS NULL THEN
      PERFORM public.upsert_alert_item(
        'voyage_terminal_date_pending', 'voyage_escala_terminal', v_term_entity_id,
        'ATD pendente no terminal para a escala ' || v_port_norm || ' (ETD ' || to_char(v_term_rec.terminal_etd, 'DD/MM/YYYY') || ' atingido)',
        p_source, jsonb_build_object('voyage_id', p_voyage_id, 'port', v_port_norm, 'terminal', public.voyage_terminal_code(v_term_rec.terminal_id), 'milestone', 'atd', 'etd', v_term_rec.terminal_etd),
        '/viagens/' || p_voyage_id || '?escala=' || v_port_norm || '&terminal=' || public.voyage_terminal_code(v_term_rec.terminal_id)
      );
    ELSE
      PERFORM public.resolve_alert_item('voyage_terminal_date_pending', 'voyage_escala_terminal', v_term_entity_id, p_source, '{}'::jsonb);
    END IF;
  END LOOP;
END;
$$;



--
-- Name: refresh_alert_aggregate(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_alert_aggregate(p_alert_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_message TEXT;
  v_open BOOLEAN;
BEGIN
  SELECT string_agg(i.message, ' | ' ORDER BY i.id), bool_or(i.status = 'active')
    INTO v_message, v_open
  FROM public.alert_items i
  WHERE i.alert_id = p_alert_id;

  UPDATE public.alerts
  SET message = COALESCE(v_message, message),
      status = CASE WHEN COALESCE(v_open, false) THEN 'open' ELSE 'closed' END,
      closed_at = CASE WHEN COALESCE(v_open, false) THEN NULL ELSE COALESCE(closed_at, now()) END
  WHERE id = p_alert_id;
END;
$$;



--
-- Name: refresh_customer_reconciliation_queue_for_bl(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_customer_reconciliation_queue_for_bl(p_bl_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuário sem permissão para atualizar a fila de reconciliação.' USING ERRCODE = '42501';
  END IF;

  PERFORM public.sync_customer_reconciliation_queue_for_bl(p_bl_id);
END;
$$;



--
-- Name: refresh_voyage_status_from_terminal_scales(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refresh_voyage_status_from_terminal_scales(p_voyage_id bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_active_scales INTEGER;
  v_pending_scales INTEGER;
BEGIN
  WITH entities AS (
    SELECT DISTINCT entity_id, upper(btrim(split_part(entity_id, '::', 2))) AS port
    FROM public.audit_logs
    WHERE entity_type = 'voyage_pod_schedule'
      AND split_part(entity_id, '::', 1)::bigint = p_voyage_id
  ), latest_flags AS (
    SELECT e.entity_id,
      COALESCE((SELECT a.new_value = 'true' FROM public.audit_logs a WHERE a.entity_type = 'voyage_pod_schedule' AND a.entity_id = e.entity_id AND a.field_name = 'deleted' ORDER BY a.changed_at DESC, a.id DESC LIMIT 1), false) AS deleted,
      COALESCE((SELECT a.new_value = 'true' FROM public.audit_logs a WHERE a.entity_type = 'voyage_pod_schedule' AND a.entity_id = e.entity_id AND a.field_name = 'omitted' ORDER BY a.changed_at DESC, a.id DESC LIMIT 1), false) AS omitted
    FROM entities e
  ), scale_state AS (
    SELECT f.entity_id,
      EXISTS (SELECT 1 FROM public.voyage_escala_terminal_state s WHERE s.voyage_id = p_voyage_id AND s.port = split_part(f.entity_id, '::', 2)) AS has_atracacao,
      EXISTS (SELECT 1 FROM public.voyage_escala_terminal_state s WHERE s.voyage_id = p_voyage_id AND s.port = split_part(f.entity_id, '::', 2) AND s.terminal_atd IS NULL) AS has_pending_atracacao
    FROM latest_flags f
    WHERE NOT f.deleted AND NOT f.omitted
  )
  SELECT COUNT(*)::integer, COUNT(*) FILTER (WHERE NOT has_atracacao OR has_pending_atracacao)::integer
  INTO v_active_scales, v_pending_scales
  FROM scale_state;

  IF v_active_scales > 0 THEN
    UPDATE public.voyages
    SET status = CASE WHEN v_pending_scales = 0 THEN 'completed' ELSE 'active' END
    WHERE id = p_voyage_id AND status <> 'cancelled';
  END IF;
END;
$$;



--
-- Name: register_invoice_payment(bigint, numeric, text, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_invoice_payment(p_invoice_id bigint, p_amount_brl numeric, p_payment_method text DEFAULT 'pix'::text, p_paid_at timestamp with time zone DEFAULT now(), p_notes text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice RECORD;
  v_actor UUID;
  v_total_paid NUMERIC(14,2);
  v_balance NUMERIC(14,2);
  v_remaining NUMERIC(14,2);
  v_next_status TEXT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  IF COALESCE(p_amount_brl, 0) <= 0 THEN
    INSERT INTO public.audit_logs (
      entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification
    )
    VALUES (
      'system_event',
      'billing',
      'invoice_payment_invalid',
      NULL,
      CONCAT('invoice=', p_invoice_id, ' | amount=', COALESCE(p_amount_brl, 0)),
      auth.uid(),
      now(),
      'Valor de pagamento menor ou igual a zero'
    );
    RAISE EXCEPTION 'Valor de pagamento deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % nao encontrada.', p_invoice_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_invoice.status, 'issued') = 'cancelled' THEN
    INSERT INTO public.audit_logs (
      entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification
    )
    VALUES (
      'system_event',
      'billing',
      'invoice_payment_invalid',
      NULL,
      CONCAT('invoice=', p_invoice_id, ' cancelada'),
      auth.uid(),
      now(),
      'Tentativa de pagamento em invoice cancelada'
    );
    RAISE EXCEPTION 'Invoice cancelada nao aceita pagamento.' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_invoice.status, 'issued') = 'paid' THEN
    INSERT INTO public.audit_logs (
      entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification
    )
    VALUES (
      'system_event',
      'billing',
      'invoice_payment_invalid',
      NULL,
      CONCAT('invoice=', p_invoice_id, ' ja paga'),
      auth.uid(),
      now(),
      'Tentativa de pagamento em invoice ja quitada'
    );
    RAISE EXCEPTION 'Invoice ja esta paga.' USING ERRCODE = '22023';
  END IF;

  v_remaining := GREATEST(COALESCE(v_invoice.balance_brl, COALESCE(v_invoice.total_brl, 0)), 0);
  IF p_amount_brl > v_remaining THEN
    INSERT INTO public.audit_logs (
      entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification
    )
    VALUES (
      'system_event',
      'billing',
      'invoice_payment_invalid',
      NULL,
      CONCAT('invoice=', p_invoice_id, ' | amount=', p_amount_brl, ' | remaining=', v_remaining),
      auth.uid(),
      now(),
      'Tentativa de pagamento acima do saldo da invoice'
    );
    RAISE EXCEPTION 'Pagamento acima do saldo em aberto da invoice.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.payments (
    invoice_id,
    amount_brl,
    payment_method,
    paid_at,
    registered_by,
    notes
  )
  VALUES (
    p_invoice_id,
    p_amount_brl,
    COALESCE(NULLIF(TRIM(COALESCE(p_payment_method, '')), ''), 'pix'),
    COALESCE(p_paid_at, now()),
    v_actor,
    NULLIF(TRIM(COALESCE(p_notes, '')), '')
  );

  SELECT COALESCE(SUM(amount_brl), 0)
  INTO v_total_paid
  FROM public.payments
  WHERE invoice_id = p_invoice_id;

  v_balance := GREATEST(COALESCE(v_invoice.total_brl, 0) - v_total_paid, 0);

  IF v_balance = 0 THEN
    v_next_status := 'paid';
  ELSIF v_total_paid > 0 THEN
    v_next_status := 'partially_paid';
  ELSE
    v_next_status := 'issued';
  END IF;

  UPDATE public.invoices
  SET
    total_paid_brl = v_total_paid,
    balance_brl = v_balance,
    status = v_next_status
  WHERE id = p_invoice_id;

  IF v_next_status = 'paid' THEN
    UPDATE public.bls AS b
    SET financial_status = CASE
      WHEN EXISTS (
        SELECT 1
        FROM public.invoice_bls AS ib2
        JOIN public.invoices AS inv2 ON inv2.id = ib2.invoice_id
        WHERE ib2.bl_id = b.id
          AND inv2.id <> p_invoice_id
          AND COALESCE(inv2.status, 'issued') IN ('draft', 'issued', 'partially_paid', 'overdue')
      ) THEN 'invoiced'
      ELSE 'paid'
    END
    WHERE b.id IN (
      SELECT ib.bl_id
      FROM public.invoice_bls AS ib
      WHERE ib.invoice_id = p_invoice_id
    );
  ELSE
    UPDATE public.bls
    SET financial_status = 'invoiced'
    WHERE id IN (
      SELECT ib.bl_id
      FROM public.invoice_bls AS ib
      WHERE ib.invoice_id = p_invoice_id
    );
  END IF;

  INSERT INTO public.audit_logs (
    entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification
  )
  VALUES (
    'invoice',
    p_invoice_id::TEXT,
    'register_payment',
    COALESCE(v_invoice.total_paid_brl::TEXT, '0'),
    v_total_paid::TEXT,
    auth.uid(),
    now(),
    'Registro de pagamento'
  );

  RETURN jsonb_build_object(
    'invoice_id', p_invoice_id,
    'status', v_next_status,
    'total_paid_brl', v_total_paid,
    'balance_brl', v_balance
  );
END;
$$;



--
-- Name: register_ledger_invoice_payment(bigint, numeric, text, timestamp with time zone, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_ledger_invoice_payment(p_invoice_id bigint, p_amount_brl numeric, p_method text DEFAULT 'pix'::text, p_paid_at timestamp with time zone DEFAULT now(), p_pix_txid text DEFAULT NULL::text, p_source text DEFAULT 'manual'::text, p_notes text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice RECORD;
  v_actor UUID;
  v_open NUMERIC(14,2);
  v_excess NUMERIC(14,2) := 0;
  v_remaining NUMERIC(14,2);
  v_remaining_open NUMERIC(14,2);
  v_allocation NUMERIC(14,2);
  v_payment_id BIGINT;
  v_total_paid NUMERIC(14,2);
  v_all_receivable_ids BIGINT[];
  v_receivable_ids BIGINT[];
  v_receivable RECORD;
  v_next_status TEXT;
  v_covered INTEGER := 0;
  v_obsoleted INTEGER := 0;
  v_receivables_settled INTEGER := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  IF COALESCE(p_source, 'manual') NOT IN ('manual', 'pix_extract') THEN
    RAISE EXCEPTION 'Origem de pagamento invalida.' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(p_amount_brl, 0) <= 0 THEN
    RAISE EXCEPTION 'Valor de pagamento deve ser maior que zero.' USING ERRCODE = '22023';
  END IF;

  IF NULLIF(TRIM(COALESCE(p_pix_txid, '')), '') IS NOT NULL
     AND EXISTS (
       SELECT 1 FROM public.ledger_settlements
       WHERE pix_txid IS NOT NULL
         AND UPPER(REGEXP_REPLACE(pix_txid, '[^A-Za-z0-9]', '', 'g'))
           = UPPER(REGEXP_REPLACE(p_pix_txid, '[^A-Za-z0-9]', '', 'g'))
     ) THEN
    RAISE EXCEPTION 'TXID % ja foi conciliado.', p_pix_txid USING ERRCODE = '23505';
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % nao encontrada.', p_invoice_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_invoice.status, 'issued') NOT IN ('issued', 'partially_paid', 'overdue') THEN
    RAISE EXCEPTION 'Invoice % nao esta em estado pagavel (status=%).', p_invoice_id, v_invoice.status
      USING ERRCODE = '22023';
  END IF;

  SELECT ARRAY_AGG(irl.receivable_id ORDER BY irl.receivable_id)
  INTO v_all_receivable_ids
  FROM public.invoice_receivable_links irl
  WHERE irl.invoice_id = p_invoice_id;

  SELECT ARRAY_AGG(irl.receivable_id ORDER BY irl.receivable_id)
  INTO v_receivable_ids
  FROM public.invoice_receivable_links irl
  WHERE irl.invoice_id = p_invoice_id
    AND irl.status = 'active';

  IF v_receivable_ids IS NULL OR ARRAY_LENGTH(v_receivable_ids, 1) = 0 THEN
    RAISE EXCEPTION 'Invoice % sem receivables ativos vinculados no ledger.', p_invoice_id
      USING ERRCODE = '22023';
  END IF;

  PERFORM 1 FROM public.bl_receivables WHERE id = ANY(v_receivable_ids) ORDER BY id FOR UPDATE;

  SELECT COALESCE(SUM(balance_brl), 0)
  INTO v_open
  FROM public.bl_receivables
  WHERE id = ANY(v_receivable_ids)
    AND status IN ('open', 'partially_settled');

  IF COALESCE(v_open, 0) <= 0 THEN
    RAISE EXCEPTION 'Invoice % nao possui saldo em aberto no ledger.', p_invoice_id USING ERRCODE = '22023';
  END IF;

  -- PIX e copia-e-cola de valor fixo: precisa quitar exatamente o saldo aberto.
  -- Sem pagamento parcial e sem excedente por PIX.
  IF COALESCE(p_source, 'manual') = 'pix_extract' AND ABS(p_amount_brl - v_open) > 0.01 THEN
    RAISE EXCEPTION 'Conciliacao PIX exige valor exato: recebido %, saldo aberto %.',
      p_amount_brl, v_open USING ERRCODE = '22023';
  END IF;

  -- Excedente (valor pago acima do saldo aberto). So permitido na baixa manual,
  -- onde vira restituicao ao cliente. Para PIX o bloco acima ja rejeitou.
  v_excess := ROUND(GREATEST(p_amount_brl - v_open, 0)::NUMERIC, 2);
  IF v_excess > 0.01 AND COALESCE(p_source, 'manual') <> 'manual' THEN
    RAISE EXCEPTION 'Valor (%) excede o saldo em aberto do documento (%).',
      p_amount_brl, v_open USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.payments (invoice_id, amount_brl, payment_method, paid_at, registered_by, notes)
  VALUES (
    p_invoice_id,
    ROUND(p_amount_brl::NUMERIC, 2),
    COALESCE(NULLIF(TRIM(COALESCE(p_method, '')), ''), 'pix'),
    COALESCE(p_paid_at, now()),
    v_actor,
    NULLIF(TRIM(COALESCE(p_notes, '')), '')
  )
  RETURNING id INTO v_payment_id;

  -- Aloca no maximo o saldo aberto; o que passar disso e excedente (restituicao).
  v_remaining := ROUND(LEAST(p_amount_brl, v_open)::NUMERIC, 2);

  FOR v_receivable IN
    SELECT id, balance_brl
    FROM public.bl_receivables
    WHERE id = ANY(v_receivable_ids)
      AND status IN ('open', 'partially_settled')
      AND balance_brl > 0
    ORDER BY id
  LOOP
    EXIT WHEN v_remaining <= 0;

    v_allocation := ROUND(LEAST(v_receivable.balance_brl, v_remaining)::NUMERIC, 2);
    IF v_allocation <= 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO public.ledger_settlements (
      payment_id, receivable_id, invoice_id, amount_brl, settled_at, method, pix_txid, source
    )
    VALUES (
      v_payment_id,
      v_receivable.id,
      p_invoice_id,
      v_allocation,
      COALESCE(p_paid_at, now()),
      COALESCE(NULLIF(TRIM(COALESCE(p_method, '')), ''), 'pix'),
      NULLIF(TRIM(COALESCE(p_pix_txid, '')), ''),
      COALESCE(p_source, 'manual')
    );

    UPDATE public.bl_receivables
    SET
      settled_amount_brl = LEAST(original_amount_brl, COALESCE(settled_amount_brl, 0) + v_allocation),
      balance_brl = GREATEST(COALESCE(balance_brl, 0) - v_allocation, 0),
      status = CASE
        WHEN GREATEST(COALESCE(balance_brl, 0) - v_allocation, 0) <= 0.01 THEN 'settled'
        ELSE 'partially_settled'
      END,
      updated_at = now()
    WHERE id = v_receivable.id;

    v_remaining := ROUND((v_remaining - v_allocation)::NUMERIC, 2);
  END LOOP;

  IF v_remaining > 0.01 THEN
    RAISE EXCEPTION 'Falha ao alocar pagamento: saldo residual %.', v_remaining USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.invoice_receivable_links irl
  SET status = 'settled_by_this_invoice'
  WHERE irl.invoice_id = p_invoice_id
    AND irl.status = 'active'
    AND EXISTS (
      SELECT 1
      FROM public.bl_receivables br
      WHERE br.id = irl.receivable_id
        AND br.balance_brl <= 0.01
    );

  SELECT COALESCE(SUM(balance_brl), 0)
  INTO v_remaining_open
  FROM public.bl_receivables
  WHERE id = ANY(v_receivable_ids)
    AND status IN ('open', 'partially_settled');

  SELECT COALESCE(SUM(amount_brl), 0)
  INTO v_total_paid
  FROM public.payments
  WHERE invoice_id = p_invoice_id;

  v_next_status := CASE WHEN v_remaining_open <= 0.01 THEN 'paid' ELSE 'partially_paid' END;

  UPDATE public.invoices
  SET
    total_paid_brl = v_total_paid,
    balance_brl = GREATEST(v_remaining_open, 0),
    status = v_next_status
  WHERE id = p_invoice_id;

  -- Excedente da baixa manual: registra restituicao pendente ao cliente.
  IF v_excess > 0.01 THEN
    INSERT INTO public.invoice_refunds (invoice_id, payment_id, amount_brl, status, registered_by, notes)
    VALUES (p_invoice_id, v_payment_id, v_excess, 'pending', v_actor, NULLIF(TRIM(COALESCE(p_notes, '')), ''));
  END IF;

  UPDATE public.bls b
  SET financial_status = 'paid'
  WHERE b.id IN (
    SELECT br.bl_id
    FROM public.bl_receivables br
    WHERE br.id = ANY(v_receivable_ids)
      AND br.balance_brl <= 0.01
  );

  SELECT COUNT(*)
  INTO v_receivables_settled
  FROM public.bl_receivables
  WHERE id = ANY(v_all_receivable_ids)
    AND balance_brl <= 0.01;

  IF v_next_status = 'paid' THEN
    IF COALESCE(v_invoice.invoice_type, 'individual') = 'consolidated' THEN
      WITH covered AS (
        UPDATE public.invoices ind
        SET status = 'covered', covered_by_invoice_id = p_invoice_id
        WHERE ind.id <> p_invoice_id
          AND ind.invoice_type = 'individual'
          AND COALESCE(ind.status, 'issued') IN ('issued', 'partially_paid', 'overdue')
          AND EXISTS (
            SELECT 1
            FROM public.invoice_receivable_links l
            WHERE l.invoice_id = ind.id
              AND l.receivable_id = ANY(v_all_receivable_ids)
          )
        RETURNING ind.id
      )
      SELECT COUNT(*) INTO v_covered FROM covered;

      UPDATE public.invoice_receivable_links
      SET status = 'settled_elsewhere'
      WHERE invoice_id <> p_invoice_id
        AND receivable_id = ANY(v_all_receivable_ids)
        AND status = 'active';

      INSERT INTO public.invoice_lifecycle_events (invoice_id, event_type, related_invoice_id, actor, payload)
      SELECT ind.id, 'covered', p_invoice_id, v_actor,
        jsonb_build_object('reason', 'Coberta por consolidada', 'consolidated_invoice_id', p_invoice_id)
      FROM public.invoices ind
      WHERE ind.covered_by_invoice_id = p_invoice_id
        AND ind.status = 'covered';
    ELSE
      WITH obsoleted AS (
        UPDATE public.invoices con
        SET status = 'obsolete',
            obsolete_reason = 'B/L liquidado por invoice individual ' || COALESCE(v_invoice.invoice_number, p_invoice_id::TEXT)
        WHERE con.id <> p_invoice_id
          AND con.invoice_type = 'consolidated'
          AND COALESCE(con.status, 'issued') IN ('issued', 'partially_paid', 'overdue')
          AND EXISTS (
            SELECT 1
            FROM public.invoice_receivable_links l
            WHERE l.invoice_id = con.id
              AND l.receivable_id = ANY(v_all_receivable_ids)
          )
        RETURNING con.id
      )
      SELECT COUNT(*) INTO v_obsoleted FROM obsoleted;

      UPDATE public.invoice_receivable_links
      SET status = 'obsolete'
      WHERE invoice_id <> p_invoice_id
        AND receivable_id = ANY(v_all_receivable_ids)
        AND invoice_id IN (
          SELECT id FROM public.invoices WHERE invoice_type = 'consolidated' AND status = 'obsolete'
        )
        AND status = 'active';

      INSERT INTO public.invoice_lifecycle_events (invoice_id, event_type, related_invoice_id, actor, payload)
      SELECT con.id, 'obsolete', p_invoice_id, v_actor,
        jsonb_build_object('reason', con.obsolete_reason, 'paid_invoice_id', p_invoice_id)
      FROM public.invoices con
      WHERE con.invoice_type = 'consolidated'
        AND con.status = 'obsolete'
        AND EXISTS (
          SELECT 1
          FROM public.invoice_receivable_links l
          WHERE l.invoice_id = con.id
            AND l.receivable_id = ANY(v_all_receivable_ids)
        );
    END IF;
  END IF;

  INSERT INTO public.invoice_lifecycle_events (invoice_id, event_type, receivable_id, actor, payload)
  VALUES (
    p_invoice_id,
    CASE
      WHEN COALESCE(p_source, 'manual') = 'pix_extract' THEN 'reconciled_by_txid'
      WHEN v_next_status = 'paid' THEN 'paid'
      ELSE 'partially_paid'
    END,
    NULL,
    v_actor,
    jsonb_build_object(
      'amount_brl', p_amount_brl,
      'source', COALESCE(p_source, 'manual'),
      'pix_txid', NULLIF(TRIM(COALESCE(p_pix_txid, '')), ''),
      'status', v_next_status,
      'refund_due_brl', v_excess
    )
  );

  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification)
  VALUES (
    'invoice', p_invoice_id::TEXT, 'ledger_payment',
    COALESCE(v_invoice.balance_brl::TEXT, '0'), v_remaining_open::TEXT, auth.uid(), now(),
    'Baixa via ledger (' || COALESCE(p_source, 'manual') || ')'
  );

  RETURN jsonb_build_object(
    'invoice_id', p_invoice_id,
    'payment_id', v_payment_id,
    'status', v_next_status,
    'amount_brl', p_amount_brl,
    'balance_brl', GREATEST(v_remaining_open, 0),
    'refund_due_brl', v_excess,
    'receivables_settled', v_receivables_settled,
    'individuals_covered', v_covered,
    'consolidated_obsoleted', v_obsoleted
  );
END;
$$;



--
-- Name: register_portal_login_abuse(bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_portal_login_abuse(p_customer_id bigint, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' AND NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;
  RETURN public.block521_upsert_alert(
    'portal_abuso_login', 'customer', p_customer_id::text,
    'Padrão de tentativas de login exige investigação de segurança.',
    'portal_login_security', 'documentacao', COALESCE(p_evidence, '{}'::jsonb),
    '/clientes/portal?cliente=' || p_customer_id
  );
END;
$$;



--
-- Name: reject_customer_reconciliation(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_customer_reconciliation(p_queue_id bigint, p_notes text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_queue RECORD;
  v_actor UUID;
  v_reason TEXT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());
  v_reason := COALESCE(NULLIF(TRIM(COALESCE(p_notes, '')), ''), 'Reconciliacao rejeitada; revisar cliente/manualmente.');

  SELECT *
  INTO v_queue
  FROM public.customer_reconciliation_queue
  WHERE id = p_queue_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Item de reconciliacao % nao encontrado.', p_queue_id USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.bls
  SET
    customer_reconciliation_status = 'rejected',
    customer_reconciliation_notes = v_reason,
    billing_hold_reason = v_reason,
    charge_status = CASE
      WHEN financial_status = 'pending' THEN 'not_calculated'
      ELSE charge_status
    END
  WHERE id = v_queue.bl_id;

  UPDATE public.customer_reconciliation_queue
  SET
    status = 'rejected',
    resolution_notes = v_reason,
    rejected_by = v_actor,
    rejected_at = now(),
    approved_by = NULL,
    approved_at = NULL
  WHERE id = p_queue_id;

  INSERT INTO public.audit_logs (
    entity_type,
    entity_id,
    field_name,
    old_value,
    new_value,
    changed_by,
    changed_at,
    justification
  )
  VALUES (
    'bl',
    v_queue.bl_id,
    'customer_reconciliation_status',
    COALESCE(v_queue.status, 'pending'),
    'rejected',
    v_actor,
    now(),
    v_reason
  );

  RETURN jsonb_build_object(
    'queue_id', p_queue_id,
    'bl_id', v_queue.bl_id,
    'status', 'rejected'
  );
END;
$$;



--
-- Name: reject_deleted_agency_report_deadline_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reject_deleted_agency_report_deadline_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.type = 'agency_report_deadline_missed'
     AND EXISTS (
       SELECT 1
       FROM public.audit_logs d
       WHERE d.entity_type = 'voyage_pod_schedule'
         AND d.entity_id = split_part(NEW.entity_id, '::', 1) || '::' || upper(btrim(split_part(NEW.entity_id, '::', 2)))
         AND d.field_name = 'deleted'
         AND d.new_value = 'true'
         AND NOT EXISTS (
           SELECT 1
           FROM public.audit_logs newer
           WHERE newer.entity_type = d.entity_type
             AND newer.entity_id = d.entity_id
             AND newer.field_name = d.field_name
             AND newer.changed_at > d.changed_at
         )
     ) THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: release_customer_communication_automation_claim(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_customer_communication_automation_claim(p_claim_key text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Executor server-only.' USING ERRCODE = '42501';
  END IF;

  IF p_claim_key IS NULL OR btrim(p_claim_key) = '' THEN
    RAISE EXCEPTION 'Chave da claim e obrigatoria.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.customer_communication_automation_claims
  SET released_at = COALESCE(released_at, now())
  WHERE claim_key = p_claim_key
    AND released_at IS NULL;

  RETURN FOUND;
END;
$$;



--
-- Name: release_demurrage_dunning_claim(bigint, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_demurrage_dunning_claim(p_demurrage_invoice_id bigint, p_attempt_discriminator integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Executor server-only.' USING ERRCODE = '42501';
  END IF;

  IF p_demurrage_invoice_id IS NULL
     OR p_attempt_discriminator IS NULL
     OR p_attempt_discriminator < 1 THEN
    RAISE EXCEPTION 'Invoice e posição da régua são obrigatórios.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.demurrage_dunning_claims
  SET released_at = COALESCE(released_at, now())
  WHERE demurrage_invoice_id = p_demurrage_invoice_id
    AND attempt_discriminator = p_attempt_discriminator
    AND released_at IS NULL;

  RETURN FOUND;
END;
$$;



--
-- Name: relink_bl_customer(text, bigint, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.relink_bl_customer(p_bl_id text, p_customer_id bigint, p_changed_by uuid, p_reason text DEFAULT 'Troca de consignatario na reimportacao do B/L'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl public.bls%ROWTYPE;
  v_blockers TEXT[] := ARRAY[]::TEXT[];
  v_invoice RECORD;
  v_moved_invoices TEXT[] := ARRAY[]::TEXT[];
  v_has_financials BOOLEAN;
  v_settled_receivables INTEGER;
  v_status TEXT;
BEGIN
  SELECT * INTO v_bl FROM public.bls WHERE id = p_bl_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('bl_id', p_bl_id, 'applied', false, 'blockers', ARRAY['B/L nao encontrado.']);
  END IF;

  IF v_bl.customer_id IS NOT DISTINCT FROM p_customer_id THEN
    RETURN jsonb_build_object('bl_id', p_bl_id, 'applied', false, 'blockers', ARRAY[]::TEXT[], 'unchanged', true);
  END IF;

  IF p_customer_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.customers WHERE id = p_customer_id) THEN
    RETURN jsonb_build_object(
      'bl_id', p_bl_id,
      'applied', false,
      'blockers', ARRAY['Cliente de destino nao existe.']
    );
  END IF;

  -- Uma fatura só troca de dono enquanto ninguém pagou nada nela e ela cobre
  -- apenas este B/L. Consolidada ou com pagamento, transferir reescreveria
  -- histórico de recebimento — vira trabalho manual do financeiro.
  FOR v_invoice IN
    SELECT
      i.id,
      i.invoice_number,
      i.status,
      i.total_paid_brl,
      (SELECT COUNT(*) FROM public.invoice_bls AS ib2 WHERE ib2.invoice_id = i.id) AS bl_count
    FROM public.invoice_bls AS ib
    JOIN public.invoices AS i ON i.id = ib.invoice_id
    WHERE ib.bl_id = p_bl_id
      AND i.status NOT IN ('cancelled', 'obsolete')
    ORDER BY i.id
  LOOP
    IF v_invoice.bl_count > 1 THEN
      v_blockers := array_append(
        v_blockers,
        format('Fatura %s e consolidada com outros B/Ls.', v_invoice.invoice_number)
      );
    ELSIF COALESCE(v_invoice.total_paid_brl, 0) > 0 OR v_invoice.status = 'paid' THEN
      v_blockers := array_append(
        v_blockers,
        format('Fatura %s ja tem pagamento registrado.', v_invoice.invoice_number)
      );
    END IF;
  END LOOP;

  FOR v_invoice IN
    SELECT id, doc_number, status
    FROM public.demurrage_invoices
    WHERE bl_id = p_bl_id
      AND COALESCE(status, '') NOT IN ('cancelled', 'obsolete')
    ORDER BY id
  LOOP
    IF v_invoice.status = 'paid' THEN
      v_blockers := array_append(
        v_blockers,
        format('Demurrage %s ja esta quitada.', v_invoice.doc_number)
      );
    END IF;
  END LOOP;

  -- O razão guarda a baixa mesmo quando a fatura que a originou foi reemitida
  -- (`obsolete`, portanto invisível para a varredura acima). Recebível com
  -- pagamento parcial ou total não muda de dono: `ledger_settlements` ficaria
  -- pendurado em quem nunca pagou.
  SELECT COUNT(*) INTO v_settled_receivables
  FROM public.bl_receivables
  WHERE bl_id = p_bl_id
    AND status <> 'void'
    AND COALESCE(settled_amount_brl, 0) > 0;

  IF v_settled_receivables > 0 THEN
    v_blockers := array_append(
      v_blockers,
      'Recebivel do B/L ja tem baixa registrada; estorne no razao antes de trocar o cliente.'
    );
  END IF;

  v_has_financials :=
    EXISTS (
      SELECT 1
      FROM public.invoice_bls AS ib
      JOIN public.invoices AS i ON i.id = ib.invoice_id
      WHERE ib.bl_id = p_bl_id AND i.status NOT IN ('cancelled', 'obsolete')
    )
    OR EXISTS (SELECT 1 FROM public.bl_receivables WHERE bl_id = p_bl_id AND status <> 'void')
    OR EXISTS (
      SELECT 1 FROM public.demurrage_invoices
      WHERE bl_id = p_bl_id AND COALESCE(status, '') NOT IN ('cancelled', 'obsolete')
    );

  -- Sem cliente de destino cadastrado não há para onde mover a cobrança:
  -- `bl_receivables.customer_id` e `invoices.customer_id` são NOT NULL.
  IF p_customer_id IS NULL AND v_has_financials THEN
    v_blockers := array_append(
      v_blockers,
      'Novo consignatario nao esta cadastrado como cliente; cadastre-o antes de trocar o B/L faturado.'
    );
  END IF;

  IF cardinality(v_blockers) > 0 THEN
    RETURN jsonb_build_object('bl_id', p_bl_id, 'applied', false, 'blockers', v_blockers);
  END IF;

  UPDATE public.bls
  SET
    customer_id = p_customer_id,
    customer_reconciliation_status = CASE WHEN p_customer_id IS NULL THEN 'missing_customer' ELSE 'reconciled' END,
    customer_reconciliation_notes = CASE
      WHEN p_customer_id IS NULL THEN 'Consignatario reimportado ainda sem cliente cadastrado.'
      ELSE 'Cliente trocado pela reimportacao do B/L (novo consignatario).'
    END,
    billing_hold_reason = CASE
      WHEN p_customer_id IS NULL THEN 'Aguardando reconciliacao de cliente antes do faturamento.'
      ELSE NULL
    END
  WHERE id = p_bl_id;

  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES ('bl', p_bl_id, 'customer_id', v_bl.customer_id::TEXT, p_customer_id::TEXT, p_changed_by, p_reason);

  IF p_customer_id IS NOT NULL THEN
    -- O valor devido não muda; muda o cliente vinculado à fatura.
    FOR v_invoice IN
      SELECT i.id, i.invoice_number, i.customer_id
      FROM public.invoice_bls AS ib
      JOIN public.invoices AS i ON i.id = ib.invoice_id
      WHERE ib.bl_id = p_bl_id
        AND i.status NOT IN ('cancelled', 'obsolete')
        AND i.customer_id IS DISTINCT FROM p_customer_id
      ORDER BY i.id
    LOOP
      UPDATE public.invoices SET customer_id = p_customer_id, updated_at = now() WHERE id = v_invoice.id;
      v_moved_invoices := array_append(v_moved_invoices, v_invoice.invoice_number);

      INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
      VALUES ('invoice', v_invoice.id::TEXT, 'customer_id', v_invoice.customer_id::TEXT, p_customer_id::TEXT, p_changed_by, p_reason);
    END LOOP;

    FOR v_invoice IN
      SELECT id, doc_number, customer_id
      FROM public.demurrage_invoices
      WHERE bl_id = p_bl_id
        AND COALESCE(status, '') NOT IN ('cancelled', 'obsolete')
        AND customer_id IS DISTINCT FROM p_customer_id
      ORDER BY id
    LOOP
      UPDATE public.demurrage_invoices SET customer_id = p_customer_id, updated_at = now() WHERE id = v_invoice.id;
      v_moved_invoices := array_append(v_moved_invoices, v_invoice.doc_number);

      -- `bl_timeline` (migration 130) só resolve 'bl', 'invoice', 'bl_container',
      -- 'charge_calculation' e 'system_event'; a linha própria da demurrage já
      -- é gravada pelo trigger genérico (294), e esta entra sob o B/L para a
      -- troca aparecer no Histórico com a justificativa.
      INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
      VALUES ('bl', p_bl_id, format('demurrage_%s_customer_id', v_invoice.doc_number), v_invoice.customer_id::TEXT, p_customer_id::TEXT, p_changed_by, p_reason);
    END LOOP;

    -- Recebível `void` é história encerrada do cliente antigo e fica onde está.
    UPDATE public.bl_receivables
    SET customer_id = p_customer_id, updated_at = now()
    WHERE bl_id = p_bl_id
      AND status <> 'void'
      AND customer_id IS DISTINCT FROM p_customer_id;
  END IF;

  PERFORM public.sync_customer_reconciliation_queue_for_bl(p_bl_id);

  SELECT review_status INTO v_status FROM public.bls WHERE id = p_bl_id;

  RETURN jsonb_build_object(
    'bl_id', p_bl_id,
    'applied', true,
    'blockers', ARRAY[]::TEXT[],
    'from_customer_id', v_bl.customer_id,
    'to_customer_id', p_customer_id,
    'moved_invoices', to_jsonb(v_moved_invoices),
    'review_status', v_status
  );
END;
$$;



--
-- Name: reopen_agency_departure_report(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_agency_departure_report(p_voyage_id bigint, p_port text, p_justification text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_report_id UUID;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;
  IF btrim(COALESCE(p_justification, '')) = '' THEN
    RAISE EXCEPTION 'Reabertura exige justificativa.' USING ERRCODE = '22023';
  END IF;
  SELECT id INTO v_report_id
  FROM public.agency_departure_reports
  WHERE voyage_id = p_voyage_id
    AND port = upper(btrim(p_port))
    AND status = 'closed'
    AND terminal_id IS NULL
  FOR UPDATE;
  IF v_report_id IS NULL THEN
    RAISE EXCEPTION 'ADR nao esta fechado.' USING ERRCODE = 'P0002';
  END IF;
  UPDATE public.agency_departure_reports
  SET status = 'open', closed_at = NULL, closed_by = NULL, closed_snapshot = NULL
  WHERE id = v_report_id;
  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES ('agency_departure_report', p_voyage_id || '::' || upper(btrim(p_port)),
          'status', 'closed', 'open', auth.uid(), btrim(p_justification));
  RETURN jsonb_build_object('report_id', v_report_id);
END;
$$;



--
-- Name: reopen_agency_departure_report_by_report_id(uuid, bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_agency_departure_report_by_report_id(p_report_id uuid, p_voyage_id bigint, p_port text, p_justification text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_report RECORD;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501'; END IF;
  IF btrim(COALESCE(p_justification, '')) = '' THEN RAISE EXCEPTION 'Reabertura exige justificativa.' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_report FROM public.agency_departure_reports WHERE id = p_report_id FOR UPDATE;
  IF NOT FOUND OR v_report.voyage_id <> p_voyage_id OR upper(btrim(v_report.port)) <> upper(btrim(p_port))
     OR v_report.terminal_id IS NULL THEN RAISE EXCEPTION 'report_id nao pertence a ADR terminalizado da escala %::%.', p_voyage_id, upper(btrim(p_port)) USING ERRCODE = '23514'; END IF;
  IF v_report.status <> 'closed' THEN RAISE EXCEPTION 'ADR nao esta fechado.' USING ERRCODE = 'P0002'; END IF;
  UPDATE public.agency_departure_reports SET status = 'open', closed_at = NULL, closed_by = NULL, closed_snapshot = NULL WHERE id = p_report_id;
  -- Reabrir destrava a edição sem apagar decisões, assinaturas ou histórico.
  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES ('agency_departure_report', p_report_id::TEXT, 'status', 'closed', 'open', auth.uid(), btrim(p_justification));
  RETURN jsonb_build_object('report_id', p_report_id);
END;
$$;



--
-- Name: reopen_demurrage_dispute(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_demurrage_dispute(p_dispute_id bigint, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := public._portal_actor_role();
  v_dispute public.demurrage_disputes%ROWTYPE;
BEGIN
  IF v_role <> 'equipamentos' THEN RAISE EXCEPTION 'Apenas Equipamentos pode reabrir a Dispute.' USING ERRCODE = '42501'; END IF;
  IF NULLIF(btrim(p_reason), '') IS NULL THEN RAISE EXCEPTION 'Justificativa é obrigatória.' USING ERRCODE = '22023'; END IF;
  SELECT * INTO v_dispute FROM public.demurrage_disputes WHERE id = p_dispute_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dispute não encontrada.' USING ERRCODE = 'P0002'; END IF;
  UPDATE public.demurrage_disputes SET state = 'aberta', next_responder = 'equipamentos', resolved_at = NULL, cancelled_at = NULL WHERE id = p_dispute_id;
  INSERT INTO public.demurrage_dispute_messages(dispute_id, author_id, author_type, body, next_responder, metadata)
  VALUES (p_dispute_id, auth.uid(), 'equipamentos', btrim(p_reason), 'equipamentos', jsonb_build_object('action', 'reopen'));
  UPDATE public.demurrage_invoices SET dispute_open = true, dispute_status = 'aberto' WHERE id = v_dispute.demurrage_invoice_id;
  PERFORM public.block521_upsert_alert('portal_dispute_opened', 'demurrage_invoice', v_dispute.demurrage_invoice_id::text, 'Dispute reaberta; análise de Equipamentos pendente.', 'portal_dispute_reopened', 'equipamentos', jsonb_build_object('dispute_id', p_dispute_id), '/demurrage?dispute=' || p_dispute_id);
END;
$$;



--
-- Name: reopen_pix_exception_for_authority_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_pix_exception_for_authority_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payload JSONB := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  v_invoice_id BIGINT := NULLIF(v_payload->>'invoice_id', '')::BIGINT;
  v_demurrage_invoice_id BIGINT := NULLIF(v_payload->>'id', '')::BIGINT;
  v_exception RECORD;
BEGIN
  IF TG_TABLE_NAME = 'ledger_settlements' THEN
    FOR v_exception IN
      SELECT id FROM public.pix_reconciliation_exceptions
      WHERE status = 'resolved' AND resolved_invoice_id = v_invoice_id
    LOOP
      PERFORM public.reopen_pix_reconciliation_exception(v_exception.id, 'ledger_settlement_reverted_or_changed');
    END LOOP;
  ELSIF TG_TABLE_NAME = 'demurrage_invoices' THEN
    FOR v_exception IN
      SELECT id FROM public.pix_reconciliation_exceptions
      WHERE status = 'resolved' AND resolved_demurrage_invoice_id = v_demurrage_invoice_id
    LOOP
      PERFORM public.reopen_pix_reconciliation_exception(v_exception.id, 'demurrage_payment_reverted_or_changed');
    END LOOP;
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$$;



--
-- Name: reopen_pix_reconciliation_exception(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_pix_reconciliation_exception(p_exception_id bigint, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_exception public.pix_reconciliation_exceptions%ROWTYPE;
BEGIN
  SELECT * INTO v_exception
  FROM public.pix_reconciliation_exceptions
  WHERE id = p_exception_id
  FOR UPDATE;
  IF NOT FOUND OR v_exception.status <> 'resolved' THEN
    RETURN;
  END IF;
  IF public.pix_reconciliation_authority_holds(p_exception_id) THEN
    RETURN;
  END IF;

  UPDATE public.pix_reconciliation_exceptions
  SET status = 'active', resolved_at = NULL, resolved_by = NULL,
      resolution_source = NULL, resolved_invoice_id = NULL,
      resolved_demurrage_invoice_id = NULL,
      metadata = metadata || jsonb_build_object('reopened_reason', COALESCE(p_reason, 'authority_invalidated')),
      updated_at = now()
  WHERE id = v_exception.id;

  PERFORM set_config('alerts.foundation_trigger', 'on', true);
  PERFORM public.upsert_alert_item(
    'pix_unreconciled', 'pix_transaction', v_exception.id::TEXT,
    format('PIX sem conciliacao na linha %s do import %s.', v_exception.line_number, v_exception.import_key),
    'pix_authority_invalidated',
    jsonb_build_object('exception_id', v_exception.id, 'reason', COALESCE(p_reason, 'authority_invalidated')) || v_exception.metadata,
    '/reconciliacao'
  );
  PERFORM set_config('alerts.foundation_trigger', 'off', true);
END;
$$;



--
-- Name: reorder_vessel_schedules(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reorder_vessel_schedules(p_order jsonb) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_requested_count INTEGER;
  v_locked_count INTEGER;
  v_updated_count INTEGER;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Credenciais invalidas para reordenar navios.'
      USING ERRCODE = '42501';
  END IF;

  IF jsonb_typeof(p_order) <> 'array' OR jsonb_array_length(p_order) = 0 THEN
    RAISE EXCEPTION 'Ordem de navios invalida.' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*), COUNT(DISTINCT item.id), COUNT(DISTINCT item.display_order)
  INTO v_requested_count, v_locked_count, v_updated_count
  FROM jsonb_to_recordset(p_order) AS item(id UUID, display_order INTEGER);

  IF v_requested_count <> v_locked_count
     OR v_requested_count <> v_updated_count THEN
    RAISE EXCEPTION 'A ordem contem navios ou posicoes duplicadas.'
      USING ERRCODE = '22023';
  END IF;

  PERFORM vessel.id
  FROM public.vessel_schedules AS vessel
  JOIN jsonb_to_recordset(p_order) AS item(id UUID, display_order INTEGER)
    ON item.id = vessel.id
  FOR UPDATE OF vessel;

  GET DIAGNOSTICS v_locked_count = ROW_COUNT;
  IF v_locked_count <> v_requested_count THEN
    RAISE EXCEPTION 'A lista de navios mudou; recarregue antes de reordenar.'
      USING ERRCODE = '40001';
  END IF;

  UPDATE public.vessel_schedules AS vessel
  SET display_order = item.display_order
  FROM jsonb_to_recordset(p_order) AS item(id UUID, display_order INTEGER)
  WHERE vessel.id = item.id;

  GET DIAGNOSTICS v_updated_count = ROW_COUNT;
  IF v_updated_count <> v_requested_count THEN
    RAISE EXCEPTION 'Nem todos os navios foram reordenados.'
      USING ERRCODE = '40001';
  END IF;

  RETURN v_updated_count;
END;
$$;



--
-- Name: replace_vazios_from_baplie_transactional(bigint, text, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_vazios_from_baplie_transactional(p_voyage_id bigint, p_description text, p_uploaded_by uuid, p_replace_existing boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_manifest_id UUID;
  v_total INTEGER;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR p_uploaded_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para importar vazios Baplie.' USING ERRCODE = '42501';
  END IF;

  SELECT count(*)::INTEGER
  INTO v_total
  FROM public.baplie_containers
  WHERE voyage_id = p_voyage_id AND status = 'empty';

  IF v_total = 0 THEN
    RAISE EXCEPTION 'Nenhum container vazio encontrado no Baplie desta viagem.'
      USING ERRCODE = 'P0002';
  END IF;

  IF p_replace_existing THEN
    DELETE FROM public.vazios_importacao_manifests
    WHERE voyage_id = p_voyage_id AND source = 'baplie';
  ELSIF EXISTS (
    SELECT 1 FROM public.vazios_importacao_manifests
    WHERE voyage_id = p_voyage_id AND source = 'baplie'
  ) THEN
    RAISE EXCEPTION 'Ja existe manifesto Baplie para esta viagem.'
      USING ERRCODE = '23505';
  END IF;

  INSERT INTO public.vazios_importacao_manifests (
    voyage_id, description, total_containers, imported_by, source
  )
  VALUES (
    p_voyage_id, COALESCE(p_description, 'Importado via Baplie EDI'),
    v_total, p_uploaded_by, 'baplie'
  )
  RETURNING id INTO v_manifest_id;

  INSERT INTO public.vazios_importacao_containers (
    manifest_id, container_number, container_type, tare_kg, pol, pod
  )
  SELECT v_manifest_id, container_number, size_type, weight_kg, pol, pod
  FROM public.baplie_containers
  WHERE voyage_id = p_voyage_id AND status = 'empty';

  RETURN jsonb_build_object('manifest_id', v_manifest_id, 'total', v_total);
END;
$$;



--
-- Name: reprocess_customer_billing_after_portal_activation(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reprocess_customer_billing_after_portal_activation(p_customer_id bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor UUID;
  v_bl RECORD;
  v_issued INTEGER := 0;
  v_blocked INTEGER := 0;
  v_failed INTEGER := 0;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Executor server-only.' USING ERRCODE = '42501'; END IF;
  SELECT id INTO v_actor FROM public.user_profiles WHERE active AND role IN ('admin', 'administrativo') ORDER BY created_at, id LIMIT 1;
  IF v_actor IS NULL THEN RAISE EXCEPTION 'Não há usuário Administrativo ativo para reprocessar faturamento.' USING ERRCODE = 'P0002'; END IF;
  PERFORM set_config('request.jwt.claim.sub', v_actor::text, true);
  PERFORM set_config('request.jwt.claim.role', 'authenticated', true);

  FOR v_bl IN
    SELECT b.id, b.customer_id, b.customer_reconciliation_status
    FROM public.bls b
    WHERE b.customer_id = p_customer_id
      AND b.financial_status IS DISTINCT FROM 'cancelled'
      AND COALESCE(b.financial_status, 'pending') = 'pending'
      AND b.customer_reconciliation_status IN ('matched_document', 'reconciled')
    ORDER BY b.id
  LOOP
    BEGIN
      PERFORM public.mark_bl_ready_and_create_invoice(v_bl.id, p_customer_id, NULL, 'Reprocessamento idempotente após ativação do Portal.', v_actor);
      v_issued := v_issued + 1;
      PERFORM public.block521_resolve_alert('portal_reprocessamento_falhou', 'bl', v_bl.id, 'documentacao', 'portal_activation');
    EXCEPTION WHEN OTHERS THEN
      IF SQLSTATE IN ('P0003', '22023', 'P0002', 'P0004') THEN
        v_blocked := v_blocked + 1;
      ELSE
        v_failed := v_failed + 1;
        PERFORM public.block521_upsert_alert('portal_reprocessamento_falhou', 'bl', v_bl.id, 'Falha técnica ao reprocessar faturamento após ativação do Portal.', 'portal_activation', 'documentacao', jsonb_build_object('sqlstate', SQLSTATE, 'error', SQLERRM), '/manifestos/' || v_bl.id || '?tab=faturamento');
      END IF;
    END;
  END LOOP;
  RETURN jsonb_build_object('customer_id', p_customer_id, 'issued', v_issued, 'blocked', v_blocked, 'failed', v_failed);
END;
$$;



--
-- Name: resolve_alert_item(text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_alert_item(p_type text, p_entity_type text, p_entity_id text, p_source text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item RECORD;
  v_found BOOLEAN := false;
BEGIN
  IF NOT public.alert_actor_is_authorized() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;
  FOR v_item IN
    SELECT i.id, i.alert_id, i.occurrence_id
    FROM public.alert_items i
    JOIN public.alerts a ON a.id = i.alert_id
    WHERE i.item_type = p_type
      AND a.entity_type = p_entity_type
      AND a.entity_id = p_entity_id
      AND i.status = 'active'
    FOR UPDATE
  LOOP
    v_found := true;
    UPDATE public.alert_items
    SET status = 'resolved', updated_at = now(), resolved_at = now()
    WHERE id = v_item.id;
    INSERT INTO public.alert_item_events(
      alert_item_id, occurrence_id, event_type, previous_status,
      new_status, actor_id, metadata
    ) VALUES (
      v_item.id, v_item.occurrence_id, 'resolved', 'active', 'resolved',
      auth.uid(), COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('source', p_source)
    );
    PERFORM public.refresh_alert_aggregate(v_item.alert_id);
  END LOOP;
  RETURN v_found;
END;
$$;



--
-- Name: resolve_alert_item_for_department(text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_alert_item_for_department(p_type text, p_entity_type text, p_entity_id text, p_department text, p_source text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item public.alert_items%ROWTYPE;
  v_alert_id BIGINT;
BEGIN
  IF NOT public.alert_actor_is_authorized() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;
  SELECT i.* INTO v_item
  FROM public.alert_items i
  JOIN public.alerts a ON a.id = i.alert_id
  WHERE i.item_type = p_type
    AND i.department = p_department
    AND a.entity_type = p_entity_type
    AND a.entity_id = p_entity_id
    AND i.status = 'active'
  FOR UPDATE;
  IF NOT FOUND THEN RETURN false; END IF;

  v_alert_id := v_item.alert_id;
  UPDATE public.alert_items
  SET status = 'resolved', updated_at = now(), resolved_at = now()
  WHERE id = v_item.id;
  INSERT INTO public.alert_item_events (
    alert_item_id, occurrence_id, event_type, previous_status, new_status,
    actor_id, metadata
  )
  VALUES (
    v_item.id, v_item.occurrence_id, 'resolved', 'active', 'resolved',
    auth.uid(), COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('source', p_source)
  );
  PERFORM public.refresh_alert_aggregate(v_alert_id);
  RETURN true;
END;
$$;



--
-- Name: resolve_billing_alert(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_billing_alert(p_type text, p_bl_id text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_active_user() THEN RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501'; END IF;
  IF p_type NOT IN ('billing_calculation_blocked', 'billing_auto_issue_failed') THEN
    RAISE EXCEPTION 'Tipo de faturamento inválido.' USING ERRCODE = '22023';
  END IF;
  RETURN public.resolve_alert_item(p_type, 'bl', p_bl_id, 'billing_client_compatibility', p_metadata);
END;
$$;



--
-- Name: resolve_bl_local_charge_items(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_bl_local_charge_items(p_bl_id text, p_pod text) RETURNS TABLE(charge_table_id bigint, charge_item_id bigint, quantity numeric, unit_value_brl numeric, unit_value_usd numeric, total_value_brl numeric, total_value_usd numeric, override_applied boolean, source text, status text, calculation_key text, review_reason text, notes text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_bl RECORD;
  v_table_id BIGINT;
  v_ref_date DATE;
  v_qty_total NUMERIC(12,6) := 0;
  v_qty_std NUMERIC(12,6) := 0;
  v_qty_imo NUMERIC(12,6) := 0;
  v_qty_oog NUMERIC(12,6) := 0;
  v_qty_dual NUMERIC(12,6) := 0;
  v_container_shares JSONB;
  v_weight_ton NUMERIC(12,3);
  v_qty NUMERIC(12,6);
  v_unit_brl NUMERIC(12,2);
  v_unit_usd NUMERIC(12,2);
  v_total_line_brl NUMERIC(14,2);
  v_total_line_usd NUMERIC(14,2);
  v_is_thd BOOLEAN;
  v_override BOOLEAN;
  item RECORD;
BEGIN
  SELECT
    b.id,
    b.voyage_id,
    COALESCE(b.cargo_mode, 'container') AS cargo_mode,
    b.customer_id,
    NULLIF((to_jsonb(b)->>'bb_weight_ton'), '')::NUMERIC AS bb_weight_ton,
    b.total_weight_kg
  INTO v_bl
  FROM public.bls AS b
  WHERE b.id = p_bl_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

-- A vigência da tabela é informativa; a data só participa do override.
  SELECT v_eta_raw.eta_text::DATE
  INTO v_ref_date
  FROM public.voyages AS v
  CROSS JOIN LATERAL (
    SELECT NULLIF(TRIM(v.pod_schedule_snapshot -> p_pod ->> 'eta'), '') AS eta_text
  ) AS v_eta_raw
  WHERE v.id = v_bl.voyage_id
    AND v_eta_raw.eta_text ~ '^\d{4}-\d{2}-\d{2}$';

  IF v_ref_date IS NULL THEN
    SELECT v.eta::DATE
    INTO v_ref_date
    FROM public.voyages AS v
    WHERE v.id = v_bl.voyage_id
      AND v.eta IS NOT NULL;
  END IF;

  v_ref_date := COALESCE(v_ref_date, CURRENT_DATE);
  v_table_id := public.resolve_local_charge_table_id(v_bl.cargo_mode, p_pod, v_ref_date);

  IF v_table_id IS NULL THEN
    RETURN;
  END IF;

  IF v_bl.cargo_mode = 'container' THEN
    WITH current_containers AS (
      SELECT
        UPPER(TRIM(bc.container_number)) AS cn,
        BOOL_OR(COALESCE(bc.is_imo, false)) AS has_imo,
        BOOL_OR(COALESCE(bc.is_oog, false)) AS has_oog
      FROM public.bl_containers AS bc
      WHERE bc.bl_id = p_bl_id
        AND TRIM(COALESCE(bc.container_number, '')) <> ''
      GROUP BY UPPER(TRIM(bc.container_number))
    ),
    shares AS (
      SELECT
        cc.cn,
        cc.has_imo,
        cc.has_oog,
        sh.share_count,
        sh.last_bl_id
      FROM current_containers AS cc
      JOIN LATERAL (
        SELECT
          COUNT(DISTINCT b2.id)::NUMERIC AS share_count,
          MAX(b2.id) AS last_bl_id
        FROM public.bls AS b2
        JOIN public.bl_containers AS bc2 ON bc2.bl_id = b2.id
        WHERE b2.voyage_id = v_bl.voyage_id
          AND COALESCE(b2.cargo_mode, 'container') = 'container'
          AND UPPER(TRIM(COALESCE(bc2.container_number, ''))) = cc.cn
      ) AS sh ON TRUE
    )
    SELECT
      COALESCE(SUM(CASE WHEN share_count > 0 THEN 1 / share_count ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN NOT has_imo AND NOT has_oog AND share_count > 0 THEN 1 / share_count ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN has_imo AND NOT has_oog AND share_count > 0 THEN 1 / share_count ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN has_oog AND NOT has_imo AND share_count > 0 THEN 1 / share_count ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN has_imo AND has_oog AND share_count > 0 THEN 1 / share_count ELSE 0 END), 0),
      jsonb_agg(jsonb_build_object(
        'has_imo', has_imo,
        'has_oog', has_oog,
        'share_count', share_count,
        'is_last', (p_bl_id = last_bl_id)
      )) FILTER (WHERE share_count > 0)
    INTO v_qty_total, v_qty_std, v_qty_imo, v_qty_oog, v_qty_dual, v_container_shares
    FROM shares;
  END IF;

  FOR item IN
    SELECT
      cti.id,
      cti.name,
      cti.application_basis,
      COALESCE(cti.cargo_profile, 'any') AS cargo_profile,
      COALESCE(cti.currency, 'BRL') AS currency,
      cti.unit_value_brl,
      cti.unit_value_usd,
      ov.override_value
    FROM public.charge_table_items AS cti
    LEFT JOIN LATERAL (
      SELECT cro.override_value
      FROM public.customer_rate_overrides AS cro
      WHERE cro.customer_id = v_bl.customer_id
        AND cro.charge_item_id = cti.id
        AND (cro.valid_from IS NULL OR cro.valid_from <= v_ref_date)
        AND (cro.valid_to IS NULL OR cro.valid_to >= v_ref_date)
      LIMIT 1
    ) AS ov ON TRUE
    WHERE cti.charge_table_id = v_table_id
      AND COALESCE(cti.active, true)
      AND NOT COALESCE(cti.manual_only, false)
    ORDER BY COALESCE(cti.sort_order, 100), cti.id
  LOOP
    charge_table_id := v_table_id;
    charge_item_id := item.id;
    quantity := 0;
    unit_value_brl := NULL;
    unit_value_usd := NULL;
    total_value_brl := 0;
    total_value_usd := NULL;
    override_applied := false;
    source := 'auto';
    status := 'review_required';
    calculation_key := NULL;
    review_reason := NULL;
    notes := 'Revisao manual obrigatoria';

    v_qty := 0;
    v_is_thd := UPPER(COALESCE(item.name, '')) LIKE 'THD%';

    IF item.application_basis = 'bl' THEN
      v_qty := 1;
    -- Ramo 1 da 274: item por tonelada sem peso utilizável.
    ELSIF item.application_basis = 'weight_ton' THEN
      v_weight_ton := COALESCE(
        v_bl.bb_weight_ton,
        CASE WHEN v_bl.total_weight_kg IS NULL THEN NULL ELSE v_bl.total_weight_kg / 1000 END,
        0
      );
      IF v_weight_ton <= 0 THEN
        calculation_key := CONCAT('review:weight_missing:', item.id);
        review_reason := 'Weight ton ausente/invalido para calculo';
        RETURN NEXT;
        CONTINUE;
      END IF;
      v_qty := v_weight_ton;
    ELSIF item.application_basis = 'container_distinct_voyage' THEN
      IF v_bl.cargo_mode = 'container' THEN
        IF v_is_thd THEN
          IF item.cargo_profile = 'standard' THEN
            v_qty := v_qty_std;
          ELSIF item.cargo_profile = 'imo' THEN
            v_qty := v_qty_imo;
          ELSIF item.cargo_profile = 'oog' THEN
            v_qty := v_qty_oog;
          ELSE
            -- Ramo 2 da 274: THD sem perfil que o motor saiba distinguir.
            calculation_key := CONCAT('review:thd_any_profile:', item.id);
            review_reason := 'Item THD cadastrado com perfil de carga ''any''; motor so calcula standard/imo/oog';
            notes := 'Revisao manual obrigatoria';
            RETURN NEXT;
            CONTINUE;
          END IF;
        ELSE
          v_qty := v_qty_total;
        END IF;
      END IF;
    ELSE
      -- Ramo 3 da 274: base de aplicação não implementada pelo motor.
      calculation_key := CONCAT('review:unsupported_basis:', item.id);
      review_reason := CONCAT('Base de aplicacao nao suportada pelo motor: ', COALESCE(item.application_basis, '(vazia)'));
      RETURN NEXT;
      CONTINUE;
    END IF;

    IF COALESCE(v_qty, 0) <= 0 THEN
      CONTINUE;
    END IF;

    -- Ramo 4 da 274: item resolvido e pronto para o INSERT do RPC pai.
    status := 'calculated';
    notes := NULL;
    calculation_key := CONCAT('auto:item:', item.id);
    v_override := item.override_value IS NOT NULL;
    override_applied := v_override;
    v_unit_brl := COALESCE(item.override_value, item.unit_value_brl, 0);
    v_unit_usd := item.unit_value_usd;
    quantity := v_qty;
    unit_value_brl := CASE WHEN item.currency = 'USD' THEN NULL ELSE v_unit_brl END;
    unit_value_usd := CASE WHEN item.currency = 'USD' THEN v_unit_usd ELSE NULL END;

    IF item.application_basis = 'container_distinct_voyage' AND v_bl.cargo_mode = 'container' THEN
      IF item.currency = 'USD' THEN
        SELECT COALESCE(SUM(
          CASE WHEN (elem->>'is_last')::BOOLEAN
            THEN COALESCE(v_unit_usd, 0) - ((elem->>'share_count')::NUMERIC - 1) * ROUND(COALESCE(v_unit_usd, 0) / (elem->>'share_count')::NUMERIC, 2)
            ELSE ROUND(COALESCE(v_unit_usd, 0) / (elem->>'share_count')::NUMERIC, 2)
          END
        ), 0)
        INTO v_total_line_usd
        FROM jsonb_array_elements(COALESCE(v_container_shares, '[]'::jsonb)) AS elem
        WHERE
          NOT v_is_thd
          OR (item.cargo_profile = 'standard' AND NOT (elem->>'has_imo')::BOOLEAN AND NOT (elem->>'has_oog')::BOOLEAN)
          OR (item.cargo_profile = 'imo' AND (elem->>'has_imo')::BOOLEAN AND NOT (elem->>'has_oog')::BOOLEAN)
          OR (item.cargo_profile = 'oog' AND (elem->>'has_oog')::BOOLEAN AND NOT (elem->>'has_imo')::BOOLEAN);
        v_total_line_brl := NULL;
      ELSE
        SELECT COALESCE(SUM(
          CASE WHEN (elem->>'is_last')::BOOLEAN
            THEN COALESCE(v_unit_brl, 0) - ((elem->>'share_count')::NUMERIC - 1) * ROUND(COALESCE(v_unit_brl, 0) / (elem->>'share_count')::NUMERIC, 2)
            ELSE ROUND(COALESCE(v_unit_brl, 0) / (elem->>'share_count')::NUMERIC, 2)
          END
        ), 0)
        INTO v_total_line_brl
        FROM jsonb_array_elements(COALESCE(v_container_shares, '[]'::jsonb)) AS elem
        WHERE
          NOT v_is_thd
          OR (item.cargo_profile = 'standard' AND NOT (elem->>'has_imo')::BOOLEAN AND NOT (elem->>'has_oog')::BOOLEAN)
          OR (item.cargo_profile = 'imo' AND (elem->>'has_imo')::BOOLEAN AND NOT (elem->>'has_oog')::BOOLEAN)
          OR (item.cargo_profile = 'oog' AND (elem->>'has_oog')::BOOLEAN AND NOT (elem->>'has_imo')::BOOLEAN);
        v_total_line_usd := NULL;
      END IF;
    ELSE
      v_total_line_brl := CASE WHEN item.currency = 'USD' THEN NULL ELSE ROUND(v_qty * COALESCE(v_unit_brl, 0), 2) END;
      v_total_line_usd := CASE WHEN item.currency = 'USD' THEN ROUND(v_qty * COALESCE(v_unit_usd, 0), 2) ELSE NULL END;
    END IF;

    total_value_brl := v_total_line_brl;
    total_value_usd := v_total_line_usd;
    RETURN NEXT;
  END LOOP;
END;
$_$;



--
-- Name: resolve_customer_contact_bounce_alert_on_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_customer_contact_bounce_alert_on_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NULLIF(btrim(NEW.email), '') IS NOT NULL
     AND NOT EXISTS (
       SELECT 1 FROM public.portal_suppressed_emails pse
       WHERE lower(btrim(pse.email)) = lower(btrim(NEW.email))
         AND pse.reason = 'bounce_permanente'
     ) THEN
    PERFORM set_config('alerts.foundation_trigger', 'on', true);
    PERFORM public.resolve_alert_item(
      'cliente_contato_bounced_sem_alternativa', 'customer', NEW.customer_id::TEXT,
      'customer_contact_change', jsonb_build_object('contact_id', NEW.id)
    );
    PERFORM set_config('alerts.foundation_trigger', 'off', true);
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('alerts.foundation_trigger', 'off', true);
  RAISE WARNING 'Reconciliação de alerta de bounce ignorada para customer_contacts.id=%: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;



--
-- Name: resolve_demurrage_alert_on_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_demurrage_alert_on_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (NEW.dispute_open IS DISTINCT FROM OLD.dispute_open
      OR NEW.dispute_status IS DISTINCT FROM OLD.dispute_status)
     AND (COALESCE(NEW.dispute_open, false) = false OR NEW.dispute_status IN ('resolvido', 'cancelado')) THEN
    PERFORM set_config('alerts.foundation_trigger', 'on', true);
    PERFORM public.resolve_alert_item(
      'portal_dispute_opened', 'demurrage_invoice', NEW.id::TEXT,
      'demurrage_dispute_status', jsonb_build_object(
        'dispute_open', NEW.dispute_open,
        'dispute_status', NEW.dispute_status
      )
    );
    PERFORM set_config('alerts.foundation_trigger', 'off', true);
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: resolve_invoice_alerts_on_status_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_invoice_alerts_on_status_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status THEN
    PERFORM set_config('alerts.foundation_trigger', 'on', true);
    IF NEW.status IN ('paid', 'partially_paid', 'cancelled') THEN
      PERFORM public.resolve_alert_item(
        'invoice_payment_invalid', 'invoice', NEW.id::TEXT,
        'invoice_status_change', jsonb_build_object('invoice_status', NEW.status)
      );
    END IF;
    IF NEW.status = 'cancelled' THEN
      PERFORM public.resolve_alert_item(
        'invoice_cancel_blocked', 'invoice', NEW.id::TEXT,
        'invoice_status_change', jsonb_build_object('invoice_status', NEW.status)
      );
    END IF;
    PERFORM set_config('alerts.foundation_trigger', 'off', true);
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: resolve_local_charge_table_id(text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_local_charge_table_id(p_cargo_mode text, p_pod text, p_reference_date date DEFAULT NULL::date) RETURNS bigint
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- p_reference_date é aceito por compatibilidade de assinatura e
  -- deliberadamente ignorado (ADR 0040): a vigência da tabela é informativa.
  SELECT ct.id
  FROM public.charge_tables AS ct
  WHERE ct.active = true
    AND ct.cargo_mode = p_cargo_mode
    AND public.normalize_port_code(ct.pod) = public.normalize_port_code(p_pod)
  ORDER BY ct.valid_from DESC, ct.id DESC
  LIMIT 1;
$$;



--
-- Name: resolve_pix_reconciliation_exception(bigint, text, bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_pix_reconciliation_exception(p_exception_id bigint, p_resolution_source text, p_invoice_id bigint DEFAULT NULL::bigint, p_demurrage_invoice_id bigint DEFAULT NULL::bigint, p_txid text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_exception public.pix_reconciliation_exceptions%ROWTYPE;
  v_normalized_txid TEXT := public.normalize_pix_txid(p_txid);
  v_authoritative BOOLEAN := false;
  v_paid_date DATE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao para reconciliacao PIX.' USING ERRCODE = '42501';
  END IF;
  IF p_resolution_source NOT IN ('local', 'demurrage') THEN
    RAISE EXCEPTION 'Origem de resolucao PIX invalida.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_exception
  FROM public.pix_reconciliation_exceptions
  WHERE id = p_exception_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Excecao PIX % nao encontrada.', p_exception_id USING ERRCODE = 'P0002';
  END IF;
  IF v_exception.status = 'resolved' THEN
    RETURN jsonb_build_object('id', v_exception.id, 'status', 'resolved');
  END IF;
  IF v_normalized_txid IS DISTINCT FROM v_exception.normalized_txid THEN
    RAISE EXCEPTION 'TXID informado nao corresponde exatamente ao TXID persistido na excecao.' USING ERRCODE = '22023';
  END IF;

  IF p_resolution_source = 'local' THEN
    IF p_invoice_id IS NULL OR p_demurrage_invoice_id IS NOT NULL OR v_normalized_txid = '' THEN
      RAISE EXCEPTION 'Resolucao local exige invoice local e TXID persistido.' USING ERRCODE = '22023';
    END IF;
    SELECT EXISTS (
      SELECT 1
      FROM public.invoices i
      JOIN public.ledger_settlements first_settlement
        ON first_settlement.invoice_id = i.id
       AND first_settlement.source = 'pix_extract'
       AND public.normalize_pix_txid(first_settlement.pix_txid) = v_exception.normalized_txid
      WHERE i.id = p_invoice_id
        AND i.invoice_type IN ('individual', 'consolidated')
        AND ABS((
          SELECT COALESCE(SUM(all_settlements.amount_brl), 0)
          FROM public.ledger_settlements all_settlements
          WHERE all_settlements.payment_id = first_settlement.payment_id
        ) - v_exception.amount_brl) <= 0.01
        AND (
          public.normalize_pix_txid(i.pix_txid) = v_exception.normalized_txid
          OR v_exception.normalized_txid <> ''
        )
    ) INTO v_authoritative;
  ELSE
    IF p_demurrage_invoice_id IS NULL OR p_invoice_id IS NOT NULL OR v_exception.paid_at IS NULL THEN
      RAISE EXCEPTION 'Resolucao Demurrage exige invoice e data paga persistida.' USING ERRCODE = '22023';
    END IF;
    v_paid_date := (v_exception.paid_at AT TIME ZONE 'UTC')::DATE;
    SELECT EXISTS (
      SELECT 1
      FROM public.demurrage_invoices d
      WHERE d.id = p_demurrage_invoice_id
        AND d.status = 'paid'
        AND d.conciliated_by_extract = true
        AND d.paid_at = v_paid_date
        AND public.normalize_pix_txid(d.pix_txid) = v_exception.normalized_txid
        AND EXISTS (
          SELECT 1
          FROM public.get_demurrage_recent_values(d.id, v_paid_date) w
          WHERE ABS(w.total_brl - v_exception.amount_brl) <= 0.01
        )
    ) INTO v_authoritative;
  END IF;

  IF NOT v_authoritative THEN
    RAISE EXCEPTION 'Nenhuma baixa/settlement autoritativa corresponde a excecao PIX %.', p_exception_id USING ERRCODE = 'P0001';
  END IF;

  UPDATE public.pix_reconciliation_exceptions
  SET status = 'resolved', resolved_at = now(), resolved_by = auth.uid(),
      resolution_source = p_resolution_source,
      resolved_invoice_id = p_invoice_id,
      resolved_demurrage_invoice_id = p_demurrage_invoice_id,
      updated_at = now()
  WHERE id = v_exception.id;

  PERFORM set_config('alerts.foundation_trigger', 'on', true);
  PERFORM public.resolve_alert_item(
    'pix_unreconciled', 'pix_transaction', v_exception.id::TEXT,
    'pix_reconciliation_authoritative', jsonb_build_object(
      'exception_id', v_exception.id,
      'resolution_source', p_resolution_source,
      'invoice_id', COALESCE(p_invoice_id, p_demurrage_invoice_id),
      'txid', NULLIF(p_txid, '')
    )
  );
  PERFORM set_config('alerts.foundation_trigger', 'off', true);

  RETURN jsonb_build_object('id', v_exception.id, 'status', 'resolved');
END;
$$;



--
-- Name: resolve_portal_alert_items_on_account_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_portal_alert_items_on_account_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.account_situation IS DISTINCT FROM OLD.account_situation
     OR NEW.recovery_email_status IS DISTINCT FROM OLD.recovery_email_status THEN
    PERFORM set_config('alerts.foundation_trigger', 'on', true);
    IF NEW.account_situation <> 'convite_expirado' THEN
      PERFORM public.resolve_alert_item(
        'portal_convite_expirado', 'customer', NEW.customer_id::TEXT,
        'portal_account_status', jsonb_build_object('account_situation', NEW.account_situation)
      );
    END IF;
    IF NEW.account_situation <> 'falha_no_envio' THEN
      PERFORM public.resolve_alert_item(
        'portal_falha_envio', 'customer', NEW.customer_id::TEXT,
        'portal_account_status', jsonb_build_object('account_situation', NEW.account_situation)
      );
    END IF;
    IF NEW.recovery_email_status = 'ok' THEN
      PERFORM public.resolve_alert_item(
        'portal_email_suprimido', 'customer', NEW.customer_id::TEXT,
        'portal_account_status', jsonb_build_object('recovery_email_status', NEW.recovery_email_status)
      );
    END IF;
    PERFORM set_config('alerts.foundation_trigger', 'off', true);
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: reverse_demurrage_payment(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_demurrage_payment(p_invoice_id bigint, p_reason text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor UUID;
  v_old_status TEXT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao.' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(TRIM(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Informe a justificativa para cancelar a baixa.' USING ERRCODE = '22023';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  SELECT status INTO v_old_status
  FROM public.demurrage_invoices
  WHERE id = p_invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Demurrage invoice % nao encontrada.', p_invoice_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_old_status, '') <> 'paid' THEN
    RAISE EXCEPTION 'Demurrage invoice % nao esta paga (status=%).', p_invoice_id, COALESCE(v_old_status, '?')
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.demurrage_invoices
  SET
    status = 'issued',
    paid_at = NULL,
    pix_txid = NULL,
    conciliated_by_extract = false
  WHERE id = p_invoice_id;

  INSERT INTO public.audit_logs (
    entity_type,
    entity_id,
    field_name,
    old_value,
    new_value,
    changed_by,
    changed_at,
    justification
  )
  VALUES (
    'demurrage_invoice',
    p_invoice_id::TEXT,
    'payment_reversed',
    v_old_status,
    'issued',
    v_actor,
    now(),
    TRIM(p_reason)
  );

  RETURN jsonb_build_object(
    'invoice_id', p_invoice_id,
    'new_status', 'issued'
  );
END;
$$;



--
-- Name: reverse_invoice_payment(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_invoice_payment(p_payment_id bigint, p_reason text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payment RECORD;
  v_invoice RECORD;
  v_settlement RECORD;
  v_unsettled_invoice_ids BIGINT[];
  v_total_paid NUMERIC(14,2);
  v_balance NUMERIC(14,2);
  v_actor UUID;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao.' USING ERRCODE = '42501';
  END IF;

  -- Justificativa obrigatoria para cancelar a baixa.
  IF NULLIF(TRIM(COALESCE(p_reason, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Informe a justificativa para cancelar a baixa.' USING ERRCODE = '22023';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  SELECT * INTO v_payment
  FROM public.payments
  WHERE id = p_payment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pagamento % nao encontrado.', p_payment_id USING ERRCODE = 'P0002';
  END IF;

  SELECT * INTO v_invoice
  FROM public.invoices
  WHERE id = v_payment.invoice_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invoice % nao encontrada.', v_payment.invoice_id USING ERRCODE = 'P0002';
  END IF;

  -- Reverte cada settlement, restaurando o receivable
  FOR v_settlement IN
    SELECT * FROM public.ledger_settlements
    WHERE payment_id = p_payment_id
    ORDER BY id
  LOOP
    UPDATE public.bl_receivables
    SET
      settled_amount_brl = GREATEST(COALESCE(settled_amount_brl, 0) - v_settlement.amount_brl, 0),
      balance_brl = COALESCE(balance_brl, 0) + v_settlement.amount_brl,
      status = CASE
        WHEN GREATEST(COALESCE(balance_brl, 0) + v_settlement.amount_brl, 0) >= original_amount_brl - 0.01 THEN 'open'
        ELSE 'partially_settled'
      END,
      updated_at = now()
    WHERE id = v_settlement.receivable_id;
  END LOOP;

  DELETE FROM public.ledger_settlements WHERE payment_id = p_payment_id;

  -- Restaura invoice_receivable_links que foram afetados por este pagamento
  UPDATE public.invoice_receivable_links irl
  SET status = 'active'
  WHERE irl.invoice_id = v_payment.invoice_id
    AND irl.status = 'settled_by_this_invoice'
    AND EXISTS (
      SELECT 1 FROM public.bl_receivables br
      WHERE br.id = irl.receivable_id
        AND br.balance_brl > 0.01
    );

  -- Recalcula totais da invoice
  SELECT COALESCE(SUM(COALESCE(balance_brl, 0)), 0)
  INTO v_balance
  FROM public.bl_receivables
  WHERE id IN (
    SELECT receivable_id FROM public.invoice_receivable_links
    WHERE invoice_id = v_payment.invoice_id
  );

  SELECT COALESCE(SUM(amount_brl), 0)
  INTO v_total_paid
  FROM public.payments
  WHERE invoice_id = v_payment.invoice_id
    AND id <> p_payment_id;

  UPDATE public.invoices
  SET
    total_paid_brl = v_total_paid,
    balance_brl = GREATEST(v_balance, 0),
    -- Libera o TXID conciliado para que o mesmo PIX possa ser reconciliado de novo.
    pix_txid = NULL,
    conciliated_by_extract = false,
    status = CASE
      WHEN COALESCE(v_invoice.status, '') = 'covered' THEN 'covered'
      WHEN v_total_paid <= 0.01 AND GREATEST(v_balance, 0) >= (SELECT COALESCE(SUM(original_amount_brl), 0) FROM public.bl_receivables WHERE id IN (SELECT receivable_id FROM public.invoice_receivable_links WHERE invoice_id = v_payment.invoice_id)) - 0.01 THEN 'issued'
      WHEN v_total_paid <= 0.01 THEN 'issued'
      WHEN GREATEST(v_balance, 0) <= 0.01 THEN 'paid'
      ELSE 'partially_paid'
    END
  WHERE id = v_payment.invoice_id;

  -- Se a invoice estava 'paid' e agora tem saldo > 0, reverte coberturas/obsolescencia
  IF COALESCE(v_invoice.status, '') IN ('paid') AND v_balance > 0.01 THEN
    -- Reverte invoices individuais que foram cobertas por esta consolidada
    UPDATE public.invoices ind
    SET status = 'issued', covered_by_invoice_id = NULL
    WHERE ind.covered_by_invoice_id = v_payment.invoice_id
      AND ind.status = 'covered';

    -- Reverte links de outras invoices que foram 'settled_elsewhere'
    UPDATE public.invoice_receivable_links irl
    SET status = 'active'
    WHERE irl.receivable_id IN (
      SELECT receivable_id FROM public.invoice_receivable_links
      WHERE invoice_id = v_payment.invoice_id
    )
      AND irl.invoice_id <> v_payment.invoice_id
      AND irl.status = 'settled_elsewhere';

    -- Reverte consolidations que foram obsoletadas por esta individual
    UPDATE public.invoices con
    SET status = 'issued', obsolete_reason = NULL
    WHERE con.id IN (
      SELECT con2.id FROM public.invoices con2
      WHERE con2.invoice_type = 'consolidated'
        AND con2.status = 'obsolete'
        AND EXISTS (
          SELECT 1 FROM public.invoice_receivable_links l
          WHERE l.invoice_id = con2.id
            AND l.receivable_id IN (
              SELECT receivable_id FROM public.invoice_receivable_links
              WHERE invoice_id = v_payment.invoice_id
            )
        )
    );

    -- Reverte links obsoletos
    UPDATE public.invoice_receivable_links irl
    SET status = 'active'
    WHERE irl.status = 'obsolete'
      AND irl.invoice_id IN (
        SELECT id FROM public.invoices WHERE invoice_type = 'consolidated' AND status = 'issued'
      )
      AND irl.receivable_id IN (
        SELECT receivable_id FROM public.invoice_receivable_links
        WHERE invoice_id = v_payment.invoice_id
      );
  END IF;

  -- Atualiza financial_status dos BLs vinculados.
  -- bls.financial_status so aceita 'pending','invoiced','paid','cancelled'
  -- (constraint bls_financial_status_check). Ao cancelar a baixa, o BL volta a
  -- 'invoiced' quando ainda ha saldo, ou 'paid' se tudo continua liquidado.
  UPDATE public.bls b
  SET financial_status = (
    SELECT CASE
      WHEN COUNT(*) FILTER (WHERE br.balance_brl > 0.01) = 0 THEN 'paid'
      ELSE 'invoiced'
    END
    FROM public.bl_receivables br
    WHERE br.bl_id = b.id
  )
  WHERE b.id IN (
    SELECT br.bl_id FROM public.bl_receivables br
    WHERE br.id IN (
      SELECT receivable_id FROM public.invoice_receivable_links
      WHERE invoice_id = v_payment.invoice_id
    )
  );

  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, changed_at, justification)
  VALUES (
    'invoice', v_payment.invoice_id::TEXT, 'payment_reversed',
    COALESCE(v_invoice.status, '?') || ' total_paid=' || COALESCE(v_invoice.total_paid_brl::TEXT, '?'),
    (SELECT COALESCE(status, '?') || ' total_paid=' || COALESCE(total_paid_brl::TEXT, '?') FROM public.invoices WHERE id = v_payment.invoice_id),
    v_actor, now(),
    TRIM(p_reason)
  );

  DELETE FROM public.payments WHERE id = p_payment_id;

  RETURN jsonb_build_object(
    'payment_id', p_payment_id,
    'invoice_id', v_payment.invoice_id,
    'new_status', (SELECT status FROM public.invoices WHERE id = v_payment.invoice_id)
  );
END;
$$;



--
-- Name: revert_voyage_omission(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revert_voyage_omission(p_omission_id bigint, p_justification text, p_changed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_omission RECORD;
  v_justification TEXT := NULLIF(btrim(COALESCE(p_justification, '')), '');
  v_cod_count INTEGER;
  v_entity_id TEXT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_admin() OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Somente Admin pode reverter omissao, com o proprio usuario autenticado.'
      USING ERRCODE = '42501';
  END IF;

  IF v_justification IS NULL THEN
    RAISE EXCEPTION 'Reversao de omissao exige justificativa.' USING ERRCODE = '22023';
  END IF;

  SELECT o.id, o.voyage_id, o.omitted_pod, o.discharge_pod, o.reverted_at
  INTO v_omission
  FROM public.voyage_omissions AS o
  WHERE o.id = p_omission_id
  FOR UPDATE OF o;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Omissao % nao encontrada.', p_omission_id USING ERRCODE = 'P0002';
  END IF;
  IF v_omission.reverted_at IS NOT NULL THEN
    RAISE EXCEPTION 'Omissao % ja foi revertida.', p_omission_id USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*)::INTEGER
  INTO v_cod_count
  FROM public.bl_transshipments AS t
  WHERE t.omission_id = p_omission_id
    AND t.disposition = 'cod';

  IF v_cod_count > 0 THEN
    RAISE EXCEPTION 'Nao e possivel reverter a omissao: % B/L(s) afetado(s) estao em COD.', v_cod_count
      USING ERRCODE = '22023';
  END IF;

  v_entity_id := v_omission.voyage_id::TEXT || '::' || upper(btrim(v_omission.omitted_pod));

  -- Este audit row é obrigatório: voyageRouteSchedules deriva omitted dele e,
  -- desde a 306, os consumidores de estado terminalizado e de alertas de ADR
  -- contam a escala ativa pela mesma decisão mais recente.
  INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES (
    'voyage_pod_schedule',
    v_entity_id,
    'omitted',
    'true',
    'false',
    p_changed_by,
    v_justification
  );

  INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES (
    'voyage',
    v_omission.voyage_id::TEXT,
    'omissao_revertida',
    v_omission.omitted_pod,
    v_omission.discharge_pod,
    p_changed_by,
    v_justification
  );

  INSERT INTO public.portal_notifications(customer_id, bl_id, type, title, message, link)
  SELECT
    b.customer_id,
    b.id,
    'transshipment',
    'Correção de omissão de escala',
    'A omissão da escala de ' || v_omission.omitted_pod || ' foi revertida. O B/L ' || b.id ||
      ' voltou a seguir a programação original da viagem.',
    NULL
  FROM public.bl_transshipments AS t
  JOIN public.bls AS b ON b.id = t.bl_id
  WHERE t.omission_id = p_omission_id
    AND b.customer_id IS NOT NULL;

  UPDATE public.voyage_omissions
  SET reverted_at = now(),
      reverted_by = p_changed_by,
      revert_justification = v_justification
  WHERE id = p_omission_id;
END;
$$;



--
-- Name: review_bl_document_candidates(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_bl_document_candidates(p_manifest_cnpj text, p_consignee_block text, p_cargo_description text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result TEXT[] := ARRAY[]::TEXT[];
  v_value TEXT;
BEGIN
  v_value := public.normalize_cnpj(p_manifest_cnpj);
  IF v_value IS NOT NULL AND public.is_valid_cnpj(v_value) THEN
    v_result := array_append(v_result, v_value);
  END IF;

  FOREACH v_value IN ARRAY public.extract_review_cnpjs_from_text(p_consignee_block)
  LOOP
    IF NOT (v_value = ANY(v_result)) THEN v_result := array_append(v_result, v_value); END IF;
  END LOOP;

  FOREACH v_value IN ARRAY public.extract_review_cnpjs_from_text(p_cargo_description)
  LOOP
    IF NOT (v_value = ANY(v_result)) THEN v_result := array_append(v_result, v_value); END IF;
  END LOOP;

  RETURN v_result;
END;
$$;



--
-- Name: route_catalog_alert_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_catalog_alert_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.type <> 'aggregate'
     AND NEW.entity_type IS NOT NULL
     AND NEW.entity_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.alert_type_catalog WHERE type = NEW.type AND active)
     AND current_setting('alerts.foundation_direct_insert', true) IS DISTINCT FROM 'on' THEN
    PERFORM set_config('alerts.foundation_trigger', 'on', true);
    PERFORM public.upsert_alert_item(
      NEW.type, NEW.entity_type, NEW.entity_id, NEW.message,
      'legacy_insert', '{}'::jsonb, NULL
    );
    UPDATE public.alerts
    SET status = 'closed', closed_at = COALESCE(closed_at, now())
    WHERE id = NEW.id;
    PERFORM set_config('alerts.foundation_trigger', 'off', true);
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: run_alert_detectors(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_alert_detectors() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor UUID;
  v_adr_pending INTEGER := 0;
  v_adr_deadline INTEGER := 0;
  v_bl_review INTEGER := 0;
  v_granite_review INTEGER := 0;
  v_voyage_ops INTEGER := 0;
  v_portal JSONB;
  v_customer_communications JSONB;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'Executor server-only.' USING ERRCODE = '42501';
  END IF;

  SELECT id INTO v_actor
  FROM public.user_profiles
  WHERE active = true AND role <> 'equipamentos'
  ORDER BY CASE WHEN role IN ('admin', 'administrativo') THEN 0 ELSE 1 END, created_at, id
  LIMIT 1;

  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Não há usuário interno ativo para executar os detectores.' USING ERRCODE = 'P0002';
  END IF;

  PERFORM set_config('request.jwt.claim.sub', v_actor::TEXT, true);
  PERFORM set_config('request.jwt.claim.role', 'service_role', true);
  PERFORM set_config('alerts.detector_runner', 'on', true);

  -- Faturas vencidas saíram do runner: taxa local não tem vencimento praticado
  -- (issue #605). O Demurrage nunca teve (ADR 0014).

  -- ADR - Relatório de Saída da Agência (Bloco 5)
  v_adr_pending := public.detect_agency_report_pending();
  v_adr_deadline := public.detect_agency_report_deadline_missed();

  -- Revisão Manual de B/L e Granito (Bloco 1)
  v_bl_review := public.detect_bl_review_pendencies();
  v_granite_review := public.detect_granite_bl_review_pendencies();

  -- Operação e Viagens (Bloco 4)
  v_voyage_ops := public.detect_voyage_operation_alerts();

  -- Portal do Cliente e Disputas (Bloco 2)
  v_portal := public.reconcile_client_portal_alerts();

  -- Comunicados ao Cliente: NOA/NOR/NOB e falha de contato alternativo.
  v_customer_communications := public.detect_customer_communication_alerts();

  RETURN jsonb_build_object(
    'agency_report_pending', v_adr_pending,
    'agency_report_deadline_missed', v_adr_deadline,
    'bl_review_pendencies', v_bl_review,
    'granite_bl_review_pendencies', v_granite_review,
    'voyage_operation_alerts', v_voyage_ops,
    'client_portal', v_portal,
    'customer_communications', v_customer_communications
  );
END;
$$;



--
-- Name: run_billing_for_import_batch(bigint, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.run_billing_for_import_batch(p_batch_id bigint, p_actor uuid DEFAULT NULL::uuid, p_recalculate boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch RECORD;
  v_run_id BIGINT;
  v_actor UUID;
  v_bl RECORD;
  v_result JSONB;
  v_hold_reason TEXT;
  v_total_bls INTEGER := 0;
  v_eligible_bls INTEGER := 0;
  v_blocked_bls INTEGER := 0;
  v_calculated_bls INTEGER := 0;
  v_total_brl NUMERIC(14,2) := 0;
  v_total_usd NUMERIC(14,2) := 0;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  SELECT *
  INTO v_batch
  FROM public.import_batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Manifesto/lote % nao encontrado.', p_batch_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_batch.status, 'processing') NOT IN ('completed', 'partial') THEN
    RAISE EXCEPTION 'Manifesto % ainda nao esta pronto para faturamento automatico.', p_batch_id USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.billing_runs (
    manifest_id,
    trigger_source,
    status,
    requested_by,
    input_hash,
    total_bls,
    summary
  )
  VALUES (
    p_batch_id,
    CASE WHEN COALESCE(p_recalculate, true) THEN 'manifest_import' ELSE 'manual_reprocess' END,
    'running',
    v_actor,
    v_batch.file_hash,
    COALESCE(v_batch.total_bls, 0),
    jsonb_build_object('filename', v_batch.filename, 'cargo_mode', v_batch.cargo_mode)
  )
  RETURNING id INTO v_run_id;

  FOR v_bl IN
    SELECT
      b.id,
      b.customer_id,
      b.customer_reconciliation_status,
      b.manifest_customer_cnpj_cpf,
      b.manifest_customer_name,
      b.manifest_customer_email
    FROM public.bls AS b
    WHERE b.batch_id = p_batch_id
    ORDER BY b.id
  LOOP
    v_total_bls := v_total_bls + 1;

    UPDATE public.bls
    SET last_billing_run_id = v_run_id
    WHERE id = v_bl.id;

    PERFORM public.sync_customer_reconciliation_queue_for_bl(v_bl.id);

    IF v_bl.customer_id IS NULL OR COALESCE(v_bl.customer_reconciliation_status, 'missing_customer') NOT IN ('matched_document', 'reconciled') THEN
      v_blocked_bls := v_blocked_bls + 1;
      v_hold_reason := CASE COALESCE(v_bl.customer_reconciliation_status, 'missing_customer')
        WHEN 'matched_name' THEN 'Cliente vinculado apenas por nome; requer reconciliacao manual.'
        WHEN 'rejected' THEN 'Reconciliacao de cliente rejeitada; revisar cadastro.'
        ELSE 'Cliente inexistente ou nao reconciliado.'
      END;

      UPDATE public.bls
      SET
        billing_hold_reason = v_hold_reason,
        charge_status = CASE
          WHEN financial_status = 'pending' THEN 'not_calculated'
          ELSE charge_status
        END
      WHERE id = v_bl.id;

      PERFORM public.insert_billing_run_log(
        v_run_id,
        p_batch_id,
        v_bl.id,
        'warning',
        'customer_reconciliation_blocked',
        v_hold_reason,
        jsonb_build_object(
          'customer_id', v_bl.customer_id,
          'customer_reconciliation_status', v_bl.customer_reconciliation_status,
          'manifest_customer_cnpj_cpf', v_bl.manifest_customer_cnpj_cpf,
          'manifest_customer_name', v_bl.manifest_customer_name,
          'manifest_customer_email', v_bl.manifest_customer_email
        )
      );

      CONTINUE;
    END IF;

    v_eligible_bls := v_eligible_bls + 1;
    v_result := public.calculate_bl_local_charges(v_bl.id, v_actor, COALESCE(p_recalculate, true));

    UPDATE public.charge_calculations
    SET
      billing_run_id = v_run_id,
      manifest_id = COALESCE(manifest_id, p_batch_id)
    WHERE bl_id = v_bl.id
      AND COALESCE(source, 'auto') = 'auto';

    v_hold_reason := CASE
      WHEN EXISTS (
        SELECT 1
        FROM public.charge_calculations
        WHERE bl_id = v_bl.id
          AND COALESCE(total_value_usd, 0) > 0
      ) THEN 'Linhas em USD exigem ajuste manual antes do faturamento.'
      WHEN COALESCE(v_result->>'status', '') = 'review_required' THEN 'Pendencia de revisao nas taxas locais.'
      ELSE NULL
    END;

    UPDATE public.bls
    SET billing_hold_reason = v_hold_reason
    WHERE id = v_bl.id;

    v_calculated_bls := v_calculated_bls + 1;

    PERFORM public.insert_billing_run_log(
      v_run_id,
      p_batch_id,
      v_bl.id,
      CASE WHEN v_hold_reason IS NULL THEN 'info' ELSE 'warning' END,
      'charges_calculated',
      COALESCE(v_result->>'reason', 'Calculo executado com sucesso.'),
      jsonb_build_object(
        'status', v_result->>'status',
        'line_count', COALESCE((v_result->>'line_count')::INT, 0),
        'total_brl', COALESCE((v_result->>'total_brl')::NUMERIC, 0),
        'total_usd', COALESCE((v_result->>'total_usd')::NUMERIC, 0),
        'billing_hold_reason', v_hold_reason
      )
    );
  END LOOP;

  SELECT
    COALESCE(SUM(total_value_brl), 0),
    COALESCE(SUM(total_value_usd), 0)
  INTO
    v_total_brl,
    v_total_usd
  FROM public.charge_calculations
  WHERE billing_run_id = v_run_id;

  UPDATE public.billing_runs
  SET
    completed_at = now(),
    status = CASE
      WHEN v_blocked_bls > 0 THEN 'completed_with_blocks'
      ELSE 'completed'
    END,
    total_bls = v_total_bls,
    eligible_bls = v_eligible_bls,
    blocked_bls = v_blocked_bls,
    calculated_bls = v_calculated_bls,
    total_brl = v_total_brl,
    total_usd = v_total_usd,
    summary = jsonb_build_object(
      'filename', v_batch.filename,
      'cargo_mode', v_batch.cargo_mode,
      'eligible_bls', v_eligible_bls,
      'blocked_bls', v_blocked_bls,
      'calculated_bls', v_calculated_bls
    )
  WHERE id = v_run_id;

  RETURN jsonb_build_object(
    'billing_run_id', v_run_id,
    'manifest_id', p_batch_id,
    'status', CASE WHEN v_blocked_bls > 0 THEN 'completed_with_blocks' ELSE 'completed' END,
    'total_bls', v_total_bls,
    'eligible_bls', v_eligible_bls,
    'blocked_bls', v_blocked_bls,
    'calculated_bls', v_calculated_bls,
    'total_brl', v_total_brl,
    'total_usd', v_total_usd
  );
EXCEPTION
  WHEN OTHERS THEN
    IF v_run_id IS NOT NULL THEN
      UPDATE public.billing_runs
      SET
        completed_at = now(),
        status = 'failed',
        summary = COALESCE(summary, '{}'::JSONB) || jsonb_build_object(
          'error', SQLERRM,
          'failed_at', now()
        )
      WHERE id = v_run_id;

      PERFORM public.insert_billing_run_log(
        v_run_id,
        p_batch_id,
        NULL,
        'error',
        'billing_run_failed',
        SQLERRM,
        jsonb_build_object('sqlstate', SQLSTATE)
      );
    END IF;
    RAISE;
END;
$$;



--
-- Name: save_bl_demurrage_config(text, timestamp with time zone, integer, numeric, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_bl_demurrage_config(p_bl_id text, p_expected_updated_at timestamp with time zone, p_free_time_override integer, p_rate_p1_usd numeric, p_rate_p2_usd numeric, p_changed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl public.bls%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para configurar demurrage.' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_bl FROM public.bls WHERE id = p_bl_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'BL % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;
  IF p_expected_updated_at IS NOT NULL AND v_bl.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'BL % foi alterado por outro usuario; recarregue antes de salvar', p_bl_id
      USING ERRCODE = 'PT409';
  END IF;

  UPDATE public.bls
  SET
    free_time_override = p_free_time_override,
    demurrage_rate_override_p1_usd = p_rate_p1_usd,
    demurrage_rate_override_p2_usd = p_rate_p2_usd
  WHERE id = p_bl_id;

  INSERT INTO public.audit_logs (
    entity_type, entity_id, field_name, old_value, new_value, changed_by, justification
  )
  SELECT 'bl', p_bl_id, change.field_name, change.old_value, change.new_value,
         p_changed_by, 'Config de demurrage (Faturamento).'
  FROM (VALUES
    ('free_time_override', v_bl.free_time_override::TEXT, p_free_time_override::TEXT),
    ('demurrage_rate_override_p1_usd', v_bl.demurrage_rate_override_p1_usd::TEXT, p_rate_p1_usd::TEXT),
    ('demurrage_rate_override_p2_usd', v_bl.demurrage_rate_override_p2_usd::TEXT, p_rate_p2_usd::TEXT)
  ) AS change(field_name, old_value, new_value)
  WHERE change.old_value IS DISTINCT FROM change.new_value;
END;
$$;



--
-- Name: save_bl_review(text, timestamp with time zone, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_bl_review(p_bl_id text, p_expected_updated_at timestamp with time zone, p_update_payload jsonb, p_audit_rows jsonb, p_changed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_new_updated_at TIMESTAMPTZ;
  v_current_updated_at TIMESTAMPTZ;
  v_next_customer_id BIGINT;
  v_previous_status TEXT;
  v_input_notes TEXT;
  v_human_notes TEXT;
  v_rowcount INT;
  v_reasons TEXT[];
  v_status TEXT;
  v_notes TEXT;
  v_justification TEXT := 'Revisao manual';
  v_manifest_email TEXT;
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.is_active_user()
     OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para revisar B/L.'
      USING ERRCODE = '42501';
  END IF;

  IF p_bl_id IS NULL OR p_bl_id = '' THEN
    RAISE EXCEPTION 'bl_id obrigatorio' USING ERRCODE = '22004';
  END IF;

  SELECT updated_at
  INTO v_current_updated_at
  FROM public.bls
  WHERE id = p_bl_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'BL % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF p_expected_updated_at IS NOT NULL
     AND v_current_updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'BL % foi alterado por outro usuario; recarregue antes de salvar', p_bl_id
      USING ERRCODE = 'PT409';
  END IF;

  v_next_customer_id := CASE
    WHEN p_update_payload ? 'customer_id'
      THEN NULLIF(p_update_payload->>'customer_id', '')::BIGINT
    ELSE NULL
  END;

  UPDATE public.bls AS b
  SET
    shipper            = CASE WHEN p_update_payload ? 'shipper' THEN p_update_payload->>'shipper' ELSE b.shipper END,
    consignee          = CASE WHEN p_update_payload ? 'consignee' THEN p_update_payload->>'consignee' ELSE b.consignee END,
    notify_party       = CASE WHEN p_update_payload ? 'notify_party' THEN p_update_payload->>'notify_party' ELSE b.notify_party END,
    ce_mercante        = CASE WHEN p_update_payload ? 'ce_mercante' THEN p_update_payload->>'ce_mercante' ELSE b.ce_mercante END,
    pol                = CASE WHEN p_update_payload ? 'pol' THEN p_update_payload->>'pol' ELSE b.pol END,
    pod                = CASE WHEN p_update_payload ? 'pod' THEN p_update_payload->>'pod' ELSE b.pod END,
    place_of_delivery  = CASE WHEN p_update_payload ? 'place_of_delivery' THEN p_update_payload->>'place_of_delivery' ELSE b.place_of_delivery END,
    place_of_receipt   = CASE WHEN p_update_payload ? 'place_of_receipt' THEN p_update_payload->>'place_of_receipt' ELSE b.place_of_receipt END,
    movement_from      = CASE WHEN p_update_payload ? 'movement_from' THEN p_update_payload->>'movement_from' ELSE b.movement_from END,
    movement_to        = CASE WHEN p_update_payload ? 'movement_to' THEN p_update_payload->>'movement_to' ELSE b.movement_to END,
    issue_place        = CASE WHEN p_update_payload ? 'issue_place' THEN p_update_payload->>'issue_place' ELSE b.issue_place END,
    bl_emission_date   = CASE WHEN p_update_payload ? 'bl_emission_date' THEN NULLIF(p_update_payload->>'bl_emission_date', '')::DATE ELSE b.bl_emission_date END,
    cargo_description  = CASE WHEN p_update_payload ? 'cargo_description' THEN p_update_payload->>'cargo_description' ELSE b.cargo_description END,
    total_weight_kg    = CASE WHEN p_update_payload ? 'total_weight_kg' THEN NULLIF(p_update_payload->>'total_weight_kg', '')::NUMERIC ELSE b.total_weight_kg END,
    total_cbm          = CASE WHEN p_update_payload ? 'total_cbm' THEN NULLIF(p_update_payload->>'total_cbm', '')::NUMERIC ELSE b.total_cbm END,
    bb_machine_qty     = CASE WHEN p_update_payload ? 'bb_machine_qty' THEN NULLIF(p_update_payload->>'bb_machine_qty', '')::NUMERIC ELSE b.bb_machine_qty END,
    bb_packages_qty    = CASE WHEN p_update_payload ? 'bb_packages_qty' THEN NULLIF(p_update_payload->>'bb_packages_qty', '')::NUMERIC ELSE b.bb_packages_qty END,
    bb_packages_total  = CASE WHEN p_update_payload ? 'bb_packages_total' THEN NULLIF(p_update_payload->>'bb_packages_total', '')::NUMERIC ELSE b.bb_packages_total END,
    bb_weight_ton      = CASE WHEN p_update_payload ? 'bb_weight_ton' THEN NULLIF(p_update_payload->>'bb_weight_ton', '')::NUMERIC ELSE b.bb_weight_ton END,
    incoterm           = CASE WHEN p_update_payload ? 'incoterm' THEN p_update_payload->>'incoterm' ELSE b.incoterm END,
    payment_type       = CASE WHEN p_update_payload ? 'payment_type' THEN NULLIF(p_update_payload->>'payment_type', '') ELSE b.payment_type END,
    free_time_override = CASE WHEN p_update_payload ? 'free_time_override' THEN NULLIF(p_update_payload->>'free_time_override', '')::INT ELSE b.free_time_override END,
    notes              = CASE WHEN p_update_payload ? 'notes' THEN p_update_payload->>'notes' ELSE b.notes END,
    -- NCM cadastrado a mão na ficha (migration 358). Chega como array JSON de
    -- códigos; `[]` é uma decisão do operador de limpar, não um valor ausente.
    ncm_codes          = CASE
      WHEN p_update_payload ? 'ncm_codes'
        THEN public.normalize_ncm_codes(p_update_payload->'ncm_codes')
      ELSE b.ncm_codes
    END,
    customer_id        = CASE WHEN p_update_payload ? 'customer_id' THEN v_next_customer_id ELSE b.customer_id END,
    customer_reconciliation_status = CASE
      WHEN p_update_payload ? 'customer_reconciliation_status'
        THEN p_update_payload->>'customer_reconciliation_status'
      WHEN p_update_payload ? 'customer_id'
        THEN CASE WHEN v_next_customer_id IS NULL THEN 'missing_customer' ELSE 'reconciled' END
      ELSE b.customer_reconciliation_status
    END,
    customer_reconciliation_notes = CASE
      WHEN p_update_payload ? 'customer_reconciliation_notes'
        THEN NULLIF(p_update_payload->>'customer_reconciliation_notes', '')
      WHEN p_update_payload ? 'customer_id'
        THEN CASE
          WHEN v_next_customer_id IS NULL THEN 'Cliente removido manualmente do B/L.'
          ELSE 'Cliente reconciliado manualmente na revisao do B/L.'
        END
      ELSE b.customer_reconciliation_notes
    END,
    billing_hold_reason = CASE
      WHEN p_update_payload ? 'billing_hold_reason'
        THEN NULLIF(p_update_payload->>'billing_hold_reason', '')
      WHEN p_update_payload ? 'customer_id'
        THEN CASE
          WHEN v_next_customer_id IS NULL
            THEN COALESCE(b.billing_hold_reason, 'Cliente sem reconciliacao aprovada.')
          ELSE NULL
        END
      ELSE b.billing_hold_reason
    END
  WHERE b.id = p_bl_id
    AND (p_expected_updated_at IS NULL OR b.updated_at = p_expected_updated_at)
  RETURNING b.review_status, b.notes
  INTO v_previous_status, v_input_notes;

  GET DIAGNOSTICS v_rowcount = ROW_COUNT;
  IF v_rowcount = 0 THEN
    RAISE EXCEPTION 'BL % foi alterado por outro usuario; recarregue antes de salvar', p_bl_id
      USING ERRCODE = 'PT409';
  END IF;

  v_reasons := public.compute_bl_review_pendencies(p_bl_id);
  v_status := CASE
    WHEN COALESCE(cardinality(v_reasons), 0) = 0 THEN 'reviewed'
    ELSE 'pending_review'
  END;

  -- The machine-owned line always stays at the end. Human notes remain intact.
  v_human_notes := btrim(
    regexp_replace(
      COALESCE(v_input_notes, ''),
      E'(^|\\n)Pendencias de importacao:[^\\n]*$',
      '',
      'i'
    )
  );

  v_notes := CASE
    WHEN COALESCE(cardinality(v_reasons), 0) > 0 THEN concat_ws(
      E'\n',
      NULLIF(v_human_notes, ''),
      'Pendencias de importacao: ' || array_to_string(v_reasons, ', ')
    )
    ELSE NULLIF(v_human_notes, '')
  END;

  UPDATE public.bls AS b
  SET
    review_status = v_status,
    notes = v_notes
  WHERE b.id = p_bl_id
  RETURNING b.updated_at INTO v_new_updated_at;

  IF p_audit_rows IS NOT NULL
     AND jsonb_typeof(p_audit_rows) = 'array'
     AND jsonb_array_length(p_audit_rows) > 0 THEN
    SELECT COALESCE(NULLIF(a->>'justification', ''), v_justification)
    INTO v_justification
    FROM jsonb_array_elements(p_audit_rows) AS a
    LIMIT 1;

    INSERT INTO public.audit_logs (
      entity_type,
      entity_id,
      field_name,
      old_value,
      new_value,
      changed_by,
      justification
    )
    SELECT
      COALESCE(a->>'entity_type', 'bl'),
      COALESCE(a->>'entity_id', p_bl_id),
      a->>'field_name',
      a->>'old_value',
      a->>'new_value',
      p_changed_by,
      COALESCE(NULLIF(a->>'justification', ''), v_justification)
    FROM jsonb_array_elements(p_audit_rows) AS a
    WHERE a->>'field_name' IS DISTINCT FROM 'review_status';
  END IF;

  IF v_previous_status IS DISTINCT FROM v_status THEN
    INSERT INTO public.audit_logs (
      entity_type,
      entity_id,
      field_name,
      old_value,
      new_value,
      changed_by,
      justification
    )
    VALUES (
      'bl',
      p_bl_id,
      'review_status',
      v_previous_status,
      v_status,
      p_changed_by,
      v_justification
    );
  END IF;

  PERFORM public.sync_customer_reconciliation_queue_for_bl(p_bl_id);

  -- ADR 0061: a conciliacao de cliente tem casa unica na Revisao, e por isso a
  -- Revisao precisa produzir aqui o efeito completo que a Validacao produzia —
  -- vincular o cliente E capturar o e-mail do manifesto como contato
  -- financeiro. Sem isto, remover os botoes da Validacao seria regressao.
  --
  -- Roda depois do sync porque e ele quem fecha a fila (`status = 'approved'`)
  -- para o B/L recem-vinculado; a fila e tambem quem guarda o e-mail do
  -- manifesto que a Validacao usava. `approved_by` fica com o revisor: quem
  -- resolveu foi quem salvou a revisao, e o sync nao conhece o ator (roda
  -- tambem na importacao, sem revisor humano).
  IF p_update_payload ? 'customer_id' AND v_next_customer_id IS NOT NULL THEN
    UPDATE public.customer_reconciliation_queue AS q
    SET approved_by = COALESCE(q.approved_by, p_changed_by)
    WHERE q.bl_id = p_bl_id
      AND q.status = 'approved'
    RETURNING q.manifest_customer_email INTO v_manifest_email;

    PERFORM public.capture_manifest_financial_contact(v_next_customer_id, v_manifest_email);
  END IF;

  RETURN jsonb_build_object(
    'updated_at', v_new_updated_at,
    'review_status', v_status,
    'pendencias', to_jsonb(v_reasons)
  );
END;
$_$;



--
-- Name: save_customer_communication_saved_template(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_customer_communication_saved_template(p_name text, p_subject text, p_body text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_id BIGINT;
BEGIN
  IF public._portal_actor_role() NOT IN ('admin', 'administrativo', 'operator', 'documentacao', 'equipamentos') THEN
    RAISE EXCEPTION 'Sem permissão para salvar modelos.' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.customer_communication_saved_templates (name, subject, body, created_by)
  VALUES (btrim(p_name), btrim(p_subject), btrim(p_body), auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;



--
-- Name: save_exchange_rate_reference(numeric, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_exchange_rate_reference(p_ptax numeric, p_roe numeric, p_effective_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
     AND NOT public.is_active_user() THEN
    RAISE EXCEPTION 'permission denied' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.exchange_rate_reference (id, ptax, roe, effective_date, updated_at)
  VALUES (1, p_ptax, p_roe, p_effective_date, now())
  ON CONFLICT (id) DO UPDATE
  SET ptax = EXCLUDED.ptax,
      roe = EXCLUDED.roe,
      effective_date = EXCLUDED.effective_date,
      updated_at = now();
END;
$$;



--
-- Name: save_granite_bl_review(uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_granite_bl_review(p_granite_bl_id uuid, p_client_id bigint, p_changed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.save_granite_bl_review_legacy_148(p_granite_bl_id, p_client_id, p_changed_by);
  UPDATE public.granite_bls
  SET suggested_client_id = NULL
  WHERE id = p_granite_bl_id;
END;
$$;



--
-- Name: save_granite_bl_review_legacy_148(uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_granite_bl_review_legacy_148(p_granite_bl_id uuid, p_client_id bigint, p_changed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_previous_client_id BIGINT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para revisar B/L Granite.' USING ERRCODE = '42501';
  END IF;

  SELECT client_id
  INTO v_previous_client_id
  FROM public.granite_bls
  WHERE id = p_granite_bl_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L Granite % nao encontrado', p_granite_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF v_previous_client_id IS NOT DISTINCT FROM p_client_id THEN
    RETURN;
  END IF;

  UPDATE public.granite_bls
  SET client_id = p_client_id
  WHERE id = p_granite_bl_id;

  INSERT INTO public.audit_logs (
    entity_type, entity_id, field_name, old_value, new_value, changed_by, justification
  )
  VALUES (
    'granite_bl', p_granite_bl_id::TEXT, 'client_id',
    v_previous_client_id::TEXT, p_client_id::TEXT, p_changed_by,
    'Cliente vinculado via fila de revisao'
  );
END;
$$;



--
-- Name: save_voyage_escala_terminal_state(bigint, text, integer, jsonb, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_voyage_escala_terminal_state(p_voyage_id bigint, p_port text, p_expected_revision integer, p_fronts jsonb, p_terminals jsonb, p_export_expectation jsonb, p_justification text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_role TEXT;
  v_department TEXT;
  v_port TEXT := upper(btrim(COALESCE(p_port, '')));
  v_port_id BIGINT;
  v_current_revision INTEGER := 0;
  v_next_revision INTEGER;
  v_entity_id TEXT;
  v_front RECORD;
  v_old_front RECORD;
  v_new_front RECORD;
  v_terminal RECORD;
  v_old_terminal RECORD;
  v_depot RECORD;
  v_report RECORD;
  v_old_export_exists BOOLEAN := FALSE;
  v_old_export_declared BOOLEAN := FALSE;
  v_old_export_granite BOOLEAN := FALSE;
  v_old_export_empty BOOLEAN := FALSE;
  v_old_export_containers_qty INTEGER;
  v_old_export_movements_qty INTEGER;
  v_old_export_discharge_ports TEXT[] := '{}'::TEXT[];
  v_old_export_ce_status TEXT;
  v_old_export_linked BOOLEAN := FALSE;
  v_export_existing_id UUID;
  v_export_existing_id_found BOOLEAN := FALSE;
  v_export_canonical_id UUID;
  v_export_granite BOOLEAN := FALSE;
  v_export_empty BOOLEAN := FALSE;
  v_export_declared BOOLEAN := FALSE;
  v_export_containers_qty INTEGER;
  v_export_movements_qty INTEGER;
  v_export_discharge_ports TEXT[] := '{}'::TEXT[];
  v_export_ce_status TEXT;
  v_export_linked BOOLEAN := FALSE;
  v_export_old JSONB;
  v_export_new JSONB;
  v_current_terminal_assignment BOOLEAN;
  v_existing_terminal_state BOOLEAN;
  v_existing_front BOOLEAN;
  v_front_changed BOOLEAN;
  v_state_changed BOOLEAN;
  v_requires_justification BOOLEAN := FALSE;
  v_closed_blockers JSONB := '[]'::JSONB;
  v_report_id UUID;
  v_report_status TEXT;
  v_terminal_code TEXT;
  v_blocked_report_id UUID;
  v_schedule JSONB;
  v_schedule_entity_id TEXT;
  v_schedule_field TEXT;
  v_schedule_old_value TEXT;
  v_schedule_new_value TEXT;
  v_new_voyage_status TEXT;
  v_active_pods INTEGER;
  v_pending_pods INTEGER;
BEGIN
  SELECT up.role INTO v_role
  FROM public.user_profiles AS up
  WHERE up.id = auth.uid() AND up.active = TRUE;

  IF auth.uid() IS NULL OR v_role IS NULL
     OR v_role NOT IN ('admin', 'administrativo', 'operacoes', 'operator', 'documentacao', 'equipamentos', 'financeiro') THEN
    RAISE EXCEPTION 'Usuario ativo sem permissao para editar a escala.'
      USING ERRCODE = '42501';
  END IF;
  v_department := CASE
    WHEN v_role IN ('admin', 'administrativo') THEN 'administrativo'
    WHEN v_role = 'documentacao' THEN 'documentacao'
    WHEN v_role = 'equipamentos' THEN 'equipamentos'
    ELSE 'operacoes'
  END;
  v_entity_id := p_voyage_id::TEXT || '::' || v_port;

  IF p_expected_revision IS NULL THEN
    RAISE EXCEPTION 'Revision esperada obrigatoria.' USING ERRCODE = '22023';
  END IF;
  IF p_fronts IS NULL OR jsonb_typeof(p_fronts) <> 'array'
     OR p_terminals IS NULL OR jsonb_typeof(p_terminals) <> 'array'
     OR p_export_expectation IS NULL OR jsonb_typeof(p_export_expectation) <> 'object'
     OR (p_export_expectation ? 'discharge_ports'
         AND jsonb_typeof(p_export_expectation->'discharge_ports') <> 'array')
     OR (p_export_expectation ? 'schedule'
         AND jsonb_typeof(p_export_expectation->'schedule') <> 'object') THEN
    RAISE EXCEPTION 'Payload de escala invalido.' USING ERRCODE = '22023';
  END IF;

  -- A escala física é a linha da viagem; o lock serializa todas as escritas
  -- terminais da mesma escala, mesmo quando ela ainda não tem state próprio.
  PERFORM 1 FROM public.voyages WHERE id = p_voyage_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Viagem nao encontrada.' USING ERRCODE = 'P0002';
  END IF;

  IF v_port !~ '^BR[A-Z0-9]{3}$' THEN
    RAISE EXCEPTION 'LOCODE brasileiro invalido: %.', v_port USING ERRCODE = '22023';
  END IF;

  -- ports é a referência FK usada pela escala, não uma lista fechada de lanes.
  -- O seed 307 dá nomes aos portos conhecidos; um LOCODE brasileiro válido
  -- informado pela operação também precisa poder criar a primeira escala.
  -- O lock por código evita duas primeiras escritas criarem linhas duplicadas.
  PERFORM pg_advisory_xact_lock(hashtextextended(v_port, 0));
  SELECT p.id INTO v_port_id
  FROM public.ports AS p
  WHERE upper(btrim(p.locode)) = v_port
    AND upper(btrim(p.locode)) LIKE 'BR%'
  ORDER BY p.id
  LIMIT 1;
  IF v_port_id IS NULL THEN
    INSERT INTO public.ports (name, locode, country)
    VALUES (v_port, v_port, 'Brasil')
    RETURNING id INTO v_port_id;
  END IF;

  SELECT rs.revision
  INTO v_current_revision
  FROM public.voyage_escala_revision_state AS rs
  WHERE rs.voyage_id = p_voyage_id AND rs.port = v_port
  FOR UPDATE;
  IF NOT FOUND THEN
    v_current_revision := 0;
  END IF;
  IF p_expected_revision <> v_current_revision THEN
    RAISE EXCEPTION 'REVISAO_OBSOLETA: esperada %, atual %.', p_expected_revision, v_current_revision
      USING ERRCODE = 'P0001';
  END IF;
  v_next_revision := v_current_revision + 1;

  -- A declaração de exportação usa esta RPC para manter a mesma proteção de
  -- revisão, mas perfis operacionais já existentes não podem ganhar poder de
  -- trocar terminal/data só por passarem pelo caminho transacional. Eles
  -- podem alterar a expectativa exportadora; qualquer mudança de state físico
  -- continua exclusiva de Operações/Admin.
  IF v_role NOT IN ('admin', 'administrativo', 'operacoes') AND (
    EXISTS (
      SELECT 1
      FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
      LEFT JOIN public.voyage_escala_operation_fronts AS old_f
        ON old_f.voyage_id = p_voyage_id AND old_f.port = v_port
       AND old_f.sentido = lower(btrim(f.sentido))
       AND old_f.modalidade = lower(btrim(f.modalidade))
      WHERE f.terminal_id IS DISTINCT FROM old_f.terminal_id
    )
    OR EXISTS (
      SELECT 1
      FROM public.voyage_escala_operation_fronts AS old_f
      WHERE old_f.voyage_id = p_voyage_id AND old_f.port = v_port
        AND old_f.terminal_id IS NOT NULL
        AND NOT EXISTS (
          SELECT 1
          FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
          WHERE lower(btrim(f.sentido)) = old_f.sentido
            AND lower(btrim(f.modalidade)) = old_f.modalidade
        )
    )
    OR EXISTS (
      SELECT 1
      FROM jsonb_to_recordset(p_terminals) AS t(terminal_id UUID, terminal_atb TIMESTAMPTZ, terminal_atd TIMESTAMPTZ, terminal_rtw INTEGER)
      LEFT JOIN public.voyage_escala_terminal_state AS old_t
        ON old_t.voyage_id = p_voyage_id AND old_t.port = v_port AND old_t.terminal_id = t.terminal_id
      WHERE old_t.terminal_id IS NULL
         OR old_t.terminal_atb IS DISTINCT FROM t.terminal_atb
         OR old_t.terminal_atd IS DISTINCT FROM t.terminal_atd
         OR old_t.terminal_rtw IS DISTINCT FROM t.terminal_rtw
    )
    OR EXISTS (
      SELECT 1
      FROM public.voyage_escala_terminal_state AS old_t
      WHERE old_t.voyage_id = p_voyage_id AND old_t.port = v_port
        AND old_t.terminal_id IS NOT NULL AND NOT EXISTS (
          SELECT 1
          FROM jsonb_to_recordset(p_terminals) AS t(terminal_id UUID, terminal_atb TIMESTAMPTZ, terminal_atd TIMESTAMPTZ, terminal_rtw INTEGER)
          WHERE t.terminal_id = old_t.terminal_id
        )
    )
  ) THEN
    RAISE EXCEPTION 'Somente Operações/Admin podem editar terminais da escala.' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
    GROUP BY lower(btrim(sentido)), lower(btrim(modalidade))
    HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION 'Frente duplicada na escala.' USING ERRCODE = '23505';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_terminals) AS t(terminal_id UUID, terminal_atb TIMESTAMPTZ, terminal_atd TIMESTAMPTZ, terminal_rtw INTEGER)
    GROUP BY terminal_id
    HAVING COUNT(*) > 1
  ) THEN
    RAISE EXCEPTION 'Terminal duplicado no estado da escala.' USING ERRCODE = '23505';
  END IF;

  FOR v_front IN
    SELECT lower(btrim(f.sentido)) AS sentido,
           lower(btrim(f.modalidade)) AS modalidade,
           f.terminal_id,
           f.source
    FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
  LOOP
    IF NOT (
      (v_front.sentido = 'importacao' AND v_front.modalidade IN ('carga_cheia', 'carga_solta', 'vazio', 'veiculo'))
      OR (v_front.sentido = 'exportacao' AND v_front.modalidade IN ('granito', 'vazio'))
    ) THEN
      RAISE EXCEPTION 'Frente %/% invalida.', v_front.sentido, v_front.modalidade USING ERRCODE = '23514';
    END IF;
    IF (v_front.sentido = 'importacao' AND v_front.source <> 'operational_data')
       OR (v_front.sentido = 'exportacao' AND v_front.source <> 'export_declaration') THEN
      RAISE EXCEPTION 'Fonte invalida para a frente %/%.', v_front.sentido, v_front.modalidade USING ERRCODE = '23514';
    END IF;

    IF v_front.terminal_id IS NOT NULL THEN
      SELECT d.id, d.code, d.name, d.active, d.tipo, d.port_id
      INTO v_depot
      FROM public.depots AS d
      WHERE d.id = v_front.terminal_id AND d.port_id = v_port_id
        AND d.tipo = 'terminal_portuario';
      IF NOT FOUND THEN
        RAISE EXCEPTION 'Terminal nao pertence ao porto % ou nao e terminal portuario.', v_port
          USING ERRCODE = '23514';
      END IF;

      SELECT EXISTS (
        SELECT 1 FROM public.voyage_escala_terminal_state AS s
        WHERE s.voyage_id = p_voyage_id AND s.port = v_port AND s.terminal_id = v_front.terminal_id
      ) INTO v_existing_terminal_state;
      SELECT EXISTS (
        SELECT 1 FROM public.voyage_escala_operation_fronts AS old_f
        WHERE old_f.voyage_id = p_voyage_id AND old_f.port = v_port
          AND old_f.sentido = v_front.sentido
          AND old_f.modalidade = v_front.modalidade
          AND old_f.terminal_id = v_front.terminal_id
      ) INTO v_current_terminal_assignment;
      -- Histórico pode continuar apontando para terminal inativo; uma nova
      -- atribuição só aceita cadastro ativo.
      IF NOT v_current_terminal_assignment AND NOT v_depot.active THEN
        RAISE EXCEPTION 'Terminal inativo % nao pode receber nova atribuicao.', v_depot.code
          USING ERRCODE = '23514';
      END IF;
    END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1
    FROM jsonb_to_recordset(p_fronts) AS f(
      sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT
    )
    WHERE f.terminal_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_terminals) AS t(
          terminal_id UUID, terminal_atb TIMESTAMPTZ, terminal_atd TIMESTAMPTZ, terminal_rtw INTEGER
        )
        WHERE t.terminal_id = f.terminal_id
      )
  ) THEN
    RAISE EXCEPTION 'Frente atribuida exige terminal no estado da escala.'
      USING ERRCODE = '23514';
  END IF;

  FOR v_terminal IN
    SELECT t.terminal_id, t.terminal_atb, t.terminal_atd, t.terminal_rtw
    FROM jsonb_to_recordset(p_terminals) AS t(
      terminal_id UUID,
      terminal_atb TIMESTAMPTZ,
      terminal_atd TIMESTAMPTZ,
      terminal_rtw INTEGER
    )
  LOOP
    SELECT d.id, d.code, d.name, d.active, d.tipo, d.port_id
    INTO v_depot
    FROM public.depots AS d
    WHERE d.id = v_terminal.terminal_id AND d.port_id = v_port_id
      AND d.tipo = 'terminal_portuario';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Terminal de estado nao pertence ao porto %.', v_port USING ERRCODE = '23514';
    END IF;
    SELECT EXISTS (
      SELECT 1 FROM public.voyage_escala_terminal_state AS s
      WHERE s.voyage_id = p_voyage_id AND s.port = v_port AND s.terminal_id = v_terminal.terminal_id
    ) INTO v_existing_terminal_state;
    IF NOT v_existing_terminal_state AND NOT v_depot.active THEN
      RAISE EXCEPTION 'Terminal inativo % nao pode receber novo estado.', v_depot.code
        USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
      WHERE f.terminal_id = v_terminal.terminal_id
    ) AND NOT v_existing_terminal_state THEN
      RAISE EXCEPTION 'Estado informado para terminal sem frente atribuida.' USING ERRCODE = '23514';
    END IF;
    IF v_terminal.terminal_atd IS NOT NULL
       AND (v_terminal.terminal_atb IS NULL OR v_terminal.terminal_atd < v_terminal.terminal_atb) THEN
      RAISE EXCEPTION 'terminal_atd < terminal_atb para o terminal %.', v_depot.code
        USING ERRCODE = '23514';
    END IF;
  END LOOP;

  IF COALESCE(p_export_expectation->>'existing_id', '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
    v_export_existing_id := (p_export_expectation->>'existing_id')::UUID;
  END IF;
  SELECT COALESCE(ves.tem_exportacao, FALSE), COALESCE(ves.has_granite, FALSE), COALESCE(ves.has_empty, FALSE),
         ves.containers_qty, ves.movements_qty, COALESCE(ves.discharge_ports, '{}'::TEXT[]),
         ves.ce_status, COALESCE(ves.linked, FALSE)
  INTO v_old_export_declared, v_old_export_granite, v_old_export_empty,
       v_old_export_containers_qty, v_old_export_movements_qty, v_old_export_discharge_ports,
       v_old_export_ce_status, v_old_export_linked
  FROM public.voyage_export_schedules AS ves
  WHERE ves.id = v_export_existing_id AND ves.voyage_id = p_voyage_id
  FOR UPDATE;
  v_export_existing_id_found := FOUND;
  IF NOT v_export_existing_id_found THEN
    SELECT COALESCE(ves.tem_exportacao, FALSE), COALESCE(ves.has_granite, FALSE), COALESCE(ves.has_empty, FALSE),
           ves.containers_qty, ves.movements_qty, COALESCE(ves.discharge_ports, '{}'::TEXT[]),
           ves.ce_status, COALESCE(ves.linked, FALSE)
    INTO v_old_export_declared, v_old_export_granite, v_old_export_empty,
         v_old_export_containers_qty, v_old_export_movements_qty, v_old_export_discharge_ports,
         v_old_export_ce_status, v_old_export_linked
    FROM public.voyage_export_schedules AS ves
    WHERE ves.voyage_id = p_voyage_id AND ves.pol = v_port
    FOR UPDATE;
  END IF;
  v_old_export_exists := FOUND;
  IF COALESCE(p_export_expectation, '{}'::JSONB) ? 'granito' THEN
    v_export_granite := COALESCE((p_export_expectation->>'granito')::BOOLEAN, FALSE);
  ELSE
    v_export_granite := EXISTS (
      SELECT 1 FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
      WHERE lower(btrim(f.sentido)) = 'exportacao' AND lower(btrim(f.modalidade)) = 'granito'
    );
  END IF;
  IF COALESCE(p_export_expectation, '{}'::JSONB) ? 'has_empty' THEN
    v_export_empty := COALESCE((p_export_expectation->>'has_empty')::BOOLEAN, FALSE);
  ELSIF COALESCE(p_export_expectation, '{}'::JSONB) ? 'vazios' THEN
    v_export_empty := COALESCE((p_export_expectation->>'vazios')::BOOLEAN, FALSE);
  ELSE
    v_export_empty := EXISTS (
      SELECT 1 FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
      WHERE lower(btrim(f.sentido)) = 'exportacao' AND lower(btrim(f.modalidade)) = 'vazio'
    );
  END IF;
  IF (COALESCE(p_export_expectation, '{}'::JSONB) ? 'has_empty')
     AND (COALESCE(p_export_expectation, '{}'::JSONB) ? 'vazios')
     AND COALESCE((p_export_expectation->>'has_empty')::BOOLEAN, FALSE)
         IS DISTINCT FROM COALESCE((p_export_expectation->>'vazios')::BOOLEAN, FALSE) THEN
    RAISE EXCEPTION 'Expectativas de vazios divergentes.' USING ERRCODE = '23514';
  END IF;
  IF COALESCE(p_export_expectation, '{}'::JSONB) ? 'tem_exportacao' THEN
    v_export_declared := COALESCE((p_export_expectation->>'tem_exportacao')::BOOLEAN, FALSE);
    IF NOT v_export_declared AND (v_export_granite OR v_export_empty) THEN
      RAISE EXCEPTION 'Expectativa de exportacao desligada com frente declarada.' USING ERRCODE = '23514';
    END IF;
    IF v_export_declared AND NOT (v_export_granite OR v_export_empty)
       AND NOT (v_old_export_exists AND v_old_export_declared
                AND NOT v_old_export_granite AND NOT v_old_export_empty) THEN
      RAISE EXCEPTION 'Nova expectativa de exportacao exige granito ou vazios.' USING ERRCODE = '23514';
    END IF;
  ELSE
    v_export_declared := v_export_granite OR v_export_empty;
  END IF;

  v_export_containers_qty := CASE
    WHEN COALESCE(p_export_expectation, '{}'::JSONB) ? 'containers_qty'
      THEN (p_export_expectation->>'containers_qty')::INTEGER
    ELSE v_old_export_containers_qty
  END;
  v_export_movements_qty := CASE
    WHEN COALESCE(p_export_expectation, '{}'::JSONB) ? 'movements_qty'
      THEN (p_export_expectation->>'movements_qty')::INTEGER
    ELSE v_old_export_movements_qty
  END;
  v_export_discharge_ports := CASE
    WHEN COALESCE(p_export_expectation, '{}'::JSONB) ? 'discharge_ports'
      THEN COALESCE(
        ARRAY(SELECT jsonb_array_elements_text(p_export_expectation->'discharge_ports')),
        '{}'::TEXT[]
      )
    ELSE v_old_export_discharge_ports
  END;
  v_export_ce_status := CASE
    WHEN COALESCE(p_export_expectation, '{}'::JSONB) ? 'ce_status'
      THEN p_export_expectation->>'ce_status'
    ELSE v_old_export_ce_status
  END;
  v_export_linked := CASE
    WHEN COALESCE(p_export_expectation, '{}'::JSONB) ? 'linked'
      THEN COALESCE((p_export_expectation->>'linked')::BOOLEAN, FALSE)
    ELSE v_old_export_linked
  END;
  IF v_export_granite AND NOT EXISTS (
    SELECT 1 FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
    WHERE lower(btrim(f.sentido)) = 'exportacao' AND lower(btrim(f.modalidade)) = 'granito'
  ) THEN
    RAISE EXCEPTION 'Expectativa de granito exige a frente exportacao/granito.' USING ERRCODE = '23514';
  END IF;
  IF v_export_empty AND NOT EXISTS (
    SELECT 1 FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
    WHERE lower(btrim(f.sentido)) = 'exportacao' AND lower(btrim(f.modalidade)) = 'vazio'
  ) THEN
    RAISE EXCEPTION 'Expectativa de vazios exige a frente exportacao/vazio.' USING ERRCODE = '23514';
  END IF;

  v_export_old := jsonb_build_object(
    'tem_exportacao', v_old_export_declared,
    'granito', v_old_export_granite,
    'vazios', v_old_export_empty,
    'has_empty', v_old_export_empty,
    'containers_qty', v_old_export_containers_qty,
    'movements_qty', v_old_export_movements_qty,
    'discharge_ports', v_old_export_discharge_ports,
    'ce_status', v_old_export_ce_status,
    'linked', v_old_export_linked
  );
  v_export_new := jsonb_build_object(
    'tem_exportacao', v_export_declared,
    'granito', v_export_granite,
    'vazios', v_export_empty,
    'has_empty', v_export_empty,
    'containers_qty', v_export_containers_qty,
    'movements_qty', v_export_movements_qty,
    'discharge_ports', v_export_discharge_ports,
    'ce_status', v_export_ce_status,
    'linked', v_export_linked
  );
  IF v_export_old IS DISTINCT FROM v_export_new THEN
    v_requires_justification := v_current_revision > 0;
  END IF;

  -- Primeiro compara tudo. Nenhuma escrita, nem de uma frente, acontece
  -- antes de terminar a checagem de ADR fechado.
  FOR v_old_front IN
    SELECT old_f.sentido, old_f.modalidade, old_f.terminal_id, old_f.source
    FROM public.voyage_escala_operation_fronts AS old_f
    WHERE old_f.voyage_id = p_voyage_id AND old_f.port = v_port
  LOOP
    SELECT lower(btrim(f.sentido)) AS sentido,
           lower(btrim(f.modalidade)) AS modalidade,
           f.terminal_id,
           f.source
    INTO v_new_front
    FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
    WHERE lower(btrim(f.sentido)) = v_old_front.sentido
      AND lower(btrim(f.modalidade)) = v_old_front.modalidade;
    v_existing_front := FOUND;
    IF NOT v_existing_front THEN
      v_front_changed := TRUE;
    ELSE
      v_front_changed := v_old_front.terminal_id IS DISTINCT FROM v_new_front.terminal_id
        OR v_old_front.source IS DISTINCT FROM v_new_front.source;
    END IF;
    IF v_front_changed THEN
      v_requires_justification := v_current_revision > 0;
      IF v_old_front.terminal_id IS NOT NULL THEN
        SELECT d.code, r.id
        INTO v_terminal_code, v_blocked_report_id
        FROM public.agency_departure_reports AS r
        JOIN public.depots AS d ON d.id = r.terminal_id
        WHERE r.voyage_id = p_voyage_id AND r.port = v_port
          AND r.terminal_id = v_old_front.terminal_id AND r.status = 'closed'
        LIMIT 1;
        IF FOUND THEN
          v_closed_blockers := v_closed_blockers || jsonb_build_array(jsonb_build_object(
            'terminal_code', v_terminal_code, 'report_id', v_blocked_report_id,
            'reason', 'front_change'
          ));
        END IF;
      END IF;
    END IF;
  END LOOP;

  FOR v_front IN
    SELECT lower(btrim(f.sentido)) AS sentido,
           lower(btrim(f.modalidade)) AS modalidade,
           f.terminal_id,
           f.source
    FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
  LOOP
    SELECT old_f.terminal_id, old_f.source
    INTO v_old_front
    FROM public.voyage_escala_operation_fronts AS old_f
    WHERE old_f.voyage_id = p_voyage_id AND old_f.port = v_port
      AND old_f.sentido = v_front.sentido AND old_f.modalidade = v_front.modalidade;
    v_existing_front := FOUND;
    IF NOT v_existing_front THEN
      v_front_changed := TRUE;
    ELSE
      v_front_changed := v_old_front.terminal_id IS DISTINCT FROM v_front.terminal_id
        OR v_old_front.source IS DISTINCT FROM v_front.source;
    END IF;
    IF v_front_changed AND v_front.terminal_id IS NOT NULL THEN
      SELECT d.code, r.id
      INTO v_terminal_code, v_blocked_report_id
      FROM public.agency_departure_reports AS r
      JOIN public.depots AS d ON d.id = r.terminal_id
      WHERE r.voyage_id = p_voyage_id AND r.port = v_port
        AND r.terminal_id = v_front.terminal_id AND r.status = 'closed'
      LIMIT 1;
      IF FOUND THEN
        v_closed_blockers := v_closed_blockers || jsonb_build_array(jsonb_build_object(
          'terminal_code', v_terminal_code, 'report_id', v_blocked_report_id,
          'reason', 'front_change'
        ));
      END IF;
    END IF;
  END LOOP;

  FOR v_terminal IN
    SELECT t.terminal_id, t.terminal_atb, t.terminal_atd, t.terminal_rtw
    FROM jsonb_to_recordset(p_terminals) AS t(
      terminal_id UUID, terminal_atb TIMESTAMPTZ, terminal_atd TIMESTAMPTZ, terminal_rtw INTEGER
    )
  LOOP
    SELECT s.terminal_atb, s.terminal_atd, s.terminal_rtw
    INTO v_old_terminal
    FROM public.voyage_escala_terminal_state AS s
    WHERE s.voyage_id = p_voyage_id AND s.port = v_port AND s.terminal_id = v_terminal.terminal_id;
    v_existing_terminal_state := FOUND;
    IF NOT v_existing_terminal_state THEN
      v_state_changed := TRUE;
    ELSE
      v_state_changed := v_old_terminal.terminal_atb IS DISTINCT FROM v_terminal.terminal_atb
        OR v_old_terminal.terminal_atd IS DISTINCT FROM v_terminal.terminal_atd
        OR v_old_terminal.terminal_rtw IS DISTINCT FROM v_terminal.terminal_rtw;
    END IF;
    IF v_state_changed THEN
      v_requires_justification := v_current_revision > 0;
      SELECT d.code, r.id
      INTO v_terminal_code, v_blocked_report_id
      FROM public.agency_departure_reports AS r
      JOIN public.depots AS d ON d.id = r.terminal_id
      WHERE r.voyage_id = p_voyage_id AND r.port = v_port
        AND r.terminal_id = v_terminal.terminal_id AND r.status = 'closed'
      LIMIT 1;
      IF FOUND THEN
        v_closed_blockers := v_closed_blockers || jsonb_build_array(jsonb_build_object(
          'terminal_code', v_terminal_code, 'report_id', v_blocked_report_id,
          'reason', 'terminal_dates'
        ));
      END IF;
    END IF;
  END LOOP;

  IF v_export_old IS DISTINCT FROM v_export_new AND v_current_revision > 0 THEN
    v_requires_justification := TRUE;
    FOR v_report IN
      SELECT DISTINCT r.id, r.terminal_id, d.code
      FROM public.agency_departure_reports AS r
      JOIN public.depots AS d ON d.id = r.terminal_id
      WHERE r.voyage_id = p_voyage_id AND r.port = v_port AND r.status = 'closed'
        AND r.terminal_id IN (
          SELECT f.terminal_id
          FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
          WHERE f.terminal_id IS NOT NULL
          UNION
          SELECT old_f.terminal_id
          FROM public.voyage_escala_operation_fronts AS old_f
          WHERE old_f.voyage_id = p_voyage_id AND old_f.port = v_port AND old_f.terminal_id IS NOT NULL
        )
    LOOP
      v_closed_blockers := v_closed_blockers || jsonb_build_array(jsonb_build_object(
        'terminal_code', v_report.code, 'report_id', v_report.id,
        'reason', 'export_expectation'
      ));
    END LOOP;
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      blocker
      ORDER BY blocker->>'terminal_code', blocker->>'reason', blocker->>'report_id'
    ),
    '[]'::JSONB
  )
  INTO v_closed_blockers
  FROM jsonb_array_elements(v_closed_blockers) AS blockers(blocker);

  IF jsonb_array_length(v_closed_blockers) > 0 THEN
    -- A tentativa bloqueada não escreve nada: a UI recebe o contrato estável
    -- e pode traduzir terminal_code/report_id sem parsear DETAIL.
    RETURN jsonb_build_object(
      'revision', v_current_revision,
      'fronts', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'sentido', f.sentido, 'modalidade', f.modalidade,
          'terminal_id', f.terminal_id, 'source', f.source,
          'last_changed_at', f.last_changed_at, 'last_changed_by', f.last_changed_by,
          'revision', f.revision
        ) ORDER BY f.sentido, f.modalidade)
        FROM public.voyage_escala_operation_fronts AS f
        WHERE f.voyage_id = p_voyage_id AND f.port = v_port
      ), '[]'::JSONB),
      'terminals', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'terminal_id', s.terminal_id, 'code', d.code, 'name', d.name,
          'active', d.active, 'port_id', s.port_id,
          'terminal_atb', s.terminal_atb, 'terminal_atd', s.terminal_atd,
          'terminal_rtw', s.terminal_rtw, 'revision', s.revision,
          'report_id', r.id
        ) ORDER BY s.terminal_atb NULLS LAST, d.code)
        FROM public.voyage_escala_terminal_state AS s
        JOIN public.depots AS d ON d.id = s.terminal_id
        LEFT JOIN public.agency_departure_reports AS r
          ON r.voyage_id = s.voyage_id AND r.port = s.port AND r.terminal_id = s.terminal_id
        WHERE s.voyage_id = p_voyage_id AND s.port = v_port
      ), '[]'::JSONB),
      'closed_blockers', v_closed_blockers,
      'blocked', TRUE
    );
  END IF;
  IF v_requires_justification AND NULLIF(btrim(COALESCE(p_justification, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Justificativa obrigatoria para alterar estado terminalizado existente.'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.voyage_escala_revision_state (voyage_id, port, port_id, revision)
  VALUES (p_voyage_id, v_port, v_port_id, 0)
  ON CONFLICT (voyage_id, port) DO NOTHING;

  -- O conjunto recebido representa todos os terminais ainda atribuídos a
  -- frentes. Remover os ausentes evita que ATB/ATD órfãos continuem visíveis
  -- no Line-Up e que a FK contra depots impeça a limpeza do terminal.
  FOR v_old_terminal IN
    SELECT s.*
    FROM public.voyage_escala_terminal_state AS s
    WHERE s.voyage_id = p_voyage_id AND s.port = v_port
      AND s.terminal_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_terminals) AS t(terminal_id UUID, terminal_atb TIMESTAMPTZ, terminal_atd TIMESTAMPTZ, terminal_rtw INTEGER)
        WHERE t.terminal_id = s.terminal_id
      )
  LOOP
    INSERT INTO public.audit_logs (
      entity_type, entity_id, field_name, old_value, new_value,
      changed_by, changed_at, justification, actor_role, actor_department
    )
    VALUES (
      'voyage_pod_schedule', v_entity_id, 'terminal_state_removed',
      jsonb_build_object(
        'terminal_id', v_old_terminal.terminal_id,
        'terminal_atb', v_old_terminal.terminal_atb,
        'terminal_atd', v_old_terminal.terminal_atd,
        'terminal_rtw', v_old_terminal.terminal_rtw
      )::TEXT,
      NULL, auth.uid(), clock_timestamp(), p_justification, v_role, v_department
    );
    DELETE FROM public.voyage_escala_terminal_state
    WHERE voyage_id = p_voyage_id AND port = v_port AND terminal_id = v_old_terminal.terminal_id;
  END LOOP;

  UPDATE public.voyage_escala_revision_state
  SET revision = v_next_revision, updated_at = now()
  WHERE voyage_id = p_voyage_id AND port = v_port;

  UPDATE public.voyage_escala_terminal_state
  SET revision = v_next_revision, updated_at = now()
  WHERE voyage_id = p_voyage_id AND port = v_port;

  FOR v_terminal IN
    SELECT t.terminal_id, t.terminal_atb, t.terminal_atd, t.terminal_rtw
    FROM jsonb_to_recordset(p_terminals) AS t(
      terminal_id UUID, terminal_atb TIMESTAMPTZ, terminal_atd TIMESTAMPTZ, terminal_rtw INTEGER
    )
  LOOP
    SELECT s.terminal_atb, s.terminal_atd, s.terminal_rtw
    INTO v_old_terminal
    FROM public.voyage_escala_terminal_state AS s
    WHERE s.voyage_id = p_voyage_id AND s.port = v_port AND s.terminal_id = v_terminal.terminal_id;
    v_existing_terminal_state := FOUND;
    INSERT INTO public.voyage_escala_terminal_state (
      voyage_id, port, port_id, terminal_id, terminal_atb, terminal_atd, terminal_rtw, revision
    )
    VALUES (
      p_voyage_id, v_port, v_port_id, v_terminal.terminal_id,
      v_terminal.terminal_atb, v_terminal.terminal_atd, v_terminal.terminal_rtw, v_next_revision
    )
    ON CONFLICT (voyage_id, port, terminal_id) DO UPDATE SET
      port_id = EXCLUDED.port_id,
      terminal_atb = EXCLUDED.terminal_atb,
      terminal_atd = EXCLUDED.terminal_atd,
      terminal_rtw = EXCLUDED.terminal_rtw,
      revision = EXCLUDED.revision,
      updated_at = now();

    IF NOT v_existing_terminal_state THEN
      v_state_changed := TRUE;
    ELSE
      v_state_changed := v_old_terminal.terminal_atb IS DISTINCT FROM v_terminal.terminal_atb
        OR v_old_terminal.terminal_atd IS DISTINCT FROM v_terminal.terminal_atd
        OR v_old_terminal.terminal_rtw IS DISTINCT FROM v_terminal.terminal_rtw;
    END IF;

    IF v_state_changed THEN
      INSERT INTO public.audit_logs (
        entity_type, entity_id, field_name, old_value, new_value,
        changed_by, changed_at, justification, actor_role, actor_department
      )
      VALUES (
        'voyage_pod_schedule', v_entity_id, 'terminal_dates',
        CASE WHEN v_existing_terminal_state THEN jsonb_build_object(
          'terminal_id', v_terminal.terminal_id,
          'terminal_atb', v_old_terminal.terminal_atb,
          'terminal_atd', v_old_terminal.terminal_atd,
          'terminal_rtw', v_old_terminal.terminal_rtw
        )::TEXT ELSE NULL END,
        jsonb_build_object(
          'terminal_id', v_terminal.terminal_id,
          'terminal_atb', v_terminal.terminal_atb,
          'terminal_atd', v_terminal.terminal_atd,
          'terminal_rtw', v_terminal.terminal_rtw
        )::TEXT,
        auth.uid(), clock_timestamp(), p_justification, v_role, v_department
      );
    END IF;
  END LOOP;

  FOR v_old_front IN
    SELECT old_f.*
    FROM public.voyage_escala_operation_fronts AS old_f
    WHERE old_f.voyage_id = p_voyage_id AND old_f.port = v_port
      AND NOT EXISTS (
        SELECT 1
        FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
        WHERE lower(btrim(f.sentido)) = old_f.sentido
          AND lower(btrim(f.modalidade)) = old_f.modalidade
      )
  LOOP
    INSERT INTO public.audit_logs (
      entity_type, entity_id, field_name, old_value, new_value,
      changed_by, changed_at, justification, actor_role, actor_department
    )
    VALUES (
      'voyage_pod_schedule', v_entity_id, 'front_removed', to_jsonb(v_old_front)::TEXT, NULL,
      auth.uid(), clock_timestamp(), p_justification, v_role, v_department
    );
    DELETE FROM public.voyage_escala_operation_fronts WHERE id = v_old_front.id;
  END LOOP;

  FOR v_front IN
    SELECT lower(btrim(f.sentido)) AS sentido,
           lower(btrim(f.modalidade)) AS modalidade,
           f.terminal_id,
           f.source
    FROM jsonb_to_recordset(p_fronts) AS f(sentido TEXT, modalidade TEXT, terminal_id UUID, source TEXT)
  LOOP
    SELECT old_f.*
    INTO v_old_front
    FROM public.voyage_escala_operation_fronts AS old_f
    WHERE old_f.voyage_id = p_voyage_id AND old_f.port = v_port
      AND old_f.sentido = v_front.sentido AND old_f.modalidade = v_front.modalidade;
    v_existing_front := FOUND;

    INSERT INTO public.voyage_escala_operation_fronts (
      voyage_id, port, port_id, sentido, modalidade, terminal_id, source,
      revision, last_changed_at, last_changed_by
    )
    VALUES (
      p_voyage_id, v_port, v_port_id, v_front.sentido, v_front.modalidade,
      v_front.terminal_id, v_front.source, v_next_revision, clock_timestamp(), auth.uid()
    )
    ON CONFLICT (voyage_id, port, sentido, modalidade) DO UPDATE SET
      port_id = EXCLUDED.port_id,
      terminal_id = EXCLUDED.terminal_id,
      source = EXCLUDED.source,
      revision = EXCLUDED.revision,
      last_changed_at = EXCLUDED.last_changed_at,
      last_changed_by = EXCLUDED.last_changed_by,
      updated_at = now();

    IF NOT v_existing_front THEN
      INSERT INTO public.audit_logs (
        entity_type, entity_id, field_name, old_value, new_value,
        changed_by, changed_at, justification, actor_role, actor_department
      )
      VALUES (
        'voyage_pod_schedule', v_entity_id, 'front_created', NULL,
        jsonb_build_object('sentido', v_front.sentido, 'modalidade', v_front.modalidade,
                           'terminal_id', v_front.terminal_id, 'source', v_front.source)::TEXT,
        auth.uid(), clock_timestamp(), p_justification, v_role, v_department
      );
    ELSE
      IF v_old_front.terminal_id IS DISTINCT FROM v_front.terminal_id THEN
        INSERT INTO public.audit_logs (
          entity_type, entity_id, field_name, old_value, new_value,
          changed_by, changed_at, justification, actor_role, actor_department
        )
        VALUES (
          'voyage_pod_schedule', v_entity_id, 'terminal_assignment',
          jsonb_build_object(
            'terminal_id', v_old_front.terminal_id,
            'terminal_code', (SELECT d.code FROM public.depots AS d WHERE d.id = v_old_front.terminal_id)
          )::TEXT,
          jsonb_build_object(
            'terminal_id', v_front.terminal_id,
            'terminal_code', (SELECT d.code FROM public.depots AS d WHERE d.id = v_front.terminal_id)
          )::TEXT,
          auth.uid(), clock_timestamp(), p_justification, v_role, v_department
        );
      END IF;
      IF v_old_front.source IS DISTINCT FROM v_front.source THEN
        INSERT INTO public.audit_logs (
          entity_type, entity_id, field_name, old_value, new_value,
          changed_by, changed_at, justification, actor_role, actor_department
        )
        VALUES (
          'voyage_pod_schedule', v_entity_id, 'front_source',
          v_old_front.source, v_front.source,
          auth.uid(), clock_timestamp(), p_justification, v_role, v_department
        );
      END IF;
    END IF;
  END LOOP;

  IF p_export_expectation IS NOT NULL OR v_old_export_exists OR v_export_declared THEN
    IF (p_export_expectation IS NOT NULL OR v_export_declared)
       AND (NOT v_old_export_exists OR v_export_old IS DISTINCT FROM v_export_new) THEN
      INSERT INTO public.audit_logs (
        entity_type, entity_id, field_name, old_value, new_value,
        changed_by, changed_at, justification, actor_role, actor_department
      )
      VALUES (
        'voyage_pod_schedule', v_entity_id, 'export_expectation',
        CASE WHEN v_old_export_exists THEN v_export_old::TEXT ELSE NULL END,
        v_export_new::TEXT,
        auth.uid(), clock_timestamp(), p_justification, v_role, v_department
      );
    END IF;
    IF v_export_existing_id_found THEN
      SELECT ves.id
      INTO v_export_canonical_id
      FROM public.voyage_export_schedules AS ves
      WHERE ves.voyage_id = p_voyage_id
        AND ves.pol = v_port
        AND ves.id <> v_export_existing_id
      FOR UPDATE;
      IF FOUND THEN
        UPDATE public.voyage_export_schedules
        SET tem_exportacao = v_export_declared,
            has_granite = v_export_granite,
            has_empty = v_export_empty,
            containers_qty = v_export_containers_qty,
            movements_qty = v_export_movements_qty,
            discharge_ports = v_export_discharge_ports,
            ce_status = v_export_ce_status,
            linked = v_export_linked,
            updated_at = now()
        WHERE id = v_export_canonical_id AND voyage_id = p_voyage_id;
        DELETE FROM public.voyage_export_schedules
        WHERE id = v_export_existing_id AND voyage_id = p_voyage_id;
      ELSE
        UPDATE public.voyage_export_schedules
        SET pol = v_port,
            tem_exportacao = v_export_declared,
            has_granite = v_export_granite,
            has_empty = v_export_empty,
            containers_qty = v_export_containers_qty,
            movements_qty = v_export_movements_qty,
            discharge_ports = v_export_discharge_ports,
            ce_status = v_export_ce_status,
            linked = v_export_linked,
            updated_at = now()
        WHERE id = v_export_existing_id AND voyage_id = p_voyage_id;
      END IF;
    ELSE
      INSERT INTO public.voyage_export_schedules (
        voyage_id, pol, tem_exportacao, has_granite, has_empty,
        containers_qty, movements_qty, discharge_ports, ce_status, linked, updated_at
      )
      VALUES (
        p_voyage_id, v_port, v_export_declared, v_export_granite, v_export_empty,
        v_export_containers_qty, v_export_movements_qty, v_export_discharge_ports,
        v_export_ce_status, v_export_linked, now()
      )
      ON CONFLICT (voyage_id, pol) DO UPDATE SET
        tem_exportacao = EXCLUDED.tem_exportacao,
        has_granite = EXCLUDED.has_granite,
        has_empty = EXCLUDED.has_empty,
        containers_qty = EXCLUDED.containers_qty,
        movements_qty = EXCLUDED.movements_qty,
        discharge_ports = EXCLUDED.discharge_ports,
        ce_status = EXCLUDED.ce_status,
        linked = EXCLUDED.linked,
        updated_at = now();
    END IF;
  END IF;

  -- O editor terminalizado envia também o snapshot dos campos do POD. Como
  -- esta função já segura o lock da escala, os audit rows são gravados na
  -- mesma transação das frentes, evitando o estado parcial antigo (frentes
  -- salvas, datas do POD falhando em uma segunda chamada).
  v_schedule := p_export_expectation->'schedule';
  IF v_schedule IS NOT NULL THEN
    v_schedule_entity_id := p_voyage_id::TEXT || '::' || v_port;
    FOREACH v_schedule_field IN ARRAY ARRAY[
      'eta', 'etb', 'ata', 'atb', 'etd', 'atd', 'rtw', 'ces',
      'linked', 'escala_number', 'tem_importacao', 'deleted'
    ] LOOP
      IF v_schedule ? v_schedule_field THEN
        SELECT al.new_value
        INTO v_schedule_old_value
        FROM public.audit_logs AS al
        WHERE al.entity_type = 'voyage_pod_schedule'
          AND al.entity_id = v_schedule_entity_id
          AND al.field_name = v_schedule_field
        ORDER BY al.changed_at DESC, al.id DESC
        LIMIT 1;
        v_schedule_new_value := CASE
          WHEN v_schedule->v_schedule_field IS NULL OR v_schedule->v_schedule_field = 'null'::JSONB THEN NULL
          ELSE v_schedule->>v_schedule_field
        END;
        -- O editor sempre envia deleted=false para retirar um soft-delete,
        -- mas isso não deve gerar uma linha de auditoria em cada salvamento.
        IF v_schedule_field = 'deleted'
           AND v_schedule_new_value = 'false'
           AND v_schedule_old_value IS DISTINCT FROM 'true' THEN
          CONTINUE;
        END IF;
        IF v_schedule_field = 'ces'
           AND v_schedule_old_value IS NULL
           AND v_schedule_new_value IN ('waiting', 'missing') THEN
          CONTINUE;
        END IF;
        IF v_schedule_old_value IS DISTINCT FROM v_schedule_new_value THEN
          INSERT INTO public.audit_logs (
            entity_type, entity_id, field_name, old_value, new_value,
            changed_by, changed_at, justification, actor_role, actor_department
          )
          VALUES (
            'voyage_pod_schedule', v_schedule_entity_id, v_schedule_field,
            v_schedule_old_value, v_schedule_new_value,
            auth.uid(), clock_timestamp(), p_justification, v_role, v_department
          );
        END IF;
      END IF;
    END LOOP;
  END IF;

  -- O caminho terminalizado já gravou o ATD na mesma transação. Recalcula o
  -- status da viagem aqui para manter o contrato do save legado sem uma
  -- segunda chamada sujeita a observar um snapshot parcial.
  IF v_schedule ? 'atd' THEN
    WITH pod_entities AS (
      SELECT DISTINCT al.entity_id
      FROM public.audit_logs AS al
      WHERE al.entity_type = 'voyage_pod_schedule'
        AND split_part(al.entity_id, '::', 1)::BIGINT = p_voyage_id
    ), latest_atd AS (
      SELECT DISTINCT ON (al.entity_id) al.entity_id, NULLIF(btrim(al.new_value), '') AS atd
      FROM public.audit_logs AS al
      WHERE al.entity_type = 'voyage_pod_schedule'
        AND al.field_name = 'atd'
        AND split_part(al.entity_id, '::', 1)::BIGINT = p_voyage_id
      ORDER BY al.entity_id, al.changed_at DESC, al.id DESC
    ), latest_omitted AS (
      SELECT DISTINCT ON (al.entity_id) al.entity_id, al.new_value
      FROM public.audit_logs AS al
      WHERE al.entity_type = 'voyage_pod_schedule'
        AND al.field_name = 'omitted'
        AND split_part(al.entity_id, '::', 1)::BIGINT = p_voyage_id
      ORDER BY al.entity_id, al.changed_at DESC, al.id DESC
    ), latest_deleted AS (
      SELECT DISTINCT ON (al.entity_id) al.entity_id, al.new_value
      FROM public.audit_logs AS al
      WHERE al.entity_type = 'voyage_pod_schedule'
        AND al.field_name = 'deleted'
        AND split_part(al.entity_id, '::', 1)::BIGINT = p_voyage_id
      ORDER BY al.entity_id, al.changed_at DESC, al.id DESC
    ), active AS (
      SELECT e.entity_id, a.atd
      FROM pod_entities AS e
      LEFT JOIN latest_atd AS a ON a.entity_id = e.entity_id
      LEFT JOIN latest_omitted AS o ON o.entity_id = e.entity_id
      LEFT JOIN latest_deleted AS d ON d.entity_id = e.entity_id
      WHERE COALESCE(o.new_value, 'false') <> 'true'
        AND COALESCE(d.new_value, 'false') <> 'true'
    )
    SELECT COUNT(*)::INTEGER, COUNT(*) FILTER (WHERE NULLIF(btrim(atd), '') IS NULL)::INTEGER
    INTO v_active_pods, v_pending_pods
    FROM active;

    IF v_active_pods > 0 THEN
      v_new_voyage_status := CASE WHEN v_pending_pods = 0 THEN 'completed' ELSE 'active' END;
      UPDATE public.voyages
      SET status = v_new_voyage_status
      WHERE id = p_voyage_id
        AND status <> 'cancelled'
        AND status IS DISTINCT FROM v_new_voyage_status;
    END IF;
  END IF;

  -- A primeira frente cria/reutiliza o ADR do terminal. Um ADR aberto sem
  -- frentes é o único que pode ser removido; ADR fechado fica preservado.
  FOR v_depot IN
    SELECT DISTINCT f.terminal_id, d.code, d.name, d.port_id
    FROM public.voyage_escala_operation_fronts AS f
    JOIN public.depots AS d ON d.id = f.terminal_id
    WHERE f.voyage_id = p_voyage_id AND f.port = v_port AND f.terminal_id IS NOT NULL
  LOOP
    SELECT r.id, r.status INTO v_report_id, v_report_status
    FROM public.agency_departure_reports AS r
    WHERE r.voyage_id = p_voyage_id AND r.port = v_port AND r.terminal_id = v_depot.terminal_id
    FOR UPDATE;
    IF NOT FOUND THEN
      INSERT INTO public.agency_departure_reports (
        voyage_id, port, terminal, terminal_id, terminal_port_id
      )
      VALUES (p_voyage_id, v_port, v_depot.code, v_depot.terminal_id, v_depot.port_id)
      ON CONFLICT (voyage_id, port, terminal_id) WHERE terminal_id IS NOT NULL
      DO UPDATE SET terminal = EXCLUDED.terminal
      RETURNING id INTO v_report_id;
      INSERT INTO public.audit_logs (
        entity_type, entity_id, field_name, old_value, new_value,
        changed_by, changed_at, justification, actor_role, actor_department
      )
      VALUES (
        'voyage_pod_schedule', v_entity_id, 'adr_created', NULL,
        jsonb_build_object('terminal_code', v_depot.code, 'report_id', v_report_id)::TEXT,
        auth.uid(), clock_timestamp(), p_justification, v_role, v_department
      );
    END IF;
  END LOOP;

  FOR v_report IN
    SELECT r.id, r.terminal_id, r.status, d.code
    FROM public.agency_departure_reports AS r
    JOIN public.depots AS d ON d.id = r.terminal_id
    WHERE r.voyage_id = p_voyage_id AND r.port = v_port
      AND r.terminal_id IS NOT NULL
      AND NOT EXISTS (
        SELECT 1 FROM public.voyage_escala_operation_fronts AS f
        WHERE f.voyage_id = p_voyage_id AND f.port = v_port
          AND f.terminal_id = r.terminal_id
      )
    FOR UPDATE OF r
  LOOP
    IF v_report.status = 'open' THEN
      -- Um ADR aberto só pode ser removido quando não há filhos, histórico ou
      -- alertas associados. Qualquer alerta do ADR, em qualquer status, preserva
      -- o registro para não perder o histórico operacional.
      IF NOT EXISTS (
        SELECT 1
        FROM public.agency_departure_report_signoffs
        WHERE report_id = v_report.id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.agency_departure_report_department_signoffs
        WHERE report_id = v_report.id
      )
      AND NOT EXISTS (
        SELECT 1
        FROM public.agency_departure_report_occurrences
        WHERE report_id = v_report.id
      )
       AND NOT EXISTS (
         SELECT 1
         FROM public.audit_logs AS al
         -- Eventos do ciclo do ADR usam o próprio report_id como entity_id.
         -- O índice idx_audit_logs_entity_id torna esta guarda pontual; não
         -- faça ILIKE sobre old_value/new_value dentro do lock da escala.
         WHERE al.entity_id = v_report.id::TEXT
       )
      AND NOT EXISTS (
        SELECT 1
        FROM public.alerts AS a
        WHERE a.entity_type = 'agency_departure_report'
          AND a.entity_id LIKE public.agency_report_alert_entity_prefix(p_voyage_id, v_port, v_report.code) || '%'
      ) THEN
        INSERT INTO public.audit_logs (
          entity_type, entity_id, field_name, old_value, new_value,
          changed_by, changed_at, justification, actor_role, actor_department
        )
        VALUES (
          'voyage_pod_schedule', v_entity_id, 'adr_removed',
          jsonb_build_object('terminal_code', v_report.code, 'report_id', v_report.id)::TEXT,
          NULL, auth.uid(), clock_timestamp(), p_justification, v_role, v_department
        );
        DELETE FROM public.agency_departure_reports
        WHERE id = v_report.id AND status = 'open';
      ELSE
        INSERT INTO public.audit_logs (
          entity_type, entity_id, field_name, old_value, new_value,
          changed_by, changed_at, justification, actor_role, actor_department
        )
        VALUES (
          'voyage_pod_schedule', v_entity_id, 'adr_preserved',
          jsonb_build_object('terminal_code', v_report.code, 'report_id', v_report.id)::TEXT,
          'dependentes ou historico preservados', auth.uid(), clock_timestamp(),
          p_justification, v_role, v_department
        );
      END IF;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'revision', v_next_revision,
    'fronts', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'sentido', f.sentido, 'modalidade', f.modalidade,
        'terminal_id', f.terminal_id, 'source', f.source,
        'last_changed_at', f.last_changed_at, 'last_changed_by', f.last_changed_by,
        'revision', f.revision
      ) ORDER BY f.sentido, f.modalidade)
      FROM public.voyage_escala_operation_fronts AS f
      WHERE f.voyage_id = p_voyage_id AND f.port = v_port
    ), '[]'::JSONB),
    'terminals', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'terminal_id', s.terminal_id, 'code', d.code, 'name', d.name,
        'active', d.active, 'port_id', s.port_id,
        'terminal_atb', s.terminal_atb, 'terminal_atd', s.terminal_atd,
        'terminal_rtw', s.terminal_rtw, 'revision', s.revision,
        'report_id', r.id
      ) ORDER BY s.terminal_atb NULLS LAST, d.code)
      FROM public.voyage_escala_terminal_state AS s
      JOIN public.depots AS d ON d.id = s.terminal_id
      LEFT JOIN public.agency_departure_reports AS r
        ON r.voyage_id = s.voyage_id AND r.port = s.port AND r.terminal_id = s.terminal_id
      WHERE s.voyage_id = p_voyage_id AND s.port = v_port
    ), '[]'::JSONB),
    'closed_blockers', '[]'::JSONB,
    'blocked', FALSE
  );
END;
$_$;



--
-- Name: save_voyage_escala_terminal_state_v2(bigint, text, integer, jsonb, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_voyage_escala_terminal_state_v2(p_voyage_id bigint, p_port text, p_expected_revision integer, p_fronts jsonb, p_terminals jsonb, p_export_expectation jsonb, p_justification text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_legacy JSONB;
  v_non_tbc JSONB;
  v_port TEXT := upper(btrim(COALESCE(p_port, '')));
  v_port_id BIGINT;
  v_revision INTEGER;
  v_terminal JSONB;
  v_terminal_id UUID;
BEGIN
  IF p_terminals IS NULL OR jsonb_typeof(p_terminals) <> 'array' THEN
    RAISE EXCEPTION 'Payload de Atracacoes invalido.' USING ERRCODE = '22023';
  END IF;

  SELECT p.id INTO v_port_id
  FROM public.ports AS p
  WHERE upper(btrim(p.locode)) = v_port
  LIMIT 1;
  IF v_port_id IS NULL THEN
    INSERT INTO public.ports (name, locode, country)
    VALUES (v_port, v_port, 'Brasil')
    RETURNING id INTO v_port_id;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'terminal_id', item->>'terminal_id',
    'terminal_atb', item->>'terminal_atb',
    'terminal_atd', item->>'terminal_atd',
    'terminal_rtw', item->>'terminal_rtw'
  )), '[]'::JSONB)
  INTO v_non_tbc
  FROM jsonb_array_elements(p_terminals) AS entries(item)
  WHERE NULLIF(entries.item->>'terminal_id', '') IS NOT NULL;

  -- O RPC legado não pode interpretar NULL com igualdade simples: uma linha
  -- TBC não deve ser considerada removida nem bloquear uma edição que só
  -- altera a expectativa de exportação. O patch abaixo mantém essa regra no
  -- corpo legado, sem duplicar sua implementação nesta migration.
  v_legacy := public.save_voyage_escala_terminal_state(
    p_voyage_id,
    v_port,
    p_expected_revision,
    p_fronts,
    v_non_tbc,
    p_export_expectation,
    p_justification
  );

  IF COALESCE((v_legacy->>'blocked')::BOOLEAN, FALSE) THEN
    RETURN v_legacy;
  END IF;

  SELECT rs.revision INTO v_revision
  FROM public.voyage_escala_revision_state AS rs
  WHERE rs.voyage_id = p_voyage_id AND rs.port = v_port;

  FOR v_terminal IN SELECT value FROM jsonb_array_elements(p_terminals)
  LOOP
    v_terminal_id := NULLIF(v_terminal->>'terminal_id', '')::UUID;
    IF v_terminal_id IS NULL THEN
      INSERT INTO public.voyage_escala_terminal_state (
        voyage_id, port, port_id, terminal_id, terminal_etb, terminal_atb,
        terminal_etd, terminal_atd, terminal_rtw, revision
      ) VALUES (
        p_voyage_id, v_port, v_port_id, NULL,
        NULLIF(v_terminal->>'terminal_etb', '')::TIMESTAMPTZ,
        NULLIF(v_terminal->>'terminal_atb', '')::TIMESTAMPTZ,
        NULLIF(v_terminal->>'terminal_etd', '')::TIMESTAMPTZ,
        NULLIF(v_terminal->>'terminal_atd', '')::TIMESTAMPTZ,
        NULLIF(v_terminal->>'terminal_rtw', '')::INTEGER,
        COALESCE(v_revision, 0)
      )
      ON CONFLICT (voyage_id, port) WHERE terminal_id IS NULL DO UPDATE SET
        terminal_etb = EXCLUDED.terminal_etb,
        terminal_atb = EXCLUDED.terminal_atb,
        terminal_etd = EXCLUDED.terminal_etd,
        terminal_atd = EXCLUDED.terminal_atd,
        terminal_rtw = EXCLUDED.terminal_rtw,
        revision = EXCLUDED.revision,
        updated_at = now();
    ELSE
      UPDATE public.voyage_escala_terminal_state
      SET terminal_etb = NULLIF(v_terminal->>'terminal_etb', '')::TIMESTAMPTZ,
          terminal_etd = NULLIF(v_terminal->>'terminal_etd', '')::TIMESTAMPTZ,
          revision = COALESCE(v_revision, revision),
          updated_at = now()
      WHERE voyage_id = p_voyage_id AND port = v_port AND terminal_id = v_terminal_id;
    END IF;
  END LOOP;

  -- O status da viagem deixa de depender do atd documental do POD. A função
  -- é criada na migration de alertas seguinte e existe antes de qualquer
  -- chamada operacional desta RPC.
  PERFORM public.refresh_voyage_status_from_terminal_scales(p_voyage_id);

  RETURN jsonb_set(
    v_legacy,
    '{terminals}',
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'terminal_id', s.terminal_id,
        'terminal_etb', s.terminal_etb,
        'terminal_atb', s.terminal_atb,
        'terminal_etd', s.terminal_etd,
        'terminal_atd', s.terminal_atd,
        'terminal_rtw', s.terminal_rtw
      ) ORDER BY s.terminal_atb NULLS LAST, s.terminal_etb NULLS LAST, s.terminal_id NULLS LAST)
      FROM public.voyage_escala_terminal_state AS s
      WHERE s.voyage_id = p_voyage_id AND s.port = v_port
    ), '[]'::JSONB),
    TRUE
  );
END;
$$;



