-- Name: seed_customer_contact_preferences(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seed_customer_contact_preferences() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO public.customer_contact_preferences (contact_id, nature, enabled, source)
  VALUES
    (NEW.id, 'avisos_gerais', true, 'interno'),
    (NEW.id, 'avisos_operacionais', true, 'interno'),
