--
-- Name: set_agency_report_signoff(bigint, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_agency_report_signoff(p_voyage_id bigint, p_port text, p_section text, p_state text, p_justification text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_owner TEXT;
  v_report_id UUID;
  v_current TEXT;
  v_justification TEXT := NULLIF(btrim(COALESCE(p_justification, '')), '');
BEGIN
  SELECT role INTO v_role FROM public.user_profiles
  WHERE id = auth.uid() AND active = TRUE;
  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501';
  END IF;
  v_role := CASE v_role WHEN 'admin' THEN 'administrativo'
                        WHEN 'operator' THEN 'documentacao'
                        ELSE v_role END;

  v_owner := public.agency_report_section_owner(p_section);
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Secao invalida.' USING ERRCODE = '22023';
  END IF;
  IF v_role NOT IN ('administrativo', v_owner) THEN
    RAISE EXCEPTION 'Secao pertence ao departamento %.', v_owner USING ERRCODE = '42501';
  END IF;
  IF p_state NOT IN ('pending', 'confirmed', 'nothing_to_declare') THEN
    RAISE EXCEPTION 'Estado invalido.' USING ERRCODE = '22023';
  END IF;

  v_report_id := public.ensure_agency_departure_report(p_voyage_id, p_port);

  IF EXISTS (
    SELECT 1 FROM public.agency_departure_reports
    WHERE id = v_report_id AND status = 'closed'
  ) THEN
    RAISE EXCEPTION 'ADR fechado: reabra antes de alterar sign-offs.' USING ERRCODE = '42501';
  END IF;

  -- Estado atual da secao: decide se ha transicao e se exige justificativa.
  SELECT state INTO v_current
  FROM public.agency_departure_report_signoffs
  WHERE report_id = v_report_id AND section = p_section
  FOR UPDATE;
  v_current := COALESCE(v_current, 'pending');

  -- Sem mudanca: nao grava evento nem exige justificativa (idempotente).
  IF v_current = p_state THEN
    RETURN jsonb_build_object('report_id', v_report_id, 'unchanged', TRUE);
  END IF;

  -- Alterar uma decisao ja registrada exige justificativa; a primeira saida de
  -- "pending" nao (a UI faz a confirmacao explicita).
  IF v_current <> 'pending' AND v_justification IS NULL THEN
    RAISE EXCEPTION 'Alterar uma decisao ja registrada exige justificativa.' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.agency_departure_report_signoffs
    (report_id, section, state, department, signed_by, signed_at)
  VALUES (v_report_id, p_section, p_state, v_owner, auth.uid(),
          CASE WHEN p_state = 'pending' THEN NULL ELSE now() END)
  ON CONFLICT (report_id, section) DO UPDATE SET
    state = EXCLUDED.state,
    department = EXCLUDED.department,
    signed_by = EXCLUDED.signed_by,
    signed_at = EXCLUDED.signed_at;

  -- Historico da transicao (de->para + justificativa quando aplicavel).
  INSERT INTO public.audit_logs
    (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES ('agency_departure_report_signoff',
          p_voyage_id || '::' || upper(btrim(p_port)) || '::' || p_section,
          'state', v_current, p_state, auth.uid(), v_justification);

  RETURN jsonb_build_object('report_id', v_report_id);
END;
$$;



--
-- Name: set_agency_report_signoff_by_report_id(uuid, bigint, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_agency_report_signoff_by_report_id(p_report_id uuid, p_voyage_id bigint, p_port text, p_section text, p_state text, p_justification text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_owner TEXT;
  v_current TEXT;
  v_report RECORD;
  v_justification TEXT := NULLIF(btrim(COALESCE(p_justification, '')), '');
BEGIN
  SELECT role INTO v_role FROM public.user_profiles WHERE id = auth.uid() AND active = TRUE;
  IF v_role IS NULL THEN RAISE EXCEPTION 'Sem permissao.' USING ERRCODE = '42501'; END IF;
  v_role := CASE v_role WHEN 'admin' THEN 'administrativo' WHEN 'operator' THEN 'documentacao' ELSE v_role END;
  v_owner := public.agency_report_section_owner(p_section);
  IF v_owner IS NULL OR p_state NOT IN ('pending', 'confirmed', 'nothing_to_declare') THEN
    RAISE EXCEPTION 'Secao ou estado invalido.' USING ERRCODE = '22023';
  END IF;
  IF v_role NOT IN ('administrativo', v_owner) THEN
    RAISE EXCEPTION 'Secao pertence ao departamento %.', v_owner USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_report FROM public.agency_departure_reports WHERE id = p_report_id FOR UPDATE;
  IF NOT FOUND OR v_report.voyage_id <> p_voyage_id OR upper(btrim(v_report.port)) <> upper(btrim(p_port))
     OR v_report.terminal_id IS NULL THEN
    RAISE EXCEPTION 'report_id nao pertence a ADR terminalizado da escala %::%.', p_voyage_id, upper(btrim(p_port)) USING ERRCODE = '23514';
  END IF;
  IF v_report.status = 'closed' THEN RAISE EXCEPTION 'ADR fechado: reabra antes de alterar sign-offs.' USING ERRCODE = '42501'; END IF;

  SELECT state INTO v_current FROM public.agency_departure_report_signoffs
  WHERE report_id = p_report_id AND section = p_section FOR UPDATE;
  v_current := COALESCE(v_current, 'pending');
  IF v_current = p_state THEN RETURN jsonb_build_object('report_id', p_report_id, 'unchanged', TRUE); END IF;
  IF v_current <> 'pending' AND v_justification IS NULL THEN
    RAISE EXCEPTION 'Alterar uma decisao ja registrada exige justificativa.' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.agency_departure_report_signoffs
    (report_id, section, state, department, signed_by, signed_at)
  VALUES (p_report_id, p_section, p_state, v_owner, auth.uid(), CASE WHEN p_state = 'pending' THEN NULL ELSE now() END)
  ON CONFLICT (report_id, section) DO UPDATE SET state = EXCLUDED.state, department = EXCLUDED.department,
    signed_by = EXCLUDED.signed_by, signed_at = EXCLUDED.signed_at;
  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES ('agency_departure_report_signoff', p_report_id::TEXT || '::' || p_section, 'state', v_current, p_state, auth.uid(), v_justification);
  RETURN jsonb_build_object('report_id', p_report_id);
END;
$$;



--
-- Name: set_agency_report_terminal(bigint, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_agency_report_terminal(p_voyage_id bigint, p_port text, p_terminal text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT;
  v_report_id UUID;
BEGIN
  SELECT role INTO v_role FROM public.user_profiles
  WHERE id = auth.uid() AND active = TRUE;
  v_role := CASE v_role WHEN 'admin' THEN 'administrativo'
                        WHEN 'operator' THEN 'documentacao'
                        ELSE v_role END;
  IF v_role NOT IN ('administrativo', 'operacoes') THEN
    RAISE EXCEPTION 'Terminal pertence ao departamento operacoes.' USING ERRCODE = '42501';
  END IF;

  v_report_id := public.ensure_agency_departure_report(p_voyage_id, p_port);
  UPDATE public.agency_departure_reports
  SET terminal = NULLIF(btrim(p_terminal), '')
  WHERE id = v_report_id AND status = 'open';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ADR fechado: reabra antes de alterar terminal.' USING ERRCODE = '42501';
  END IF;
END;
$$;



--
-- Name: set_bl_cod(text, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_bl_cod(p_bl_id text, p_omission_id bigint, p_justification text, p_changed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_discharge TEXT;
  v_omitted TEXT;
  v_old_pod TEXT;
  v_customer BIGINT;
  v_justification TEXT := NULLIF(btrim(COALESCE(p_justification, '')), '');
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa.' USING ERRCODE = '42501';
  END IF;
  IF v_justification IS NULL THEN
    RAISE EXCEPTION 'Marcar COD exige justificativa.' USING ERRCODE = '22023';
  END IF;

  SELECT o.discharge_pod, o.omitted_pod INTO v_discharge, v_omitted
  FROM public.bl_transshipments AS t
  JOIN public.voyage_omissions AS o ON o.id = t.omission_id
  WHERE t.bl_id = p_bl_id AND t.omission_id = p_omission_id
  FOR UPDATE OF o;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transbordo do B/L % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  SELECT pod, customer_id INTO v_old_pod, v_customer
  FROM public.bls WHERE id = p_bl_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.bl_transshipments
  SET disposition = 'cod', updated_at = now()
  WHERE bl_id = p_bl_id AND omission_id = p_omission_id;
  UPDATE public.bls SET pod = v_discharge, updated_at = now() WHERE id = p_bl_id;

  IF to_regprocedure('public.apply_cod_financial_effect(text,bigint,text)') IS NOT NULL THEN
    PERFORM public.apply_cod_financial_effect(p_bl_id, p_omission_id, v_old_pod);
  END IF;

  INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES ('bls', p_bl_id, 'pod', v_old_pod, v_discharge, p_changed_by,
    'COD apos omissao da escala de ' || v_omitted || ': ' || v_justification);
  IF v_customer IS NOT NULL THEN
    INSERT INTO public.portal_notifications(customer_id, bl_id, type, title, message, link)
    VALUES (v_customer, p_bl_id, 'transshipment', 'Destino alterado (COD)',
      'A pedido, o destino final do B/L ' || p_bl_id || ' foi alterado para ' || v_discharge ||
        ' (COD), apos a omissao da escala de ' || v_omitted || '.', NULL);
  END IF;
END;
$$;



--
-- Name: set_bl_transshipment(text, bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_bl_transshipment(p_bl_id text, p_omission_id bigint, p_justification text, p_changed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_was TEXT;
  v_original_pod TEXT;
  v_old_pod TEXT;
  v_customer BIGINT;
  v_justification TEXT := NULLIF(btrim(COALESCE(p_justification, '')), '');
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa.' USING ERRCODE = '42501';
  END IF;

  SELECT t.disposition, o.omitted_pod INTO v_was, v_original_pod
  FROM public.bl_transshipments AS t
  JOIN public.voyage_omissions AS o ON o.id = t.omission_id
  WHERE t.bl_id = p_bl_id AND t.omission_id = p_omission_id
  FOR UPDATE OF o;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Transbordo do B/L % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  SELECT pod, customer_id INTO v_old_pod, v_customer
  FROM public.bls WHERE id = p_bl_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF v_was = 'cod' AND v_justification IS NULL THEN
    RAISE EXCEPTION 'Reverter COD exige justificativa.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.bl_transshipments
  SET disposition = 'transshipment', updated_at = now()
  WHERE bl_id = p_bl_id AND omission_id = p_omission_id;

  IF v_was = 'cod' THEN
    UPDATE public.bls SET pod = v_original_pod, updated_at = now() WHERE id = p_bl_id;

    IF to_regprocedure('public.apply_cod_financial_effect(text,bigint,text)') IS NOT NULL THEN
      PERFORM public.apply_cod_financial_effect(p_bl_id, p_omission_id, v_old_pod);
    END IF;

    INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
    VALUES ('bls', p_bl_id, 'pod', v_old_pod, v_original_pod, p_changed_by,
      'Reversao de COD para transbordo: ' || v_justification);

    IF v_customer IS NOT NULL THEN
      INSERT INTO public.portal_notifications(customer_id, bl_id, type, title, message, link)
      VALUES (
        v_customer, p_bl_id, 'transshipment', 'Correção de destino (COD)',
        'O destino final do B/L ' || p_bl_id || ' foi restaurado para ' || v_original_pod ||
          ' após a reversão do COD.', NULL
      );
    END IF;
  END IF;

  INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES ('bls', p_bl_id, 'transbordo', v_was, 'transshipment', p_changed_by,
    'Definicao de transbordo (navio de terceiros)');
END;
$$;



--
-- Name: set_communications_enabled(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_communications_enabled(p_enabled boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := public._portal_actor_role();
  v_previous BOOLEAN;
BEGIN
  IF p_enabled IS NULL THEN
    RAISE EXCEPTION 'O estado da chave de Comunicados é obrigatório.' USING ERRCODE = '22023';
  END IF;

  IF v_role IS DISTINCT FROM 'administrativo' THEN
    RAISE EXCEPTION 'Somente o perfil administrativo pode alterar a chave de Comunicados.'
      USING ERRCODE = '42501';
  END IF;

  SELECT communications_enabled
    INTO v_previous
    FROM public.app_settings
    WHERE id = 1
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Configuração global não encontrada.' USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.app_settings
  SET communications_enabled = p_enabled
  WHERE id = 1;

  IF v_previous IS DISTINCT FROM p_enabled THEN
    INSERT INTO public.audit_logs (
      entity_type,
      entity_id,
      field_name,
      old_value,
      new_value,
      changed_by,
      justification
    )
    VALUES (
      'app_settings',
      '1',
      'communications_enabled',
      v_previous::TEXT,
      p_enabled::TEXT,
      auth.uid(),
      'Alteração da chave global de envio de Comunicados'
    );
  END IF;

  RETURN p_enabled;
END;
$$;



--
-- Name: set_container_discharge_date(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_container_discharge_date() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_ata date;
BEGIN
  SELECT v.ata::date INTO v_ata
  FROM bls b
  JOIN voyages v ON v.id = b.voyage_id
  WHERE b.id = NEW.bl_id;
  IF v_ata IS NOT NULL THEN
    NEW.discharge_date := v_ata;
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: set_customer_portal_account_active(bigint, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_customer_portal_account_active(p_customer_id bigint, p_active boolean, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.is_active_user()
     OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao administrativa.'
      USING ERRCODE = '42501';
  END IF;

  IF COALESCE(p_active, true)
     AND NOT EXISTS (
       SELECT 1
       FROM public.customer_portal_accounts AS a
       WHERE a.customer_id = p_customer_id
         AND a.auth_user_id IS NOT NULL
     ) THEN
    RAISE EXCEPTION 'Conta do portal sem usuario Auth nao pode ser ativada.'
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.customer_portal_accounts
  SET
    active = COALESCE(p_active, true),
    updated_at = now()
  WHERE customer_id = p_customer_id;

  RETURN public.get_customer_portal_account(p_customer_id);
END;
$$;



--
-- Name: set_demurrage_dunning_interval_days(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_demurrage_dunning_interval_days(p_days integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role TEXT := public._portal_actor_role();
  v_previous INTEGER;
BEGIN
  IF v_role IS DISTINCT FROM 'administrativo' THEN
    RAISE EXCEPTION 'Somente o perfil administrativo pode alterar o intervalo da régua.' USING ERRCODE = '42501';
  END IF;
  IF p_days IS NULL OR p_days < 1 OR p_days > 365 THEN
    RAISE EXCEPTION 'O intervalo deve estar entre 1 e 365 dias.' USING ERRCODE = '22023';
  END IF;
  SELECT demurrage_dunning_interval_days INTO v_previous
  FROM public.app_settings WHERE id = 1 FOR UPDATE;
  UPDATE public.app_settings SET demurrage_dunning_interval_days = p_days WHERE id = 1;
  IF v_previous IS DISTINCT FROM p_days THEN
    INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
    VALUES ('app_settings', '1', 'demurrage_dunning_interval_days', v_previous::TEXT, p_days::TEXT, auth.uid(), 'Alteração do intervalo da régua de Demurrage');
  END IF;
  RETURN p_days;
END;
$$;



--
-- Name: set_import_batch_ce_master(bigint, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_import_batch_ce_master(p_batch_id bigint, p_ce_master text, p_changed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_batch public.import_batches%ROWTYPE;
  v_normalized TEXT := NULLIF(btrim(COALESCE(p_ce_master, '')), '');
  v_old_value TEXT;
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.is_active_user()
     OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para editar CE Master.'
      USING ERRCODE = '42501';
  END IF;

  SELECT *
  INTO v_batch
  FROM public.import_batches
  WHERE id = p_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Lote de importacao % nao encontrado', p_batch_id
      USING ERRCODE = 'P0002';
  END IF;

  v_old_value := NULLIF(btrim(COALESCE(v_batch.ce_master, '')), '');
  IF v_old_value IS NOT DISTINCT FROM v_normalized THEN
    RETURN;
  END IF;

  UPDATE public.import_batches
  SET ce_master = v_normalized
  WHERE id = p_batch_id;

  INSERT INTO public.audit_logs (
    entity_type, entity_id, field_name, old_value, new_value, changed_by, justification
  )
  VALUES (
    'import_batches',
    COALESCE(v_batch.voyage_id::TEXT, p_batch_id::TEXT),
    'ce_master',
    v_old_value,
    v_normalized,
    p_changed_by,
    'Atualizacao manual de CE Master'
  );
END;
$$;



--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;



--
-- Name: set_voyage_route_ce_master(bigint, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_voyage_route_ce_master(p_voyage_id bigint, p_pol text, p_pod text, p_ce_master text, p_changed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM public.set_voyage_route_ce_master(p_voyage_id, p_pol, p_pod, p_ce_master, p_changed_by, 'container');
END;
$$;



--
-- Name: set_voyage_route_ce_master(bigint, text, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_voyage_route_ce_master(p_voyage_id bigint, p_pol text, p_pod text, p_ce_master text, p_changed_by uuid, p_cargo_mode text DEFAULT 'container'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_norm TEXT := NULLIF(btrim(COALESCE(p_ce_master, '')), '');
  v_pol TEXT := upper(btrim(COALESCE(p_pol, '')));
  v_pod TEXT := upper(btrim(COALESCE(p_pod, '')));
  v_mode TEXT := lower(btrim(COALESCE(p_cargo_mode, 'container')));
  v_old TEXT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para editar CE Master.' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.voyages WHERE id = p_voyage_id) THEN
    RAISE EXCEPTION 'Viagem % nao encontrada', p_voyage_id USING ERRCODE = 'P0002';
  END IF;

  SELECT ce_master INTO v_old FROM public.voyage_route_ce_master
    WHERE voyage_id = p_voyage_id AND pol = v_pol AND pod = v_pod AND cargo_mode = v_mode;

  INSERT INTO public.voyage_route_ce_master(voyage_id, pol, pod, cargo_mode, ce_master, updated_by, updated_at)
  VALUES (p_voyage_id, v_pol, v_pod, v_mode, v_norm, p_changed_by, now())
  ON CONFLICT (voyage_id, pol, pod, cargo_mode)
  DO UPDATE SET ce_master = EXCLUDED.ce_master, updated_by = EXCLUDED.updated_by, updated_at = now();

  IF COALESCE(v_old, '') IS DISTINCT FROM COALESCE(v_norm, '') THEN
    INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
    VALUES ('voyage', p_voyage_id::TEXT, 'ce_master', NULLIF(v_old, ''), v_norm, p_changed_by,
            CASE WHEN v_mode = 'vazios' THEN 'CE Master por rota (manifesto de vazios)'
                 ELSE 'CE Master por rota (viagem so-B/L)' END);
  END IF;
END;
$$;



--
-- Name: settle_cod_adjustment(bigint, uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_cod_adjustment(p_adjustment_id bigint, p_actor uuid DEFAULT NULL::uuid, p_resulting_document_id bigint DEFAULT NULL::bigint, p_resulting_document_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_adjustment RECORD;
  v_actor UUID := COALESCE(p_actor, auth.uid());
  v_invoice_id BIGINT;
  v_offset NUMERIC(14,2) := 0;
  v_refund_id BIGINT;
  v_document_type TEXT := NULLIF(lower(btrim(COALESCE(p_resulting_document_type, ''))), '');
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_financeiro_user() THEN
    RAISE EXCEPTION 'Apenas Financeiro, Administrativo ou Admin pode liquidar ajustes de COD.'
      USING ERRCODE = '42501';
  END IF;
  IF p_actor IS NOT NULL AND p_actor <> auth.uid() THEN
    RAISE EXCEPTION 'O ator da liquidação deve ser o usuário autenticado.' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_adjustment
  FROM public.cod_adjustments
  WHERE id = p_adjustment_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Ajuste de COD % nao encontrado.', p_adjustment_id USING ERRCODE = 'P0002';
  END IF;
  IF v_adjustment.status <> 'pending' THEN
    RAISE EXCEPTION 'Ajuste de COD % nao esta pendente (status=%).', p_adjustment_id, v_adjustment.status
      USING ERRCODE = '22023';
  END IF;
  IF v_adjustment.action IN ('complementary_invoice', 'cancel_and_reissue', 'manual_charge_review') THEN
    IF p_resulting_document_id IS NULL OR v_document_type IS DISTINCT FROM 'invoice' THEN
      RAISE EXCEPTION 'A ação % exige o ID de uma invoice emitida para concluir o ajuste.', v_adjustment.action
        USING ERRCODE = '22023';
    END IF;
  ELSIF p_resulting_document_id IS NOT NULL OR v_document_type IS NOT NULL THEN
    RAISE EXCEPTION 'A ação % não aceita vínculo manual de documento.', v_adjustment.action
      USING ERRCODE = '22023';
  END IF;

  SELECT i.id INTO v_invoice_id
  FROM public.invoices AS i
  WHERE i.bl_id = v_adjustment.bl_id
    AND i.status NOT IN ('cancelled', 'obsolete', 'covered')
  ORDER BY i.issued_at DESC NULLS LAST, i.id DESC
  LIMIT 1
  FOR UPDATE;

  IF v_invoice_id IS NULL THEN
    SELECT i.id INTO v_invoice_id
    FROM public.invoices AS i
    JOIN public.invoice_bls AS ib ON ib.invoice_id = i.id
    WHERE ib.bl_id = v_adjustment.bl_id
      AND i.status NOT IN ('cancelled', 'obsolete', 'covered')
    ORDER BY i.issued_at DESC NULLS LAST, i.id DESC
    LIMIT 1
    FOR UPDATE;
  END IF;

  IF p_resulting_document_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM public.invoices AS resulting
      WHERE resulting.id = p_resulting_document_id
        AND COALESCE(resulting.status, 'issued') NOT IN ('cancelled', 'obsolete', 'covered')
        AND (resulting.bl_id = v_adjustment.bl_id OR EXISTS (
          SELECT 1
          FROM public.invoice_bls AS resulting_link
          WHERE resulting_link.invoice_id = resulting.id
            AND resulting_link.bl_id = v_adjustment.bl_id
        ))
    ) THEN
      RAISE EXCEPTION 'O documento % não pertence ao B/L % ou não está ativo.',
        p_resulting_document_id, v_adjustment.bl_id USING ERRCODE = '22023';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.cod_adjustments AS linked
      WHERE linked.id <> p_adjustment_id
        AND linked.resulting_document_id = p_resulting_document_id
    ) THEN
      RAISE EXCEPTION 'O documento % já está vinculado a outro ajuste de COD.', p_resulting_document_id
        USING ERRCODE = '23505';
    END IF;
  END IF;

  IF v_invoice_id IS NULL THEN
    RAISE EXCEPTION 'Nao foi encontrada fatura ativa para o B/L %.', v_adjustment.bl_id
      USING ERRCODE = 'P0002';
  END IF;

  IF v_adjustment.offset_amount_brl > 0 THEN
    v_offset := public.apply_cod_open_balance_offset(
      v_invoice_id, v_adjustment.bl_id, v_adjustment.offset_amount_brl, v_actor
    );
  END IF;

  IF v_adjustment.action = 'refund_overpayment' THEN
    IF v_adjustment.refund_amount_brl <= 0 THEN
      RAISE EXCEPTION 'Ajuste de COD sem excedente para restituir.' USING ERRCODE = '22023';
    END IF;

    INSERT INTO public.invoice_refunds (
      invoice_id, payment_id, cod_adjustment_id, amount_brl, status,
      registered_by, notes
    ) VALUES (
      v_invoice_id, NULL, p_adjustment_id, v_adjustment.refund_amount_brl,
      'pending', v_actor, 'Crédito de COD; abatimento aplicado antes da restituição.'
    )
    RETURNING id INTO v_refund_id;
  END IF;

  UPDATE public.cod_adjustments
  SET status = 'settled',
      resulting_document_id = CASE
        WHEN v_refund_id IS NOT NULL THEN v_refund_id
        WHEN p_resulting_document_id IS NOT NULL THEN p_resulting_document_id
        ELSE v_invoice_id
      END,
      resulting_document_type = CASE
        WHEN v_refund_id IS NOT NULL THEN 'refund'
        WHEN p_resulting_document_type IS NOT NULL THEN v_document_type
        ELSE 'invoice'
      END
  WHERE id = p_adjustment_id;

  INSERT INTO public.audit_logs (
    entity_type, entity_id, field_name, old_value, new_value, changed_by,
    changed_at, justification
  ) VALUES (
    'cod_adjustment', p_adjustment_id::TEXT, 'status', 'pending', 'settled',
    v_actor, now(), 'Liquidação financeira de ajuste de COD'
  );

  RETURN jsonb_build_object(
    'adjustment_id', p_adjustment_id,
    'invoice_id', v_invoice_id,
    'refund_id', v_refund_id,
    'offset_amount_brl', v_offset,
    'status', 'settled'
  );
END;
$$;



--
-- Name: settle_invoice_refund(bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.settle_invoice_refund(p_refund_id bigint, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_refund RECORD;
  v_actor UUID;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_financeiro_user() THEN
    RAISE EXCEPTION 'Apenas Financeiro, Administrativo ou Admin pode liquidar restituições.'
      USING ERRCODE = '42501';
  END IF;
  IF p_actor IS NOT NULL AND p_actor <> auth.uid() THEN
    RAISE EXCEPTION 'O ator da liquidação deve ser o usuário autenticado.' USING ERRCODE = '42501';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());
  SELECT * INTO v_refund FROM public.invoice_refunds WHERE id = p_refund_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Restituicao % nao encontrada.', p_refund_id USING ERRCODE = 'P0002';
  END IF;
  IF v_refund.status <> 'pending' THEN
    RAISE EXCEPTION 'Restituicao % nao esta pendente (status=%).', p_refund_id, v_refund.status
      USING ERRCODE = '22023';
  END IF;

  UPDATE public.invoice_refunds
  SET status = 'settled', settled_at = now()
  WHERE id = p_refund_id;

  INSERT INTO public.audit_logs (
    entity_type, entity_id, field_name, old_value, new_value, changed_by,
    changed_at, justification
  ) VALUES (
    'invoice_refund', p_refund_id::TEXT, 'status', 'pending', 'settled',
    v_actor, now(), 'Restituição marcada como efetuada'
  );

  RETURN jsonb_build_object(
    'refund_id', p_refund_id, 'invoice_id', v_refund.invoice_id, 'status', 'settled'
  );
END;
$$;



--
-- Name: summarize_alert_queue_by_department(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.summarize_alert_queue_by_department() RETURNS TABLE(department text, active_count bigint, dismissed_count bigint, is_legacy boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;

  RETURN QUERY
  WITH item_rows AS (
    SELECT
      COALESCE(NULLIF(btrim(i.department), ''), 'sem_departamento') AS dept,
      COALESCE(d.review_at > now(), false) AS is_dismissed,
      false AS is_legacy
    FROM public.alerts a
    JOIN public.alert_items i ON i.alert_id = a.id AND i.status = 'active'
    LEFT JOIN LATERAL (
      SELECT ad.review_at
      FROM public.alert_item_dismissals ad
      WHERE ad.alert_item_id = i.id AND ad.occurrence_id = i.occurrence_id
      ORDER BY ad.dismissed_at DESC
      LIMIT 1
    ) d ON true
    WHERE a.status <> 'closed'

    UNION ALL

    SELECT
      COALESCE(NULLIF(btrim(c.responsible_department), ''), 'sem_departamento') AS dept,
      false AS is_dismissed,
      true AS is_legacy
    FROM public.alerts a
    LEFT JOIN public.alert_type_catalog c ON c.type = a.type
    WHERE a.status <> 'closed'
      AND NOT EXISTS (SELECT 1 FROM public.alert_items i WHERE i.alert_id = a.id)
  )
  SELECT
    dept AS department,
    COUNT(*) FILTER (WHERE NOT is_dismissed) AS active_count,
    COUNT(*) FILTER (WHERE is_dismissed) AS dismissed_count,
    bool_or(item_rows.is_legacy) AS is_legacy
  FROM item_rows
  GROUP BY dept
  ORDER BY
    CASE WHEN dept = 'sem_departamento' THEN 1 ELSE 0 END,
    dept ASC;
END;
$$;



--
-- Name: suppress_normal_portal_alert_events(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suppress_normal_portal_alert_events() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.type IN ('portal_invoice_created', 'portal_consolidation_obsoleted') THEN
    NEW.status := 'closed';
    NEW.closed_at := COALESCE(NEW.closed_at, now());
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: sync_customer_reconciliation_queue_for_bl(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_customer_reconciliation_queue_for_bl(p_bl_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl RECORD;
  v_detection_type TEXT;
  v_status TEXT;
BEGIN
  SELECT
    b.id,
    b.batch_id,
    b.customer_id,
    b.suggested_customer_id,
    b.manifest_customer_cnpj_cpf,
    b.manifest_customer_name,
    b.manifest_customer_email,
    b.customer_reconciliation_status,
    b.customer_reconciliation_notes
  INTO v_bl
  FROM public.bls AS b
  WHERE b.id = p_bl_id;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  v_status := COALESCE(v_bl.customer_reconciliation_status, 'missing_customer');
  v_detection_type := CASE v_status
    WHEN 'matched_name' THEN 'name'
    WHEN 'matched_document' THEN 'document'
    WHEN 'reconciled' THEN 'manual'
    WHEN 'rejected' THEN 'manual'
    ELSE 'missing'
  END;

  INSERT INTO public.customer_reconciliation_queue (
    manifest_id,
    bl_id,
    customer_id,
    cnpj_cpf,
    manifest_customer_name,
    manifest_customer_email,
    detection_type,
    status,
    notes,
    resolution_notes,
    approved_at,
    rejected_at
  )
  VALUES (
    v_bl.batch_id,
    v_bl.id,
    COALESCE(v_bl.customer_id, v_bl.suggested_customer_id),
    v_bl.manifest_customer_cnpj_cpf,
    v_bl.manifest_customer_name,
    v_bl.manifest_customer_email,
    v_detection_type,
    CASE
      WHEN v_status IN ('matched_document', 'reconciled') THEN 'approved'
      WHEN v_status = 'rejected' THEN 'rejected'
      ELSE 'pending'
    END,
    v_bl.customer_reconciliation_notes,
    CASE
      WHEN v_status IN ('matched_document', 'reconciled') THEN COALESCE(v_bl.customer_reconciliation_notes, 'Cliente reconciliado.')
      WHEN v_status = 'rejected' THEN COALESCE(v_bl.customer_reconciliation_notes, 'Reconciliacao rejeitada.')
      ELSE NULL
    END,
    CASE WHEN v_status IN ('matched_document', 'reconciled') THEN now() ELSE NULL END,
    CASE WHEN v_status = 'rejected' THEN now() ELSE NULL END
  )
  ON CONFLICT (bl_id) DO UPDATE
  SET
    manifest_id = EXCLUDED.manifest_id,
    customer_id = EXCLUDED.customer_id,
    cnpj_cpf = EXCLUDED.cnpj_cpf,
    manifest_customer_name = EXCLUDED.manifest_customer_name,
    manifest_customer_email = EXCLUDED.manifest_customer_email,
    detection_type = EXCLUDED.detection_type,
    status = EXCLUDED.status,
    notes = EXCLUDED.notes,
    resolution_notes = CASE
      WHEN EXCLUDED.status = 'pending' THEN NULL
      ELSE EXCLUDED.resolution_notes
    END,
    approved_at = CASE
      WHEN EXCLUDED.status = 'approved' THEN COALESCE(public.customer_reconciliation_queue.approved_at, now())
      ELSE NULL
    END,
    rejected_at = CASE
      WHEN EXCLUDED.status = 'rejected' THEN COALESCE(public.customer_reconciliation_queue.rejected_at, now())
      ELSE NULL
    END,
    updated_at = now();
END;
$$;



--
-- Name: sync_demurrage_dispute_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_demurrage_dispute_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
DECLARE
  v_link_column TEXT;
  v_next_responder TEXT;
BEGIN
  IF to_regclass('public.demurrage_disputes') IS NULL THEN
    PERFORM public.sync_demurrage_dispute_alert_for_invoice(NEW.id, NULL);
    RETURN NEW;
  END IF;

  SELECT CASE
    WHEN EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'demurrage_disputes' AND column_name = 'demurrage_invoice_id') THEN 'demurrage_invoice_id'
    WHEN EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'demurrage_disputes' AND column_name = 'invoice_id') THEN 'invoice_id'
    ELSE NULL
  END INTO v_link_column;

  IF v_link_column IS NULL
     OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'demurrage_disputes' AND column_name = 'next_responder') THEN
    PERFORM public.sync_demurrage_dispute_alert_for_invoice(NEW.id, NULL);
    RETURN NEW;
  END IF;

  EXECUTE format(
    'SELECT next_responder::text FROM public.demurrage_disputes WHERE %I = $1 ORDER BY 1 DESC NULLS LAST LIMIT 1',
    v_link_column
  ) INTO v_next_responder USING NEW.id;
  PERFORM public.sync_demurrage_dispute_alert_for_invoice(NEW.id, v_next_responder);
  RETURN NEW;
END;
$_$;



--
-- Name: sync_demurrage_dispute_alert_for_invoice(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_demurrage_dispute_alert_for_invoice(p_demurrage_invoice_id bigint, p_next_responder text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_invoice RECORD;
BEGIN
  SELECT id, dispute_open, dispute_status INTO v_invoice
  FROM public.demurrage_invoices
  WHERE id = p_demurrage_invoice_id;
  IF NOT FOUND THEN RETURN; END IF;

  IF COALESCE(lower(trim(p_next_responder)), '') = 'equipamentos'
     AND v_invoice.dispute_open
     AND COALESCE(v_invoice.dispute_status, 'aberto') NOT IN ('resolvido', 'cancelado') THEN
    PERFORM set_config('alerts.foundation_trigger', 'on', true);
    PERFORM public.upsert_alert_item(
      'portal_dispute_opened', 'demurrage_invoice', v_invoice.id::TEXT,
      'Disputa de invoice Demurrage aguardando Equipamentos.',
      'demurrage_dispute', jsonb_build_object('next_responder', 'equipamentos'), '/demurrage'
    );
    PERFORM set_config('alerts.foundation_trigger', 'off', true);
  ELSE
    PERFORM set_config('alerts.foundation_trigger', 'on', true);
    PERFORM public.resolve_alert_item(
      'portal_dispute_opened', 'demurrage_invoice', v_invoice.id::TEXT,
      CASE WHEN p_next_responder IS NULL THEN 'next_action_source_unavailable' ELSE 'next_action_not_equipamentos' END,
      jsonb_build_object('next_responder', p_next_responder)
    );
    PERFORM set_config('alerts.foundation_trigger', 'off', true);
  END IF;
END;
$$;



--
-- Name: sync_demurrage_dispute_lifecycle_from_invoice(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_demurrage_dispute_lifecycle_from_invoice() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_state TEXT;
  v_next_responder TEXT;
BEGIN
  IF NEW.dispute_status = 'resolvido' THEN
    v_state := 'resolvida';
    v_next_responder := 'ninguem';
  ELSIF NEW.dispute_status = 'cancelado' THEN
    v_state := 'cancelada';
    v_next_responder := 'ninguem';
  ELSIF COALESCE(NEW.dispute_open, false) THEN
    v_state := 'aberta';
    v_next_responder := 'equipamentos';
  ELSE
    RETURN NEW;
  END IF;

  WITH target AS (
    SELECT id
    FROM public.demurrage_disputes
    WHERE demurrage_invoice_id = NEW.id
    ORDER BY CASE WHEN state = 'aberta' THEN 0 ELSE 1 END, id DESC
    LIMIT 1
  )
  UPDATE public.demurrage_disputes d
  SET state = v_state,
      next_responder = v_next_responder,
      resolved_at = CASE WHEN v_state = 'resolvida' THEN COALESCE(d.resolved_at, now()) ELSE NULL END,
      cancelled_at = CASE WHEN v_state = 'cancelada' THEN COALESCE(d.cancelled_at, now()) ELSE NULL END
  FROM target
  WHERE d.id = target.id;

  RETURN NEW;
END;
$$;



--
-- Name: sync_demurrage_dispute_source_alert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_demurrage_dispute_source_alert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_payload JSONB := to_jsonb(NEW);
  v_invoice_id BIGINT;
BEGIN
  v_invoice_id := NULLIF(COALESCE(v_payload->>'demurrage_invoice_id', v_payload->>'invoice_id'), '')::BIGINT;
  IF v_invoice_id IS NOT NULL THEN
    PERFORM public.sync_demurrage_dispute_alert_for_invoice(v_invoice_id, v_payload->>'next_responder');
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: sync_legacy_alert_item_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_legacy_alert_item_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_item public.alert_items%ROWTYPE;
  v_event_id BIGINT;
BEGIN
  IF NEW.type = 'aggregate'
     OR current_setting('alerts.foundation_internal', true) = 'on'
     OR OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  IF OLD.status <> 'closed' AND NEW.status = 'closed' THEN
    FOR v_item IN
      SELECT *
      FROM public.alert_items
      WHERE alert_id = NEW.id AND item_type = NEW.type AND status = 'active'
      FOR UPDATE
    LOOP
      UPDATE public.alert_items
      SET status = 'resolved', updated_at = now(), resolved_at = now()
      WHERE id = v_item.id;
      INSERT INTO public.alert_item_events (
        alert_item_id, occurrence_id, event_type, previous_status, new_status,
        actor_id, metadata
      ) VALUES (
        v_item.id, v_item.occurrence_id, 'resolved', 'active', 'resolved',
        auth.uid(), jsonb_build_object('source', 'legacy_alert_status')
      );
    END LOOP;
  ELSIF OLD.status = 'closed' AND NEW.status <> 'closed' THEN
    FOR v_item IN
      SELECT *
      FROM public.alert_items
      WHERE alert_id = NEW.id AND item_type = NEW.type AND status = 'resolved'
      FOR UPDATE
    LOOP
      UPDATE public.alert_items
      SET status = 'active', updated_at = now(), resolved_at = NULL,
          occurrence_id = gen_random_uuid()
      WHERE id = v_item.id
      RETURNING * INTO v_item;
      INSERT INTO public.alert_item_events (
        alert_item_id, occurrence_id, event_type, previous_status, new_status,
        actor_id, metadata
      ) VALUES (
        v_item.id, v_item.occurrence_id, 'opened', 'resolved', 'active',
        auth.uid(), jsonb_build_object('source', 'legacy_alert_status')
      ) RETURNING id INTO v_event_id;
      PERFORM public.fanout_alert_item(NEW.id, v_item.id, v_event_id);
    END LOOP;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: sync_local_charge_receivable(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_local_charge_receivable(p_bl_id text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bl RECORD;
  v_amount NUMERIC(14,2);
  v_roe NUMERIC(10,4);
  v_roe_effective_date DATE;
  v_paid_amount NUMERIC(14,2);
  v_receivable_id BIGINT;
  v_status TEXT;
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao de faturamento.' USING ERRCODE = '42501';
  END IF;

  SELECT id, customer_id, voyage_id, cargo_mode, pol, pod
  INTO v_bl
  FROM public.bls
  WHERE id = UPPER(TRIM(p_bl_id));

  IF NOT FOUND THEN
    RAISE EXCEPTION 'B/L % nao encontrado.', p_bl_id USING ERRCODE = 'P0002';
  END IF;

  IF v_bl.customer_id IS NULL THEN
    RAISE EXCEPTION 'B/L % sem cliente vinculado.', p_bl_id USING ERRCODE = '22023';
  END IF;

  SELECT roe, effective_date INTO v_roe, v_roe_effective_date
  FROM public.exchange_rate_reference WHERE id = 1;

  IF v_roe IS NULL AND EXISTS (
    SELECT 1 FROM public.charge_calculations AS cc
    WHERE cc.bl_id = v_bl.id
      AND COALESCE(cc.total_value_usd, 0) > 0
      AND COALESCE(cc.status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing', 'exempt')
  ) THEN
    RAISE EXCEPTION 'Cambio (ROE) nao configurado; nao e possivel calcular o saldo de linhas em USD.' USING ERRCODE = '22023';
  END IF;

  SELECT COALESCE(SUM(
    COALESCE(cc.total_value_brl, CASE WHEN COALESCE(cc.total_value_usd, 0) > 0 THEN ROUND(cc.total_value_usd * v_roe, 2) END, 0)
  ), 0)
  INTO v_amount
  FROM public.charge_calculations AS cc
  WHERE cc.bl_id = v_bl.id
    AND COALESCE(cc.status, 'calculated') IN ('calculated', 'reviewed', 'ready_for_billing', 'exempt');

  SELECT COALESCE(SUM(p.amount_brl), 0)
  INTO v_paid_amount
  FROM public.invoice_bls ib
  JOIN public.invoices i ON i.id = ib.invoice_id
  JOIN public.payments p ON p.invoice_id = i.id
  WHERE ib.bl_id = v_bl.id
    AND COALESCE(i.status, 'issued') = 'paid';

  v_paid_amount := LEAST(v_paid_amount, v_amount);
  v_status := CASE
    WHEN v_amount <= 0 THEN 'void'
    WHEN v_paid_amount >= v_amount THEN 'settled'
    WHEN v_paid_amount > 0 THEN 'partially_settled'
    ELSE 'open'
  END;

  INSERT INTO public.bl_receivables (
    bl_id, customer_id, source, original_amount_brl, settled_amount_brl, balance_brl,
    status, voyage_id, cargo_mode, pol, pod, roe_frozen, roe_effective_date_frozen, updated_at
  )
  VALUES (
    v_bl.id, v_bl.customer_id, 'local_charges', v_amount, v_paid_amount,
    GREATEST(v_amount - v_paid_amount, 0), v_status, v_bl.voyage_id,
    v_bl.cargo_mode, v_bl.pol, v_bl.pod, v_roe, v_roe_effective_date, now()
  )
  ON CONFLICT (source, bl_id)
  DO UPDATE SET
    customer_id = EXCLUDED.customer_id,
    original_amount_brl = EXCLUDED.original_amount_brl,
    settled_amount_brl = EXCLUDED.settled_amount_brl,
    balance_brl = EXCLUDED.balance_brl,
    status = EXCLUDED.status,
    voyage_id = EXCLUDED.voyage_id,
    cargo_mode = EXCLUDED.cargo_mode,
    pol = EXCLUDED.pol,
    pod = EXCLUDED.pod,
    roe_frozen = EXCLUDED.roe_frozen,
    roe_effective_date_frozen = EXCLUDED.roe_effective_date_frozen,
    updated_at = now()
  RETURNING id INTO v_receivable_id;

  RETURN v_receivable_id;
END;
$$;



