--
-- Name: trg_reconcile_bl_review_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_reconcile_bl_review_alerts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  PERFORM set_config('alerts.foundation_trigger', 'on', true);

  IF TG_OP = 'DELETE' THEN
    PERFORM public.reconcile_customer_bl_review_alerts(OLD.customer_id, OLD.consignee, 'bl_deleted');
    RETURN OLD;
  ELSIF TG_OP = 'INSERT' THEN
    PERFORM public.reconcile_customer_bl_review_alerts(NEW.customer_id, NEW.consignee, 'bl_inserted');
    RETURN NEW;
  ELSE
    IF OLD.review_status IS DISTINCT FROM NEW.review_status
       OR OLD.customer_id IS DISTINCT FROM NEW.customer_id
       OR OLD.consignee IS DISTINCT FROM NEW.consignee
       OR OLD.cargo_mode IS DISTINCT FROM NEW.cargo_mode
       OR OLD.bb_weight_ton IS DISTINCT FROM NEW.bb_weight_ton THEN
      PERFORM public.reconcile_customer_bl_review_alerts(NEW.customer_id, NEW.consignee, 'bl_updated');
      IF OLD.customer_id IS DISTINCT FROM NEW.customer_id
         OR OLD.consignee IS DISTINCT FROM NEW.consignee THEN
        PERFORM public.reconcile_customer_bl_review_alerts(OLD.customer_id, OLD.consignee, 'bl_customer_changed');
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  PERFORM set_config('alerts.foundation_trigger', 'off', true);
END;
$$;



--
-- Name: trg_reconcile_bl_review_on_portal_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_reconcile_bl_review_on_portal_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_customer_id BIGINT;
  v_bl_id TEXT;
BEGIN
  v_customer_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.customer_id ELSE NEW.customer_id END;
  PERFORM set_config('alerts.foundation_trigger', 'on', true);
  FOR v_bl_id IN
    SELECT id FROM public.bls
    WHERE customer_id = v_customer_id
      AND review_status IN ('pending_review', 'reviewed')
      AND COALESCE(financial_status, '') NOT IN ('invoiced', 'partially_paid', 'paid')
  LOOP
    PERFORM public.recompute_bl_review_status(v_bl_id);
    PERFORM public.reconcile_bl_review_alerts(v_bl_id, 'portal_account_change');
  END LOOP;
  PERFORM set_config('alerts.foundation_trigger', 'off', true);
  RETURN NEW;
END;
$$;



--
-- Name: trg_reconcile_granite_bl_review_alerts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_reconcile_granite_bl_review_alerts() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    PERFORM set_config('alerts.foundation_trigger', 'on', true);
    PERFORM public.reconcile_granite_bl_review_alerts(OLD.id);
    PERFORM set_config('alerts.foundation_trigger', 'off', true);
    RETURN OLD;
  ELSE
    IF TG_OP = 'INSERT' OR OLD.client_id IS DISTINCT FROM NEW.client_id THEN
      PERFORM set_config('alerts.foundation_trigger', 'on', true);
      PERFORM public.reconcile_granite_bl_review_alerts(NEW.id);
      PERFORM set_config('alerts.foundation_trigger', 'off', true);
    END IF;
    RETURN NEW;
  END IF;
END;
$$;



--
-- Name: trg_voyage_schedule_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_voyage_schedule_snapshot() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_voyage_id  TEXT;
  v_sub_key    TEXT;
  v_parts      TEXT[];
BEGIN
  v_parts     := string_to_array(NEW.entity_id, '::');
  v_voyage_id := v_parts[1];
  v_sub_key   := COALESCE(v_parts[2], '');

  IF v_voyage_id IS NULL OR v_voyage_id = '' THEN
    RETURN NEW;
  END IF;

  IF NEW.entity_type = 'voyage_pod_schedule' THEN
    UPDATE public.voyages
    SET pod_schedule_snapshot = jsonb_set(
      COALESCE(pod_schedule_snapshot, '{}'::jsonb),
      ARRAY[v_sub_key, NEW.field_name],
      COALESCE(to_jsonb(NEW.new_value), 'null'::jsonb),
      true
    )
    WHERE id::TEXT = v_voyage_id;

  ELSIF NEW.entity_type = 'voyage_pol_schedule' THEN
    UPDATE public.voyages
    SET pol_schedule_snapshot = jsonb_set(
      COALESCE(pol_schedule_snapshot, '{}'::jsonb),
      ARRAY[v_sub_key, NEW.field_name],
      COALESCE(to_jsonb(NEW.new_value), 'null'::jsonb),
      true
    )
    WHERE id::TEXT = v_voyage_id;
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: update_container_demurrage_dates(bigint, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_container_demurrage_dates(p_container_id bigint, p_discharge_date date, p_return_date date, p_demurrage_status text, p_justification text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_before public.bl_containers%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario inativo ou nao autenticado.' USING ERRCODE = '42501';
  END IF;

  IF p_demurrage_status NOT IN ('within_free_time', 'overdue', 'returned') THEN
    RAISE EXCEPTION 'Status de demurrage invalido.' USING ERRCODE = '22023';
  END IF;

  SELECT *
  INTO v_before
  FROM public.bl_containers
  WHERE id = p_container_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Container % nao encontrado.', p_container_id USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.bl_containers
  SET
    discharge_date = p_discharge_date,
    return_date = p_return_date,
    demurrage_status = p_demurrage_status
  WHERE id = p_container_id;

  INSERT INTO public.audit_logs (
      entity_type,
      entity_id,
      field_name,
      old_value,
      new_value,
      changed_by,
      changed_at,
      justification
  )
  SELECT
    'bl_container',
    p_container_id::TEXT,
    change.field_name,
    change.old_value,
    change.new_value,
    auth.uid(),
    now(),
    NULLIF(TRIM(COALESCE(p_justification, '')), '')
  FROM (
    VALUES
      ('discharge_date', v_before.discharge_date::TEXT, p_discharge_date::TEXT),
      ('return_date', v_before.return_date::TEXT, p_return_date::TEXT),
      ('demurrage_status', v_before.demurrage_status, p_demurrage_status)
  ) AS change(field_name, old_value, new_value)
  WHERE change.old_value IS DISTINCT FROM change.new_value;
END;
$$;



--
-- Name: update_customer_with_audit(bigint, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_customer_with_audit(p_customer_id bigint, p_updates jsonb, p_changed_by uuid, p_justification text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  v_before public.customers%ROWTYPE;
  v_after public.customers%ROWTYPE;
  v_invalid_key TEXT;
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.is_active_user()
     OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Credenciais invalidas para editar cliente.' USING ERRCODE = '42501';
  END IF;

  IF NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao para editar cliente.' USING ERRCODE = '42501';
  END IF;

  IF NULLIF(BTRIM(COALESCE(p_justification, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Justificativa obrigatoria para editar cliente.' USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(p_updates) <> 'object' OR p_updates = '{}'::JSONB THEN
    RETURN FALSE;
  END IF;

  SELECT key INTO v_invalid_key
  FROM jsonb_object_keys(p_updates) AS key
  WHERE key NOT IN ('name', 'trade_name', 'address', 'city', 'state', 'zip', 'notes')
  LIMIT 1;

  IF v_invalid_key IS NOT NULL THEN
    RAISE EXCEPTION 'Campo de cliente nao editavel: %.', v_invalid_key USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_before FROM public.customers WHERE id = p_customer_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Cliente % nao encontrado.', p_customer_id USING ERRCODE = 'P0002';
  END IF;

  UPDATE public.customers SET
    name = CASE WHEN p_updates ? 'name' THEN p_updates->>'name' ELSE name END,
    trade_name = CASE WHEN p_updates ? 'trade_name' THEN NULLIF(p_updates->>'trade_name', '') ELSE trade_name END,
    address = CASE WHEN p_updates ? 'address' THEN NULLIF(p_updates->>'address', '') ELSE address END,
    city = CASE WHEN p_updates ? 'city' THEN NULLIF(p_updates->>'city', '') ELSE city END,
    state = CASE WHEN p_updates ? 'state' THEN NULLIF(p_updates->>'state', '') ELSE state END,
    zip = CASE WHEN p_updates ? 'zip' THEN NULLIF(p_updates->>'zip', '') ELSE zip END,
    notes = CASE WHEN p_updates ? 'notes' THEN NULLIF(p_updates->>'notes', '') ELSE notes END
  WHERE id = p_customer_id
  RETURNING * INTO v_after;

  INSERT INTO public.audit_logs (entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  SELECT 'customer', p_customer_id::TEXT, changed.field_name, changed.old_value, changed.new_value,
    p_changed_by, BTRIM(p_justification)
  FROM (VALUES
    ('name', v_before.name, v_after.name),
    ('trade_name', v_before.trade_name, v_after.trade_name),
    ('address', v_before.address, v_after.address),
    ('city', v_before.city, v_after.city),
    ('state', v_before.state, v_after.state),
    ('zip', v_before.zip, v_after.zip),
    ('notes', v_before.notes, v_after.notes)
  ) AS changed(field_name, old_value, new_value)
  WHERE p_updates ? changed.field_name
    AND changed.old_value IS DISTINCT FROM changed.new_value;

  RETURN TRUE;
END;
$$;



--
-- Name: update_manual_bl_charge(bigint, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_manual_bl_charge(p_charge_calculation_id bigint, p_quantity numeric, p_notes text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row RECORD;
  v_qty NUMERIC(12,6);
  v_total_brl NUMERIC(14,2);
  v_total_usd NUMERIC(14,2);
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa' USING ERRCODE = '42501';
  END IF;

  SELECT
    cc.id,
    cc.bl_id,
    cc.source,
    cc.quantity,
    cc.unit_value_brl,
    cc.unit_value_usd,
    cc.total_value_brl,
    cc.total_value_usd,
    cc.notes,
    b.financial_status AS bl_financial_status
  INTO v_row
  FROM public.charge_calculations AS cc
  LEFT JOIN public.bls AS b ON b.id = cc.bl_id
  WHERE cc.id = p_charge_calculation_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Linha de calculo % nao encontrada', p_charge_calculation_id USING ERRCODE = 'P0002';
  END IF;

  IF COALESCE(v_row.source, '') <> 'manual' THEN
    RAISE EXCEPTION 'Somente linhas manuais podem ser editadas' USING ERRCODE = '22023';
  END IF;

  IF COALESCE(v_row.bl_financial_status, 'open') IN ('invoiced', 'partially_paid', 'paid') THEN
    RAISE EXCEPTION 'B/L % ja foi faturado; nao e permitido editar taxa manual.', v_row.bl_id
      USING ERRCODE = '22023';
  END IF;

  v_qty := COALESCE(p_quantity, v_row.quantity, 1);
  IF v_qty <= 0 THEN
    RAISE EXCEPTION 'Quantidade deve ser maior que zero' USING ERRCODE = '22023';
  END IF;

  v_total_brl := CASE WHEN v_row.unit_value_brl IS NULL THEN NULL ELSE ROUND(v_qty * v_row.unit_value_brl, 2) END;
  v_total_usd := CASE WHEN v_row.unit_value_usd IS NULL THEN NULL ELSE ROUND(v_qty * v_row.unit_value_usd, 2) END;

  UPDATE public.charge_calculations
  SET
    quantity = v_qty,
    total_value_brl = v_total_brl,
    total_value_usd = v_total_usd,
    notes = NULLIF(TRIM(COALESCE(p_notes, '')), ''),
    calculated_at = NOW()
  WHERE id = p_charge_calculation_id;

  INSERT INTO public.audit_logs (
    entity_type,
    entity_id,
    field_name,
    old_value,
    new_value,
    changed_by,
    changed_at,
    justification
  )
  VALUES (
    'charge_calculation',
    p_charge_calculation_id::TEXT,
    'manual_update',
    CONCAT('qty=', COALESCE(v_row.quantity::TEXT, '0'), ' | note=', COALESCE(v_row.notes, '')),
    CONCAT('qty=', v_qty, ' | note=', COALESCE(NULLIF(TRIM(COALESCE(p_notes, '')), ''), '')),
    auth.uid(),
    NOW(),
    COALESCE(NULLIF(TRIM(COALESCE(p_notes, '')), ''), 'Atualizacao manual de other charge')
  );

  RETURN jsonb_build_object(
    'id', p_charge_calculation_id,
    'bl_id', v_row.bl_id,
    'quantity', v_qty,
    'total_value_brl', v_total_brl,
    'total_value_usd', v_total_usd
  );
END;
$$;



--
-- Name: update_manual_vazios_booking(uuid, text, text, uuid, text, date, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_manual_vazios_booking(p_booking_id uuid, p_container_number text, p_container_type text, p_local_id uuid, p_condition text, p_hand_in_date date, p_hand_out_date date, p_movement_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
BEGIN
  IF auth.uid() IS NULL OR NOT (public.is_active_user() OR public.is_active_user()) THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa para editar unidade.' USING ERRCODE = '42501';
  END IF;
  IF upper(btrim(COALESCE(p_container_number, ''))) !~ '^[A-Z]{4}[0-9]{7}$' THEN
    RAISE EXCEPTION 'Container invalido.' USING ERRCODE = '22023';
  END IF;

  UPDATE public.vazios_bookings
  SET container_number = upper(btrim(p_container_number)),
      container_type = p_container_type,
      local_id = p_local_id,
      condition = p_condition,
      hand_in_date = p_hand_in_date,
      hand_out_date = p_hand_out_date,
      movement_date = p_movement_date
  WHERE id = p_booking_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Unidade embarcada nao encontrada.' USING ERRCODE = 'P0002';
  END IF;
END;
$_$;



--
-- Name: update_updated_at_column(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_updated_at_column() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;



--
-- Name: update_voyage_omission(bigint, text, text, text, timestamp with time zone, timestamp with time zone, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_voyage_omission(p_omission_id bigint, p_onward_vessel_name text, p_onward_carrier text, p_onward_voyage_number text, p_onward_etd timestamp with time zone, p_onward_eta timestamp with time zone, p_reason text, p_changed_by uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_old RECORD;
  v_new_vessel TEXT;
  v_new_carrier TEXT;
  v_new_voyage TEXT;
  v_new_etd TIMESTAMPTZ;
  v_new_eta TIMESTAMPTZ;
  v_reason TEXT;
  v_changed BOOLEAN := false;
  v_justification TEXT := 'Informacoes de Transbordo complementadas';
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR p_changed_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Usuario sem permissao ativa.' USING ERRCODE = '42501';
  END IF;

  SELECT * INTO v_old FROM public.voyage_omissions WHERE id = p_omission_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Omissao % nao encontrada', p_omission_id USING ERRCODE = 'P0002';
  END IF;

  v_reason := NULLIF(btrim(COALESCE(p_reason, '')), '');
  v_new_vessel := NULLIF(btrim(COALESCE(p_onward_vessel_name, '')), '');
  v_new_carrier := NULLIF(btrim(COALESCE(p_onward_carrier, '')), '');
  v_new_voyage := NULLIF(btrim(COALESCE(p_onward_voyage_number, '')), '');
  v_new_etd := p_onward_etd;
  v_new_eta := p_onward_eta;

  v_changed := v_old.onward_vessel_name IS DISTINCT FROM v_new_vessel
    OR v_old.onward_carrier IS DISTINCT FROM v_new_carrier
    OR v_old.onward_voyage_number IS DISTINCT FROM v_new_voyage
    OR v_old.onward_etd IS DISTINCT FROM v_new_etd
    OR v_old.onward_eta IS DISTINCT FROM v_new_eta
    OR (v_reason IS NOT NULL AND v_old.reason IS DISTINCT FROM v_reason);

  UPDATE public.voyage_omissions SET
    onward_vessel_name = v_new_vessel,
    onward_carrier = v_new_carrier,
    onward_voyage_number = v_new_voyage,
    onward_etd = v_new_etd,
    onward_eta = v_new_eta,
    reason = COALESCE(v_reason, v_old.reason)
  WHERE id = p_omission_id;

  IF NOT v_changed THEN
    RETURN;
  END IF;

  INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  VALUES ('voyage', v_old.voyage_id::TEXT, 'transshipment_info', NULL,
    v_justification, p_changed_by, v_justification);
  INSERT INTO public.audit_logs(entity_type, entity_id, field_name, old_value, new_value, changed_by, justification)
  SELECT 'bls', bt.bl_id, 'transshipment_info', NULL, v_justification, p_changed_by, v_justification
  FROM public.bl_transshipments AS bt
  WHERE bt.omission_id = p_omission_id;
END;
$$;



--
-- Name: upsert_alert_item(text, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_alert_item(p_type text, p_entity_type text, p_entity_id text, p_message text, p_source text, p_metadata jsonb DEFAULT '{}'::jsonb, p_destination text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_department TEXT;
BEGIN
  SELECT responsible_department INTO v_department
  FROM public.alert_type_catalog
  WHERE type = p_type AND active;
  IF v_department IS NULL THEN
    RAISE EXCEPTION 'Tipo de alerta fora do catálogo: %', p_type USING ERRCODE = '22023';
  END IF;
  RETURN public.upsert_alert_item(
    p_type, p_entity_type, p_entity_id, p_message, p_source,
    v_department, COALESCE(p_metadata, '{}'::jsonb), p_destination
  );
END;
$$;



--
-- Name: upsert_alert_item(text, text, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_alert_item(p_type text, p_entity_type text, p_entity_id text, p_message text, p_source text, p_department text, p_metadata jsonb DEFAULT '{}'::jsonb, p_destination text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_before RECORD;
  v_after RECORD;
  v_result JSONB;
  v_event_id BIGINT;
  v_metadata JSONB := COALESCE(p_metadata, '{}'::jsonb);
BEGIN
  SELECT i.id, i.status, i.metadata
  INTO v_before
  FROM public.alert_items i
  JOIN public.alerts a ON a.id = i.alert_id
  WHERE i.item_type = p_type
    AND i.department = NULLIF(btrim(p_department), '')
    AND a.entity_type = p_entity_type
    AND a.entity_id = p_entity_id
  ORDER BY i.id DESC
  LIMIT 1;

  v_result := public.upsert_alert_item_before_milestone_hardening(
    p_type, p_entity_type, p_entity_id, p_message, p_source,
    p_department, v_metadata, p_destination
  );

  IF v_before.id IS NOT NULL
     AND v_before.status = 'active'
     AND v_metadata ? 'milestone'
     AND v_before.metadata->>'milestone' IS DISTINCT FROM v_metadata->>'milestone' THEN
    SELECT i.id, i.alert_id, i.occurrence_id
    INTO v_after
    FROM public.alert_items i
    WHERE i.id = v_before.id
    FOR UPDATE;

    UPDATE public.alert_items
    SET occurrence_id = gen_random_uuid(), updated_at = now()
    WHERE id = v_after.id
    RETURNING id, alert_id, occurrence_id INTO v_after;

    INSERT INTO public.alert_item_events(
      alert_item_id, occurrence_id, event_type, previous_status, new_status,
      actor_id, metadata
    )
    VALUES (
      v_after.id, v_after.occurrence_id, 'opened', 'active', 'active',
      auth.uid(), v_metadata
    )
    RETURNING id INTO v_event_id;

    IF p_source <> 'foundation_backfill' THEN
      PERFORM public.fanout_alert_item_for_department(
        v_after.alert_id, v_after.id, v_event_id, p_department
      );
    END IF;

    v_result := jsonb_set(v_result, '{event_id}', to_jsonb(v_event_id), true);
  END IF;

  RETURN v_result;
END;
$$;



--
-- Name: upsert_alert_item_before_milestone_hardening(text, text, text, text, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_alert_item_before_milestone_hardening(p_type text, p_entity_type text, p_entity_id text, p_message text, p_source text, p_department text, p_metadata jsonb DEFAULT '{}'::jsonb, p_destination text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_catalog public.alert_type_catalog%ROWTYPE;
  v_alert public.alerts%ROWTYPE;
  v_item public.alert_items%ROWTYPE;
  v_event_id BIGINT;
  v_reopened BOOLEAN := false;
  v_new_item BOOLEAN := false;
  v_department TEXT := NULLIF(btrim(p_department), '');
BEGIN
  IF NOT public.alert_actor_is_authorized() THEN
    RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501';
  END IF;
  IF NULLIF(btrim(p_type), '') IS NULL OR NULLIF(btrim(p_entity_type), '') IS NULL
     OR NULLIF(btrim(p_entity_id), '') IS NULL OR NULLIF(btrim(p_message), '') IS NULL
     OR NULLIF(btrim(p_source), '') IS NULL OR v_department IS NULL THEN
    RAISE EXCEPTION 'Tipo, entidade, mensagem, origem e departamento são obrigatórios.' USING ERRCODE = '22023';
  END IF;
  IF v_department NOT IN ('operacoes', 'documentacao', 'equipamentos') THEN
    RAISE EXCEPTION 'Departamento inválido.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_catalog
  FROM public.alert_type_catalog
  WHERE type = p_type AND active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Tipo de alerta fora do catálogo: %', p_type USING ERRCODE = '22023';
  END IF;

  PERFORM set_config('alerts.foundation_internal', 'on', true);
  PERFORM pg_advisory_xact_lock(hashtextextended('alert:' || p_entity_type || ':' || p_entity_id, 0));

  SELECT * INTO v_alert
  FROM public.alerts a
  WHERE a.type = 'aggregate'
    AND a.entity_type = p_entity_type
    AND a.entity_id = p_entity_id
  ORDER BY a.id DESC
  LIMIT 1
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.alerts(type, entity_type, entity_id, message, status)
    VALUES ('aggregate', p_entity_type, p_entity_id, p_message, 'open')
    RETURNING * INTO v_alert;
  ELSE
    UPDATE public.alerts
    SET status = 'open', closed_at = NULL
    WHERE id = v_alert.id;
    v_alert.status := 'open';
  END IF;

  SELECT * INTO v_item
  FROM public.alert_items
  WHERE alert_id = v_alert.id AND item_type = p_type AND department = v_department
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.alert_items (
      alert_id, item_type, source, severity, department, destination,
      message, metadata, status
    )
    VALUES (
      v_alert.id, p_type, p_source, v_catalog.severity, v_department,
      COALESCE(p_destination, v_catalog.default_destination), p_message,
      COALESCE(p_metadata, '{}'::jsonb), 'active'
    )
    RETURNING * INTO v_item;
    v_new_item := true;
  ELSE
    v_reopened := v_item.status = 'resolved';
    IF v_reopened
       OR v_item.source IS DISTINCT FROM p_source
       OR v_item.severity IS DISTINCT FROM v_catalog.severity
       OR v_item.department IS DISTINCT FROM v_department
       OR v_item.destination IS DISTINCT FROM COALESCE(p_destination, v_catalog.default_destination)
       OR v_item.message IS DISTINCT FROM p_message
       OR v_item.metadata IS DISTINCT FROM COALESCE(p_metadata, '{}'::jsonb) THEN
      UPDATE public.alert_items
      SET source = p_source,
          severity = v_catalog.severity,
          department = v_department,
          destination = COALESCE(p_destination, v_catalog.default_destination),
          message = p_message,
          metadata = COALESCE(p_metadata, '{}'::jsonb),
          status = 'active',
          updated_at = now(),
          resolved_at = NULL,
          occurrence_id = CASE WHEN v_reopened THEN gen_random_uuid() ELSE occurrence_id END
      WHERE id = v_item.id
      RETURNING * INTO v_item;
    END IF;
  END IF;

  IF v_new_item OR v_reopened THEN
    INSERT INTO public.alert_item_events (
      alert_item_id, occurrence_id, event_type, previous_status, new_status,
      actor_id, metadata
    )
    VALUES (
      v_item.id, v_item.occurrence_id, 'opened',
      CASE WHEN v_new_item THEN NULL ELSE 'resolved' END,
      'active', auth.uid(), COALESCE(p_metadata, '{}'::jsonb)
    )
    RETURNING id INTO v_event_id;
    IF p_source <> 'foundation_backfill' THEN
      PERFORM public.fanout_alert_item_for_department(v_alert.id, v_item.id, v_event_id, v_department);
    END IF;
  ELSIF v_item.source IS DISTINCT FROM p_source
     OR v_item.severity IS DISTINCT FROM v_catalog.severity
     OR v_item.department IS DISTINCT FROM v_department
     OR v_item.destination IS DISTINCT FROM COALESCE(p_destination, v_catalog.default_destination)
     OR v_item.message IS DISTINCT FROM p_message
     OR v_item.metadata IS DISTINCT FROM COALESCE(p_metadata, '{}'::jsonb) THEN
    INSERT INTO public.alert_item_events (
      alert_item_id, occurrence_id, event_type, previous_status, new_status,
      actor_id, metadata
    )
    VALUES (v_item.id, v_item.occurrence_id, 'updated', 'active', 'active',
            auth.uid(), COALESCE(p_metadata, '{}'::jsonb));
  END IF;

  PERFORM public.refresh_alert_aggregate(v_alert.id);
  PERFORM set_config('alerts.foundation_internal', 'off', true);
  RETURN jsonb_build_object(
    'alert_id', v_alert.id, 'item_id', v_item.id, 'event_id', v_event_id,
    'reopened', v_reopened, 'created', v_new_item
  );
END;
$$;



--
-- Name: upsert_billing_alert(text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_billing_alert(p_type text, p_bl_id text, p_message text, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT public.is_active_user() THEN RAISE EXCEPTION 'Sem permissão.' USING ERRCODE = '42501'; END IF;
  IF p_type NOT IN ('billing_calculation_blocked', 'billing_auto_issue_failed') THEN
    RAISE EXCEPTION 'Tipo de faturamento inválido.' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.bls WHERE id = p_bl_id) THEN
    RAISE EXCEPTION 'B/L não encontrado.' USING ERRCODE = 'P0002';
  END IF;
  RETURN public.upsert_alert_item(
    p_type, 'bl', p_bl_id, p_message, 'billing_client_compatibility',
    'documentacao', COALESCE(p_metadata, '{}'::jsonb), '/taxas-locais'
  );
END;
$$;



--
-- Name: upsert_customer_portal_account(bigint, text, text, boolean, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_customer_portal_account(p_customer_id bigint, p_password text, p_contact_email text DEFAULT NULL::text, p_active boolean DEFAULT true, p_actor uuid DEFAULT NULL::uuid, p_login_cnpj text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_actor UUID;
  v_normalized_cnpj TEXT;
BEGIN
  IF auth.uid() IS NULL
     OR NOT public.is_active_user()
     OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao administrativa.'
      USING ERRCODE = '42501';
  END IF;

  IF COALESCE(length(trim(COALESCE(p_password, ''))), 0) < 8 THEN
    RAISE EXCEPTION 'Senha do portal deve ter no minimo 8 caracteres.'
      USING ERRCODE = '22023';
  END IF;

  v_actor := COALESCE(p_actor, auth.uid());

  IF p_login_cnpj IS NOT NULL AND trim(p_login_cnpj) <> '' THEN
    v_normalized_cnpj := regexp_replace(trim(p_login_cnpj), '\D', '', 'g');
    IF length(v_normalized_cnpj) NOT IN (11, 14) THEN
      RAISE EXCEPTION 'CNPJ/CPF invalido para login do portal.'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.customer_portal_accounts (
    customer_id,
    contact_email,
    password_hash,
    active,
    created_by,
    login_cnpj
  )
  VALUES (
    p_customer_id,
    NULLIF(trim(COALESCE(p_contact_email, '')), ''),
    extensions.crypt(p_password, extensions.gen_salt('bf')),
    false,
    v_actor,
    v_normalized_cnpj
  )
  ON CONFLICT (customer_id) DO UPDATE
  SET
    contact_email = EXCLUDED.contact_email,
    password_hash = EXCLUDED.password_hash,
    active = COALESCE(p_active, true)
      AND customer_portal_accounts.auth_user_id IS NOT NULL,
    login_cnpj = EXCLUDED.login_cnpj,
    updated_at = now();

  RETURN public.get_customer_portal_account(p_customer_id);
END;
$$;



--
-- Name: upsert_pix_reconciliation_exceptions(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_pix_reconciliation_exceptions(p_import_key text, p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row RECORD;
  v_exception public.pix_reconciliation_exceptions%ROWTYPE;
  v_alert JSONB;
  v_items JSONB := '[]'::jsonb;
  v_import_key TEXT := NULLIF(btrim(COALESCE(p_import_key, '')), '');
  v_normalized_txid TEXT;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_active_user() OR NOT public.is_admin() THEN
    RAISE EXCEPTION 'Credenciais invalidas ou sem permissao para reconciliacao PIX.' USING ERRCODE = '42501';
  END IF;
  IF v_import_key IS NULL OR char_length(v_import_key) < 8 THEN
    RAISE EXCEPTION 'Identificador do import PIX invalido.' USING ERRCODE = '22023';
  END IF;

  FOR v_row IN
    SELECT *
    FROM jsonb_to_recordset(COALESCE(p_rows, '[]'::jsonb)) AS row(
      line_number INTEGER,
      txid TEXT,
      cnpj TEXT,
      paid_at TIMESTAMPTZ,
      amount_brl NUMERIC,
      reason TEXT,
      candidate_count INTEGER,
      metadata JSONB
    )
  LOOP
    IF v_row.line_number IS NULL OR v_row.line_number <= 0
       OR v_row.reason NOT IN ('unmatched', 'ambiguous')
       OR COALESCE(v_row.amount_brl, 0) < 0 THEN
      RAISE EXCEPTION 'Linha de excecao PIX invalida.' USING ERRCODE = '22023';
    END IF;

    v_normalized_txid := UPPER(REGEXP_REPLACE(COALESCE(v_row.txid, ''), '[^A-Za-z0-9]', '', 'g'));
    INSERT INTO public.pix_reconciliation_exceptions (
      import_key, line_number, txid, normalized_txid, cnpj, paid_at,
      amount_brl, reason, candidate_count, metadata, status, updated_at
    )
    VALUES (
      v_import_key, v_row.line_number, COALESCE(v_row.txid, ''), v_normalized_txid,
      COALESCE(v_row.cnpj, ''), v_row.paid_at, ROUND(COALESCE(v_row.amount_brl, 0), 2),
      v_row.reason, GREATEST(COALESCE(v_row.candidate_count, 0), 0),
      COALESCE(v_row.metadata, '{}'::jsonb), 'active', now()
    )
    ON CONFLICT (import_key, line_number) DO UPDATE
      SET txid = EXCLUDED.txid,
          normalized_txid = EXCLUDED.normalized_txid,
          cnpj = EXCLUDED.cnpj,
          paid_at = EXCLUDED.paid_at,
          amount_brl = EXCLUDED.amount_brl,
          reason = EXCLUDED.reason,
          candidate_count = EXCLUDED.candidate_count,
          metadata = EXCLUDED.metadata,
          status = CASE
            WHEN public.pix_reconciliation_exceptions.status = 'resolved' THEN 'resolved'
            ELSE 'active'
          END,
          updated_at = now()
    RETURNING * INTO v_exception;

    v_alert := NULL;
    PERFORM set_config('alerts.foundation_trigger', 'on', true);
    IF v_exception.status = 'active' THEN
      v_alert := public.upsert_alert_item(
        'pix_unreconciled', 'pix_transaction', v_exception.id::TEXT,
        CASE WHEN v_exception.reason = 'ambiguous'
          THEN format('PIX ambiguo na linha %s do import %s.', v_exception.line_number, v_exception.import_key)
          ELSE format('PIX sem conciliacao na linha %s do import %s.', v_exception.line_number, v_exception.import_key)
        END,
        'pix_extract_import',
        jsonb_build_object(
          'exception_id', v_exception.id,
          'import_key', v_exception.import_key,
          'line_number', v_exception.line_number,
          'normalized_txid', v_exception.normalized_txid,
          'reason', v_exception.reason,
          'candidate_count', v_exception.candidate_count
        ) || v_exception.metadata,
        '/reconciliacao'
      );
    ELSE
      PERFORM public.resolve_alert_item(
        'pix_unreconciled', 'pix_transaction', v_exception.id::TEXT,
        'pix_exception_already_resolved', jsonb_build_object('exception_id', v_exception.id)
      );
    END IF;
    PERFORM set_config('alerts.foundation_trigger', 'off', true);

    v_items := v_items || jsonb_build_array(jsonb_build_object(
      'id', v_exception.id, 'line_number', v_exception.line_number,
      'status', v_exception.status, 'alert_id', v_alert->>'alert_id'
    ));
  END LOOP;

  RETURN jsonb_build_object('items', v_items);
END;
$$;



--
-- Name: upsert_portal_invoice_exception(bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_portal_invoice_exception(p_invoice_id bigint, p_bl_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_gate JSONB;
BEGIN
  v_gate := public.portal_billing_gate(p_bl_id);
  IF COALESCE((v_gate->>'allowed')::boolean, false) THEN
    PERFORM public.block521_resolve_alert('portal_excecao_critica_fatura', 'bl', p_bl_id, 'documentacao', 'portal_invoice_gate');
    RETURN;
  END IF;
  PERFORM public.block521_upsert_alert(
    'portal_excecao_critica_fatura', 'bl', p_bl_id,
    'Invoice emitida sem Portal ativo ou email de recuperação utilizável.',
    CASE WHEN current_setting('alerts.foundation_backfill', true) = 'on' THEN 'foundation_backfill' ELSE 'portal_invoice_gate' END,
    'documentacao',
    jsonb_build_object('invoice_id', p_invoice_id, 'gate', v_gate),
    '/manifestos/' || p_bl_id || '?tab=faturamento'
  );
END;
$$;



--
-- Name: validate_agency_departure_report_port(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_agency_departure_report_port() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.ports AS p
    WHERE p.id = NEW.terminal_port_id
      AND upper(btrim(p.locode)) = NEW.port
  ) THEN
    RAISE EXCEPTION 'Porto do ADR não corresponde ao ports.id informado.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: validate_bl_breakbulk_item_parent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_bl_breakbulk_item_parent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  parent_mode TEXT;
BEGIN
  SELECT cargo_mode
    INTO parent_mode
  FROM public.bls
  WHERE id = NEW.bl_id;

  IF parent_mode IS NULL THEN
    RAISE EXCEPTION 'BL nao encontrado para item de carga solta';
  END IF;

  IF parent_mode <> 'carga_solta' THEN
    RAISE EXCEPTION 'BL de item de carga solta precisa ter cargo_mode = carga_solta';
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: validate_depot_terminal_port(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_depot_terminal_port() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.tipo = 'depot' AND NEW.port_id IS NOT NULL THEN
    RAISE EXCEPTION 'Depot comum nao pode ter porto brasileiro.' USING ERRCODE = '23514';
  END IF;
  IF NEW.tipo = 'terminal_portuario'
     AND NEW.port_id IS NULL
     AND (TG_OP = 'INSERT' OR OLD.tipo <> 'terminal_portuario' OR OLD.port_id IS NOT NULL) THEN
    RAISE EXCEPTION 'Novo terminal portuario exige porto brasileiro.' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: validate_escala_port_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_escala_port_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.ports AS p
    WHERE p.id = NEW.port_id
      AND upper(btrim(p.locode)) = NEW.port
  ) THEN
    RAISE EXCEPTION 'Porto da escala não corresponde ao ports.id informado.'
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: validate_vazios_booking_operation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_vazios_booking_operation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_operation_voyage_id BIGINT;
  v_local_tipo TEXT;
BEGIN
  SELECT voyage_id INTO v_operation_voyage_id FROM public.vazios_export_operations WHERE id = NEW.operation_id;
  SELECT tipo INTO v_local_tipo FROM public.depots WHERE id = NEW.local_id;
  IF v_operation_voyage_id IS NULL OR v_operation_voyage_id <> NEW.voyage_id THEN
    RAISE EXCEPTION 'Unidade deve pertencer a uma operacao da mesma viagem.' USING ERRCODE = '22023';
  END IF;
  IF v_local_tipo IS NULL THEN RAISE EXCEPTION 'Local invalido.' USING ERRCODE = '22023'; END IF;
  IF v_local_tipo = 'depot' AND (NEW.hand_in_date IS NULL OR NEW.hand_out_date IS NULL OR NEW.hand_out_date < NEW.hand_in_date) THEN
    RAISE EXCEPTION 'Depot exige entrada e saida validas.' USING ERRCODE = '22023';
  END IF;
  IF v_local_tipo = 'terminal_portuario' AND (NEW.hand_in_date IS NOT NULL OR NEW.hand_out_date IS NOT NULL) THEN
    RAISE EXCEPTION 'Terminal portuario nao aceita entrada ou saida.' USING ERRCODE = '22023';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: validate_vazios_export_service_line(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_vazios_export_service_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_natureza TEXT;
  v_service_local UUID;
  v_service_destino UUID;
  v_service_condition TEXT;
  v_local_tipo TEXT;
BEGIN
  SELECT natureza, depot_id, route_destino_id, condition
    INTO v_natureza, v_service_local, v_service_destino, v_service_condition
  FROM public.depot_services WHERE id = NEW.service_id;
  SELECT tipo INTO v_local_tipo FROM public.depots WHERE id = NEW.local_id;

  IF v_natureza IS NULL OR v_service_local IS DISTINCT FROM NEW.local_id THEN
    RAISE EXCEPTION 'Servico deve pertencer ao local informado.' USING ERRCODE = '23514';
  END IF;
  IF v_natureza = 'armazenagem' THEN
    IF v_local_tipo <> 'depot' OR NEW.condition IS NULL
       OR v_service_condition IS DISTINCT FROM NEW.condition
       OR NEW.container_type IS NOT NULL OR NEW.destino_id IS NOT NULL
       OR NEW.percentual IS NOT NULL THEN
      RAISE EXCEPTION 'Armazenagem exige depot e a condicao do servico, sem tipo, rota ou percentual.' USING ERRCODE = '23514';
    END IF;
  ELSIF v_natureza = 'transporte' THEN
    IF v_service_destino IS NULL OR NEW.destino_id IS DISTINCT FROM v_service_destino
       OR NEW.condition IS NOT NULL OR NEW.percentual IS NOT NULL THEN
      RAISE EXCEPTION 'Transporte exige o destino vinculado ao servico, sem condicao ou percentual.' USING ERRCODE = '23514';
    END IF;
  ELSIF v_natureza = 'geral' THEN
    IF NEW.destino_id IS NOT NULL OR NEW.condition IS NOT NULL OR NEW.percentual IS NOT NULL THEN
      RAISE EXCEPTION 'Servico geral nao aceita rota, condicao ou percentual.' USING ERRCODE = '23514';
    END IF;
  ELSE
    RAISE EXCEPTION 'Natureza de servico invalida.' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$$;



--
-- Name: validate_vehicle_relationships(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_vehicle_relationships() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  container_bl_id TEXT;
  bl_voyage_id BIGINT;
BEGIN
  NEW.chassis := upper(trim(NEW.chassis));
  NEW.brand := trim(NEW.brand);
  NEW.model := trim(NEW.model);

  IF NEW.chassis = '' THEN
    RAISE EXCEPTION 'Chassi obrigatorio';
  END IF;

  IF NEW.brand = '' THEN
    RAISE EXCEPTION 'Marca obrigatoria';
  END IF;

  IF NEW.model = '' THEN
    RAISE EXCEPTION 'Modelo obrigatorio';
  END IF;

  SELECT bl_id
    INTO container_bl_id
  FROM public.bl_containers
  WHERE id = NEW.container_id;

  IF container_bl_id IS NULL THEN
    RAISE EXCEPTION 'Container nao encontrado';
  END IF;

  IF container_bl_id <> NEW.bl_id THEN
    RAISE EXCEPTION 'BL nao pertence ao container informado';
  END IF;

  SELECT voyage_id
    INTO bl_voyage_id
  FROM public.bls
  WHERE id = NEW.bl_id;

  IF bl_voyage_id IS NULL THEN
    RAISE EXCEPTION 'BL nao encontrado';
  END IF;

  IF bl_voyage_id <> NEW.voyage_id THEN
    RAISE EXCEPTION 'BL nao pertence a viagem informada';
  END IF;

  RETURN NEW;
END;
$$;



--
-- Name: voyage_terminal_code(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.voyage_terminal_code(p_terminal_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
