CREATE POLICY customer_contact_preferences_edit ON public.customer_contact_preferences FOR UPDATE TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.user_profiles
  WHERE ((user_profiles.id = auth.uid()) AND (user_profiles.active = true) AND (user_profiles.role = ANY (ARRAY['admin'::text, 'administrativo'::text, 'operator'::text, 'documentacao'::text, 'equipamentos'::text])))))) WITH CHECK (((EXISTS ( SELECT 1
   FROM public.user_profiles
  WHERE ((user_profiles.id = auth.uid()) AND (user_profiles.active = true) AND (user_profiles.role = ANY (ARRAY['admin'::text, 'administrativo'::text, 'operator'::text, 'documentacao'::text, 'equipamentos'::text]))))) AND (source = 'interno'::text)));



